alter table hadith add column if not exists review_note text;
begin;
update hadith set arabic = 'عَنْ أَمِيرِ المُؤْمِنِينَ أَبِي حَفْصٍ عُمَرَ بْنِ الخَطَّابِ بْنِ نُفَيْلِ بْنِ عَبْدِ العُزَّى بْنِ رِيَاحِ بْنِ قُرْطِ بْنِ رَزَاحِ بْنِ عَدِيِّ بْنِ لُؤَيِّ ابْنِ غَالِبٍ القُرَشِيِّ العَدَوِيِّ. رَضِيَ اللَّهُ عَنْهُ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: « إنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِىءٍ مَا نَوَى فَمَنْ كَانَتْ هِجْرَتُهُ إلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا، أَوْ امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إلَى مَا هَاجَرَ إلَيْهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66511 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20001;
update hadith set arabic = 'عَنْ أُمِّ المُؤْمِنِينَ أُمِّ عَبْدِ اللَّهِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "يَغزُو جَيْشٌ الكَعْبَةَ فَإِذَا كَانُوا بِبَيْدَاءَ مِنَ الأرضِ يُخْسَفُ بأَوَّلِهِم وَآخِرِهِم". قَالَتْ: قُلْتُ: يَارَسُولَ اللَّهِ، كَيْفَ يُخْسَفُ بِأَوَّلِهِمْ وَآخِرِهِمْ وَفِيهِمْ أَسْوَاقُهُم وَمَنْ لَيْسَ مِنْهُمْ!؟ قَالَ: "يُخْسَفُ بِأَوَّلِهِمْ وَآخِرِهِمْ، ثُمَّ يُبْعَثُونَ عَلَى نِيَّاتِهِم".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4812 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20002;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « لَا هِجْرَةَ بَعْدَ الفَتْحِ، وَلَكِنْ جِهَادٌ وَنِيَّةٌ، وَإِذَا اسْتُنْفِرْتُم فَانْفِرُوا».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20003;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ اللَّهِ جَابِرِ بْنِ عَبْدِ اللَّهِ الأَنْصَارِى رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزَاةٍ فَقَالَ: "إِنَّ بِالمَدِينَةِ لَرِجَالًا مَاسِرْتُمْ مَسِيرًا، وَلَا قَطَعْتُم وَادِيًا إِلَّا كَانُوا مَعَكُم حَبَسَهُمُ المَرَضُ" وَفِى رِوَايَةٍ: "إِلَّا شَارَكُوكُمْ فِي الأَجْرِ" ((رَوَاهُ مُسْلِمٌ)). ((وَرَوَاهُ البُخَارِيُّ)) عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَجَعْنَا مِنْ غَزْوَةِ تَبُوكَ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: " إِنَّ أَقْوَامًا خَلْفَنَا بِالمَدِينَةِ مَا سَلَكْنَا شِعْبَا وَلَا وَادِيًا إِلَّا وَهُمْ مَعَنَا، حَبَسَهُمُ العُذْرُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4557 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20004;
update hadith set arabic = 'عَنْ أَبِي يَزِيدَ مَعْنِ بْنِ يَزِيدَ بْنِ الأَخْنَسِ رَضِيَ اللَّهُ عَنْهُمْ، وَهُوَ وَأَبُوهُ وَجَدُّهُ صَحَابِيُّونَ، قَالَ: كَانَ أَبِي يَزِيدُ أَخْرجَ دَنَانِيرَ يَتَصَدَّقُ بِهَا فَوَضَعَهَا عِنْدَ رَجُلٍ فِي المَسْجِدِ فجِئْتُ فَأَخَذْتُهَا فَأَتَيْتُهُ بِهَا، فَقَالَ: وَاللَّهِ مَا إِيَّاكَ أَرَدْتُ، فخَاصَمْتُهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: « لَكَ مَا نَوَيْتَ يَا يَزِيدُ، وَلَكَ مَا أَخَذْتَ يَامَعْنُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4719 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20005;
update hadith set arabic = 'عَنْ أَبِي إِسْحَاقَ سَعْدِ بْنِ أَبِي وَقَّاصٍ مَالِكِ بْنِ أُهَيْبِ بْنِ عَبْدِ مَنَافِ بْنِ زُهْرَةَ بْنِ كِلَابِ بْنِ مُرَّةَ بْنِ كَعْبِ بْنِ لُؤَىٍّ القُرَشِ الزُّهْرِىِّ رَضِيَ اللَّهُ عَنْهُ، أَحَدِ العَشَرَةِ المَشْهُودِ لَهُمْ بِالجَنَّةِ، رَضِيَ اللَّهُ عَنْهُمْ، قَالَ: « جَاءَنِى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِى عَامَ حَجَّةِ الوَدَاعِ مِنْ وَجَعٍ اشْتَدَّ بِى فَقُلْتُ: يَارَسُولَ اللَّهِ إِنِّي قَدْ بَلَغَ بِى مِنَ الوَجَعِ مَا تَرَى، وَأَنَا ذُو مَالٍ وَلَا يَرِثُنِى إِلَّا ابْنَةٌ لِي، أَفَاتَصَدَّقُ بِثُلُثَى مَا لِي؟ قَالَ: لَا، قُلْتُ: فَالشَّطْرُ يَارَسُولَ اللَّهِ؟ فَقَالَ: لَا، قُلْتُ: فَالثُّلُثُ يَا رَسُولَ اللَّهِ؟ قَالَ الثُّلُثُ وَالثُّلُثُ كَثِيرٌ- أَوْ كَبِيرٌ- إِنَّكَ أَنْ تَذَرَ وَرَثَتَكَ أَغْنِيَاءَ خَيْرٌ مِنْ أَنْ تَذَرَهُم عَالَةً يَتَكَفَّفُونَ النَّاسَ، وَإِنَّكَ لَنْ تُنْفِقَ نَفَقَةً تَبْتَغِى بِهَا وَجْهَ اللَّهِ إِلَّا أُجِرْتَ عَلَيْهَا حَتَّى مَا تَجْعَلُ فِي فِيْ امْرَأَتِكَ قَالَ: فَقُلْتُ: يَارَسُولَ اللَّهِ أُخَلَّفُ بَعْدَ أَصْحَابِي؟ قَالَ: إِنَّكَ لَنْ تُخَلَّفُ فَتَعْمَلَ عَمَلًا تَبْتَغِي بهوَجْهَ اللَّهِ إِلَّا ازْدَدْتَ بِهِ دَرَجَةً ورِفْعَةً، وَلَعَلَّكَ أَنْ تُخَلَّفَ حَتَّى يَنْتَفِعَ بِكَ أَقْوَامٌ ويُضَرُّ بِكَ آخَرُونَ. اللَّهُمَّ امْضِ لَآصْحَابِى هِجْرَتَهُمْ، وَلَا تَرُدَّهُم عَلَى أَعْقَابِهِم، لكنِ البَائِسُ سَعْدُ بْنُ خَوْلَةَ» يَرْثِى لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ مَاتَ بِمَكَّةَ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5885 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20006;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ عَبْدِ الرَّحْمَنِ بْنِ صَخْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « إِنَّ اللهَ لَا يَنْظُرُ إِلَى أَجْسَامِكُمْ ، وَلَا إِلَى صُوَرِكُمْ، وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20007;
update hadith set arabic = 'عَنْ أَبِي مُوسَى عَبْدِ اللَّهِ بْنِ قَيْسٍ الأَشْعَرِى رَضِيَ اللَّهُ عَنْهُ قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الرَّجُلِ يُقَاتِلُ شَجَاعَةً، وَيُقَاتِلُ حَمِيَّةً، وَيُقَاتِلُ رِيَاءً، أَى ذَلِكَ فِي سَبِيلِ اللهِ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: « مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللهِ هِىَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/2969 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20008;
update hadith set arabic = 'عَنْ أَبِي بَكرة نُفَيْعِ بْنِ الحَارِثِ الثَّقَفِى رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إذ الْتَقَى الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَالْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ" قُلْتُ يَارَسُولَ اللهِ، هَذَا الْقَاتِلُ فَمَا بَالُ الْمَقْتُولِ؟ قَالَ: "إِنَّهُ كَانَ حَرِيصًا عَلَى قَتْلِ صَاحِبِهِ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20009;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : «صَلَاةُ الرَّجُلِ فِي جَمَاعَةٍ تَزِيدُ عَلَى صَلَاتِهِ فِي سُوقِهِ وَبَيْتِهِ بِضْعًا وَعِشْرِينَ دَرَجه وَذَلِكَ أَنَّ أَحَدَهُمْ إِذَا تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ أَتَى الْمَسْجِدَ لَا يُرِيدُ إِلَّا الصَّلَاةَ، لَا يَنْهَزُهُ إِلَّا الصَّلَاةُ، لَمْ يَخْطُ خَطْوَةً إِلَّا رُفِعَ لَهُ بِهَا دَرَجَةٌ، وَحُطَّ عَنْهُ بِهَا خَطِيئَةٌ حَتَّى يَدْخُلَ الْمَسْجِدَ، فَإِذَا دَخَلَ الْمَسْجِدَ كَانَ فِي الصَّلَاةِ مَا كَانَتِ الصَّلَاةُ هِىَ تَحْبِسُهُ، وَالْمَلَائِكَةُ يُصَلُّونَ عَلَى أَحَدِكُمْ مَا دَامَ فِي مَجْلِسِهِ الذِى صَلَّى فِيهِ، مَا لَمْ يُحْدِثْ فِيهِ» ((مُتَّفَقٌ عَلَيْهِ، وَهَذَا لَفْظُ مُسْلِمٍ)). وَقَوْلُهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: '' يَنْهَزُهُ هُوَ بِفَتْحِ اليَاءِ وَالهَاءِ وَبِالزَّاىِ: أَى يُخْرِجُهُ وَيُنْهِضُهُ ''', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4566 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20010;
update hadith set arabic = 'عَنْ أَبِي العَبَّاسِ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ بْنِ عَبْدِ المُطَّلِبِ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فِيمَا يَرْوِى عَنْ رَبِّهِ، تَبَارَكَ وَتَعَالَى قَالَ: « إنَّ اللهَ كَتَبَ الحَسَنَاتِ وَالسَّيِّئَاتِ ثُمَّ بَيَّنَ ذَلِكَ: فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللهُ تَبَارَكَ وَتَعَالَى عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللهُ عَشْرَ حَسَنَاتٍ إلَى سَبْعِمِائه ضِعْفٍ إلَى أَضْعَافٍ كَثِيرَةٍ، وَإِنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللهُ عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللهُ سَيِّئَةً وَاحِدَةً ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66533 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20011;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الخَطَّابِ، رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: " انْطَلَقَ ثَلَاثَةُ نَفَرٍ مِمَّنْ كَانَ قَبْلَكُمْ حَتَّى آوَاهُمُ المَبِيتُ إِلَى غَارٍ فَدَخَلُوهُ، فَانْحَدَرَتْ صَخْرَةٌ مِنَ الجَبَلِ فَسَدَّتْ عَلَيْهِمُ الغَارَ، فَقَالُوا: إنَّهُ لاَ يُنْجِيكُمْ مِنْ هَذِهِ الصَّخْرَةِ إِلَّا أَنْ تَدْعُوا اللَّهَ بِصَالِحِ أَعْمَالِكُمْ. قَالَ رَجُلٌ مِنْهُمْ: اللهُمَّ كَانَ لِي أَبَوَانِ شَيْخَانِ كَبِيرَانِ، وَكُنْتُ لاَ أَغْبِقُ قَبْلَهُمَا أَهْلًا وَلَا مَالًا. فَنَأَى بِى طَلَبُ الشَّجَرِ يَوْمًا فَلَمْ أَرِحْ عَلَيْهِمَا حَتَّى نَامَا فَحَلَبْتُ لَهُمَا غَبُوقَهُمَا فَوَجَدْتُهُمَا نَائِمَيْنِ فَكَرِهْتُ أَنْ أُوقِظَهُمَا وأَنْ أغْبِقَ قَبْلَهُمَا أَهْلًا أَوْ مَالًا، فَلَبِثْتُ- وَالقَدَحُ عَلَى يَدِى- أَنْتَظِرُ اسْتِيقَاظَهُمَا حَتَّى بَرِقَ الفَجْرُ وَالصِّبْيَةُ يَتَضَاغَوْن عِنْدَ قَدَمِى- فَاسْتَيْقَظَا فَشَرِبَا غَبُوقَهُما. اللَّهُمَّ إِنْ كُنْتُ فَعَلْتُ ذَلِكَ ابْتِغَاءَ وَجْهِكَ فَفَرِّجْ عَنَّا مَا نَحْنُ فِيهِ مِنْ هَذِهِ الصَّخْرَةِ، فَانْفَرَجَتْ شَيْئًا لَا يَسْتَطِيعُونَ الخُرُوجَ مِنْهُ. قَالَ الآخَرُ: اللَّهُمَّ إنَّهُ كَانَتْ لِي ابْنَةُ عَمٍّ كَانَتْ أَحَبَّ النَّاسِ إِلَىّ " وَفِى رِوَايَةٍ: "كُنْتُ أُحِبُّهَا كَأَشَدِّ مَا يُحِبُّ الرِّجَالُ النِّسَاءَ، فَأَرَدْتُهَا عَلَى نَفْسِهَا فَامْتَنَعَتْ مِنِّى حَتَّى أَلَمَّتْ بِهَا سَنَةٌ مِنَ السِّنِينَ فَجَاءَتْنِى فَأَعْطَيْتُهَا عِشْرِينَ وَمِائَةَ دِينَارٍ عَلَى أنْ تُخَلِّىَ بَيْنِى وَبَيْنَ نَفْسِهَا فَفَعَلَتْ، حَتَّى إِذَا قَدَرْتُ عَلَيْهَا" وَفِى رِوَايَةٍ: "فَلَمَّا قَعَدْتُ بَيْنَ رِجْلَيْهَا، قالتْ: اتَّقِ اللهَ ولاَ تَفُضَّ الخَاتَمَ إِلَّا بِحَقِّهِ، فَانْصَرَفْتُ عَنْهَا وَهِىَ أَحَبُّ النَّاسِ إِلَى وَتَرَكْتُ الذَّهَبَ الذِى أَعْطَيْتُهَا، اللَّهُمَّ إنْ كُنْتُ فَعَلْتُ ذَلِكَ ابْتِغَاءَ وَجْهِكَ فافْرُجْ عَنَّا مَا نَحْنُ فِيهِ، فَانْفَرَجَتِ الصَّخْرَةُ غَيْرَ أَنَّهُمْ لَا يَسْتَطِيعُونَ الخُرُوجَ مِنْهَا. وَقَالَ الثَّالِثُ: اللَّهُمَّ اسْتَأْجَرْتُ أُجَرَاءَ وَأَعْطَيْتُهُمْ أَجْرَهُمْ غَيْرَ رَجُلٍ وَاحِدٍ تَرَكَ الذِى لَهُ وَذَهَبَ، فَثمَّرْتُ أَجْرَهُ حَتَّى كَثُرَتْ مِنْهُ الأَمْوَالُ، فَجَاءَنِى بَعْدَ حِينٍ فَقَالَ: يَا عَبْدَ اللَّهِ أدِّ إِلَى أَجْرِى، فَقُلْتُ: كُلُّ مَا تَرَى مِنْ أَجْرِكَ: مِنَ الإِبِلِ وَالبَقَرِ وَالغَنَمِ وَالرَّقِيقِ. فَقَالَ: يَا عَبْدَ اللَّهِ لَا تَسْتَهْزِئْ بِى! فَقُلْتُ: لاَ أسْتَهْزِئُ بِكَ، فَأَخَذَهُ كُلَّهُ فَاسْتَاقَهُ فَلَمْ يَتْرُكْ مِنْهُ شَيْئًا، الَلهُمَّ إنْ كُنْتُ فَعَلْتُ ذَلِكَ ابْتِغَاءَ وَجْهِكَ فافْرُجْ عَنَّا مَا نَحْنُ فِيهِ، فَانْفَرَجَتِ الصَّخْرَةُ فَخَرَجُوا يَمْشُونَ".', updated_at = now() where id = 20012;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «وَاللهِ إِنِّي لأَسْتَغْفِرُ اللهَ وأَتُوبُ إِلَيْهِ فِي اليَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةً ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4808 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20013;
update hadith set arabic = 'عَنِ الأَغَرِّ بْنِ يَسَارٍ المُزَنِى رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « يَاأَيُّهَا النَّاسُ تُوبُوا إِلَى اللَّهِ وَاسْتَغْفِرُوهُ فَإِنِّى أَتُوبُ فِي اليَوْمِ مِائه مَرَّةٍ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20014;
update hadith set arabic = 'عَنْ أَبِي حَمْزَةَ أَنَسِ بْنِ مَالِكٍ الأَنْصَارِى خَادِمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : " للَّهُ أَفْرَحُ بِتَوْبَةِ عَبْدِهِ مِنْ أَحَدِكُمْ سَقَطَ عَلَى بَعِيرِهِ وَقَدْ أَضَلَّهُ فِي أَرْضِ فَلاَةٍ " ((مُتَّفَقٌ عَلَيْهِ)). وَفِى رِوَايَةٍ لِمُسْلِمٍ: لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ حِينَ يَتُوبُ إِلَيْهِ مِنْ أَحَدِكُمْ كَانَ عَلَى رَاحِلَتِهِ بِأَرْضِ فَلَاةٍ، فَانْفَلَتَتْ مِنْهُ وَعَلَيْهَا طَعَامُهُ وَشَرَابُهُ فَأَيِسَ مِنْهَا، فَأَتَى شَجَرَةً فَاضْطَجَعَ فِي ظِلِّهَا، وقَدْ أَيِسَ مِنْ رَاحِلَتِهِ، فَبَيْنَمَا هُوَ كَذَلِكَ إِذَا هُوَ بِهَا، قَائِمَةً عِنْدَهُ ، فَأَخَذَ بِخِطَامِهَا ثُمَّ قَالَ مِنْ شِدَّةِ الْفَرَحِ: اللهُمَّ أَنْتَ عَبْدِي وَأَنَا رَبُّكَ، أَخْطَأَ مِنْ شِدَّةِ الْفَرَح".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4313 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20015;
update hadith set arabic = 'عَنْ أَبِي مُوسَى عَبْدِ اللَّهِ بْنِ قَيْسٍ الأَشْعَرِى رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « إِنَّ اللهَ تَعَالَى يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ، وَيَبْسُطُ يَدَهُ بِالنَّهَارِ لِيَتُوبَ مُسِيءُ اللَّيْلِ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4318 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20016;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « مَنْ تَابَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا تَابَ اللهُ عَلَيْهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4797 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20017;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقْبَلُ تَوْبَةَ العَبْدِ مَا لَمْ يُغَرْغِرْ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4315 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20018;
update hadith set arabic = 'عَنْ زِرِّ بْنِ حُبَيْشٍ قَالَ: أَتَيْتُ صَفْوَانَ بْنَ عَسَّالٍ رَضِيَ اللَّهُ عَنْهُ أَسْأَلُهُ عَنِ المَسْحِ عَلَى الخُفَّيْنِ فَقَالَ: مَا جَاءَ بِكَ يَازِرُّ؟ فَقُلْتُ: ابْتِغَاءَ العِلْمِ، فَقَالَ: إِنَّ المَلاَئِكَةَ تَضَعُ أَجْنِحَتَهَا لِطَالِبِ العِلْمِ رِضًى بِمَا يَطْلُبُ، فَقُلْتُ: مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَجِئْتُ أَسْأَلُكَ: هَلْ سَمِعْتَهُ يَذْكُرُ فِي ذَلِكَ شَيْئًا؟ قَالَ: نَعَمْ، كَانَ يَأْمُرُنَا إِذَا كُنَّا سَفْرًا- أَوْ مُسَافِرِينَ- أَنْ لَا نَنْزِعَ خِفَافَنَا ثَلاَثَةَ أَيَّامٍ وَلَيَالِيهِنَّ إِلَّا مِنْ جَنَابَةٍ، وَلَكِنْ مِنْ غَائِطٍ وَبَوْلٍ وَنَوْمٍ. فَقُلْتُ: سَفَرٍ، فَبَيْنَا نَحْنُ عِنْدَهُ إِذْ نَادَاهُ أَعْرَابِى بِصَوْتٍ لَهُ جَهْوَرِى: يَا مُحَمَّدُ، فَأَجَابَهُ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَحْواً مِنْ صَوْتِهِ: "هَاؤُمُ" فَقُلْتُ لَهُ: وَيْحَكَ اغْضُضْ مِنْ صَوْتِكَ فَإِنَّكَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَقَدْ نُهِيتَ عَنْ هَذَا! فَقَالَ: وَاللَّهِ لاَ أَغْضُضُ. قَالَ الأَعْرَابِى: المَرْءُ يُحِبُّ القَوْمَ وَلَمَّا يَلْحَقْ بِهِمْ؟ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: " المَرْءُ مَعَ مَنْ أَحَبَّ يَوْمَ القِيَامَةِ" فَمَا زَالَ يُحَدِّثُنَا حَتَّى ذَكَرَ بَابًا مِنْ المَغْرِبِ مَسِيرَةُ عَرْضِهِ أَوْ يَسِيرُ الرَّاكِبُ فِي عَرْضِهِ أَرْبَعِينَ أَوْ سَبْعِينَ عَامًا. قَالَ سُفْيَانُ أَحَدُ الرُّوَاةِ قِبَلَ الشَّامِ خَلَقَهُ اللَّهُ تَعَالَى يَوْمَ خَلَقَ السَّمَاوَاتِ وَالأَرْضَ مَفْتُوحاً لِلتَّوْبَةِ لَا يُغْلَقُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْهُ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20019;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ سَعْدِ بْنِ مَالِكِ بْنِ سِنَانٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « كَانَ فِيمَنْ كَانَ قَبْلَكُمْ رَجُلٌ قَتَلَ تِسْعَةً وَتِسْعِينَ نَفْسًا، فَسَأَلَ عَنْ أَعْلَمِ أَهْلِ الأَرْضِ، فَدُلَّ عَلَى رَاهِبٍ، فَأَتَاهُ فَقَالَ: إِنَّهُ قَتَلَ تِسْعه وَتِسْعِينَ نَفْسًا، فَهَلْ لَهُ مِنْ تَوْبَةٍ؟ فَقَالَ: لَا، فَقَتَلَهُ فَكمَّلَ بِهِ مِائَةً، ثُمَّ سَأَلَ عَنْ أَعْلَمِ أَهْلِ الأَرْضِ، فَدُلَّ عَلَى رَجُلٍ عَالِمٍ فَقَالَ: إِنَّهُ قَتَلَ مِائَةَ نَفْسٍ فَهَلْ لَهُ مِنْ تَوْبَةٍ؟ فَقَالَ: نَعَمْ، ومَنْ يَحُولُ بَيْنَهُ وَبَيْنَ التَّوْبَةِ؟ انْطَلِقْ إِلَى أَرْضِ كَذَا وَكَذَا، فَإِنَّ بِهَا أُنَاسًا يَعْبُدُونَ اللَّهَ تَعَالَى فَاعْبُدِ اللَّهَ مَعَهُمْ، وَلَا تَرْجِعْ إِلَى أَرْضِكَ فَإِنَّهَا أَرْضُ سُوءٍ، فَانْطَلَقَ حَتَّى إِذَا نَصَفَ الطَّرِيقَ أَتَاهُ المَوْتُ، فَاخْتَصَمَتْ فِيهِ مَلَائِكَةُ الرَّحْمَةِ وَمَلَائِكَةُ العَذَابِ. فَقَالَتْ مَلَائِكَةُ الرَّحْمَةِ: جَاءَ تَائِبًا مُقْبِلًا بِقَلْبِهِ إِلَى اللَّهِ تَعَالَى، وَقَالَتْ مَلَائِكَةُ العَذَابِ: إِنَّهُ لَمْ يَعْمَلْ خَيْرًا قَطُّ، فَأَتَاهُمْ مَلَكٌ فِي صُورَةِ آدَمِيٍّ فَجَعَلُوهُ بَيْنَهُمْ- أَيْ حَكَمًا- فَقَالَ: قِيسُوا مَا بَيْنَ الأَرْضَيْنِ فَإِلَى أَيَّتِهِمَا كَانَ أَدْنَى فَهُوَ لَهُ، فَقَاسُوا فَوَجَدُوهُ أَدْنَى إِلَى الأَرْضِ الَّتِي أَرَادَ، فَقَبَضَتْهُ مَلَائِكَةُ الرَّحْمَةِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4310 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20020;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ، وَكَانَ قَائِدَ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ مِنْ بَنِيهِ حِينَ عَمِيَ قَالَ: سَمِعْتُ كَعْبَ بْنَ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ يُحَدِّثُ بِحَدِيثِهِ حِينَ تَخَلَّفَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ. قَالَ كَعْبٌ: لَمْ اتَخَلَّفْ عَنْ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فِي غَزْوَةٍ غَزَاهَا قَطُّ إِلَّا فِي غَزْوَةِ تَبُوكَ، غَيْرَ أَنِّي قَدْ تَخَلَّفْتُ فِي غَزْوَةِ بَدْرٍ، وَلَمْ يُعَاتَبْ أَحَدٌ تَخَلَّفَ عَنْهُ، إِنَّمَا خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالمُسْلِمُونَ يُرِيدُونَ عِيرَ قُرَيْشٍ حَتَّى جَمَعَ اللَّهُ تَعَالَى بَيْنَهُمْ وَبَيْنَ عَدُوِّهِمْ عَلَى غَيْرِ مِيعَادٍ. وَلَقَدْ شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةَ العَقَبَةِ حِينَ تَوَاثَقْنَا عَلَى الإِسْلَامِ، وَمَا أُحِبُّ أَنَّ لِي بِهَا مَشْهَدَ بَدْرٍ، وَإِنْ كَانَتْ بَدْرٌ أَذْكَرَ فِي النَّاسِ مِنْهَا. وَكَانَ مِنْ خَبَرِي حِينَ تَخَلَّفَ عَنْ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِي غَزْوَةِ تَبُوكَ أَنِّي لَمْ أَكُنْ قَطُّ أَقْوَى وَلَا أَيْسَرَ مِنِّي حِينَ تَخَلَّفْتُ عَنْهُ فِي تِلْكَ الغَزْوَةِ، وَاللَّهِ مَا جَمَعْتُ قَبْلَهَا رَاحِلَتَيْنِ قَطُّ حَتَّى جَمَعْتُهُمَا فِي تِلْكَ الغَزْوَةِ، وَلَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُرِيدُ غَزْوَةً إِلَّا وَرَّى بِغَيْرِهَا حَتَّى كَانَتْ تِلْكَ الغَزْوَةُ، فَغَزَاهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَرٍّ شَدِيدٍ، وَاسْتَقْبَلَ سَفَرًا بَعِيدًا ومَفَازًا، وَاسْتَقْبَلَ عَدَدًا كَثِيرًا، فجَلَّى لِلْمُسْلِمِينَ أَمْرَهُمْ ليتَأهَّبُوا أُهْبَةَ غَزْوِهِمْ فَأَخْبَرَهُمْ بِوَجْهِهِمُ الَّذِي يُرِيدُ، وَالمُسْلِمُونَ مَعَ رَسُولِ اللَّهِ كَثِيرٌ وَلَا يَجْمَعُهُمْ كِتَابٌ حَافِظٌ "يُرِيدُ بِذَلِكَ الدِّيوَانَ" قَالَ كَعْبٌ: فَقَلَّ رَجُلٌ يُرِيدُ أَنْ يَتَغَيَّبَ إِلَّا ظَنَّ أَنَّ ذَلِكَ سَيَخْفَى بِهِ مَالَمْ يَنْزِلْ فِيهِ وَحْيٌ مِنَ اللَّهِ، وَغَزَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِلْكَ الغَزْوَةَ حِينَ طَابَتِ الثِّمَارُ وَالظِّلَالُ فَأَنَا إِلَيْهَا أَصْعَرُ فَتَجَهَّزَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالمُسْلِمُونَ مَعَهُ، وطَفِقْتُ أَغْدُو لِكَيْ أَتَجَهَّزَ مَعَهُ، فَأَرْجِعُ وَلَمْ أَقْضِ شَيْئاً، وَأَقُولُ فِي نَفْسِي: أَنَا قَادِرٌ عَلَى ذَلِكَ إِذَا أَرَدْتُ، فَلَمْ يَزَلْ يَتَمَادَى بِي حَتَّى اسْتَمَرَّ بِالنَّاسِ الجِدُّ، فَأَصْبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَادِياً وَالمُسْلِمُونَ مَعَهُ، وَلَمْ أَقْضِ مِنْ جَهَازِي شَيْئاً، ثُمَّ غَدَوْتُ فَرَجَعْتُ وَلَمْ أَقْضِ شَيْئاً، فَلَمْ يَزَلْ يَتَمَادَى بِي حَتَّى أَسْرَعُوا وَتَفَارَطَ الغَرْوُ، فَهَمَمْتُ أَنْ أَرْتَحِلَ فَأُدْرِكَهُمْ، فَيَالَيْتَنِي فَعَلْتُ، ثُمَّ لَمْ يُقَدَّرْ ذَلِكَ لِي، فَطَفِقْتُ إِذَا خَرَجْتُ فِي النَّاسِ بَعْدَ خُرُوجِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْزُنُنِي أَنِّي أَرَى لِي أُسْوَةً، إِلَّا رَجُلاً مَغْمُوصاً عَلَيْهِ فِي النِّفَاقِ، أَوْ رَجُلاً مِمَّنْ عَذَرَ اللَّهُ تَعَالَى مِنْ أُسْوَةً، إِلَّا رَجُلًا مَغْمُوصًا عَلَيْهِ فِي النِّفَاقِ، أَوْ رَجُلًا مِمَّنْ عَذَرَ اللَّهُ تَعَالَى مِنَ الضُّعَفَاءِ، وَلَمْ يَذْكُرْنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَلَغَ تَبُوكَ، فَقَالَ وَهُوَ جَالِسٌ فِي القَوْمِ بِتَبُوكَ: مَا فَعَلَ كَعْبُ بْنُ مَالِكٍ؟ قَالَ رَجُلٌ مِنْ بَنِي سَلِمَةَ يَا رَسُولَ اللَّهِ حَبَسَهُ بُرْدَاهُ وَالنَّظَرُ فِي عِطْفَيْهِ.فَقَالَ لَهُ مُعَاذُ بْنُ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ بِئْسَ مَا قُلْتَ! وَاللَّهِ يَارَسُولَ اللَّهِ مَا عَلِمْنَا عَلَيْهِ إِلَّا خَيْرًا ، فَسَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَيْنَا هُوَ عَلَى ذَلِكَ رَأَى رَجُلًا مُبَيِّضًا يَزُولُ بِهِ السَّرَابُ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُنْ أَبَا خَيْثَمَةَ، فَإِذَا أَبُو خَيْثَمَةَ الأَنْصَارِيُّ وَهُوَ الَّذِي تَصَدَّقَ بِصَاعِ التَّمْرِ حِينَ لَمَزَهُ المُنَافِقُونَ، قَالَ كَعْبٌ: فَلَمَّا بَلَغَنِي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ تَوَجَّهَ قَافِلًا مِنْ تَبُوكَ حَضَرَنِي بَثِّي، فطَفِقْتُ أَتَذَكَّرُ الكَذِبَ وَأَقُولُ: بِمَ أَخْرُجُ مِنْ سَخَطِهِ غَدًا وَأَسْتَعِينُ عَلَى ذَلِكَ بِكُلِّ ذِي رَأْىٍ مِنْ أَهْلِي، فَلَمَّا قِيلَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَظَلَّ قَادِمًا زَاحَ عَنِّي البَاطِلُ حَتَّى عَرَفْتُ أَنِّي لَمْ أَنْجُ مِنْهُ بِشَيْءٍ أَبَدًا، فَأَجْمَعْتُ صِدْقَهُ، وَأَصْبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَادِمًا، وَكَانَ إِذَا قَدِمَ مِنْ سَفَرٍ بَدَأَ بِالمَسْجِدِ فَرَكَعَ فِيهِ رَكْعَتَيْنِ ثُمَّ جَلَسَ لِلنَّاسِ، فَلَمَّا فَعَلَ فَعَلَ ذَلِكَ جَاءَهُ المُخَلَّفُونَ يَعْتَذِرُونَ إِلَيْهِ وَيَحْلِفُونَ لَهُ، وَكَانُوا بِضْعًا وَثَمَانِينَ رَجُلًا فَقَبِلَ مِنْهُمْ عَلَانِيَتَهُمْ وَبَايَعَهُمْ وَاسْتَغْفَرَ لَهُمْ وَوَكَلَ سَرَائِرَهُم إِلَى اللَّهِ تَعَالَى حَتَّى جِئْتُ. فَلَمَّا سَلَّمْتُ تَبَسَّمَ تَبَسُّمَ المُغْضَبِ ثُمَّ قَالَ: تَعَالَ، فَجِئْتُ أَمْشِي حَتَّى جَلَسْتُ بَيْنَ يَدَيْهِ، فَقَالَ لِي: مَا خَلَّفَكَ؟ أَلَمْ تَكُنْ قَدِ ابْتَعْتَ ظَهْرَكَ! قَالَ قُلْتُ: يَارَسُولَ اللَّهِ إِنِّي وَاللَّهِ لَوْ جَلَسْتُ عِنْدَ غَيْرِكَ مِنْ أَهْلِ الدُّنْيَا لَرَأَيْتُ أَنِّي سَأَخْرُجُ مِنْ سَخَطِهِ بِعُذْرٍ، لَقَدْ أُعْطِيتُ جَدَلًا، وَلَكِنَّنِي وَاللَّهِ لَقَدْ عَلِمْتُ لَئِنْ حَدَّثْتُكَ اليَوْمَ حَدِيثَ كَذِبٍ تَرْضَى بِهِ لَيُوشِكَنَّ اللهُ يُسْخِطَكَ عَلَيَّ، وَإِنْ حَدَّثْتُكَ حَدِيثَ صِدْقٍ تَجِدُ عَلَيَّ فِيهِ إِنِّي لَأَرْجُو فِيهِ عُقْبَى اللهِ عَزَّ وَجَلَّ، وَاللَّهِ مَا كَانَ لِي مِنْ عُذْرٍ، وَاللَّهِ مَا كُنْتُ قَطُّ أَقْوَى وَلَا أَيْسَرَ مِنِّي حِينَ تَخَلَّفْتُ عَنْكَ. قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ " أَمَّا هَذَا فَقَدْ صَدَقَ، فَقُمْ حَتَّى يَقْضِيَ اللَّهُ فِيكَ" وَسَارَ رِجَالٌ مِنْ بَنِي سَلِمَةَ فَاتَّبَعُونِي، فَقَالُوا لِي: وَاللَّهِ مَا عَلِمْنَاكَ أَذْنَبْتَ ذَنْبًا قَبْلَ هَذَا، لَقَدْ عَجَزْتَ فِي أَنْ لَا يَكُونَ اعْتَذَرْتَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَا اعْتَذَرَ إِلَيْهِ المُخَلَّفُونَ فَقَدْ كَانَ كَافِيَكَ ذَنْبَكَ اسْتِغْفَارُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَكَ. قَالَ: فَوَاللَّهِ مَا زَالُوا يُؤَنِّبُونَنِي حَتَّى أَرَدْتُ أَنْ أَرْجِعَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فأُكَذِّبَ نَفْسِي، ثُمَّ قُلْتُ لَهُمْ: هَلْ لَقِيَ هَذَا مَعِي مِنْ أَحَدٍ؟ قَالُوا: نَعَمْ لَقِيَهُ مَعَكَ رَجُلَانِ قَالَا مِثْلَ مَا قُلْتَ، وَقِيلَ لَهُمَا مِثْلُ مَا قِيلَ لَكَ، قَالَ قُلْتُ: مَنْ هُمَا؟ قَالُوا: مُرَارَةُ بنُ الرَّبِيعِ العَمْرِي، وَهِلَالُ بْنُ أُمَيَّةَ الوَاقِفِي؟ قَالَ: فَذَكَرُوا لِي رَجُلَيْنِ صَالِحَيْنِ قَدْ شَهِدَا بَدْرًا فِيهِمَا أُسْوَةٌ. قَالَ: فَمَضَيْتُ حِينَ ذَكَرُوهُمَا لِي. وَنَهَى رَسُولُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ كَلَامِنَا أَيُّهَا الثَّلَاثَةُ مِنْ بَيْنِ مَنْ تَخَلَّفَ عَنْهُ، قَالَ: فَاجْتَنَبَنَا النَّاسُ- أَوْ قَالَ: تَغَيَّرُوا لَنَا- حَتَّى تَنَكَّرَتْ لِي فِي نَفْسِ الأَرْضُ، فَمَا هِيَ بِالأَرْضِ الَّتِي أَعْرِفُ، فَلَبِثْنَا عَلَى ذَلِكَ خَمْسِينَ لَيْلَةً. فَأَمَّا صَاحِبَايَ فَاسْتَكَانَا وَقَعَدَا فِي بُيُوتِهِمَا يَبْكِيَانِ، وَأَمَّا أَنَا فَكُنْتُ أَشَبَّ القَوْمِ وَأَجْلَدَهُم، فَكُنْتُ أَخْرُجُ فَأَشْهَدُ الصَّلَاةَ مَعَ المُسْلِمِينَ، وَأَطُوفُ فِي الأَسْوَاقِ وَلَا يُكَلِّمُنِي أَحَدٌ، وَآتِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأُسَلِّمُ عَلَيْهِ، وَهُوَ فِي مَجْلِسِهِ بَعْدَ الصَّلَاةِ، فَأَقُولُ فِي نَفْسِي : هَلْ حَرَّكَ شَفَتَيْهِ بِرَدِّ السَّلَامِ أَمْ ؟ ثُمَّ أُصَلِّي قَرِيبًا مِنْهُ وَأُسَارِقُهُ النَّظَرَ، فَإِذَا أَقْبَلْتُ عَلَى صَلَاتِي نَظَرَ إِلَيَّ، وَإِذَا الْتَفَتُّ نَحْوَهُ أَعْرَضَ عَنِّي، حَتَّى إِذَا طَالَ ذَلِكَ عَلَيَّ مِنْ جَفْوَةِ المُسْلِمِينَ مَشَيْتُ حَتَّى تَسَوَّرْتُ جِدَارَ حَائِطِ أَبِي قَتَادَةَ وَهُوَ ابْنُ عَمِّي وَأَحَبُّ النَّاسِ إِلَيَّ، فَسَلَّمْتُ عَلَيْهِ فَوَاللَّهِ مَا رَدَّ عَلَيَّ السَّلَامَ، فَقُلْتُ لَهُ: يَا أَبَا قَتَادَةَ أَنْشُدُكَ بِاللَّهِ هَلْ تَعْلَمُنِي أُحِبُّ اللَّهَ وَرَسُولَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ؟ فَسَكَتَ، فَعُدْتُ فَنَاشَدْتُهُ فَسَكَتَ، فَعُدْتُ فَنَاشَدْتُهُ فَقَالَ: اللَّهُ وَرَسُولُهُ أَعْلَمُ. فَفَاضَتْ عَيْنَايَ، وَتَوَلَّيْتُ حَتَّى تَسَوَّرْتُ الجِدَارَ، فَبَيْنَمَا أَنَا أَمْشِى فِي سُوقِ المَدِينَةِ إِذَا نَبَطِىٌّ مِن نَبَطِ أَهْلِ الشَّامِ مِمَّنْ قَدِمَ بِالطَّعَامِ بِبِيعِهِ بِالمَدِينَةِ يَقُولُ: مَنْ يَدُلُّ عَلَى كَعْبِ بْنِ مَالِكٍ؟ فَطَفِقَ النَّاسُ يُشِيرُونَ لَهُ إِلَيَّ حَتَّى جَاءَنِى فَدَفَعَ إِلَيَّ كِتَابٌ مِنْ مَلِكِ غَسَّانَ، وَكُنْتُ كَاتِبًا. فَقَرَأْتُهُ فَإِذَا فِيهِ: أَمَّا بَعْدُ فَإِنَّهُ قَدْ بَلَغَنَا أَنَّ صَاحِبَكَ قَدْ جَفَاكَ، وَلَمْ يَجْعَلْكَ اللَّهُ بِدَارِ هَوَانٍ وَلَا مَضيَعَةٍ، فالْحَقْ بِنَا نُوَاسِكَ، فَقُلْتُ حِينَ قَرَأْتُهَا، وَهَذِهِ أَيْضًا مِنَ البَلَاءِ فَتَيَمَّمْتُ بِهَا التَّنُّورَ فَسَجَرْتُها، حَتَّى إِذَا مَضَتْ أَرْبَعُونَ مِنَ الخَمْسِينَ واسْتَلْبَثَ الوَحْىُ إِذَا رسولُ رسولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْتِينِى، فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكَ أَنْ تَعْتَزِلَ امْرَأَتَكَ، فَقُلْتُ: أُطَلِّقُهَا، أَمْ مَاذَا أَفْعَلُ؟ قَالَ: لَا، بَلِ اعْتَزِلْهَا فَلَا تَقْرَبَنَّهَا، وَأَرْسَلَ إِلَى صاحِبَيَّ بِمِثْلِ ذَلِكَ. فَقُلْتُ لِامْرَأَتِي: الْحَقِي بِأَهْلِكِ فَكُونِي عِنْدَهُمْ حَتَّى يَقْضِيَ اللَّهُ فِي هَذَا الأَمْرِ، فَجَاءَتِ امْرَأَةُ هِلَالِ بْنِ أُمَيَّةَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ لَهُ : يَا رَسُولَ اللَّهِ إِنَّ هِلَالَ بْنَ أُمَيَّةَ شَيْخٌ ضَائِعٌ لَيْسَ لَهُ خَادِمٌ، فَهَلْ تَكْرَهُ أَنْ أَخْدُمَهُ؟ قَالَ : لَا، وَلَكِنْ لَا يَقْرَبَنَّكِ. فَقَالَتْ: إِنَّهُ وَاللَّهِ مَا بِهِ مِنْ حَرَكَةٍ إِلَى شَيْءٍ، وَوَاللَّهِ مَا زَالَ يَبْكِي مُنْذُ كَانَ مِنْ أَمْرِهِ مَا كَانَ إِلَى يَوْمِهِ هَذَا. فَقَالَ لِي بَعْضُ أَهْلِي: لَوِ اسْتَأْذَنْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي امْرَأَتِكَ، فَقَدْ أَذِنَ لِامْرَأَةِ هِلَالِ بْنِ أُمَيَّةَ أَنْ تَخْدُمَهُ؟ فَقُلْتُ: لَا أَسْتَأْذِنُ فِيهَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَا يُدْرِينِي مَاذَا يَقُولُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذَا اسْتَأْذَنْتُهُ فِيهَا وَأَنَا رَجُلٌ شَابٌّ! فَلَبِثْتُ بِذَلِكَ عَشْرَ لَيَالٍ، فَكَمَلَ لَنَا خَمْسُونَ لَيْلَةً مِنْ حِينَ نَهَى عَنْ كَلَامِنَا. ثُمَّ صَلَّيْتُ صَلَاةَ الفَجْرِ صَبَاحَ خَمْسِينَ لَيْلَةً عَلَى ظَهْرِ بَيْتٍ مِنْ بُيُوتِنَا، فَبَيْنَمَا أَنَا جَالِسٌ عَلَى الحَالِ الَّتِى ذَكَرَ اللَّهُ تَعَالَى مِنَّا، قَدْ ضافَتْ عَلَيَّ نَفْسِي وَضَاقَتْ عَلَيَّ الأَرْضُ بِمَا رَحُبَتْ، سَمِعْتُ صَوْتَ صَارِخٍ أَوْفَى عَلَى سَلْعٍ يَقُولُ بِأَعْلَى صَوْتِهِ: يَا كَعْبُ بْنَ مَالِكٍ أبْشِرْ فَخَرَرْتُ سَاجِدًا، وَعَرَفْتُ أَنَّهُ قَدْ جَاءَ فَرَجٌ. فآذَنَ رسولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّاسَ بِتَوْبَةِ اللَّهِ عَزَّ وَجَلَّ عَلَيْنَا حِينَ صَلَّى صَلَاةَ الفَجْرِ فَذَهَبَ النَّاسُ يُبَشِّرُونَنَا، فذهبَ قِبَلَ صَاحِبَيَّ مُبَشِّرُونَ، ورَكَضَ رجلٌ إليَّ فرسًا وسعى ساعٍ مِن أَسْلَمَ قِبَلِي وَأَوْفَى عَلَى الجَبَلِ، فَكَانَ الصوتُ أسرعَ مِنَ الفَرَسِ، فَلَمَّا جَاءَنِي الَّذِى سَمِعْتُ صَوْتَهُ يُبَشِّرُنِي نَزَعْتُ لَهُ ثَوْبَيَّ فَكَسَوْتُهُمَا إِيَّاهُ بِبُشْرَاهُ، وَاللَّهِ مَا أَمْلِكُ غَيْرَهُمَا يَوْمَئِذٍ، وَاسْتَعَرْتُ ثَوْبَيْنِ فَلَبِسْتُهُمَا وَانْطَلَقْتُ أَتَأَمَّمُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَلَقَّانِى النَّاسُ فَوْجًا فَوْجًا يُهَنِّئُونِي بِالتَّوْبَةِ وَيَقُولُونَ لِي: لِتَهْنِكَ تَوْبَةُ اللَّهِ عَلَيْكَ، حَتَّى دَخَلْتُ المَسْجِدَ فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ حَوْلَهُ النَّاسُ، فَقَامَ طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ يُهَرْوِلُ حَتَّى صَافَحَنِي وهَنَّأَنِي، وَاللَّهِ مَا قَامَ رَجُلٌ مِنَ المُهَاجِرِينَ غَيْرُهُ، فَكَانَ كَعْبٌ لَا يَنْسَاهَا لِطَلْحَةَ. قَالَ كَعْبٌ: فَلَمَّا سَلَّمْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَهُوَ يَبْرُقُ وَجْهُهُ مِنَ السُّرُورِ : أَبْشِرْ بِخَيْرِ يَوْمٍ مَرَّ عَلَيْكَ مُذْ وَلَدَتْكَ أُمُّكَ، فَقُلْتُ: أَمِنْ عِنْدِكَ يَا رَسُولَ اللَّهِ أَمْ مِنْ عِنْدِ اللَّهِ؟ قَالَ : لَا ، بَلْ مِنْ عِنْدِ اللَّهِ عَزَّ وَجَلَّ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سُرَّ اسْتَنَارَ وَجْهُهُ حَتَّى كَأَنَّ وَجْهَهَ قِطْعَةُ قَمَرٍ، وَكُنَّا نَعْرِفُ ذَلِكَ مِنْهُ، فَلَمَّا جَلَسْتُ بَيْنَ يَدَيْهِ قُلْتُ: يَا رَسُولَ اللَّهِ إِنَّ مِنْ تَوْبَتِي أَنْ أنْخَلِعَ مِنْ مَالِي صَدَقَةً إِلَى اللَّهِ وَإِلَى رَسُولِهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَمْسِكْ عَلَيْكَ بَعْضَ مَالِكَ فَهُوَ خَيْرٌ لَكَ، فَقُلْتُ: إِنِّي أُمْسِكُ سَهْمِي الَّذِى بِخَيْبَرَ. وَقُلْتُ: يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ تَعَالَى إِنَّمَا أَنْجَانِي بِالصِّدْقِ، وَإِنَّ مِنْ تَوْبَتِي أَنْ لَا أُحَدِّثَ إِلَّا صِدْقًا مَا بَقِيتُ ، فَوَ اللَّهِ مَا عَلِمْتُ أَحَدًا مِنَ المُسْلِمِينَ أَبْلَاهُ اللَّهُ فِي صِدْقِ الحَدِيثِ مُنْذُ ذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحْسَنَ مِمَّا أَبْلَانِي اللَّهُ تَعَالَى ، وَاللَّهِ مَا تَعَمَّدْتُ كِذْبَةً مُنْذُ قُلْتُ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى يَوْمِي هَذَا، وَإِنِّي لَأَرْجُو أَنْ يَحْفَظَنِي اللَّهُ تَعَالَى فِيمَا بَقِيَ، قَالَ: فَأَنْزَلَ اللَّهُ تَعَالَى: {لَقَدْ تَابَ اللَّهُ عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالْأَنْصَارِ الَّذِينَ اتَّبَعُوهُ فِي سَاعَةِ الْعُسْرَةِ) حَتَّى بَلَغَ: {إِنَّهُ بِهِمْ رَؤُوفٌ رَحِيمٌ . وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا حَتَّى إِذَا ضَاقَتْ عَلَيْهِمُ الْأَرْضُ بِمَا رَحُبَتْ} حَتَّى بَلَغَ : {اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ} ((التَّوْبَةُ 117، 119)) قَالَ كَعْبٌ : وَاللَّهِ مَا أَنْعَمَ اللَّهُ عَلَيَّ مِنْ نِعْمَةٍ قَطُّ بَعْدَ إِذْ هَدَانِي اللَّهُ لِلْإِسْلَامِ أَعْظَمَ فِي نَفْسِي مِنْ صِدْقِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ لَا أَكُونَ كَذَبْتُهُ، فأَهْلِكَ كَمَا هَلَكَ الَّذِينَ كَذَبُوا، إِنَّ اللَّهَ تَعَالَى قَالَ لِلَّذِينَ كَذَبُوا حِينَ أَنْزَلَ الوَحْيَ شَرَّ مَا قَالَ لِأَحَدٍ، فَقَالَ اللَّهُ تَعَالَى : {سَيَحْلِفُونَ بِاللَّهِ لَكُمْ إِذَا انْقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا عَنْهُمْ فَأَعْرِضُوا عَنْهُمْ إِنَّهُمْ رِجْسٌ وَمَأْوَاهُمْ جَهَنَّمُ جَزَاءً بِمَا كَانُوا يَكْسِبُونَ يَحْلِفُونَ لَكُمْ لِتَرْضَوْا عَنْهُمْ فَإِنْ تَرْضَوْا عَنْهُمْ فَإِنَّ اللَّهَ لَا يَرْضَى عَنِ الْقَوْمِ الْفَاسِقِينَ} ((التَّوْبَةُ: 95،96)) . قَالَ كَعْبٌ : كُنَّا خُلِّفْنَا أَيُّهَا الثَّلَاثَةُ عَنْ أَمْرِ أُولَئِكَ الَّذِينَ قَبِلَ مِنْهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ حَلَفُوا لَهُ ، فَبَايَعَهُمْ وَاسْتَغْفَرَ لَهُمْ، وأرجَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْرَنَا حَتَّى قَضَى اللَّهُ تَعَالَى فِيهِ بِذَلِكَ، قَالَ اللَّهُ تَعَالَى : {وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا} وَلَيْسَ الَّذِي ذُكِرَ مِمَّا خُلِّفْنَا تَخَلُّفَنَا عَنِ الغَزْوِ، وَإِنَّمَا هُوَ تَخْلِيفُهُ إِيَّانَا وَإِرْجَاؤُهُ أَمْرَنَا عَمَّنْ حَلَفَ لَهُ وَاعْتَذَرَ إِلَيْهِ فَقَبِلَ مِنْهُ. مُتَّفَقٌ عَلَيْهِ. وَفِى رِوَايَةٍ "أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ فِي غَزْوَةِ تَبُوكَ يَوْمَ الخَمِيسِ، وَكَانَ يُحِبُّ أَنْ يَخْرُجَ يَوْمَ الخَمِيسِ" وَفِى رِوَايَةٍ: "وَكَانَ لَا يَقْدَمُ مِنْ سَفَرٍ إِلَّا نَهَارًا فِي الضُّحَى، فَإِذَا قَدِمَ بَدَأَ بِالمَسْجِدِ فَصَلَّى فِيهِ رَكْعَتَيْنِ ثُمَّ جَلَسَ فِيهِ" .', updated_at = now() where id = 20021;
update hadith set arabic = 'عَنْ أَبِي نُجَيد- ضَمِّ النُّونِ وَفَتْحِ الجِيمِ - عِمْرَانَ بْنِ الحُصَيْنِ الخُزَاعِى رَضِيَ اللَّهُ عَنْهُمَا أَنَّ امْرَأَةً مِنْ جُهَيْنَةَ أَتَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِىَ حُبْلَى مِنَ الزِّنَى، فَقَالَتْ: يَا رَسُولَ اللَّهِ أصبتُ حدًّا فَأَقِمْهُ عليَّ، فَدَعَا نبيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلِيَّهَا فَقَالَ: أَحْسِنْ إِلَيْهَا، فَإِذَا وَضَعَتْ فَأْتِنِي، فَفَعَلَ فَأَمَرَ بِهَا نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَشُدَّتْ عَلَيْهَا ثِيَابُهَا، ثُمَّ أَمَرَ بِهَا فَرُجِمَتْ، ثُمَّ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ وَسَلَّمَ عَلَيْهَا. فَقَالَ لَهُ عُمَرُ: تُصَلِّى عَلَيْهَا يَا رَسُولَ اللَّهِ وَقَدْ زَنَتْ، قَالَ: لَقَدْ تَابَتْ تَوْبَةً لَوْ قُمِسَتْ بَيْنَ سَبْعِينَ مِنْ أَهْلِ المَدِينَةِ لَوَسِتْعَتْهُمْ، وَهَلْ وَجَدَتْ أَفْضَلَ مِنْ أَنْ جَادَتْ بِنَفْسِهَا لِلَّهِ عَزَّ وَجَلَّ ؟! " رَوَاهُ مُسْلِمٌ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3380 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20022;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « لَوْ أَنَّ لِابْنِ آدَمَ وَادِياً مِنْ ذَهَبٍ أَحَبَّ أَنْ يَكُونَ لَهُ وَادِيَانِ، وَلَنْ يَمْلَأَ فَاهُ إِلَّا التُّرَابُ، وَيَتُوبُ اللَّهُ عَلَى مَنْ تَابَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20023;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «يضحكُ اللهُ سُبْحَانَهُ وَتَعَالَى إِلَى رَجُلَيْنِ يقتلُ أحدُهما الآخرَ يدخلانِ الجنةَ، يقاتلُ هَذَا فِي سَبِيلِ اللَّهِ فيُقْتَلُ، ثُمَّ يتوبُ اللهُ عَلَى القاتلِ فيُسْلِمُ فَيُسْتَشْهَدُ».', updated_at = now() where id = 20024;
update hadith set arabic = 'عَنْ أَبِي مالكٍ الحَارِثِ بْنِ عَاصِمٍ الأشعريِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «الطُّهُورُ شَطْرُ الْإِيمَانِ، وَالْحَمْدُ لِلهِ تَمْلَأُ الْمِيزَانَ، وَسُبْحَانَ اللهِ وَالْحَمْدُ لِلهِ تَمْلَآنِ -أَوْ تَمْلَأُ- مَا بَيْنَ السَّمَاوَاتِ وَالْأَرْضِ، وَالصَّلَاةُ نُورٌ، وَالصَّدَقَةُ بُرْهَانٌ، وَالصَّبْرُ ضِيَاءٌ، وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ. كُلُّ النَّاسِ يَغْدُو، فَبَائِعٌ نَفْسَهُ فَمُعْتِقُهَا، أَوْ مُوبِقُهَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65004 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20025;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ سَعْدِ بْنِ مَالِكِ بْنِ سِنَانٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُمَا: "أنَّ ناسًا مِنَ الأنصارِ سألوا رسولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَعْطَاهُمْ، ثُمَّ سَأَلُوهُ فَأَعْطَاهُمْ ، حَتَّى نَفِدَ مَا عِنْدَهُ، فَقَالَ لَهُمْ حِينَ أنفقَ كلَّ شيءٍ بِيَدِهِ : "ما يَكُنْ عندي مِن خيرٍ فَلَنْ أَدَّخِرَهُ عَنْكُم ، ومَنْ يَسْتَعْفِفْ يُعِفِّهُ اللهُ، ومَنْ يَسْتَغْنِ يُغْنِهِ اللهُ، ومَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللهُ. وَمَا أُعْطِيَ أَحَدٌ عطاءً خَيرًا وأَوسع مِنَ الصبرِ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4967 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20026;
update hadith set arabic = 'عَنْ أَبِي يَحْيَى صُهَيْبٍ بْنِ سِنَانٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ «عَجَبًا لِأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ لَهُ خَيْرٌ، وَلَيْسَ ذَلِكَ لِأَحَدٍ إِلَّا لِلْمُؤْمِنِ : إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ، وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3298 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20027;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لمَّا ثَقُلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَعَلَ يَتَغَشَّاهُ الكَرْبُ فَقَالَتْ فَاطِمَةُ رَضِيَ اللَّهُ عَنْهَا: واكَرْبَ أَبَتَاه. فَقَالَ : «لَيسَ عَلَى أَبِيكِ كَرْبٌ بَعْدَ اليَوْمِ» فَلَمَّا مَاتَ قَالَتْ : يَا أَبَتَاه أجابَ ربًّا دَعَاه، يَا أبَتَاه جَنَّةُ الفِردَوسِ مَأوَاه، يَا أَبَتَاه إِلَى جِبْرِيلَ نَنعَاه، فلمَّا دُفِنَ قَالَتْ : فَاطِمَةُ رَضِيَ اللَّهُ عَنْهَا: أَطَابَت أَنفُسُكُم أَن تَحثُوا عَلَى رسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ التُّرابَ؟.', updated_at = now() where id = 20028;
update hadith set arabic = 'عَنْ أَبِي زَيْدٍ أُسَامَةَ بْنِ زَيْدِ بْنِ حَارِثَةَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَحِبِّهِ وَابْنِ حِبِّهِ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: أَرْسَلَتْ بِنْتُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إنَّ ابْنِي قَدِ احتُضِرَ فاشْهَدنَا، فأرسَلَ يُقْرِئُ السَّلامَ وَيَقُولُ: "إنَّ لِلَّهِ مَا أَخَذَ، ولَهُ مَا أَعطَى، وكلُّ شَيءٍ عِنْدَهُ بِأجَلٍ مُسمًّى، فَلتَصبِرْ ولتَحتَسِبْ" فَأَرْسَلَتْ إِلَيْهِ تُقسِمُ عَلَيْهِ لَيَأتِيَنَّها. فَقَامَ وَمَعَهُ سَعْدُ بْنُ عُبَادَةَ، وَمُعَاذُ بْنُ جَبَلٍ، وَأُبَيُّ بْنُ كَعْبٍ، وَزَيْدُ بْنُ ثَابِتٍ، وَرِجَالٌ رَضِيَ اللَّهُ عَنْهُمْ، فَرُفِعَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّبِيُّ فأَقعَدَهُ فِي حِجرِهِ ونَفسُهُ تَقَعقَعُ، فَفَاضَتْ عينَاهُ، فَقَالَ سَعْدٌ: يَا رَسُولَ اللَّهِ مَاهَذَا؟ فَقَالَ: "هَذِهِ رَحمَةٌ جَعلَهَا اللَّهُ تَعَالَى فِي قُلُوبِ عِبادِهِ" وَفِى رِوَايَةٍ : "فِي قُلُوبِ مَنْ شَاءَ مِنْ عِبَادِهِ وَإنَّمَا يَرحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَماءَ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3290 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20029;
update hadith set arabic = 'عَنْ صُهَيْبٍ رَضيَ اللهُ عنه أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « كَانَ مَلِكٌ فِيمَنْ كَانَ قَبْلَكُمْ، وَكَانَ لَهُ سَاحِرٌ، فَلَمَّا كَبِرَ قَالَ لِلْمَلِكِ : إِنِّي قَدْ كَبِرْتُ فَابْعَثْ إِلَىَّ غُلَامًا أُعَلِّمْهُ السِّحْرَ؛ فَبَعَثَ إِلَيْهِ غُلَامًا يُعَلِّمُهُ، وَكَانَ فِي طَرِيقِهِ إِذَا سَلَكَ رَاهِبٌ، فَقَعَدَ إِلَيْهِ وَسَمِعَ كَلَامَهُ فَأَعْجَبَهُ، وَكَانَ إِذَا أَتَى السَّاحِرَ مَرَّ بِالرَّاهِبِ وَقَعَدَ إِلَيْهِ، فَإِذَا أَتَى السَّاحِرَ ضَرَبَهُ، فَشَكَا ذَلِكَ إِلَى الرَّاهِبِ فَقَالَ: إِذَا خَشِيتَ السَّاحِرَ فَقَالَ: حَبَسَنِي أَهْلِي، وَإِذَا خَشِيتَ أَهْلَكَ فَقُلْ: حَبَسَنِي السَّاحِرُ. فَبَيْنَمَا هُوَ عَلَى ذَلِكَ إِذْ أَتَى عَلَى دَابَّةٍ عَظِيمَةٍ قَدْ حَبَسَتِ النَّاسَ فَقَالَ: الْيَوْمَ أَعْلَمُ آلسَّاحِرُ أَفْضَلُ أَمِ الرَّاهِبُ أَفْضَلُ؟ فَآخذَ حَجَرًا فَقَالَ: اللهُمَّ إِنْ كَانَ أَمْرُ الرَّاهِبِ أَحَبَّ إِلَيْكَ مِنْ أَمْرِ السَّاحِرِ فَاقْتُلْ هَذِهِ الدَّابَّةَ حَتَّى يَمْضِيَ النَّاسُ، فَرَمَاهَا فَقَتَلَهَا وَمَضَى النَّاسُ، فَأَتَى الرَّاهِبَ فَأَخْبَرَهُ. فَقَالَ لَهُ الرَّاهِبُ: أَيْ بُنَيَّ أَنْتَ الْيَوْمَ أَفْضَلُ مِنِّي، قَدْ بَلَغَ أَمْرِكَ مَا أَرَى، وَإِنَّكَ سَتُبْتَلَى، فَإِنِ ابْتُلِيتَ فَلَا تَدُلَّ عَلَيَّ؛ وَكَانَ الْغُلَامُ يُبْرِئُ الْأَكْمَهَ وَالْأَبْرَصَ، وَيُدَاوِي النَّاسَ مِنْ سَائِرِ الْأَدْوَاءِ. فَسَمِعَ جَلِيسٌ لِلْمَلِكِ كَانَ قَدْ عَمِيَ، فَأَتَاهُ بِهَدَايَا كَثِيرَةٍ فَقَالَ: مَا هَاهُنَا لَكَ أَجْمَعُ إِنْ أَنْتَ شَفَيْتَنِى، فَقَالَ: إِنِّي لَا أَشْفِي أَحَدًا إِنَّمَا يَشْفِى اللهُ تَعَالَى، فَإِنْ آمَنْتَ بِاللهِ دَعَوْتُ اللهَ فَشَفَاكَ، فَآمَنَ بِاللهِ تَعَالَى فَشَفَاهُ اللهُ تَعَالَى، فَأَتَى الْمَلِكَ فَجَلَسَ إِلَيْهِ كَمَا كَانَ يَجْلِسُ فَقَالَ لَهُ الْمَلِكُ: مَنْ رَدَّ عَلَيْكَ بَصَرَكَ؟ فَقَالَ: رَبِّي قَالَ: وَلَكَ رَبٌّ غَيْرِي ؟( قَالَ: رَبِّي وَرَبُّكَ اللهُ، فَأَخَذَهُ فَلَمْ يَزَلْ يُعَذِّبُهُ حَتَّى دَلَّ عَلَى الْغُلَامِ، فَجِئَ بِالْغُلَامِ فَقَالَ لَهُ الْمَلِكُ: أَىْ بُنَيَّ قَدْ بَلَغَ مِنْ سِحْرِكَ مَا تُبْرِئُ الْأَكْمَهَ وَالْأَبْرَصَ وَتَفْعَلُ وَتَفْعَلُ فَقَالَ: إِنِّي لَا أَشْفِي أَحَدًا، إِنَّمَا يَشْفِي اللهُ تَعَالَى، فَأَخَذَهُ فَلَمْ يَزَلْ يُعَذِّبُهُ حَتَّى دَلَّ عَلَى الرَّاهِبِ؛ فَجِيءَ بِالرَّاهِبِ فَقِيلَ لَهُ: ارْجِعْ عَنْ دِينِكَ، فَأَبَى ، فَدَعَا بِالْمِنْشَارِ فَوَضَعَ الْمِنْشَارَ فِي مَفْرِقِ رَأْسِهِ، فَشَقَّهُ حَتَّى وَقَعَ شِقَّاهُ، ثُمَّ جِيءَ بِجَلِيسِ الْمَلِكِ فَقِيلَ لَهُ: ارْجِعْ عَنْ دِينِكَ فَأَبَى، فَوَضَعَ الْمِنْشَارَ فِي مَفْرِقِ رَأْسِهِ، فَشَقَّهُ بِهِ حَتَّى وَقَعَ شِقَّاهُ، ثُمَّ جِيءَ بِالْغُلَامِ فَقِيلَ لَهُ ارْجِعْ عَنْ دِينِكَ فَأَبَى، فَدَفَعَهُ إِلَى نَفَرٍ مِنْ أَصْحَابِهِ فَقَالَ: اذْهَبُوا بِهِ إِلَى جَبَلِ كَذَا وَكَذَا فَاصْعَدُوا بِهِ الْجَبَلَ فَقَالَ: اللهُمَّ اكْفِنِيهِمْ بِمَا شِئْتَ، فَرَجَفَ بِهِمِ الْجَبَلُ فَسَقَطُوا، وَجَاءَ يَمْشِي إِلَى الْمَلِكِ، فَقَالَ لَهُ الْمَلِكُ: مَا فَعَلَ أَصْحَابُكَ؟ فَقَالَ: كَفَانِيهِمُ اللهُ تَعَالَى، فَدَفَعَهُ إِلَى نَفَرٍ مِنْ أَصْحَابِهِ فَقَالَ : اذْهَبُوا بِهِ فَاحْمِلُوهُ فِي قُرْقُورٍ وَتَوَسَّطُوا بِهِ الْبَحْرَ، فَإِنْ رَجَعَ عَنْ دِينِهِ وَإِلَّا فَاقْذِفُوهُ، فَذَهَبُوا بِهِ فَقَالَ: اللهُمَّ اكْفِنِيهِمْ بِمَا شِئْتَ، فَانْكَفَأَتْ بِهِمِ السَّفِينَةُ فَغَرِقُوا، وَجَاءَ يَمْشِي إِلَى الْمَلِكِ. فَقَالَ لَهُ الْمَلِكُ : مَا فَعَلَ أَصْحَابُكَ؟ فَقَالَ: كَفَانِيهِمُ اللهُ تَعَالَى. فَقَالَ الْمَلِكُ إِنَّكَ لَسْتَ بِقَاتِلِي حَتَّى تَفْعَلَ مَا آمُرُكَ بِهِ. قَالَ : مَا هُوَ؟ قَالَ : تَجْمَعُ النَّاسَ فِي صَعِيدٍ وَاحِدٍ، وَتَصْلُبُنِي عَلَى جِذْعٍ ، ثُمَّ خُذْ سَهْمًا مِنْ كِنَانَتِي، ثُمَّ ضَعِ السَّهْمَ فِي كَبِدِ الْقَوْسِ ثُمَّ قُلْ: بِسْمِ اللهِ رَبِّ الْغُلَامِ ثُمَّ ارْمِنِي، فَإِنَّكَ إِنْ فَعَلْتَ ذَلِكَ قَتَلْتَنِي . فَجَمَعَ النَّاسَ فِي صَعِيدٍ وَاحِدٍ، وَصَلَبَهُ عَلَى جِذْعٍ، ثُمَّ أَخَذَ سَهْمًا مِنْ كِنَانَتِهِ، ثُمَّ وَضَعَ السَّهْمَ فِي كَبْدِ الْقَوْسِ، ثُمَّ قَالَ: بِسْمِ اللهِ رَبِّ الْغُلَامِ، ثُمَّ رَمَاهُ فَوَقَعَ السَّهْمُ فِي صُدْغِهِ، فَوَضَعَ يَدَهُ فِي صُدْغِهِ فَمَاتَ. فَقَالَ النَّاسُ آمَنَّا بِرَبِّ الْغُلَامِ، فَأُتِىَ الْمَلِكُ فَقِيلَ لَهُ: أَرَأَيْتَ مَا كُنْتَ تَحْذَرُ قَدْ وَاللهِ نَزَلَ بِكَ حَذَرُكَ. قَدْ آمَنَ النَّاسُ. فَأَمَرَ بِالْأُخْدُودِ بِأَفْوَاهِ السِّكَكِ فَخُدَّتْ وَأَضْرَمَ فِيهَا النِّيرَانَ وَقَالَ: مَنْ لَمْ يَرْجِعْ عَنْ دِينِهِ فَأَقْحِمُوهُ فِيهَا أَوْ قِيلَ لَهُ : اقْتَحِمْ ، فَفَعَلُوا حَتَّى جَاءَتِ امْرَأَةٌ وَمَعَهَا صَبِىٌّ لَهَا، فَتَقَاعَسَتْ انْ تَقَعَ فِيهَا، فَقَالَ لَهَا الْغُلَامُ: يَا أُمَّاهْ اصْبِرِي فَإِنَّكِ عَلَى الْحَقِّ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3303 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20030;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بامرَأَةٍ تَبكِي عِنْدَ قَبرٍ فَقَالَ : "اتَّقِي اللَّهَ واصْبِري" فَقَالَتْ : إِلَيْكَ عَنِّي ، فَإِنَّكَ لَمْ تُصَبْ بِمُصِيبَتِي ( وَلَمْ تَعرِفْهُ، فقِيلَ لَهَا : إِنَّهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَأَتَتْ بَابَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ تَجِدْ عِنْدَهُ بوَّابِينَ، فَقَالَتْ: لَمْ أَعرِفكَ، فَقَالَ: "إِنَّما الصَّبرُ عِندَ الصَّدمَةِ الأُولَى".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3295 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20031;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ : « يَقُولُ اللَّهُ تَعَالَى : مَا لِعَبدِي المُؤمِنِ عِندِي جَزَاءٌ إِذَا قَبَضتُ صَفِيَّهُ مِنْ أَهلِ الدُّنيَا ثُمَّ احْتَسَبَهُ إِلاَّ الجنَّةُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3162 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20032;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّها سَأَلَت رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الطَّاعُونِ، فَأَخبَرَها أَنَّهُ كَانَ عَذَابًا يَبعَثُهُ اللَّهُ تَعَالَى عَلَى مَنْ يَشَاءُ، فَجَعَلَهُ اللَّهُ تَعَالَى رحمَةً لِلْمُؤْمِنِينَ، فَلَيْسَ مِنْ عبدٍ يَقَعُ فِي الطَّاعُونِ فَيَمكُثُ فِي بَلَدِهِ صَابِرًا مُحتَسِبًا يعلَمُ أَنَّهُ لَا يُصِيبُهُ إِلاَّ مَا كتَبَ اللَّهُ لَهُ إِلَّا كَانَ لَهُ مِثلُ أجرِ الشَّهيدِ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3161 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20033;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ : «إِنَّ لِلَّهِ عَزَّوَجَلَّ قَالَ: إِذَا ابْتَلَيْتُ عَبْدِي بِحَبِيبَتَيْهِ فَصَبَرَ عَوَّضْتُهُ مِنْهُمَا الجَنَّةَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20034;
update hadith set arabic = 'عَنْ عَطَاءِ بْنِ أَبِي رَبَاحٍ قَالَ: قَالَ لِي ابْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَلَا أُرِيكَ امْرَأَةً مِنْ أَهْلِ الجَنَّةِ " فَقُلْتُ: بَلَى، قَالَ: هَذِهِ المَرْأَةُ السَّوْدَاءُ أَتَتت النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ : إِنِّي أُصْرَعُ، وَ إِنِّي أَتَكَشَّفُ، فَادْعُ اللَّهَ تَعَالَى لِي قَالَ: "إِنْ شِئْتِ صَبَرْتِ وَلَكِ الجَنَّةُ، وَإِنْ شِئْتِ دَعَوْتُ اللَّهَ تَعَالَى أَنْ يُعَافِيَكِ" فَقَالَتْ: أَصْبِرُ، فَقَالَتْ: إِنِّي أَتَكَشَّفُ ، فَادْعُ اللَّهَ أَنْ لَا أَتَشَكَّفَ ، فَدَعَا لَهَا.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20035;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَأَنِّي انْظُرُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْكِي نَبِيًّا مِنَ الأَنْبِيَاءِ، صَلَوَاتُ اللَّهِ وَسَلَامُهُ عَلَيْهِمْ، ضَرَبَهُ قَوْمُهُ فَأَدْمَوْهُ وَهُوَ يمَسحُ الدَمَ عَنْ وجهِهِ، يَقُولُ : «اللَّهُمَّ اغْفِرْ لِقَوْمِى فَإِنَّهُمْ لَا يَعْلَمُونَ».', updated_at = now() where id = 20036;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ وأبي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلَا وَصَبٍ وَلَا هَمٍّ وَلَا حُزْنٍ وَلَا أَذًى وَلَا غَمٍّ، حَتَّى الشَّوْكَةِ يُشَاكُهَا إِلَّا كَفَّرَ اللهُ بِهَا مِنْ خَطَايَاهُ» ((مُتَّفَقٌ عَلَيْهِ)) . ''وَ الوَصَبُ '': المَرَضُ .', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3701 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20037;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُوعَكُ فَقُلْتُ: يَارَسُولَ اللَّهِ إِنَّكَ تُوعَكُ وَعْكاً شَدِيداً قَالَ: "أَجَلْ إِنِّي أُوعَكُ كَمَا يُوعَكُ رَجُلَانِ مِنْكُمْ" قُلْتُ: ذَلِكَ أَنَّ لَكَ أَجْرَيْنِ ؟ قَالَ: "أَجَلْ ذَلِكَ كَذَلِكَ مَا مِنْ مُسْلِمٍ يُصِيبُهُ أَذًى؛ شَوْكَةٌ فَمَا فَوْقَهَا إِلَّا كَفَّرَ اللَّهُ بِهَا سَيِّئَاتِهِ ، وَحُطَّتْ عَنْهُ ذُنُوبُهُ كَمَا تَحُطُّ الشَّجَرَةُ وَرَقَهَا".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20038;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ « مَنْ يُرِدِ اللهُ بِهِ خَيْرًا يُصِبْ مِنْهُ» :.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4204 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20039;
update hadith set arabic = 'عَنْ أَنَسِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : « لاَ يَتَمَنَّيَنَّ أَحَدُكُمُ المَوْتَ لِضُرٍّ أَصَابَهُ، فَإِنْ كَانَ لابُدَّ فَاعِلًا فَلْيَقُلْ: اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الحَيَاةُ خَيْرًا لِي وَتَوَفَّنِي إِذَا كَانَتِ الوَفَاةُ خَيْرًا لِي».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20040;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ اللَّهِ خَبَّابِ بْنِ الأَرَتِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: شَكَوْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُتَوَسِّدٌ بُرْدَةً لَهُ فِي ظِلِّ الكَعْبَةِ، فَقُلْنَا : أَلاَ تَسْتَنْصِرُ لَنَا أَلَا تَدْعُو لَنَا؟ فَقَالَ: قَدْ كَانَ مَنْ قَبْلَكُمْ يُؤخذُ الرَّجُلُ فيُحفرُ لَهُ فِي الأَرْضِ فيُجعلُ فِيهَا ثمَّ يُؤتى بالمِنْشَارِ فَيُوضَعُ عَلَى رَأْسِهِ فيُجعلُ نِصْفَيْنِ، ويُمشطُ بأمشاطِ مِنَ الحَدِيدِ مَا دُونَ لَحْمِهِ وَعَظْمِهِ، مَا يَصُدُّهُ ذَلِكَ عَنْ دِينِهِ، وَاللَّهِ لَيُتِمَّنَّ اللَّهُ هَذَا الأَمْرَ حَتَّى يَسِيرَ الرَّاكِبُ مِنْ صَنْعَاءَ إِلَى حَضْرَمَوْتَ لَا يَخَافُ إِلَّا اللَّهَ وَالذِّئْبَ عَلَى غَنَمِه، وَلَكِنَّكُمْ تَسْتَعْجِلُونَ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4246 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20041;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ : لَمَّا كَانَ يَوْمُ حُنين آثَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَاسًا فِي القِسْمَةِ، فَأَعْطَى الأَقْرَعَ بْنَ حَابِسٍ مِائَةً مِنَ الإِبِلِ، وَأَعْطَى عُيينةَ بْنَ حِصنٍ مِثْلَ ذَلِكَ، وَأَعْطَى نَاسًا مِنْ أَشْرَافِ العَرَبِ وآثَرَهُم يَوْمَئِذٍ فِي القِسْمَةِ. فَقَالَ رَجُلٌ: وَاللَّهِ إِنَّ هَذِهِ قِسْمَةٌ مَا عُدِلَ فِيهَا، وَمَا أُريدَ فِيهَا وَجْهُ اللَّهِ، فَقُلْتُ : وَاللَّهِ لَأُخبرنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَأَتَيْتُهُ فَأَخْبَرْتُهُ بِمَا قَالَ: فَتَغَيَّرَ وجههه حَتَّى كَانَ كَالصِّرفِ . ثُمَّ قَالَ « فَمَنْ يَعْدِلُ إِذَا لَمْ يَعْدِلِ اللَّهُ وَرَسُولُهُ؟ ثُمَّ قَالَ: يَرحمُ اللَّهُ مُوسَى قَدْ أُوذِيَ بِأَكْثَرَ مِنْ هَذَا فَصَبَرَ». فَقُلْتُ: لَا جَرمَ لَا أَرْفَعُ إِلَيْهِ بَعْدَهَا حَدِيثًا.', updated_at = now() where id = 20042;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :"إِذَا أَرَادَ اللَّهُ بِعَبْدِهِ خَيْراً عَجَّلَ لَهُ العُقُوبَةَ فِي الدُّنْيَا، وَإِذَا أَرَادَ اللَّهُ بِعَبْدِهِ الشَّرَّ أَمْسَكَ عَنْهُ بِذَنْبِهِ حَتَّى يُوَافِيَ بِهِ يَوْمَ القِيَامَةِ". وَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "إِنَّ عِظَمَ الجزاءِ مَعَ عِظَمِ البلاءِ، وَإِنَّ اللَّهَ تَعَالَى إِذَا أَحَبَّ قَوْمًا ابْتَلَاهُمْ، فَمَنْ رَضِيَ فَلَهُ الرِّضَى، وَمَنْ سَخِطَ فَلَهُ السُّخْطُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3339 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20043;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ ابْنٌ لِأَبِي طَلْحَةَ رَضِيَ اللَّهُ عَنْهُ يَشْتَكِي، فَخَرَجَ أَبُو طَلْحَةَ، فَقُبِضَ الصَّبِيُّ، فَلَمَّا رَجَعَ أَبُو طَلْحَةَ قَالَ: مَا فَعَلَ ابْنِي؟ قَالَتْ أُمُّ سُلَيْمٍ وَهِىَ أُمُّ الصَّبِيِّ : هُوَ أسْكَنُ مَا كَانَ، فَقَرَّبَت إِلَيْهِ العَشَاءَ فتَعَشَّى، ثُمَّ أَصَابَ مِنْهَا، فَلَمَّا فَرَغَ قَالَتْ: وارُوا الصَّبِيَّ، فَلَمَّا أَصْبَحَ أَبُو طَلْحَةَ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ، فَقَالَ: "أعَرَّسْتُمُ اللَّيلَةَ ؟" قَالَ: نَعَمْ ، قَالَ: "اللَّهُمَّ بارِكْ لَهُمَا، فَوَلَدَتْ غُلَامًا، فَقَالَ لِي أَبُو طَلْحَةَ: احْمِلْهُ حَتَّى تَأْتِى بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَبَعَثَ مَعَهُ بِتَمَرَاتٍ، فَقَالَ: "أمَعَهُ شَيْءٌ؟" قَالَ: نَعَمْ، تَمَرَاتٌ فَأَخَذَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فمَضَغَها ، ثُمَّ أَخَذَهَا مِنْ فِيهِ فَجَعَلَهَا فِي فِيِّ الصَّبِيِّ ، ثُمَّ حَنَّكَهُ وَسَمَّاهُ عَبْدَ اللَّهِ. ((مُتَّفَقٌ عَلَيْهِ)) . وَفِى رِوَايَةٍ لِمُسْلِمٍ: مَاتَ ابْنٌ لِأَبِي طَلْحَةَ بْنِ أُمِّ سُلَيْمٍ ، فَقَالَتْ لِأَهْلِهَا لَا تُحَدِّثوا أَبَا طَلْحَةَ بابْنِهِ حَتَّى أَكُونَ أَنَا أُحدِّثُهُ، فَجَاءَ فَقَرَّبَتْ إِلَيْهِ عَشَاءً فأكَلَ وَشَرِبَ، ثُمَّ تَصَنَّعَتْ لَهُ أحْسَنَ مَا كَانَتْ تَصْنَعُ قَبْلَ ذَلِكَ، فَوَقَعَ بِهَا، فلمَّا أَنْ رَأَتْ أَنَّهُ قَدْ شَبِعَ وَأَصَابَ مِنْهَا قَالَتْ: يَا أَبَا طَلْحَةَ، أَرَأَيْتَ لَوْ أَنَّ قَوْمًا أعَارُوا عَارِيَتَهُم أَهْلَ بَيْتٍ فطَلَبوا عَارِيَتَهُم، أَلَهُمْ أَنْ يَمْنَعُوهُم؟ قَالَ: لَا، فَقَالَتْ : فَاحْتَسِبْ ابْنَكَ. قَالَ: فغضِبَ، ثُمَّ قَالَ: تَرَكْتِني حَتَّى إِذَا تَلطَّخْتُ أَخْبَرْتِنِي بِابْنِي؟! فَانْطَلَقَ حَتَّى أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ بِمَا كَانَ ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. "بَارَكَ اللَّهُ فِي لَيْلَتِكُمَا" قَالَ: فَحَمَلَتْ، قَالَ وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ وَهِيَ مَعَهُ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَتَى المَدِينَةَ مِنْ سَفَرٍ لَا يَطْرُقُهَا طُرُوقًا فَدَنَوا مِنَ المَدِينَةِ، فضَرَبَها المَخَاضُ، فَاحْتَبَسَ عَلَيْهَا أَبُو طَلْحَةَ، وَانْطَلَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَقُولُ أَبُو طَلْحَةَ: إِنَّكَ لَتَعْلَمُ يَارَبِّ أَنَّهُ يُعْجِبُنِي أَنْ أَخْرُجَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ، وَأَدْخُلَ مَعَهُ إِذَا دَخَلَ، وَقَدِ احْتَبَسْتُ بِمَا تَرَى، تَقُولُ أُمُّ سُلَيْمٍ: يَا أَبَا طَلْحَةَ مَا أجِدُ الَّذِى كُنْتُ أجِدُ، انْطَلِقْ، فَانْطَلَقْنَا، وَضَرَبَهَا المَخَاضُ حِينَ قَدِمَا فَوَلَدَتْ غُلَامًا. فَقَالَتْ لِي أُمِّي : يَا أَنَسُ لَا يُرْضِعْهُ أحدٌ حَتَّى تَغْدُوَ بِهِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فلمَّا أَصْبَحَ احتَمَلْتُهُ فانْطَلَقتُ بِهِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَذَكَرَ تَمَامَ الحَدِيثِ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6612 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20044;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِى يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5351 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20045;
update hadith set arabic = 'عَنْ سُلَيْمَانَ بْنِ صُرَدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ جَالِسًا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَرَجُلاَنِ يَسْتَبَّانِ، وَأَحَدُهُمَا قَدِ احْمَرَّ وَجْهُهُ، وَانْتَفَخَتْ أَوْدَاجُهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: " إِنِّي لَأَعْلَمُ كَلِمَةً لَوْ قَالَهَا لَذَهَبَ عَنْهُ مَا يَجِدُ، لَوْ قَالَ: أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ذَهَبَ مِنْهُ مَا يَجِدُ". فَقَالَ لَهُ: إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: " تَعَوَّذْ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20046;
update hadith set arabic = 'عَنْ مُعَاذِ بْنِ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « مَن كَظَمَ غَيظًا ، وَهُوَ قَادِرٌ عَلَى أَنْ يُنفِذَهُ، دَعَاهُ اللَّهُ سُبْحَانَهُ وَتَعَالَى عَلَى رُؤُوسِ الخَلاَئِقِ يَوْمَ القِيَامَةِ حتَّى يُخَيِّرَهُ مِنَ الحُورِ العَينِ مَا شَاءَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3287 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20047;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ ، أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَوْصِنِي، قَالَ: "لَا تَغْضَبْ" فَرَدَّدَ مِرَارًا، قَالَ: " لاتَغْضَبْ" رَوَاهُ البُخَارِيُّ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4709 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20048;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « مَا يَزَالُ البَلاَءُ بِالمُؤْمِنِ وَالمُؤْمِنَةِ فِي نَفْسِهِ وَوَلَدِهِ ة وَمَالِهِ حَتَّى يَلْقَى اللَّهَ تَعَالَى وَمَا عَلَيْهِ خَطِيئَةٌ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20049;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَدِمَ عُيَينَةُ بْنُ حِصنٍ فَنزَلَ عَلَى ابنِ أَخِيهِ الحُرِّ بْنِ قَيسٍ، وَكَانَ مِنَ النَّفَرِ الَّذِينَ يُدنِيهِم عُمَرُ رَضِيَ اللَّهُ عَنْهُ، وَكَانَ القُرَّاءُ أَصْحَابَ مَجلِسِ عُمرَ رَضِيَ اللَّهُ عَنْهُ ومُشاوَرَتِهِ كُهُولا كَانُوا أَوْ شُبَّانًا، فَقَالَ عُيَيْنَةُ لِابْنِ أَخِيهِ : يَا ابْنَ أَخِي لَكَ وَجْهٌ عِنْدَ هَذَا الأَمِيرِ فَاسْتَأذِنْ لِي عَلَيْهِ، فَاسْتَأذَنَ فَأَذِنَ عُمرُ. فَلَمَّا دَخَلَ قَالَ: هِىْ يَا ابْنَ الخطَّابِ، فَوَاللَّهِ مَا تُعطِينَا الجَزْلَ وَلَا تَحكُمُ فِينَا بِالعَدلِ، فَغَضِبَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ حَتَّى هَمَّ أَنْ يُوقِعَ بِهِ، فَقَالَ لَهُ الحُرُّ: يَا أَمِيرَ المُؤْمِنِينَ إنَّ اللَّهَ تَعَالَى قَالَ لِنَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {خُذِ الْعَفْوَ وَأْمُرْ بِالْعُرْفِ وَأَعْرِضْ عَنِ الْجَاهِلِينَ}.', updated_at = now() where id = 20050;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « إِنَّهَا سَتَكُونُ بَعْدِي أَثَرَةٌ وَأُمُورٌ تُنْكِرُونَهَا ! قَالُوا: يَا رَسُولَ اللَّهِ فَمَا تَأْمُرُنَا؟ قَالَ: تُؤَدُّونَ الحَقَّ الَّذِى عَلَيْكُمْ ، وَتَسْأَلُونَ اللَّهَ الَّذِى لَكُمْ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3156 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20051;
update hadith set arabic = 'عَنْ أَبِي يَحْيَى أُسَيْدِ بْنِ حُضَيْرٍ رَضِيَ اللَّهُ عَنْهُ أنَّ رجُلاً مِنَ الأَنْصَارِ قَالَ: يَا رَسُولَ اللَّهِ ألاَ تَستَعمِلُنِي كَمَا استَعمَلتَ فُلانًا فَقَالَ: «إِنَّكُم سَتَلقَونَ بَعدِي أَثَرَةً، فَاصبِرُوا حَتَّى تَلقَونِي عَلَى الحَوضِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3305 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20052;
update hadith set arabic = 'عَنْ أَبِي إِبْرَاهِيمَ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَيَّامِهِ الَّتِي لَقِيَ فِيهَا العَدُوَّ، انْتَظَرَ حَتَّى إِذَا مَالَتِ الشَّمْسُ قَامَ فِيهِم فَقَالَ: " يَا أَيُّها النَّاسُ لَا تَتَمَنَّوْا لِقَاءَ الْعَدُوِّ، وَاسْأَلوا اللَّهَ الْعافِيَةَ، فَإِذا لَقِيتُمُوهُمْ فَاصْبِرُوا، وَاعلَمُوا أَنَّ الْجَنَّةَ تَحْتَ ظِلالِ السُّيوفِ" ثُمَّ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : " اللهمَّ مُنزِلَ الْكتابِ وَمُجْرِيَ السَّحابِ ، وَهازِمَ الأَحْزابِ، اهْزِمْهُمْ وَانصُرْنا علَيهِم" ((مُتَّفَقٌ عَلَيْهِ)) وَبِاللَّهِ التَّوْفِيقُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/2953 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20053;
update hadith set arabic = 'فَالأَوَّلُ عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِنَّ الصِّدْقَ يَهْدِي إِلَى البِرِّ وَإِنَّ البِرَّ يَهْدِي إِلَى الجَنَّةِ، وَإِنَّ الرَّجُلَ لَيَصْدُقُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ صِدِّيقاً، وَإِنَّ الكَذِبَ يَهْدِي إِلَى الفُجُورِ، وَإِنَّ الفُجُورَ يَهْدِي إِلَى النَّارِ، وَإِنَّ الرَّجُلَ لَيَكْذِبُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّاباً».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20054;
update hadith set arabic = 'عَنْ أَبِي مُـحَمَّدٍ الحَسَنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ، رَضِيَ اللَّهُ عَنْهُمَا ، قَالَ : حَفِظْتُ مِنْ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «دَعْ مَا يَرِيبُك إلَى مَا لَا يَرِيبُكَ؛ فَإِنَّ الصِّدْقَ طُمَأْنِينَةٌ، وَالكَذِبَ رِيبَةٌ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66519 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20055;
update hadith set arabic = 'عَنْ أَبِي سُفْيَانَ صَخْرِ بْنِ حَرْبٍ ، رَضِيَ اللَّهُ عَنْهُ، فِي حَدِيثِهِ الطَّوِيلِ فِي قِصَّةِ هِرَقْلَ، قَالَ هِرَقلُ: فَمَاذَا يَأمُرُكُم -يَعْنِى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- قَالَ أَبُو سُفْيَانَ: قُلْتُ :يَقُولُ : « اعبدُوا اللَّهَ وَحدَهُ لاَ تُشرِكُوا بِهِ شَيئًا، وَاترُكُوا مَا يَقُولُ آبَاؤُكُم ، ويَأمُرُنَا بِالصَّلاَةِ، والصِّدقِ، والعَفَافِ، والصِّلَةِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3154 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20056;
update hadith set arabic = 'عَن أَبِي ثَابِتٍ، وَقِيلَ أَبِي سَعِيدٍ، وَقِيلَ أَبِي الوَلِيدِ، سَهْلِ بْنِ حُنَيْفٍ ، وَهُوَ بَدْرِيٌّ، رَضِيَ اللَّهُ عَنْهُ، أَنَّ النَّبِيَّ ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: «مَنْ سَأَلَ اللهَ، تَعَالَى، الشَّهَادَةَ بِصِدْقٍ بَلَّغَهُ اللهُ مَنَازِلَ الشُّهَدَاءِ، وَإِنْ مَاتَ عَلَى فِرَاشِهِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20057;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «غَزَا نَبِيٌّ مِنَ الأَنبِيَاءِ صَلَوَاتُ اللَّهِ وَسَلَامُهُ عَلَيْهِمْ فَقَالَ لِقَوْمِهِ: لاَ يَتبَعَنِّي رجُلٌ مَلَكَ بُضْعَ امرَأَةٍ. وَهُوَ يُرِيدُ أنْ يَبنِيَ بِهَا وَلَمَّا يَبْنِ بِهَا، وَلاَ أحَدٌ بَنَى بُيُوتًا لَمْ يَرفَعْ سُقُوفَهَا، ولاَ أَحَدٌ اشتَرَى غَنَمًا أَوْ خَلِفَاتٍ وَهُوَ يَنتظِرُ أَولاَدَها. فَغَزَا فَدَنَا مِنَ القَريَةِ صَلاةَ العَصرِ أَوْ قَرِيباً مِن ذَلِكَ، فَقَالَ لِلشَّمسِ: إِنَّكِ مَأمُورَةٌ وأَنَا مَأمُورٌ، اللَّهُمَّ احْبِسْهَا عَلَينَا، فَحُبِسَتْ حَتَّى فَتَحَ اللَّهُ عَلَيْهِ، فَجَمَعَ الغَنَائِمَ، فَجَائَتْ -يَعْنِي النَّارَ- لِتَأكُلَهَا فَلَمْ تَطعَمْها، فَقَالَ : إِنَّ فِيكُم غُلُولاً، فَليُبَايعنِي مِنْ كُلِّ قَبِيلَةٍ رَجُلٌ، فَلَزِقَتْ يَدُ رَجُلٍ بِيَدِهِ فَقَالَ: فِيكُمُ الغُلُولُ، فَلْتُبَايِعْنِي قَبِيلَتُكَ، فَلَزِقَتْ يَدُ رَجُلَيْنِ أَوْ ثَلَاثَةٍ بِيَدِهِ فَقَالَ: فِيكُمُ الغُلُولُ: فَجَاؤوا بِرَأسٍ مِثْلِ رَأْسِ بَقَرَةٍ مِنَ الذَّهَبِ، فَوَضَعَهَا فَجَاءَتِ النَّارُ فَأَكَلَتهَا، فَلَمْ تَحِلَّ الغَنَائِمُ لِأحَدٍ قَبلَنَا، ثُمَّ أَحَلَّ اللَّهُ لَنَا الغَنَائِمَ لَمَّا رَأَى ضَعفَنَا وَعَجزَنَا فَأَحَلَّهَا لَنَا».', updated_at = now() where id = 20058;
update hadith set arabic = 'عَن أَبِي خَالِدٍ حَكِيمِ بْنِ حِزَامٍ. رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : « البَيِّعَانِ بِالخِيَارِ مالَمْ يَتَفَرَّقَا، فَإِنْ صَدَقَا وَبَيَّنَا بُورِكَ لَهُمَا فِي بَيْعِهِمَا، وَإِنْ كَتَمَا وَكَذَبَا مُحِقَتْ بَرَكَةُ بَيْعِهِمَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66126 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20059;
update hadith set arabic = 'وَأَمَّا الأَحَادِيثُ ؛ فَالأَوَّلُ: عَنْ عُمَرَ بْنِ الخَطَّابِ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ « بَيْنَمَا نَحْنُ جُلُوسٌ عِنْدَ رَسُولِ اللهِ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ إِذْ طَلَعَ عينا رَجُلٌ شَدِيدُ بَيَاضِ الثِّيَابِ ، شَدِيدُ سَوَادِ الشَّعَرِ، لَا يُرَى عَلَيْهِ أَثَرُ السَّفَرِ، وَلَا يَعْرِفُهُ مِنَّا أَحَدٌ، حَتَّى جَلَسَ إِلَى النَّبِيِّ ،صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ، فَأَسْنَدَ رُكْبَتَيْهِ إِلَى رُكْبَتَيْهِ، وَوَضَعَ كَفَّيْهِ عَلَى فَخِذَيْهِ وَقَالَ: يَا مُحَمَّدُ أَخْبِرْنِي عَنِ الْإِسْلَامِ، فَقَالَ: رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: الْإِسْلَامُ أَنْ تَشْهَدَ أَنْ لَا إِلَهَ إِلَّا اللهُ ، وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ ، وَتَصُومَ رَمَضَانَ ، وَتَحُجَّ الْبَيْتَ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلًا. قَالَ صَدَقْتَ. فَعَجِبْنَا لَهُ يَسْأَلُهُ وَيُصَدِّقُهُ! قَالَ : فَأَخْبِرْنِي عَنِ الْإِيمَانِ. قَالَ أَنْ تُؤْمِنَ بِاللهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ وَرُسُلِهِ، وَالْيَوْمِ الْآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ. قَالَ صَدَقْتَ. قَالَ فَأَخْبِرْنِي عَنِ الْإِحْسَانِ . قَالَ أَنْ تَعْبُدَ اللهَ كَأَنَّكَ تَرَاهُ؛ فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ. قَالَ: فَأَخْبِرْنِي عَنِ السَّاعَةِ. قَالَ: مَا الْمَسْؤُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ. قَالَ : فَأَخْبِرْنِي عَنْ أَمَارَاتِهَا قَالَ: أَنْ تَلِدَ الْأَمَةُ رَبَّتَهَا، وَأَنْ تَرَى الْحُفَاةَ الْعُرَاةَ الْعَالَةَ رِعَاءَ الشَّاءِ يَتَطَالُونَ فِي الْبُنْيَانِ. ثُمَّ انْطَلَقَ، فَلَبِثْتُ مَلِيًّا، ثُمَّ قَالَ: يَا عُمَرُ أَتَدْرِي مَنِ السَّائِلُ؟ قُلْتُ: اللهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: فَإِنَّهُ جِبْرِيلُ أَتَاكُمْ يُعَلِّمُكُمْ أَمْرَ دِينِكُمْ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4563 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20060;
update hadith set arabic = 'عَنْ أَبِي ذَرٍّ جُنْدُبِ بْنِ جُنَادَةَ، وَأَبِي عَبْدِ الرَّحْمَنِ مُعَاذِ بْنِ جَبَلٍ، رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: « اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ وَأَتْبِعِ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا، وَخَالِقْ النَّاسَ بِخُلُقٍ حَسَنٍ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4302 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20061;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: " كُنْتُ خَلْفَ النَّبِيِّ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، يَوْمًا فَقَالَ: " يَا غُلَامُ إِنِّي أُعَلِّمُكَ كَلِمَاتٍ: "احْفَظِ اللهَ يَحْفَظْكَ، احْفَظِ اللهَ تَجِدْهُ تُجَاهَكَ، إِذَا سَأَلْتَ فَاسْأَلِ اللهَ ، وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللهِ، وَاعْلَمْ: أَنَّ الْأُمَّةَ لَوِ اجْتَمَعَتْ عَلَى أَنْ يَنْفَعُوكَ بِشَيْءٍ، لَمْ يَنْفَعُوكَ إِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللهُ لَكَ، وَإِنِ اجْتَمَعُوا عَلَى أَنْ يَضُرُّوكَ بِشَيْءٍ، لَمْ يَضُرُّوكَ بِشَيْءٍ إِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللهُ عَلَيْكَ؛ رُفِعَتِ الْأَقْلَامُ، وَجَفَّتِ الصُّحُفُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4811 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20062;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: «إِنَّكُمْ لَتَعْمَلُونَ أَعْمَالًا هِيَ أَدَقُّ فِي أَعْيُنِكُمْ مِنَ الشَّعْرِ، كُنَّا نَعُدُّهَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ المُوبِقَاتِ» ((رَوَاهُ البُخَارِيُّ )) ''وَقَالَ : المُوبِقَاتُ المُهْلِكَاتُ ''.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3300 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20063;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: « إِنَّ اللَّهَ تَعَالَى يَغَارُ، وَغَيْرَةُ اللَّهِ ، تَعَالَى، أَنْ يَأْتِيَ المَرْءُ مَا حَرَّمَ اللَّهُ عَلَيْهِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20064;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: « إنّ ثَلَاثَةً مِنْ بَنِى إِسْرَائِيلَ : أَبْرَصَ ، وَأَقْرَعَ، وَأَعْمَى، أَرَادَ اللَّهُ أَنْ يَبْتَلِيَهم فَبَعَثَ إِلَيْهِمْ ملَكًا، فَأَتَى الأَبْرَصَ فَقَالَ: أيُّ شَيْءٍ أَحَبُّ إِلَيْكَ؟ قَالَ : لَوْنٌ حَسَنٌ، وَجِلْدٌ حَسَنٌ ، وَيَذْهَبُ عَنِّي الَّذِى قَدْ قَذِرَني النَّاسُ؛ فَمَسَحَهُ فَذَهَبَ عَنْهُ قَذَرُهُ وَأُعْطِيَ لَوْناً حَسَناً. قَالَ: فَأَيُّ المَالِ أَحَبُّ إِلَيْكَ؟ قَالَ: الإِبِلُ-أَوْ قَالَ البَقَرُ-شَكَّ الرَّوَاي- فأُعْطيَ نَاقَةً عُشَرَاءَ، فَقَالَ: بَارَكَ اللَّهُ لَكَ فِيهَا. فَأَتَى الأَقْرَعَ فَقَالَ: أَيُّ شَيْءٍ أَحَبُّ إِلَيْكَ؟ قَالَ: شَعْرٌ حَسَنٌ، وَيَذْهَبُ عَنِّي هَذَا الَّذِى قَذِرَني النَّاسُ ، فَمَسَحَهُ فَذَهَبَ عَنْهُ وَأُعْطِيَ شَعْراً حَسَناً. قَالَ: فَأَيُّ المَالِ أَحَبُّ إِلَيْكَ؟ قَالَ: البَقَرُ، فأُعْطِيَ بَقَرَةً حَامِلاً،وَقَالَ بَارَكَ اللَّهُ لَكَ فِيهَا. فَأَتَي الأَعْمَى فَقَالَ: أَيُّ شَيْءٍ أَحَبُّ إِلَيْكَ؟ قَالَ: أَنْ يَرُدَّ اللَّهُ إليَّ بَصَرِي فَأُبْصِرَ النَّاسَ، فَمَسَحَهُ فردَّ اللَّهُ إِلَيْهِ بَصَرَهُ. قَالَ: فَأَيُّ المَالِ أَحَبُّ إِلَيْكَ؟ قَالَ: الغنَمُ، فأُعْطِيَ شَاةً وَالِدًا. فأُنْتِجَ هَذَانِ وَوَلَّدَ هَذَا، فَكَانَ لِهَذَا وادٍ مِنَ الإِبِلِ، وَلِهَذَا وادٍ مِنَ البَقَرِ، وَلِهَذَا وادٍ مِنَ الغَنَمِ. ثُمَّ إِنَّهُ أَتَى الأَبْرَصَ فِي صُورَتِهِ وَهَيْئَتِهِ، فَقَالَ لَهُ: رَجُلٌ مِسْكِينٌ وَابْنُ سَبِيلٍ قَدِ انْقَطَعَتْ بِيَ الحِبالُ فِي سَفَرِي، فَلَا بَلَاغَ لِيَ اليَوْمَ إِلَّا بِاللَّهِ ثُمَّ بِكَ، أَسْأَلُكَ بِالَّذِي أَعْطَاكَ اللَّوْنَ الحَسَنَ، وَالجِلْدَ الحَسَنَ، وَالمَالَ، بَعِيرًا أَتَبَلَّغُ بِهِ فِي سَفَرِي، فَقَالَ: الحُقُوقُ كَثِيرَةٌ. فَقَالَ : كَأَنِّي أَعْرِفُكَ، أَلَمْ تَكُنْ أَبْرَصَ يَقْذَرُكَ النَّاسُ فَقِيرًا، فَأَعْطَاكَ اللَّهُ ؟! فَقَالَ : إِنَّمَا وَرِثْتُ هَذَا المَالَ كَابِرًا عَنْ كابرٍ، فَقَالَ: إِنْ كُنْتَ كَاذِباً فصيَّرَكَ اللَّهُ إِلَى مَا كُنْتَ. وَأَتَى الأقرعَ، فَقَالَ لَهُ مِثْلَ مَا قَالَ لِهَذَا، وردَّ عَلَيْهِ مِثْلَ مَا ردَّ هَذَا، فَقَالَ إِنْ كُنْتَ كَاذِباً فصيّرَكَ اللَّهُ إِلَى مَا كُنْتَ . وَأَتَى الأَعْمَى فِي صُورَتِهِ وَهَيْئَتِهِ، فَقَالَ: رَجُلٌ مِسْكِينٌ وَابْنُ سَبِيلٍ انْقَطَعَتْ بِيَ الحِبالُ فِي سَفَرِي، فَلَا بَلَاغَ لِيَ اليَوْمَ إِلَّا بِاللَّهِ ثُمَّ بِكَ، أَسْأَلُكَ بِالَّذِي ردَّ عَلَيْكَ بَصَرَكَ شَاةً أَتَبَلَّغُ بِهَا فِي سَفَرِي؟ فَقَالَ: قَدْ كُنْتُ أَعْمَى فردَّ اللَّهُ بَصَرِي، فخُذْ مَا شِئْتَ ودَعْ مَا شِئْتَ، فَوَاللَّهِ مَا أَجْهَدُكَ اليَوْمَ بِشَيْءٍ أَخَذْتَهُ لِلَّهِ عَزَّ وَجَلَّ فَقَالَ: أَمْسِكْ عَلَيْكَ مَالَكَ فَإِنَّمَا ابتُلِيتُم، فَقَدْ رضِيَ اللَّهُ عَنْكَ، وَسَخِطَ عَلَى صَاحِبَيْكَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5926 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20065;
update hadith set arabic = 'عَنْ أَبِي يَعْلَى شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « الكَيِّسُ مَنْ دَانَ نَفْسَهُ، وَعَمِلَ لِمَا بَعْدَ المَوْتِ ، وَالعَاجِزُ مَنْ أَتْبَعَ نَفْسَهُ هَوَاهَا، وَتَمَنَّى عَلَى اللَّهِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20066;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : « مِنْ حُسْنِ إِسْلَامِ المَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65255 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20067;
update hadith set arabic = 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «لَا يُسْأَلُ الرَّجُلُ فِيمَ ضَرَبَ امْرَأَتَهُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20068;
update hadith set arabic = 'وَأَمَّا الأَحَادِيثُ فَالأَوَّلُ: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قِيلَ : يَا رسُولَ اللَّهِ مَن أَكرمُ النَّاسِ؟ قَالَ: "أَتْقَاهُمْ". فَقَالُوا: لَيسَ عَنْ هَذَا نَسأُلُكَ، قَالَ: " فَيُوسُفُ نَبِيُّ اللَّهِ بْنُ نَبِيِّ اللَّهِ بْنِ نَبِيِّ اللَّهِ بْنِ خَلِيلِ اللهِ" قَالُوا: لَيسَ عَن هَذَا نَسأَلُكَ، قَالَ: "فعَن مَعَادِنِ العَرَبِ تسأَلُوني؟ خِيَارُهُم فِي الجاهِليَّةِ خِيَارُهُم فِي الإِسلامِ إِذَا فَقُهُوا :.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3069 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20069;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « إِنَّ الدُّنْيَا حُلْوَةٌ خَضِرَةٌ، وَإِنَّ اللهَ مُسْتَخْلِفُكُمْ فِيهَا فَيَنْظُرُ كَيْفَ تَعْمَلُونَ، فَاتَّقُوا الدُّنْيَا وَاتَّقُوا النِّسَاءَ؛ فَإِنَّ أَوَّلَ فِتْنَةِ بَنِي إِسْرَائِيلَ كَانَتْ فِي النِّسَاءِ».', updated_at = now() where id = 20070;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: «اللَّهُمَّ ِإنِّي أَسأَلُكَ الهُدَى وَالتُّقَى وَالعَفَافَ وَالغِنَى».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3057 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20071;
update hadith set arabic = 'عَنْ أَبِي ظَرِيفٍ عَدِيِّ بْنِ حَاتِمٍ الطَّائِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «مَن حَلَفَ عَلَى يَمِينٍ ثُمَّ رَأَى أَتقَى لِلَّهِ مِنها فَلْيَأتِ التَّقوَى».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20072;
update hadith set arabic = 'عَنْ أَبِي أُمَامَةَ صُدَيِّ بْنِ عَجْلَانَ البَاهِلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ فِي حَجَّةِ الوَدَاعِ فَقَالَ : اتَّقُوا اللَّهَ ، وصَلُّوا خَمْسَكُمْ، وَصُومُوا شَهْرَكُمْ، وَأَدُّوا زَكَاةَ أموالِكم، وَأَطِيعُوا أُمَرَاءَكُمْ، تَدْخُلُوا جَنَّةَ رَبِّكُمْ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3725 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20073;
update hadith set arabic = 'فَالأَوَّلُ عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : عُرِضَتْ عَلَيّ الأُمَمُ، فرأيتُ النَّبِيَّ وَمَعَهُ الرُّهَيْطُ، وَالنَّبِيَّ وَمَعَهُ الرَّجُلُ وَالرَّجُلَانِ، وَالنَّبِيَّ وَلَيْسَ مَعَهُ أَحَدٌ إِذْ رُفِعَ لِي سَوَادٌ عَظِيمٌ فظننتُ أَنَّهُمْ أمَّتِي، فَقِيلَ لِى : هَذَا مُوسَى وَقَوْمُهُ، وَلَكِنِ انْظُرْ إِلَى الأُفُقِ، فنظرتُ فَإِذَا سَوَادٌ عَظِيمٌ، فَقِيلَ لِى، انْظُرْ إِلَى الأُفُقِ الآخَرِ، فَإِذَا سَوَادٌ عَظِيمٌ، فَقِيلَ لِي: هَذِهِ أمَّتُكَ، وَمَعَهُمْ سَبْعُونَ أَلْفًا يَدْخُلُونَ الجَنَّةَ بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ" ثُمَّ نَهَضَ فَدَخَلَ منْزلَهُ، فَخَاضَ النَّاسُ فِي أُولَئِكَ الَّذِينَ يَدْخُلُونَ الجَنَّةَ بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ، فَقَالَ بَعْضُهُمْ: فَلَعَلَّهُمُ الَّذِينَ صحِبوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَقَالَ بَعْضُهُمْ: فَلَعَلَّهُمُ الَّذِينَ وُلِدُوا فِي الإِسْلَامِ، فَلَمْ يُشْرِكُوا بِاللَّهِ شَيْئًا- وَذَكَرُوا أَشْيَاءَ- فَخَرَجَ عَلَيْهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَا الَّذِي تَخُوضُونَ فِيهِ؟" فَأَخْبَرُوهُ فَقَالَ: "هُمُ الَّذِينَ لَا يَرْقُونَ ، وَلَا يَسْتَرْقُونَ وَلَا يَتَطَيَّرون، وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ" فَقَامَ عُكاشةُ بْنُ مِحصَنٍ فَقَالَ: ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، فَقَالَ: "أَنْتَ مِنْهُمْ" ثُمَّ قَامَ رَجُلٌ آخَرُ فَقَالَ: ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ فَقَالَ: "سَبَقَكَ بِهَا عُكَّاشَةُ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20074;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَيْضاً أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: «اللَّهُمَّ لَكَ أَسْلَمْتُ وبِكَ آمَنتُ، وعَلَيكَ تَوَكَّلْتُ، وإِلَيكَ أَنَبْتُ ، وَبِكَ خَاصَمْتُ. اللَّهُمَّ أعُوذُ بِعزَّتِكَ، لَا إِلَهَ إِلَّا أَنْتَ أَنْ تُضلَّني، أَنْتَ الحَيُّ الَّذِي لَا تَمُوتُ، والجِنُّ والإنْسُ يَمُوتُونَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3598 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20075;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَيْضاً قَالَ: "حَسْبُنَا اللَّهُ وَنِعْمَ الوَكِيلُ، قَالَهَا إِبْرَاهِيمُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ أُلقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ قَالُوا: إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا: حَسْبُنَا اللَّهُ وَنِعْمَ الوَكِيلُ:.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65287 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20076;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «يَدْخُلُ الْجَنَّةَ أَقْوَامٌ أَفْئِدَتُهُمْ مِثْلُ أَفْئِدَةِ الطَّيْرِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65184 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20077;
update hadith set arabic = 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ غَزَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِبَلَ نَجْدٍ، فَلَمَّا قَفَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَفَلَ مَعَهُمْ، فَأَدْرَكَتْهُمُ القَائِلَةُ فِي وَادٍ كَثِيرِ العِضَاهِ، فَنَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَتَفَرَّقَ النَّاسُ يَسْتَظِلُّونَ بِالشَّجَرِ، ونَزلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَحْتَ سَمُرَةٍ، فَعَلَّقَ بِهَا سَيْفَهُ، وَنِمْنَا نومةً، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يدْعُونَا، وَإِذَا عِنْدَهُ أَعْرَابِيٌّ فَقَالَ: «إِنَّ هَذَا اخْتَرَاطَ عليَّ سَيفِي وَأَنَا نَائِمٌ، فَاسْيقَظْتُ وَهُوَ فِي يَدِهِ صَلتًا، قَالَ: مَنْ يَمْنَعُكَ مِنِّى؟ قُلْتُ: اللَّهُ-ثَلَاثًا» وَلَمْ يُعاقِبْهُ وَجَلَسَ. ((مُتَّفَقٌ عَلَيْهِ)) . وَفِي رِوَايَةٍ : قَالَ جَابِرٌ: كنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بذَاتِ الرِّقَاعِ: فَإِذَا أَتَيْنَا عَلَى شَجَرَةٍ ظَلِيلَةٍ تَرَكْنَاهَا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ رجُلٌ مِنَ المُشْرِكِينَ، وَسَيْفُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ معَلَّقٌ بِالشَّجَرَةِ، فَاخْتَرطَهُ فَقَالَ : تَخَافُنِي؟ قَالَ: لَا قَالَ : فَمَنْ يَمْنَعُكَ مِنِّي ؟ قَالَ: اللَّهُ . وَفِي رِوَايَةِ أَبِي بَكْرٍ الإِسْمَاعِيلِى فِي صَحِيحِهِ: قَالَ: مَنْ يَمْنَعُكَ مِنِّي؟ قَالَ : اللَّهُ قَالَ: فَسَقَطَ السَّيْفُ مِن يَدهِ، فَأَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ السَّيْفَ فَقَالَ: مَنْ يَمْنَعُكَ مِنِّي؟ فَقَالَ كُنْ خَيرَ آخِذٍ، فَقَالَ تَشهدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ ، وَأَنِّي رَسُولُ اللَّهِ؟ قَالَ: لَا، وَلَكِنِّي أُعَاهِدُكَ أَنْ لَا أُقَاتِلَكَ وَلَا أكُونَ مَعَ قَوْمٍ يُقَاتِلُونَكَ، فَخَلَّى سَبيلَهُ، فَأَتَى أَصْحَابَهُ فَقَالَ: جئتُكُمْ مِن عندِ خيرِ الناسِ.', updated_at = now() where id = 20078;
update hadith set arabic = 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ : «لَو أَنَّكُمْ تَتَوَكَّلُونَ عَلَى اللهِ حَقَّ تَوَكُّلِهِ لَرَزَقَكُمْ كَمَا يَرْزُقُ الطَّيْرَ ، تَغْدُو خِمَاصًا وَتَرُوحُ بِطَانًا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4721 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20079;
update hadith set arabic = 'عَنْ أَبِي عُمَارَةَ البَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ : قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « يَا فُلَانُ إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَقُلْ: اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ: وَفَوَّضْتُ أَمْرِي إِلَيْكَ ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَى مِنْكَ إِلَّا إِلَيْكَ ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَنَبِيِّكَ الَّذِي أَرْسَلْتَ؛ فَإِنَّكَ إِنْ مُتَّ مِنْ لَيْلَتِكَ مُتَّ عَلَى الفِطْرَةِ، وَإِنْ أَصْبَحْتَ أَصَبْتَ خَيْراً».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20080;
update hadith set arabic = 'عَنْ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُ عَنْ عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ عَامِرِ بْنِ عُمَرَ بْنِ كَعْبِ بْنِ سَعْدِ بْنِ تَيْمِ بْنِ مُرَّةَ بْنِ كَعْبِ بْنِ لُؤَيِّ بْنِ غَالِبٍ القُرَشِيِّ التَّيْمِيِّ رَضِيَ اللَّهُ عَنْهُ - وَهُوَ وَأَبُوهُ وَأُمُّهُ صَحَابَةٌ، رَضِيَ اللَّهُ عَنْهُمْ- قَالَ: نَظَرْتُ إِلَى أَقْدَامِ المُشْرِكِينَ وَنَحْنُ فِي الغَارِ وَهُمْ عَلَى رُؤُوسِنَا فَقُلْتُ يَارَسُولَ اللَّهِ لَوْ أَنَّ أَحَدَهُمْ نَظَرَ تَحْتَ قَدَمِيةِ لَأَبْصَرَنَا. فَقَالَ: « مَا ظَنُّكَ يَا أَبَا بَكْرٍ بِاثْنَيْنِ اللَّهُ ثَالِثُهُمَا».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20081;
update hadith set arabic = 'عَنْ أُمِّ المُؤْمِنِينَ أُمِّ سَلَمَةَ، وَاسْمُهَا هِنْدُ بِنْتُ أَبِي أُمَيَّةَ حُذَيْفَةَ المَخْزُومِيَّةُ، رَضِيَ اللَّهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ مِنْ بَيْتِهِ قَالَ: «بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَذِلَّ أَوْ أُذَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20082;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "مَنْ قَالَ-يَعْنِي إِذَا خَرجَ مِنْ بَيتِهِ-: بِسمِ اللَّهِ تَوَكَّلتُ عَلَى اللهِ، وَلاَ حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ، يُقَالُ لَهُ: هُدِيتَ وَكُفِيتَ وَوُقِيتَ، وَتَنَحَّى عَنهُ الشَّيطَانُ". رَوَاهُ أَبُو دَاوُدَ وَالتِّرْمِذِيُّ، وَالنَّسَائِيُّ وَغَيْرُهُمْ. وَقَالَ التِّرْمِذِيُّ: حَدِيثٌ حَسَنٌ، زَادَ أَبُو دَاوُدَ: "فَيَقُولُ :-يَعْنِي الشَّيْطَانَ-لِشَيطَانٍ آخَرَ: كَيفَ لَكَ بِرَجلٍ قَد هُدِيَ وكُفِيَ ووُقِيَ ؟', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3504 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20083;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ أخوانِ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ أحدُهما يَأْتِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَالآخَرُ يَحتَرِفُ، فَشَكَا الُمحتَرِفُ آخَاهُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ : «لعَلَّكَ تُرزَقُ بِهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3126 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20084;
update hadith set arabic = 'عَنْ أَبِي عَمْرٍو، وَقِيلَ: أَبِي عَمْرَةَ سُفْيَانَ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ قُلْ لِي فِي الْإِسْلَامِ قَوْلًا لَا أَسْأَلُ عَنْهُ أَحَدًا غَيْرَكَ. قَالَ: «قُلْ آمَنْتُ بِاللهِ: ثُمَّ اسْتَقِمْ».', updated_at = now() where id = 20085;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ : قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَارِبُوا وَسَدِّدُوا، وَاعْلَمُوا أَنَّهُ لَنْ يَنْجُوَ أَحَدٌ مِنْكُمْ بِعَمَلِهِ" قَالُوا: وَلَا أَنْتَ يَا رَسُولَ اللهِ ؟ قَالَ: "وَلَا أَنَا إِلَّا أَنْ يَتَغَمَّدَنِى اللهُ بِرَحْمَةٍ مِنْهُ وَفَضْلٍ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3469 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20086;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « بَادِرُوا بِالْأَعْمَالِ فِتَنًا كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ مُؤْمِنًا وَيُمْسِي كَافِرًا وَيُمْسِي مُؤْمِنًا وَيُصْبِحُ كَافِرًا، يَبِيعُ دِينَهُ بِعَرَضٍ مِنَ الدُّنْيَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3138 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20087;
update hadith set arabic = 'الثَّانِي عَنْ أَبِي سِرْوَعَةَ -بِكَسْرِ السِّينِ المُهْمَلَةِ وَفَتْحِهَا- عُقْبَةَ ابْنِ الحَارِثِ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَلَّيْتُ وَرَاءَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالمَدِينَةِ العَصْرَ، فسَلَّمَ ثُمَّ قَامَ مُسرعًا فتَخَطَّى رِقَابَ النَّاسِ إِلَى بَعْضِ حُجَرِ نِسائِهِ، فَفَزِعَ الناسُ مِنْ سُرْعَتِهِ، فَخَرَجَ عَلَيْهِمْ، فَرَأَى أَنَّهُمْ قَدْ عَجِبُوا مِنْ سُرْعَتِهِ، قَالَ «ذَكَرْتُ شَيْئاً مِنْ تِبْرٍ عِنْدَنَا فَكَرِهْتُ أَنْ يَحْبِسَنِى، فأمرتُ بِقِسْمَتِهِ» ((رَوَاهُ البُخَارِيُّ)). وَفِي رِوَايَةٍ لِلْبُخَارِيِّ : كُنْتُ خَلَّفْتُ فِي البَيْتِ تِبْرًا مِنَ الصَّدَقَةِ، فَكَرِهْتُ أَنْ أُبَيِّتَهُ . ((التِّبْرُ)) قِطَعُ ذَهَبٍ أَوْ فِضَّةٍ', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3483 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20088;
update hadith set arabic = 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَجُلٌ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يومَ أُحُدٍ: : رَأيتَ إِنْ قُتِلْتُ فَأَيْنَ أَنَا ؟ قَالَ : « فِي الجَنَّةِ » فأَلْقَى تَمراتٍ كُنَّ فِي يَدِهِ ، ثُمَّ قَاتَلَ حَتَّى قُتِلَ . مُتَّفَقٌ عَلَيهِ .', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3194 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20089;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ ، قَالَ : جَاءَ رَجُلٌ إِلَى النَّبِيِّ فَقَالَ : يَا رَسُولَ اللَّهِ ، أَيُّ الصَّدَقَةِ أَعْظَمُ أَجْرًا ؟ قَالَ : « أَنْ تَصَدَّقَ وَأَنْتَ صحيحٌ شَحِيحٌ ، تَخْشَى الفَقْرَ وتَأَمَلُ الغِنى ، وَلَا تُمْهِلْ حَتَّى إِذَا بَلَغَتِ الحُلْقُومَ قُلْتَ لِفُلَانٍ كَذَا وَلِفُلَانٍ كَذَا ، وَقَدْ كَانَ لِفُلَانٍ » . مُتَّفَقٌ عَلَيهِ .', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4252 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20090;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَ سَيْفًا يَوْمَ أُحُدٍ فَقَالَ: " مَنْ يَأْخُذُ مِنِّي هَذَا؟ فَبَسَطُوا أَيْدِيَهُمْ، كلُّ إنسانٍ مِنْهُمْ يَقُولُ: أَنَا أَنَا. قَالَ: "فَمَنْ يَأْخُذُهُ بِحَقِّهِ؟" فأَحْجَمَ القومُ، فَقَالَ أَبُو دُجَانةَ رَضِيَ اللَّهُ عَنْهُ: أَنَا آخُذُهُ بِحَقِّهِ، فَأَخَذَهُ فَفَلَقَ بِهِ هَامَ المُشْرِكِينَ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20091;
update hadith set arabic = 'عَنِ الزُّبَيْرِ بْنِ عَدِيٍّ قَالَ: أَتَيْنَا أنسَ بنَ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ فَشَكَوْنَا إِلَيْهِ مَا نَلْقَى مِنَ الحَجَّاجِ. فَقَالَ: «اصْبِرُوا فَإِنَّهُ لَا يَأْتِي زمانٌ إِلَّا وَالَّذِي بَعْدَهُ شَرٌّ مِنْهُ حَتَّى تَلْقَوا رَبَّكُم» سمعتُهُ مِنْ نَبِيِّكُم صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.', updated_at = now() where id = 20092;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « بَادِرُوا بِالأَعْمَالِ سَبْعاً. هَلْ تَنْتَظِرُونَ إِلَّا فَقْراً مُنْسِياً، أَوْ غِنًى مُطْغِياً، أَوْ مَرَضاً مُفْسِداً، أَوْ هَرَماً مُفَنِّداً أَوْ مَوْتاً مُجْهِزاً أَوِ الدَّجَّالَ فَشَرُّ غَائِبٍ يُنْتَظَرُ، أَوِ السَّاعَةَ فَالسَّاعَةُ أَدْهَى وَأَمَرُّ!».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20093;
update hadith set arabic = 'عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ يَوْمَ خَيْبَرَ: "لَأُعْطِيَنَّ هَذِهِ الرَّايَةَ رَجُلًا يُحِبُّ اللهَ وَرَسُولَهُ، يَفْتَحُ اللهُ عَلَى يَدَيْهِ" قَالَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: مَا أَحْبَبْتُ الْإِمَارَةَ إِلَّا يَؤْمَئِذٍ، فَتَسَاوَرْتُ لَهَا رَجَاءَ أَنْ أُدْعَى لَهَا، فَدَعَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلِيَّ بْنَ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ فَأَعْطَاهُ إِيَّاهَا وَقَالَ: " امْشِ وَلَا تَلْتَفِتْ حَتَّى يَفْتَحَ اللهُ عَلَيْكَ" فَسَارَ عَلِيٌّ شَيْئًا، ثُمَّ وَقَفَ وَلَمْ يَلْتَفِتْ، فَصَرَخَ: يَا رَسُولَ اللهِ، عَلَى مَاذَا أُقَاتِلُ النَّاسَ؟ قَالَ: " قَاتِلْهُمْ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، فَإِذَا فَعَلُوا ذَلِكَ فَقَدْ مَنَعُوا مِنْكَ دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّهَا، وَحِسَابُهُمْ عَلَى اللهِ" ((رَوَاهُ مُسْلِمٌ)): (14)', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4958 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20094;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَة رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «إنَّ اللَّهَ تَعَالَى قَالَ: مَنْ عَادَى لِي وَلِيًّا فَقْد آذَنْتُهُ بِالحَرْبِ. وَمَا تَقَرَّبَ إلَيَّ عَبْدِي بِشَيْءٍ أَحَبَّ إلَيَّ مِمَّا افْتَرَضْتُ عَلَيْهِ، وَمَا يَزَالُ عَبْدِي يَتَقَرَّبُ إلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ، فَإِذَا أَحْبَبْتُهُ كُنْتُ سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَيَدَهُ الَّتِي يَبْطِشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا، وَإِنْ سَأَلَنِي أَعْطَيْتُهُ؛ وَلَئِنْ اسْتَعَاذَنِي لَأُعِيذَنَّهُ».', updated_at = now() where id = 20095;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا يَرْوِيهِ عَنْ رَبِّهِ عَزَّ وَجَلَّ قَالَ: « إِذَا تَقَرَّبَ العبدُ إليَّ شِبْرًا تَقَرَّبْتُ إِلَيْهِ ذِرَاعًا، وَإِذَا تَقَرَّبَ إليَّ ذِرَاعًا تَقَرَّبْتُ مِنْهُ بَاعًا، وَإِذَا أَتَانِي يَمْشِي أَتَيْتُهُ هَرْوَلَةً».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6461 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20096;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: « نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ: الصِّحَّةُ، وَالفَرَاغُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5449 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20097;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُومُ مِنَ اللَّيْلِ حَتَّى تَنْفَطِرَ قَدَمَاهُ، فَقُلْتُ لَهُ: لِمَ تَصْنَعُ هَذَا يَا رَسُولَ اللَّهِ، وَقَدْ غَفَرَ اللهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ؟! قَالَ: « أَفَلَا أُحِبُّ أَنْ أَكُونَ عَبْدًا شَكُورًا؟».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4830 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20098;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: « كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ الْعَشْرُ أَحْيَا اللَّيْلَ، وَأَيْقَظَ أَهْلَهُ، وَجَدَّ وَشَدَّ الْمِئْزَرَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4944 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20099;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: « الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللهِ مِنَ الْمُؤْمِنِ الضَّعِيفِ وَفِي كُلٍّ خَيْرٌ. احْرِصْ عَلَى مَا يَنْفَعُكَ، وَاسْتَعِنْ بِاللهِ وَلَا تَعْجَزْ. وَإِنْ أَصَابَكَ شَيْءٌ فَلَا تَقُلْ: لَوْ أَنِّي فَعَلْتُ كَانَ كَذَا وَكَذَا، وَلَكِنْ قُلْ: قَدَرُ اللهِ، وَمَا شَاءَ فَعَلَ؛ فَإِنَّ لَوْ تَفْتَحُ عَمَلَ الشَّيْطَانِ».', updated_at = now() where id = 20100;
update hadith set arabic = 'عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « حُجِبَتِ النَّارُ بِالشَّهَوَاتِ، وَحُجِبَتِ الْجَنَّةُ بِالْمَكَارِهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3702 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20101;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ اللَّهِ حُذَيْفَةَ بْنِ اليَمَانِ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَافْتَتَحَ البَقَرَةَ، فَقُلْتُ يَرْكَعُ عِنْدَ المِائَةِ، ثُمَّ مَضَى؛ فَقُلْتُ يُصَلِّي بِهَا فِي رَكْعَةٍ، فَمَضَى؛ فَقُلْتُ يَرْكَعُ بِهَا، ثُمَّ افْتَتَحَ النِّسَاءَ؛ فَقَرَأَهَا، ثُمَّ افْتَتَحَ آلَ عِمْرَانَ فَقَرَأَهَا، يَقْرَأُ مُتَرَسِّلًا إِذَا مَرَّ بِآيَةٍ فِيهَا تَسبِيحٌ سَبَّحَ، وَإِذَا مَرَّ بِسُؤَالٍ سَأَلَ، وَإِذَا مَرَّ بِتَعَوُّذٍ تَعَوَّذَ، ثُمَّ رَكَعَ فَجَعَلَ يَقُولُ: " سُبْحَانَ رَبِّيَ العَظِيمِ" فَكَانَ رُكُوعُهُ نَحْوًا مِنْ قِيَامِهِ ثُمَّ قَالَ: " سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا لَكَ الحَمْدُ" ثُمَّ قَامَ قِيَاماً طَوِيلًا قَرِيبًا مِمَّا رَكَعَ، ثُمَّ سَجَدَ فَقَالَ: " سُبْحَانَ رَبِّيَ الأَعْلَى" فَكَانَ سُجُودُهُ قَرِيبًا مِنْ قِيَامِهِ" ((رَوَاهُ مُسْلِمٌ).', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3727 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20102;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً، فَأَطَالَ القِيَامَ حَتَّى هَمَمْتُ بأمْرِ سُوءٍ! قِيلَ: وَمَا هَمَمْتَ بِهِ؟ قَالَ: هَمَمْتُ أَنْ أَجْلِسَ وأَدَعَهُ.', updated_at = now() where id = 20103;
update hadith set arabic = 'العَاشِرُ عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « يَتْبَعُ المَيِّتَ ثَلَاثَةٌ: أهْلُهُ ومَالُهُ وعَمَلُهُ؛ فَيَرْجِعُ اثْنَانِ ويَبْقى وَاحِدٌ: يَرْجِعُ أهْلُهُ ومَالُهُ، وَيَبْقَى عَمَلُهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4240 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20104;
update hadith set arabic = 'الحَادِي عَشَرَ: عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « الْجَنَّةُ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ شِرَاكِ نَعْلِهِ، وَالنَّارُ مِثْلُ ذَلِكَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3581 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20105;
update hadith set arabic = 'الثَّانِي عَشَرَ: عَنْ أَبِي فِرَاسٍ رَبِيعَةَ بْنِ كَعْبٍ الأَسْلَمِى خَادِمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمِنْ أَهْلِ الصُّفَّةِ رَضِيَ اللَّهُ عَنْهُ قَالَ: " كُنْتُ أَبِيتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَآتِيهِ بِوَضُوئِهِ، وَحَاجَتِهِ فَقَالَ: "سَلْنِي" فَقُلْتُ: أَسْأَلُكَ مُرَافَقَتَكَ فِي الجَنَّةِ. فَقَالَ: { أَوَغَيْرَ ذَلِكَ؟" قُلْتُ: هُوَ ذَاكَ قَالَ: " فَأَعِنِّي عَلَى نَفْسِكَ بِكَثْرَةِ السُّجُودِ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20106;
update hadith set arabic = 'الثَّالِثَ عَشَرَ: عَنْ أَبِي عَبْدِ اللَّهِ- وَيُقَالُ: أَبُو عَبْدِ الرَّحْمَنِ- ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: « عَلَيْكَ بِكَثْرَةِ السُّجُودِ، فَإِنَّكَ لَنْ تَسْجُدَ لِلَّهِ سَجْدَةً إِلَّا رَفَعَكَ اللَّهُ بِهَا دَرَجَةً، وَحَطَّ عَنْكَ بِهَا خَطِيئَةً».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20107;
update hadith set arabic = 'الرَّابِعَ عَشَرَ: عَنْ أَبِي صَفْوَانَ عَبْدِ اللَّهِ بْنِ بُسْرٍ الأَسْلَمِيِّ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « خَيْرُ النَّاسِ مَنْ طَالَ عُمُرُهُ وحَسُنَ عَمَلُهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3710 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20108;
update hadith set arabic = 'الخَامِسَ عَشَرَ: عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ، قَالَ: غَابَ عَمِّي أَنَسُ ابْنُ النَّضْرِ رَضِيَ اللَّهُ عَنْهُ، عَنْ قِتَالِ بَدْرٍ، فَقَالَ: يَارَسُولَ اللَّهِ غِبْتُ عَنْ أَوَّلِ قِتَالٍ قَاتَلْتَ المُشْرِكِينَ، لَئِنِ اللَّهُ أَشْهَدَنِي قِتَالَ المُشْرِكِينَ لَيُرِيَنَّ اللَّهُ مَا أَصْنَعُ. فَلَمَّا كَانَ يَوْمُ أُحُدٍ انْكَشَفَ المُسْلِمُونَ، فَقَالَ اللَّهُمَّ أعْتَذِرُ إِلَيْكَ مِمَّا صَنَعَ هَؤُلَاءِ - يَعْنِي أَصْحَابَهُ- وأبرأُ إِلَيْكَ مِمَّا صَنَعَ هَؤُلَاءِ- يَعْنِي المُشْرِكِينَ- ثُمَّ تَقَدَّمَ فَاسْتَقْبَلَهُ سَعْدُ بْنُ مُعَاذٍ، فَقَالَ: يَاسَعْدُ بْنَ مُعَاذٍ الجنَّةَ وربِّ الكَعْبَةِ، إنِّي أجِدُ رِيحَهَا مِنْ دونِ أُحُدٍ. قَالَ سَعْدٌ: فَمَا اسْتَطَعْتُ يَا رَسُولَ اللَّهِ مَا صَنَعَ! قَالَ أَنَسٌ: فَوَجَدْنَا بِهِ بِضْعَا وَثَمَانِينَ ضَرْبَةً بِالسَّيْفِ، أَوْ طَعْنَةً بِرُمْحٍ ، أَوْ رَمْيَةً بِسَهْمٍ، وَوَجَدْنَاهُ قَدْ قُتِلَ ومَثَّلَ بِهِ المُشْرِكُونَ فَمَا عَرفَهُ أحدٌ إِلَّا أُختُهُ بِبَنَانِهِ. قَالَ أَنَسٌ: كنَّا نَرَى أَوْ نَظُنُّ أَنَّ هَذِهِ الآيه نَزَلَتْ فِيهِ وَفِي أَشْبَاهِهِ: {مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَهَدُوا اللَّهَ عَلَيْهِ}.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3855 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20109;
update hadith set arabic = 'السَّادِسَ عَشَرَ: عَنْ أَبِي مَسْعُودٍ عُقْبَةَ بْنِ عَمْرٍو الأَنْصَارِيِّ البَدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ آيه الصَّدَقَةِ كنَّا نُحَامِلُ عَلَى ظُهُورِنَا. فَجَاءَ رَجُلٌ فَتَصَدَّقَ بِشَيْءٍ كَثِيرٍ فَقَالُوا: مُراءٍ، وَجَاءَ رَجُلٌ آخَرُ فَتَصَدَّقَ بِصَاعٍ فَقَالُوا: إِنَّ اللَّهَ لَغَنيٌّ عَنْ صَاعِ هَذَا! فَنَزَلَتْ { الَّذِينَ يَلْمِزُونَ الْمُطَّوِّعِينَ مِنَ الْمُؤْمِنِينَ فِي الصَّدَقَاتِ وَالَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ} الآيَةَ.', updated_at = now() where id = 20110;
update hadith set arabic = 'السَّابِعَ عَشَرَ: عَنْ سَعِيدِ بْنِ عَبْدِ العَزِيزِ، عَنْ رَبِيعَةَ بْنِ يَزِيدَ، عَنْ أَبِي إِدْرِيسَ الخَوْلَانِيِّ، عَنْ أَبِي ذَرٍّ جُنْدُبِ بْنِ جُنَادَةَ، رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيمَا يَرْوِى عَنِ اللهِ تَبَارَكَ وَتَعَالَى أَنَّهُ قَالَ: « يَاعِبَادِي إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا فَلَا تَظَالَمُوا، يَا عِبَادِي كُلُّكُمْ ضَالٌّ إِلَّا مَنْ هَدَيْتُهُ؛ فَاسْتَهْدُونِي أَهْدِكُمْ، يَا عِبَادِي كُلُّكُمْ جَائِعٌ إِلَّا مَنْ أَطْعَمْتُهُ؛ فَاسْتَطْعِمُونِي أُطْعِمْكُمْ،يَا عِبَادِي كُلُّكُمْ عَارٍ إِلَّا مَنْ كَسَوْتُهُ، فَاسْتَكْسُونِي أَكْسُكُمْ، يَا عِبَادِي إِنَّكُمْ تُخْطِئُونَ بِاللَّيْلِ وَالنَّهَارِ وَأَنَا أَغْفِرُ الذُّنُوبَ جَمِيعًا، فَاسْتَغْفِرُونِي أَغْفِرْلَكُمْ، يَاعِبَادِي إِنَّكُمْ لَنْ تَبْلُغُوا ضَرِّي فَتَضُرُّونِي، وَلَنْ تَبْلُغُوا نَفْعِي فَتَنْفَعُونِي، يَا عِبَادِي ، لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَتْقَى قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ مَا زَادَ ذَلِكَ فِي مُلْكِي شَيْئًا . يَا عِبَادِي ، لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَفْجَرِ قَلْبِ رَجُلٍ وَاحِدٍ مَا نَقَصَ ذَلِكَ مِنْ مُلْكِي شَيْئًا، يَا عِبَادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ، وَإِنْسَكُمْ وَجِنَّكُمْ قَامُوا فِي صَعِيدٍ وَاحِدٍ، فَسَأَلُونِي فَأَعْطَيْتُ كُلَّ إِنْسَانٍ مَسْأَلَتَهُ، مَا نَقَصَ ذَلِكَ مِمَّا عِنْدِي إِلَّا كَمَا يَنْقُصُ الْمِخْيَطُ إِذَا أُدْخِلَ الْبَحْرَ، يَا عِبَادِي إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ، ثُمَّ أُوَفِّيكُمْ إِيَّاهَا، فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدِ اللهَ، وَمَنْ وَجَدَ غَيْرَ ذَلِكَ فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ». قَالَ سَعِيدٌ: كَانَ أَبُو إِدْرِيسَ إِذَا حَدَّثَ بِهَذَا الحَدِيثِ جَثَا عَلَى رُكْبَتَيْهِ. رَوَاهُ مُسْلِمٌ. (20).', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4810 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20111;
update hadith set arabic = 'وَأَمَّا الأَحَادِيثُ فَالأَوَّلُ: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « أَعْذَرَ اللَّهُ إِلَى امْرِئٍ أَخَّرَ أَجَلَهُ حَتَّى بَلَغَ سِتِّينَ سَنَةً».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66223 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20112;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: كَانَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ يُدْخِلُنِي مَعَ أَشْيَاخِ بَدْرٍ، فَكَأَنَّ بَعْضَهُم وَجَدَ فِي نَفْسِهِ فَقَالَ: لِمَ يُدْخِلُ هَذَا مَعَنَا وَلَنَا أبناءٌ مِثْلُهُ!؟ فَقَالَ عُمَرُ: إِنَّهُ مِنْ حَيْثُ عَلِمْتُمْ! فَدَعَانِي ذاتَ يومٍ فأَدَخَلَنِي مَعَهُمْ، فَمَا رأيتُ أَنَّهُ دَعَانِى يَوْمَئِذٍ إِلَّا لِيُرِيَهُم قَالَ: مَا تَقُولُونَ فِي قَوْلِ اللَّهِ تَعَالَى: {إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ؟).', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3377 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20113;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا صَلَّى رسولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صلاةً بَعْدَ أَنْ نَزَلَتْ عَلَيْهِ { إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ} إِلَّا يَقُولُ فِيهَا: " سُبْحَانَكَ رَبَّنَا وبِحَمْدِكَ، اللهمَّ اغْفِرْ لِي" ((مُتَّفَقٌ عَلَيْهِ)). وَفِي رِوَايَةٍ فِي الصَّحِيحَيْنِ" عَنْهَا: كانَ رسولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكْثِرُ أَنْ يَقُولَ فِي رُكُوعِهِ وسُجُودِهِ: "سُبْحَانَكَ اللهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللهُمَّ اغْفِرْ لِي" يَتَأَوَّلُ القُرْآنَ. وَفِي رِوَايَةٍ لِمُسْلِمٍ: كَانَ رسولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكْثِرُ أَنْ يَقُولَ قَبْلَ أَنْ يَمُوتَ: "سُبْحَانَكَ اللهُمَّ وَبِحَمْدِكَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ". قالتْ عَائِشَةُ: قلتُ: يا رسولَ اللهِ مَا هذهِ الكلماتُ التي أراكَ أَحْدَثْتَهَا تَقُولُها؟ قَالَ: "جُعِلَتْ لِي عَلَامَةٌ فِي أُمَّتِي إِذَا رَأَيْتُهَا قُلْتُهَا {إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ} إِلَى آخِرِ السُّورَةِ". وَفِي رِوَايَةٍ لَهُ: كانَ رسولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكْثِرُ مِنْ قَوْلِ: "سُبْحَانَ اللهِ وَبِحَمْدِهِ، أَسْتَغْفِرُ اللهَ وَأَتُوبُ إِلَيْهِ". قالتْ: قلتُ: يا رسولَ اللهِ! أراكَ تُكْثِرُ مِنْ قَوْلِ: سُبْحَانَ اللهِ وَبِحَمْدِهِ، أَسْتَغْفِرُ اللهَ وأَتُوبُ إليهِ؟ فقالَ: "أَخْبَرَنِي رَبِّي أَنِّي سَأَرَى عَلَامَةً فِي أُمَّتِي فَإِذَا رَأَيْتُهَا أَكْثَرْتُ مِنْ قَوْلِ: سُبْحَانَ اللهِ وَبِحَمْدِهِ، أَسْتَغْفِرُ اللهَ وَأَتُوبُ إليهِ، فَقَدْ رَأَيْتُهَا: {إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ} فَتْحُ مَكَّةَ، {وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجاً، فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّاباً}.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4826 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20114;
update hadith set arabic = 'الرَّابِعُ؛: عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ تَابَعَ الوَحْيَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبْلَ وَفَاتِهِ، حتَّى تُوُفِّيَ أَكْثَرَ مَا كَانَ الوَحْيُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4217 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20115;
update hadith set arabic = 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «يُبْعَثُ كلُّ عبدٍ عَلَى مَا مَاتَ عَلَيْهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5459 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20116;
update hadith set arabic = 'عَنْ أَبِي ذَرٍّ جُنْدُبِ بْنِ جُنَادَةَ رَضِيَ اللَّهُ عَنْهَا قَالَ: قُلْتُ يَا رَسُولَ اللَّهِ، أَيُّ الأَعْمَالِ أَفْضَلُ؟ قَالَ: "الإِيمَانُ بِاللَّهِ، وَالجِهَادُ فِي سَبِيلِهِ". قُلْتُ: أَيُّ الرِّقَابِ أَفْضَلُ؟ قَالَ: "أَنْفَسُهَا عِنْدَ أَهْلِهَا، وَأَكْثَرُهَا ثَمَناً" قُلْتُ: فَإِنْ لَمْ أَفْعَلْ؟ قَالَ: "تُعِينُ صَانِعاً أَوْ تَصْنَعُ لِأَخْرَقَ" قُلْتُ: يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ ضَعُفْتُ عَنْ بَعْضِ العَمَلِ؟ قَالَ: تَكُفُّ شَرَّكَ عَنِ النَّاسِ فَإِنَّهَا صَدَقَةٌ مِنْكَ عَلَى نَفْسِكَ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20117;
update hadith set arabic = 'عَنْ أَبِي ذَرٍّ أَيْضاً رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « يُصْبِحُ عَلَى كُلِّ سُلَامَى مِنْ أَحَدِكُمْ صَدَقَةٌ، فَكُلُّ تَسْبِيحَةٍ صَدَقَةٌ، وَكُلُّ تَحْمِيدَةٍ صَدَقَةٌ، وَكُلُّ تَهْلِيلَةٍ صَدَقَةٌ، وَكُلُّ تَكْبِيرَةٍ صَدَقَةٌ، وَأَمْرٌ بِالمَعْرُوفِ صَدَقَةٌ، وَنَهْىٌ عَنِ المُنْكَرِ صَدَقَةٌ، وَيُجْزِيءُ مِنْ ذَلِكَ رَكْعَتَانِ يَرْكَعُهُمَا مِنَ الضُّحَى» ((رَوَاهُ مُسْلِمٌ)) السُّلَامَى بِضَمِّ السِّينِ المُهْمَلَةِ وَتَخْفِيفِ اللَّامِ وَفَتْحِ المِيمِ: المَفْصِلُ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20118;
update hadith set arabic = 'الثَّالِثُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « عُرِضَتْ عَلَيَّ أعمالُ أُمتي حَسَنُهَا وسَيِّئُهَا، فَوَجَدتُ فِي مَحَاسِنِ أَعْمَالِهَا الأَذَى يُمَاطُ عَنِ الطَّرِيقِ، ووَجَدتُ فِي مَسَاوِىءِ أَعْمَالِهَا النُّخَاعَةُ تَكُونُ فِي المَسْجِدِ لَا تُدْفَنُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4813 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20119;
update hadith set arabic = 'الرَّابِعُ عَنْهُ: أَنَّ نَاسًا قَالُوا: يَارَسُولَ اللهِ، ذَهَبَ أَهْلُ الدُّثُورِ بِالْأُجُورِ، يُصَلُّونَ كَمَا نُصَلِّي، وَيَصُومُونَ كَمَا نَصُومُ، وَيَتَصَدَّقُونَ بِفُضُولِ أَمْوَالِهِمْ قَالَ: " أَوَ لَيْسَ قَدْ جَعَلَ اللهُ لَكُمْ مَا تَصَّدَّقُونَ بِهِ: إِنَّ بِكُلِّ تَسْبِيحَةٍ صَدَقَةً، وَكُلِّ تَكْبِيرَةٍ صَدَقَةً، وَكُلِّ تَحْمِيدَةٍ صَدَقَةً، وَكُلِّ تَهْلِيلَةٍ صَدَقَةً، وَأَمْرٌ بِالْمَعْرُوفِ صَدَقَةٌ، وَنَهْيٌ عَنْ الْمُنْكَرِ صَدَقَةٌ وَفِي بُضْعِ أَحَدِكُمْ صَدَقَةٌ قَالُوا: يَارَسُولَ اللهِ أَيَأْتِى أَحَدُنَا شَهْوَتَهُ، وَيَكُونُ لَهُ فِيهَا أَجْرٌ؟! قَالَ: " أَرَأَيْتُمْ لَوْ وَضَعَهَا فِي حَرَامٍ أَكَانَ عَلَيْهِ وِزْرٌ؟ فَكَذَلِكَ إِذَا وَضَعَهَا فِي الْحَلَالِ كَانَ لَهُ أَجْرٌ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4558 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20120;
update hadith set arabic = '-الخَامِسُ: عَنْهُ قَالَ لِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلِيقٍ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5348 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20121;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : " كُلُّ سُلَامَى مِنَ النَّاسِ عَلَيْهِ صَدَقَةٌ كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ: تَعْدِلُ بَيْنَ الأثْنَيْنِ صَدَقَةٌ، وَتُعِينُ الرَّجُلَ فِي دَابَّتِهِ، فَتَحْمِلُهُ عَلَيْهَا، أَوْ تَرْفَعُ لَهُ عَلَيْهَا مَتَاعَهُ صَدَقَةٌ، وَالكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ، وَبِكُلِّ خُطْوَةٍ تَمْشِيهَا إِلَى الصَّلَاةِ صَدَقَةٌ، وَتُمِيطُ الأَذَى عَنِ الطَّرِيقِ صَدَقَةٌ" ((مُتَّفَقٌ عَلَيْهِ)). وَرَوَاهُ مُسْلِمٌ أَيْضاً مِنْ رِوَايَةِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: " إِنَّهُ خُلِقَ كُلُّ إِنْسَانٍ مِنْ بَنِي آدَمَ عَلَى سِتِّينَ وَثَلَاثِمِائه مَفْصِلٍ، فَمَنْ كَبَّرَ اللَّهَ، وَحَمِدَ اللَّهَ، وَهَلَّلَ اللَّهَ، وَسَبَّحَ اللَّهَ وَاسْتَغْفَرَ اللَّهَ، وَعَزَلَ حَجَراً عَنْ طَرِيقِ النَّاسِ أَوْ شَوْكَةً أَوْ عَظْماً عَنْ طَرِيقِ النَّاسِ، أَوْ أَمَرَ بِمَعْرُوفٍ أَوْ نَهَى عَنِ المُنْكَرِ، عَدَدَ السِّتِّينَ وَالثَّلَاثِمِائَةِ، فَإِنَّهُ يُمْسِي يَوْمَئِذٍ وَقَدْ زَحْزَحَ نَفْسَهُ عَنِ النَّارِ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66527 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20122;
update hadith set arabic = 'عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « مَنْ غَدَا إِلَى الْمَسْجِدِ أَوْ رَاحَ، أَعَدَّ اللهُ لَهُ فِي الْجَنَّةِ نُزُلًا كُلَّمَا غَدَا أَوْ رَاحَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5436 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20123;
update hadith set arabic = 'عَنْهُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « يَا نِسَاءَ المُسْلِمَاتِ لَا تَحْقِرَنَّ جَارَةٌ لِجَارَتِهَا وَلَوْ فِرْسِنَ شَاةٍ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20124;
update hadith set arabic = 'عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « الْإِيمَانُ بِضْعٌ وَسَبْعُونَ، أَوْ بِضْعٌ وَسِتُّونَ شُعْبَةً: فَأَفْضَلُهَا قَوْلُ لَا إِلَهَ إِلَّا اللهُ، وَأَدْنَاهَا إِمَاطَةُ الْأَذَى عَنِ الطَّرِيقِ، وَالْحَيَاءُ شُعْبَةٌ مِنَ الْإِيمَانِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6468 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20125;
update hadith set arabic = 'عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: " بَيْنَمَا رجلٌ يَمْشِى بطريقٍ اشتَدَّ عَلَيْهِ العَطَشُ، فوَجَدَ بِئْرًا فَنَزَلَ فِيهَا فَشَرِبَ، ثُمَّ خَرَجَ فَإِذَا كَلْبٌ يَلْهَثُ يَأْكُلُ الثَّرَى مِنَ العَطَشِ، فَقَالَ الرجلُ: لَقَدْ بَلَغَ هَذَا الكَلْبَ مِنَ العَطَشِ مِثْلُ الذِي كَانَ قَدْ بَلَغَ مِنِّى، فنَزَلَ البِئْرَ فَمَلَأَ خُفَّهُ مَاءً ثُمَّ أَمْسَكَهُ بِفِيهِ، حَتَّى رَقِيَ فَسَقَى الكَلْبَ، فشَكَرَ اللهُ لَهُ فَغَفَرَ لهُ" قَالُوا : يَارَسُولَ اللَّهِ إنَّ لَنَا فِي البَهَائِمِ أَجْرًا؟ فَقَالَ: فِي كُلِّ كَبِدٍ رَطْبَةٍ أَجْرٌ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10100 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20126;
update hadith set arabic = 'الحَادِي عَشَرَ: عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « لَقَدْ رَأَيْتُ رَجُلًا يَتَقَلَّبُ فِي الجنةِ فِي شَجَرَةٍ قَطَعَهَا مِنْ ظَهْرِ الطَّرِيقِ كَانتْ تُؤْذِى المسلمينَ».((رَوَاهُ مُسْلِمٌ)). وَفِي رِوَايَةٍ: مَرَّ رَجُلٌ بِغُصْنِ شَجَرَةٍ عَلَى ظَهْرِ طَرِيقٍ فقالَ: واللهِ لأُنَحِّيَنَّ هَذَا عَنِ المسلمينَ لَا يُؤْذِيهِمْ، فَأُدْخِلَ الجَنَّةَ . وَفِي رِوَايَةٍ لَهُمَا: بَيْنَمَا رَجُلٌ يَمْشِى بِطَرِيقٍ وَجَدَ غُصْنَ شَوْكٍ عَلَى الطَّرِيقِ، فَأَخَّرَهُ فَشَكَرَهُ اللهُ لهُ، فَغَفَرَ لهُ .', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20127;
update hadith set arabic = 'الثَّانِي عَشَرَ: عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: « مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ، ثُمَّ أَتَى الْجُمُعَةَ، فَاسْتَمَعَ وَأَنْصَتَ، غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ وَزِيَادَةُ ثَلَاثَةِ أَيَّامٍ، وَمَنْ مَسَّ الحَصَا فَقَدْ لَغَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5433 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20128;
update hadith set arabic = 'الثَّالِثَ عَشَرَ: عنهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « إِذَا تَوَضَّأَ الْعَبْدُ الْمُسْلِمُ، أَوِ الْمُؤْمِنُ فَغَسَلَ وَجْهَهُ خَرَجَ مِنْ وَجْهِهِ كُلُّ خَطِيئَةٍ نَظَرَ إِلَيْهَا بِعَيْنَيْهِ مَعَ الْمَاءِ، أَوْ آخِرِ قَطْرِ الْمَاءِ، فَإِذَا غَسَلَ رِجْلَيْهِ خَرَجَتْ كُلُّ خَطِيئَةٍ مَشَتْهَا رِجْلَاهُ مَعَ الْمَاءِ أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ حَتَّى يَخْرُجَ نَقِيًّا مِنَ الذُّنُوبِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3284 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20129;
update hadith set arabic = 'الرَّابِعَ عَشَرَ: عَنْهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « الصَّلَوَاتُ الخَمْسُ، وَالجُمُعَةُ إِلَى الجُمُعَةِ، وَرَمَضَانُ إِلَى رَمَضَانَ مُكَفِّرَاتٌ لِمَا بَيْنَهُنَّ إِذَا اجْتُنِبَتِ الكَبَائِرُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20130;
update hadith set arabic = 'الخَامِسَ عَشَرَ: عَنْهُ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: " أَلَا أَدُلُّكُمْ عَلَى مَا يَمْحُو اللهُ بِهِ الْخَطَايَا، وَيَرْفَعُ بِهِ الدَّرَجَاتِ؟" قَالُوا: بَلَى يَا رَسُولَ اللهِ، قَالَ: " إِسْبَاغُ الْوُضُوءِ عَلَى الْمَكَارِهِ، وَكَثْرَةُ الْخُطَا إِلَى الْمَسَاجِدِ، وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ، فَذَلِكُمُ الرِّبَاطُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3574 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20131;
update hadith set arabic = 'السَّادِسَ عَشَرَ: عَنْ أَبِي مُوسَى الأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « مَنْ صَلَّى البَرْدَيْنِ دَخَلَ الجَنَّةَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20132;
update hadith set arabic = 'السَّابِعَ عَشَرَ: عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « إِذَا مَرِضَ الْعَبْدُ أَوْ سَافَرَ كُتِبَ لَهُ مِثْلُ مَا كَانَ يَعْمَلُ مُقِيمًا صَحِيحًا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3553 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20133;
update hadith set arabic = 'الثَّامِنَ عَشَرَ: عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « كُلُّ مَعْرُوفٍ صَدَقَةٌ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20134;
update hadith set arabic = 'التَّاسِعَ عَشَرَ: عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: " مَا مِنْ مُسْلِمٍ يَغرِسُ غَرسًا إِلَّا كَانَ مَا أُكِلَ مِنْهُ لَهُ صَدَقَةً، وَمَا سُرِقَ مِنْهُ لَهُ صَدَقَةً، وَلَا يَرْزَؤُهُ أَحَدٌ إِلَّا كَانَ لَهُ صَدَقَةً" ((رَوَاهُ مُسْلِمٌ. )) وَفِي رِوَايَةٍ لَهُ: " فَلَا يَغرِسُ المُسْلِمُ غَرسًا، فَيَأْكُلَ مِنْهُ إِنْسَانٌ وَلَا دَابَّةٌ وَلَا طَيْرٌ إِلَّا كَانَ لَهُ صَدَقَةً إِلَى يَوْمِ القِيَامَةِ". وَفِي رِوَايَةٍ لَهُ: " لَا يَغرِسُ مُسْلِمٌ غَرسًا، وَلَا يَزْرَعُ زَرْعًا، فَيَأْكُلُ مِنْهُ إِنْسَانٌ وَلَا دَابَّةٌ وَلَا شَىْءٌ إِلَّا كَانَتْ لَهُ صَدَقَةً" وَرَوَيَاهُ جَمِيعاً مِنْ رِوَايَةِ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3911 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20135;
update hadith set arabic = 'عَنْهُ قَالَ: أَرَادَ بَنُو سَلِمَةَ أَنْ يَنْقُلُوا قُرْبَ المَسْجِدِ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُمْ: " إِنَّهُ قَدْ بَلَغَنِي أَنَّكُمْ تُرِيدُونَ أَنْ تَنْتَقِلُوا قُربَ المَسْجِدِ؟" فَقَالُوا: نَعَمْ يَارَسُولَ اللَّهِ قَدْ أَرَدْنَا ذَلِكَ، فَقَالَ:"بَنِي سَلِمَةَ دِيارَكُم؛ تُكتَبْ آثارُكُم ، ديارَكُم، تُكتَبْ آثَارُكُم".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3713 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20136;
update hadith set arabic = 'الحَادِي وَالعِشْرُونَ: عَنْ أَبِي المُنْذِرِ أُبَيِّ بْنِ كَعْبٍ رَضيَ اللهُ عنه قَالَ: كَانَ رَجُلٌ لَا أَعْلَمُ رَجُلًا أَبْعَدَ مِنَ الْمَسْجِدِ مِنْهُ، وَكَانَ لَا تُخْطِئُهُ صَلَاةٌ فَقِيلَ لَهُ، أَوْ فَقُلْتُ لَهُ: لَوْ اشْتَرَيْتَ حِمَارًا تَرْكَبُهُ فِي الظَّلْمَاءِ، وَفِي الرَّمْضَاءِ، فَقَالَ: مَا يَسُرُّنِي أَنَّ مَنْزِلِي إِلَى جَنْبِ الْمَسْجِدِ، إِنِّي أُرِيدُ أَنْ يُكْتَبَ لِي مَمْشَايَ إِلَى الْمَسْجِدِ، وَرُجُوعِي إِذَا رَجَعْتُ إِلَى أَهْلِي، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «قَدْ جَمَعَ اللهُ لَكَ ذَلِكَ كُلَّهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3561 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20137;
update hadith set arabic = 'الثَّانِي وَالعِشْرُونَ: عَنْ أَبِي مُحَمَّدٍ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «أَرْبَعُونَ خَصْلَةً أَعْلَاهَا مَنيحةُ العَنزِ، مَا مِنْ عَامِلٍ يَعمَلُ بِخَصْلةٍ مِنْهَا رَجَاءَ ثَوَابِهَا وَتَصْدِيقَ مَوْعُودِها إِلَّا أَدْخَلَهُ اللَّهُ بِهَا الجَنَّةَ».', updated_at = now() where id = 20138;
update hadith set arabic = 'الثَّالِثُ وَالعِشْرُونَ: عَنْ عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: " اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرةٍ" ((مُتَّفَقٌ عَلَيْهِ)) . وَفِي رِوَايَةٍ لَهُمَا عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: " مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا سَيُكَلِّمُهُ رَبُّهُ لَيْسَ بَيْنَهُ وَبَيْنَهُ تُرْجُمَانٌ فَيَنْظُرُ أَيْمَنَ مِنْهُ فَلَا يَرَى إِلَّا مَا قَدَّمَ، وَيَنْظُرُ أَشْأَمَ مِنْهُ فَلَا يَرَى إِلَّا مَا قَدَّمَ، يَنْظُرُ بَيْنَ يَدَيْهِ فَلَا يَرَى إِلَّا النَّارَ تِلْقَاءَ وَجْهِهِ، فَاتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ، فَمَنْ لَمْ يَجِدْ فَبِكَلِمَةٍ طَيِّبَةٍ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6615 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20139;
update hadith set arabic = 'الرَّابِعُ وَالعِشْرُونَ: عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِنَّ اللهَ لَيَرْضَى عَنِ الْعَبْدِ أَنْ يَأْكُلَ الْأَكْلَةَ فَيَحْمَدَهُ عَلَيْهَا ، أَوْ يَشْرَبَ الشَّرْبَةَ فَيَحْمَدَهُ عَلَيْهَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5798 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20140;
update hadith set arabic = 'الخَامِسُ وَالعِشْرُونَ: عَنْ أَبِي مُوسَ رَضِيَ اللَّهُ عَنْهُ ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "عَلَى كُلِّ مُسْلِمٍ صَدَقَةٌ" قَالَ : أَرَأَيْتَ إِنْ لَمْ يَجِدْ؟ قَالَ: أَرَأَيْتَ إِنْ لَمْ يَسْتَطِعْ؟ قَالَ: "يُعِينُ ذَا الحَاجَةِ المَلْهُوفَ" قَالَ: أَرَأَيْتَ إِنْ لَمْ يَسْتَطِعْ؟ قَالَ: "يَأْمُرُ بِالمَعْرُوفِ أَوِ الخَيْرِ" قَالَ : أَرَأَيْتَ إِنْ لَمْ يَفْعَلْ؟ قَالَ: يُمسِكُ عَنِ الشَّرِّ فَإِنَّهَا صَدَقَةٌ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20141;
update hadith set arabic = '- وَعَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا وَعِنْدَهَا امْرَأَةٌ قَالَ: مَنْ هَذِهِ؟ قَالَتْ: هَذِهِ فُلَانَةُ تَذْكُرُ مِنْ صَلَاتِهَا قَالَ: « مَهْ عَلَيْكُمْ بِمَا تُطِيقُونَ، فَوَاللَّهِ لَا يَمَلُّ اللَّهُ حَتَّى تَمَلُّوا» وَكَانَ أَحَبَّ الدِّينِ إِلَيْهِ مَا دَاوَمَ صَاحِبُهُ عَلَيْهِ.', updated_at = now() where id = 20142;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ ثَلَاثَةُ رَهْطٍ إِلَى بُيُوتِ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَسْأَلُونَ عَنْ عِبَادَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا أُخْبِرُوا كَأَنَّهُمْ تَقَالُّوهَا وَقَالُوا: أَيْنَ نَحْنُ مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ غَفَرَ اللَّهُ لَهُ تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ. قَالَ أَحَدُهُمْ: أَمَّا أَنَا فَأُصَلِّي اللَّيْلَ أَبَداً وَقَالَ الآخَرُ: وَأَنَا أَصُومُ الدَّهْرَ أَبَداً وَلَا أُفْطِرُ، وَقَالَ الآخَرُ: وَأَنَا أَعْتَزِلُ النِّسَاءَ فَلَا أَتَزَوَّجُ أَبَداً، فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْهِمْ فَقَالَ: «أَنْتُمُ الَّذِينَ قُلْتُمْ كَذَا وَكَذَا؟! أَمَا وَاللَّهِ إِنِّي لَأَخْشَاكُمْ لِلَّهِ وَأَتْقَاكُمْ لَهُ لَكِنِّي أَصُومُ وَأُفْطِرُ، وَأُصَلِّي وَأَرْقُدُ، وَأَتَزَوَّجُ النِّسَاءَ، فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20143;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "هَلَكَ المُتَنَطِّعُونَ" قَالَهَا ثَلَاثاً ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20144;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « إِنَّ الدِّينَ يُسْرٌ، وَلَنْ يُشَادَّ الدِّينَ إِلَّا غَلَبَهُ، فَسَدِّدُوا وَقَارِبُوا وَأَبْشِرُوا، وَاسْتَعِينُوا بِالْغَدْوَةِ وَالرَّوْحَةِ وَشَيْءٍ مِنَ الدُّلْجَةِ» ((رَوَاهُ البُخَارِيُّ)). وَفِي رِوَايَةٍ لَهُ : سَدِّدُوا وَقَارِبُوا وَاغْدُوا وَرُوحُوا، وَشَيْءٌ مِنَ الدُّلْجَةِ، القَصْدَ القَصْدَ تَبْلُغُوا .', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5795 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20145;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ المَسْجِدَ فَإِذَا حَبْلٌ مَمْدُودٌ بَيْنَ السَّارِيَتَيْنِ فَقَالَ: "مَا هَذَا الحَبْلُ" قَالُوا : هَذَا حَبْلٌ لِزَيْنَبَ، فَإِذَا فَتَرَتْ تَعَلَّقَتْ بِهِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ " حُلُّوهُ، لِيُصَلِّ أَحَدُكُمْ نَشَاطَهُ فَإِذَا فَتَرَ فَلْيَرْقُدْ".', updated_at = now() where id = 20146;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « إِذَا نَعَسَ أَحَدُكُمْ وَهُوَ يُصَلِّي، فَلْيَرْقُدْ حَتَّى يَذْهَبَ عَنْهُ النَّوْمُ، فَإِنَّ أَحَدَكُمْ إِذَا صَلَّى وَهُوَ نَاعِسٌ لَا يَدْرِي لَعَلَّهُ يَذْهَبُ وَيَسْتَغْفِرُ فَيَسُبُّ نَفْسَهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5789 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20147;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ اللَّهِ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: «كُنْتُ أُصَلِّى مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّلَوَاتِ، فَكَانَتْ صَلَاتُهُ قَصْدًا وَخُطْبَتُهُ قَصْدًا».', updated_at = now() where id = 20148;
update hadith set arabic = 'عَنْ أَبِي جُحَيْفَةَ وَهْبِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: آخَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ سَلْمَانَ وَأَبِى الدَّرْدَاءِ ، فَزَارَ سَلْمَانُ أَبَا الدَّرْدَاءِ، فَرَأَى أُمَّ الدَّرْدَاءِ مُتَبَذِّلَةً فَقَالَ: مَا شأنُكِ قَالَتْ: أَخُوكَ أَبُو الدَّرْدَاءِ لَيْسَ لَهُ حَاجَةٌ فِي الدُّنْيَا، فَجَاءَ أَبُو الدَّرَادَاءِ فَصَنَعَ لَهُ طَعَامًا، فَقَالَ لَهُ: كُلْ فَإِنِّى صَائِمٌ، قَالَ: مَا أَنَا بِآكِلٍ حَتَّى تَأْكُلَ، فَأَكَلَ، فَلَمَّا كَانَ اللَّيْلُ ذَهَبَ أَبُو الدَّرْدَاءِ يَقُومُ فَقَالَ لَهُ: نَمْ، فَنَامَ، ثُمَّ ذَهَبَ يَقُومُ فَقَالَ لَهُ : نَمْ، فَلَمَّا كَانَ مِنْ آخِرِ اللَّيْلِ قَالَ سَلْمَانُ: قُمِ الآنَ: فَصَلَّيَا جَمِيعًا، فَقَالَ لَهُ سَلْمَانُ: إِنَّ لِرَبِّكَ عَلَيْكَ حَقًّا، وَإِنَّ لِنَفْسِكَ عَلَيْكَ حَقًّا، وَلِأَهْلِكَ عَلَيْكَ حَقًّا، فَأَعْطِ كُلَّ ذِى حَقٍّ حَقَّهُ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «صَدَقَ سَلْمَانُ».', updated_at = now() where id = 20149;
update hadith set arabic = 'عَنْ أَبِي مُحَمَّدٍ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أُخْبِرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنِّي أَقُولُ: وَاللَّهِ لَأَصُومَنَّ النَّهَارَ، وَلَأَقُومَنَّ اللَّيْلَ مَاعِشْتُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَنْتَ الَّذِي تَقُولُ ذَلِكَ؟ فَقُلْتُ لَهُ: قَدْ قُلْتُهُ بِأَبِى أَنْتَ وَأُمِّى يَا رَسُولَ اللَّهِ. قَالَ:"فَإِنَّكَ لَا تَسْتَطِيعُ ذَلِكَ؛ فَصُمْ وَأَفْطِرْ، وَنَمْ وَقُمْ، وَصُمْ مِنَ الشَّهْرِ ثَلَاثَةَ أَيَّامٍ فَإِنَّ الحَسَنَةَ بِعَشْرِ أَمْثَالِهَا، وَذَلِكَ مِثْلُ صِيَامِ الدَّهْرِ" قُلْتُ: فَإِنِّى أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ قَالَ: فَصُمْ يَوْمًا وَأَفْطِرْ يَوْمَيْنِ، قُلْتُ: فَإِنِّى أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ، قَالَ: "فَصُمْ يَوْماً وَأَفْطِرْ يَوْماً، فَذَلِكَ صِيَامُ دَاوُدَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ أَعْدَلُ الصِّيَامِ". وَفِي رِوَايَةٍ: "وَهُوَ أَفْضَلُ الصِّيَامِ" فَقُلْتُ : فَإِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: " لَا أَفْضَلَ مِنْ ذَلِكَ" وَلَأَنْ أَكُونَ قَبِلْتُ الثَّلَاثَةَ الأَيَّامَ الَّتِي قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَبُّ إِلَيَّ مِنْ أَهْلِي وَمَا لِي. وَفِي رِوَايَةٍ: "أَلَمْ أُخْبَرْ أَنَّكَ تَصُومُ النَّهَارَ وَتَقُومُ اللَّيْلَ؟" قُلْتُ : بَلَى يَا رَسُولَ اللَّهِ قَالَ: "فَلَا تَفْعَلْ: صُمْ وَأَفْطِرْ ، وَنَمْ وَقُمْ فَإِنَّ لِجَسَدِكَ عَلَيْكَ حَقّاً، وَإِنَّ لِعَيْنَيْكَ عَلَيْكَ حَقّاً، وَإِنَّ لِزَوْجِكَ عَلَيْكَ حَقّاً، وَإِنَّ لِزَوْرِكَ عَلَيْكَ حَقّاً، وَإِنَّ بِحَسْبِكَ أَنْ تَصُومَ فِي كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ ، فَإِنَّ لَكَ بِكُلِّ حَسَنَةٍ عَشْرَ أَمْثَالِهَا، فَإِنَّ ذَلِكَ صِيَامُ الدَّهْرِ" فَشَدَّدْتُ فَشُدِّدَ عَلَيَّ، قُلْتُ: يَا رَسُولَ اللَّهِ إِنِّي أَجِدُ قُوَّةً، قَالَ: "صُمْ صِيَامَ نَبِيِّ اللَّهِ دَاوُدَ وَلَا تَزِدْ عَلَيْهِ" قُلْتُ: وَمَا كَانَ صِيَامُ دَاوُدَ؟ قَالَ: "نِصْفَ الدَّهْرِ" فَكَانَ عَبْدُ اللَّهِ يَقُولُ بَعْدَمَا كَبِرَ: يَا لَيْتَنِي قَبِلْتُ رُخْصَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَفِي رِوَايَةٍ: " أَلَمْ أُخْبَرْ أَنَّكَ تَصُومُ الدَّهْرَ، وَتَقْرَأُ القُرْآنَ كُلَّ لَيْلةٍ؟" فَقُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، وَلَمْ أُرِدْ بِذَلِكَ إِلَّا الخَيْرَ قَالَ: "فَصُمْ صَوْمَ نَبِيِّ اللَّهِ دَاوُدَ، فَإِنَّهُ كَانَ أَعْبَدَ النَّاسِ، وَاقْرَأِ القُرْآنَ كُلَّ شَهْرٍ" قُلْتُ: يَا نَبِيَّ اللَّهِ إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ؟ قَالَ: "فَاقْرَأْهُ فِي كُلِّ عِشْرِينَ" قُلْتُ: يَا نَبِيَّ اللَّهِ إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ؟ قَالَ: "فَاقْرَأْهُ فِي كُلِّ عَشْرٍ" قُلْتُ يَا نَبِيَّ اللَّهِ إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ؟ قَالَ: "فَاقْرَأْهُ فِي كُلِّ سَبْعٍ وَلَا تَزِدْ عَلَى ذَلِكَ". فَشَدَّدْتُ فَشُدِّدَ عَلَيَّ ، وَقَالَ لِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّكَ لَا تَدْرِي لَعَلَّكَ يَطُولُ بِكَ عُمُرٌ" قَالَ: فَصِرْتُ إِلَى الَّذِي قَالَ لِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا كَبِرْتُ وَدِدْتُ أَنِّي كُنْتُ قَبِلْتُ رُخْصَةَ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَفِي رِوَايَةٍ: " وَإِنَّ لِوَلَدِكَ عَلَيْكَ حَقّاً" وَفِي رِوَايَةٍ: " لَا صَامَ مَنْ صَامَ الأَبَدَ" ثَلَاثاً. وَفِي رِوَايَةٍ: "أَحَبُّ الصِّيَامِ إِلَى اللَّهِ تَعَالَى صِيَامُ دَاوُدَ، وَأَحَبُّ الصَّلَاةِ إِلَى اللَّهِ تَعَالَى صَلَاةُ دَاوُدَ: كَانَ يَنَامُ نِصْفَ اللَّيْلِ، وَيَقُومُ ثُلُثَهُ، وَيَنَامُ سُدُسَهُ، وَكَانَ يَصُومُ يَوْمًا ويُفطِرُ يَوْمًا، وَلَا يَفِرُّ إِذَا لَاقَى". وَفِي رِوَايَةٍ: أَنْكَحَنِي أَبِي امْرَأَةً ذَاتَ حَسَبٍ، وَكَانَ يَتَعَاهَدُ كَنَّتَهُ-أَيْ : امْرَأَةَ وَلَدِهِ- فَيَسْأَلُهَا عَنْ بَعْلِهَا، فَتَقُولُ لَهُ : نِعْمَ الرَّجُلُ مِنْ رَجُلٍ لَمْ يَيطَأْ لَنَا فِرَاشاً وَلَمْ يُفَتِّشْ لَنَا كَنَفاً مُنْذُ أَتَيْنَاهُ. فَلَمَّا طَالَ ذَلِكَ عَلَيْهِ ذَكَرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ: "الْقَنِى بِهِ" فَلَقِيتُهُ بَعْدَ ذَلِكَ فَقَالَ: "كَيْفَ تَصُومُ؟" قُلْتُ كُلَّ يَوْمٍ، قَالَ: "وَكَيْفَ تَخْتِمُ؟" قُلْتُ: كُلَّ لَيْلةٍ، وَذَكَرَ نَحْوَن مَا سَبَقَ ، وَكَانَ يَقْرَأُ عَلَى بَعْضِ أَهْلِهِ السُّبْعَ الَّذِي يَقْرَؤُهُ، يَعْرِضُهُ مِنَ النَّهَارِ لِيَكُونَ أَخَفَّ عَلَيْهِ بِاللَّيْلِ، وَإِذَا أَرَادَ أَنْ يَتَقَوَّى أَفْطَرَ أَيَّاماً وَأَحْصَى وَصَامَ مِثْلَهُنَّ كَرَاهِيَةَ أَنْ يَتْرُكَ شَيْئاً فَارَقَ عَلَيْهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. كُلُّ هَذِهِ الرِّوَايَاتِ صَحِيحَةٌ مُعْظَمُهَا فِي الصَّحِيحَيْنِ وَقَلِيلٌ مِنْهَا فِي أَحَدِهِمَا. .', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4541 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20150;
update hadith set arabic = 'عَنْ أَبِي رِبْعِيٍّ حَنْظَلَةَ بْنِ الرَّبِيعِ الأُسَيْدِى الكَاتِبِ أَحَدِ كُتَّابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَقِيَنِي أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: كَيْفَ أَنْتَ يَا حَنْظَلَةُ؟ قُلْتُ: نَافَقَ حَنْظَلَةُ؟ قُلْتُ: نَافَقَ حَنْظَلَةُ ( قَالَ: سُبْحَانَ اللَّهِ مَا تَقُولُ؟ ( قُلْتُ: نَكُونُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُذَكِّرُنَا بِالجَنَّةِ وَالنَّارِ كَأَنَّا رَأْيَ عَيْنٍ، فَإِذَا خَرَجْنَا مِنْ عِنْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَافَسْنَا الأَزْوَاجَ وَالأَوْلَادَ وَالضَّيْعَاتِ نَسِينَا كَثِيرًا. قَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ : فَوَاللَّهِ إِنَّا لَنَلْقَى مِثْلَ هَذَا، فَانْطَلَقْتُ أَنَا وَأَبُو بَكْرٍ حَتَّى دَخَلْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقُلْتُ: نَافَقَ حَنْظَلَةُ يَا رَسُولَ اللَّهِ ( فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "وَمَا ذَاكَ؟" قُلْتُ: يَا رَسُولَ اللَّهِ نَكُونُ عِنْدَكَ تُذَكِّرُنَا بِالنَّارِ وَالجَنَّةِ كَأَنَّا رَأْيَ العَيْنِ، فَإِذَا خَرَجْنَا مِنْ عِنْدِكَ عَافَسْنَا الأَزْوَاجَ وَالأَوْلَادَ وَالضَّيْعَاتِ نَسِينًا كَثِيرًا. فَقَالَ رَسُولُ اللَّهِ 0: "وَالَّذِي نَفْسِي بِيَدِهِ لَوْ تَدُومُونَ عَلَى مَا تَكُونُونَ عِنْدِي وَفِي الذِّكْرِ لَصَافَحَتْكُمُ المَلَائِكَةُ عَلَى فُرُشِكُمْ وَفِي طُرُقِكُمْ، وَلَكِنْ يَا حَنْظَلَةُ سَاعَةً وَسَاعَةً" ثَلَاثَ مَرَّاتٍ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5846 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20151;
update hadith set arabic = '- وَعَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَيْنَمَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ إِذَا هُوَ بِرَجُلٍ قَائِمٍ، فَسَأَلَ عَنْهُ فَقَالُوا: أَبُو إِسْرَائِيلَ نَذَرَ أَنْ يَقُومَ فِي الشَّمْسِ وَلَا يَقْعُدَ، وَلَا يَسْتَظِلَّ وَلَا يَتَكَلَّمَ، وَيَصُومَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مُرُوهُ فَلْيَتَكَلَّمْ وَلْيَسْتَظِلَّ وَلْيَقْعُدْ وَلْيُتِمَّ صَوْمَهُ».', updated_at = now() where id = 20152;
update hadith set arabic = 'عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « مَنْ نَامَ عَنْ حِزْبِهِ مِنَ الليلِ، أَوْ عَنْ شَيْءٍ مِنهُ فَقَرَأَهُ مَا بَيْنَ صَلَاةِ الفَجْرِ وَصَلَاةِ الظُّهْرِ، كُتِبَ لهُ كَأَنَّمَا قَرَأَهُ مِنَ الليلِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5443 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20153;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا عَبْدَ اللَّهِ لَا تَكُنْ مِثْلَ فُلَانٍ، كَانَ يَقُومُ اللَّيْلَ فَتَرَكَ قِيَامَ اللَّيْلِ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11270 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20154;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رسولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا فَاتَتْهُ الصَّلَاةُ مِنَ الليلِ مِن وَجَعٍ أَوْ غَيْرِهِ، صَلَّى مِنَ النَّهَارِ ثِنْتَيْ عَشْرَةَ رَكْعَةً".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4829 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20155;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «دَعُونِي مَاتَرَكْتُكُمْ: إِنَّمَا أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ كَثْرَةُ سُؤَالِهِمْ ، وَاخْتِلَافُهُمْ عَلَى أَنْبِيَائِهِمْ، فَإِذَا نَهَيْتُكُمْ عَنْ شَيْءٍ فَاجْتَنِبُوهُ، وَإِذَا أَمَرْتُكُمْ بِأَمْرٍ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20156;
update hadith set arabic = 'عَنْ أَبِي نَجِيحٍ العِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: "وَعَظَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَوْعِظَةً بَلِيغَةً وَجِلَتْ مِنْهَا القُلُوبُ وَذَرَفَتْ مِنْهَا العُيُونُ، فَقُلْنَا: يَا رَسُولَ اللهِ كَأَنَّهَا مَوْعِظَةُ مُوَدِّعٍ فَأَوْصِنَا. قَالَ: "أُوصِيكُمْ بِتَقْوَى اللَّهِ ، وَالسَّمْعِ وَالطَّاعَةِ وَإِنْ تَأَمَّرَ عَلَيْكُمْ عَبْدٌ حَبَشِيٌّ، وَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا. فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الخُلَفَاءِ الرَّاشِدِينَ المَهْدِيينَ، عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ، وَإِيَّاكُمْ وَمُحْدَثَاتِ الأُمُورِ فَإِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66529 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20157;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ إِلَّا مَنْ أَبَى " . قِيلَ: وَمَنْ يَأْبَى يَا رَسُولَ اللهِ قَالَ: " مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ، وَمَنْ عَصَانِي فَقَدْ أَبَى".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4947 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20158;
update hadith set arabic = 'عَنْ أَبِي مُسْلِمٍ، وَقِيلَ : أَبِي إِيَاسٍ سَلَمَةَ بْنِ عَمْرِو بْنِ الْأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ ، أَنَّ رَجُلًا أَكَلَ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِشِمَالِهِ فَقَالَ: "كُلْ بِيَمِينِكَ" قَالَ: لَا أَسْتَطِيعُ. قَالَ: " لَا اسْتَطَعْتَ" مَا مَنَعَهُ إِلَّا الْكِبْرُ، فَمَا رَفَعَهَا إِلَى فِيهِ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3372 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20159;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ اللَّهِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَتُسَوُّنَّ صُفُوفَكُم أَوْ لَيُخَالِفَنَّ اللَّهُ بَيْنَ وُجُوهِكُم " ((مُتَّفَقٌ عَلَيْهِ)) . وَفِي رِوَايَةٍ لِمُسْلِمٍ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسَوِّي صُفُوفَنَا حَتَّى كَأَنَّمَا يُسَوِّي بِهَا القِدَاحَ ،حتَّى إِذَا رَأَى أَنَّا قَدْ عَقَلْنَا عَنهُ ثُمَّ خَرَجَ يَوْمًا، فَقَامَ حتَّى كَادَ أَنْ يُكَبِّرُ، فَرَأَى رَجُلاً بَادِيًا صَدرُهُ فَقَالَ: " عِبَادَ اللَّهِ لَتُسَوُّنَّ صُفُوفَكُم أَوْ لَيُخَالِفَنَّ اللَّهُ بَيْنَ وُجُوهِكُم".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3085 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20160;
update hadith set arabic = 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: احْتَرَقَ بَيْتٌ بِالمَدِينَةِ عَلَى أهْلِهِ مِنَ اللَّيْلِ، فَلَمَّا حُدِّثَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَأنِهِم قالَ «إنَّ هَذِهِ النارَ عَدُوٌّ لَكُمْ، فَإِذَا نِمْتُم فَأَطْفِئُوهَا عَنْكُمْ».', updated_at = now() where id = 20161;
update hadith set arabic = 'عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : «إِنَّ مَثَلَ مَا بَعَثَنِي اللَّهُ بِهِ مِنَ الهُدَى وَالعِلْمِ كَمَثَلِ غَيْثٍ أَصَابَ أَرْضًا فَكَانَتْ مِنْهَا طَائِفَةٌ طَيِّبَةٌ، قَبِلَتِ المَاءَ فَأَنْبَتَتِ الكَلَأَ وَالعُشْبَ الكَثِيرَ، وَكَانَ مِنْهَا أَجَادِبُ أَمْسَكَتِ المَاءَ، فَنَفَعَ اللَّهُ بِهَا النَّاسَ فَشَرِبُوا مِنْهَا وَسَقَوْا وَزَرَعُوا. وَأَصَابَ طَائِفَةً مِنْهَا أُخْرَى ، إِنَّمَا هِيَ قِيعَانٌ لاَ تُمْسِكُ مَاءً وَلاَ تُنْبِتُ كَلَأً. فَذَلِكَ مَثَلُ مَنْ فَقُهَ فِي دِينِ اللَّهِ، وَنَفَعَهُ بِمَا بَعَثَنِى اللَّهُ بِهِ، فَعَلِمَ وَعَلَّمَ، وَمَثَلُ مَنْ لَمْ يَرْفَعْ بِذَلِكَ رَأْسًا، وَلَمْ يَقْبَلْ هُدَى اللَّهِ الَّذِي أُرْسِلْتُ بِهِ» ((مُتَّفَقٌ عَلَيْهِ)) . فَقُهَ بِضَمِّ القَافِ عَلَى المَشْهُورِ، وَقِيلَ: بِكَسْرِهَا، أَيْ: صَارَ فَقِيهاً.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20162;
update hadith set arabic = 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «مَثَلِي ومَثَلُكم كَمَثَلِ رجلٍ أَوْقَدَ نارًا فَجَعَلَ الجنادِبُ والفَرَاشُ يَقَعْنَ فِيهَا وَهُوَ يَذُبُّهُنَّ عَنْهَا وَأَنَا آخذٌ بحُجَزِكُم عَنِ النَّارِ، وَأَنْتُمْ تَفَلَّتُونَ مِنْ يَدَيَّ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4970 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20163;
update hadith set arabic = 'عَنْهُ أنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَمَرَ بِلَعْقِ الأَصَابِعِ والصَّحْفَةِ وَقَالَ: "إنَّكُمْ لَا تَدْرُونَ فِي أَيِّهَا البَرَكَةُ" ((رَوَاهُ مُسْلِمٌ)). وَفِي رِوَايَةٍ لَهُ: " إِذَا وَقَعَتْ لُقْمَةُ أَحَدِكُمْ . فَلْيَأْخُذْهَا فَلْيُمِطْ مَاكَانَ بِهَا مِنْ أَذًى، وَلْيَأْكُلْهَا، وَلَا يَدَعْهَا لِلشَّيْطَانِ، وَلَا يَمْسَحْ يَدَهُ بِالمِنْدِيلِ حَتَّى يَلْعَقَ أَصَابِعَهُ، فَإِنَّهُ لَا يَدْرِي فِي أَيِّ طَعَامِهِ البَرَكَةُ". وَفِي رِوَايَةٍ لَهُ: "إِنَّ الشَّيْطَانَ يَحْضُرُ أَحَدَكُمْ عِنْدَ كُلِّ شَيْءٍ مِنْ شَأْنِهِ حَتَّى يَحْضُرَهُ عِنْدَ طَعَامِهِ، فَإِذَا سَقَطَتْ مِنْ أَحَدِكُمُ اللُّقْمَةُ فَلْيُمِطْ مَا كَانَ بِهَا مِنْ أَذًى ، فَلْيَأْكُلْهَا، وَلَا يَدَعْهَا لِلشَّيْطَانِ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10103 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20164;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: قَامَ فِينَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَوْعِظَةٍ فَقَالَ: «يَا أَيُّهَا النَّاسُ إِنَّكُمْ مَحْشُورُونَ إِلَى اللَّهِ تَعَالَى حُفَاةً عُرَاةً غُرْلاً {كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُعِيدُهُ وَعْداً عَلَيْنَا إِنَّا كُنَّا فَاعِلِينَ} ((الأَنْبِيَاءُ: 103)) أَلَا وَإِنَّ أَوَّلَ الخَلَائِقِ يُكْسَى يَوْمَ القِيَامَةِ إِبْرَاهِيمُ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَلَا وَإِنَّهُ سَيُجَاءُ بِرِجَالٍ مِنْ أُمَّتِي ، فَيُؤْخَذُ بِهِمْ ذَاتَ الشِّمَالِ؛ فَأَقُولُ: يَارَبِّ أَصْحَابِي؛ فَيُقَالُ: إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ، فَأَقُولُ كَمَا قَالَ العَبْدُ الصَّالِحُ: {وَكُنْتُ عَلَيْهِمْ شَهِيداً مَا دُمْتُ فِيهِمْ} إِلَى قَوْلِهِ: { الْعَزِيزُ الْحَكِيمُ} ) ((المَائِدَةُ : 117،118)) فَيُقَالُ لِي : إِنَّهُمْ لَمْ يَزَالُوا مُرْتَدِّينَ عَلَى أَعْقَابِهِمْ مُنْذُ فَارَقْتَهُمْ» ((مُتَّفَقٌ عَلَيْهِ)). (46)', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20165;
update hadith set arabic = 'الحَادِي عَشَرَ: عَنْ أَبِي سَعِيدٍ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: نَهَى رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الخَذْفِ وَقَالَ: «إِنَّهُ لاَ يَقتُلُ الصَّيدَ، ولاَ يَنْكَأُ العَدُوَّ، وإِنَّهُ يَفْقَأُ العَيْنَ، ويَكسِرُ السِّنَّ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3080 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20166;
update hadith set arabic = 'عَنْ عَابِسِ بْنِ رَبِيعَةَ قَالَ: رَأَيْتُ عُمَرَ بْنَ الخَطَّابِ ، رَضِيَ اللَّهُ عَنْهُ ، يُقَبِّلُ الحَجَرَ -يَعْنِى الأَسْوَدَ- وَيَقُولُ:إِنِّي أَعْلَمُ أَنَّكَ حَجَرٌ مَا تَنْفَعُ وَلَا تَضُرُّ، وَلَوْلَا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يُقَبِّلُكَ مَا قَبَّلْتُكَ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20167;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: لَمَّا نَزَلَتْ عَلَى رَسُولِ اللهِ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : { لِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الْأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللهُ} الآيَةُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65285 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20168;
update hadith set arabic = 'عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا، قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّم: "مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ" (( مُتَّفَقٌ عَلَيْهِ)). وَفِي رِوَايَةٍ لِمُسْلِمٍ : "مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66514 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20169;
update hadith set arabic = 'عَنْ جَابِرٍ، رَضِيَ اللَّهُ عَنْهُ ، كَانَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذَا خَطَبَ احمرَّتْ عَيْنَاهُ، وَعَلَا صَوْتُهُ، وَاشْتَدَّ غَضَبُهُ، حَتَّى كَأَنَّهُ مُنذِرُ جيشٍ يَقُولُ: "صبَّحَكم ومسَّاكم" وَيَقُولُ: "بُعثتُ أَنَا والساعةُ كَهَاتَيْنِ" وَيَقْرِنُ بَيْنَ أُصْبُعَيْهِ؛ السَّبَّابَةِ وَالوُسْطَى، وَيَقُولُ: "أَمَّا بَعْدُ؛ فَإِنَّ خَيْرَ الحَدِيثِ كِتَابُ اللَّهِ وَخَيْرَ الهُدَى هُدَى مُحَمَّدٍ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَشَرَّ الأُمُورِ مُحْدَثَاتُهَا، وَكُلَّ بِدْعَةٍ ضَلَالَةٌ" ثُمَّ يَقُولُ: "أَنَا أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ. مَنْ تَرَكَ مَالًا فَلِأَهْلِهِ، وَمَنْ تَرَكَ دَيْنًا أَوْ ضَياعًا فإليَّ وَعَلَىَّ" ((رَوَاهُ مُسْلِمٌ)). وَعَنِ العِرْبَاضِ بْنِ سَارِيَةَ، رَضِيَ اللَّهُ عَنْهُ ، حَدِيثةُ السَّابِقُ فِي بَابِ المُحَافَظَةِ عَلَى السُّنَّةِ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65760 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20170;
update hadith set arabic = 'عَنْ أَبِي عَمْرٍو، جَرِيرِ بْنِ عَبْدِ اللَّهِ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: كُنَّا فِي صَدرِ النَّهَارِ عِندَ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَهُ قَومٌ عُرَاةٌ مُجْتَابِي النِّمَارِ، أَوِ العَبَاءِ، مُتَقَلِّدِي السُّيُوفِ، عَامَّتُهُم مِن مُضَرَ، بَل كُلُّهُم مِن مُضَرَ؛ فَتَمَعَّرَ وَجْهُ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لِمَا رَأَى بِهِم مِنَ الفَاقَةِ؛ فدَخَلَ ثُمَّ خَرجَ، فأَمَرَ بِلاَلاً فَأَذَّنَ وَأَقَامَ، فَصَلَّى ثُمَّ خَطَبَ؛ فَقَالَ: {يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ} إِلَى آخِرِ الآيَةِ: {إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا}، وَالآيَةَ الأُخْرَى الَّتِي فِي آخِرِ الحَشْرِ: {يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ} تَصَدَّقَ رَجُلٌ مِن دِينَارِهِ مِن دِرهَمِهِ مِن ثَوبِهِ مِن صَاعِ بُرِّهِ مِنْ صَاعِ تَمرِهِ _حتَّى قَالَ _ وَلَو بِشِقِّ تَمرَةٍ ,فَجَاءَ رَجُلٌ مِنَ الأَنصَارِ بِصُرَّةٍ كَادَت كَفُّهُ تَعجَزُ عَنْهَا، بَلْ قَد عَجَزَت، ثُمَّ تَتَابَعَ النَّاسُ حَتَّى رَأَيتُ كَومَينِ مِن طَعَامٍ وَثِيَابٍ، حَتَّى رَأَيتُ وَجهَ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَتَهَلَّلُ كَأَنَّهُ مُذْهَبَةٌ، فَقَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، « مَنْ سَنَّ فِي الإِسلاَمِ سُنَّةً حَسَنَةً فَلَهُ أَجْرُهَا، وَأَجْرُ مَنْ عَمِلَ بِهَا مِنْ بَعْدِهِ مِنْ غَيرِ أَنْ يَقْنُصَ مِن أُجُورِهِم شَيءٌ، وَمَنْ سَنَّ فِي الإِسلاَمِ سُنَّةً سَيِّئَةً كَانَ عَلَيهِ وِزْرُهَا وَوِزرُ مَنْ عَمِلَ بِهَا مِنْ بعدِهِ مِنْ غَيْرِ أَنْ يَنقُصَ مِن أَوزَارِهَم شَيْءٌ».', updated_at = now() where id = 20171;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «لَيْسَ مِنْ نَفْسٍ تُقْتَلُ ظُلماً إِلاَّ كَانَ عَلَى ابنِ آدَمَ الأَوَّلِ كِفْلٌ مِن دمِهَا لِأَنَّهُ كَانَ أوَّلَ مَن سَنَّ القَتْلَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3445 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20172;
update hadith set arabic = 'عَنْ أَبِي مَسْعُودٍ عُقْبَةَ بْنِ عَمْرٍو الأَنْصَارِيِّ البَدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20173;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «مَنْ دَعَا إِلَى هُدًى كَانَ لَهُ مِنَ الْأَجْرِ مِثْلُ أُجُورِ مَنْ تَبِعَهُ لَا يَنْقُصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا، وَمَنْ دَعَا إِلَى ضَلَالَةٍ كَانَ عَلَيْهِ مِنَ الْإِثْمِ مِثْلُ آثَامِ مَنْ تَبِعَهُ لَا يَنْقُصُ ذَلِكَ مِنْ آثَامِهِمْ شَيْئًا».', updated_at = now() where id = 20174;
update hadith set arabic = 'عَنْ العَبَّاسِ سَهْلُ بْنُ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ يَوْمَ خَيْبَرَ: "لَأُعْطِيَنَّ الرَّايَةَ غَدًا رَجُلًا يَفْتَحُ اللَّهُ عَلَى يَدَيْهِ، يُحِبُّ اللَّهَ وَرَسُولَهُ، وَيُحِبُّهُ اللَّهُ وَرَسُولُهُ" فَبَاتَ النَّاسُ يَدُوكُونَ لَيْلَتَهُمْ أَيُّهُمْ يُعْطَاهَا. فَلَمَّا أَصْبَحَ النَّاسُ غَدَوْا عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: كُلُّهُمْ يَرْجُو أَنْ يُعْطَاهَا، فَقَالَ: "أَيْنَ عَلِيُّ بْنُ أَبِى طَالِبٍ؟" فَقِيلَ: يَا رَسُولَ اللَّهِ هُوَ يَشْتَكِي عَيْنَيْهِ قَالَ: "فَأَرْسِلُوا إِلَيْهِ" فَأُتِيَ بِهِ ، فَبَصَقَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي عَيْنَيْهِ، وَدَعَا لَهُ، فَبَرَأَ حَتَّى كَأَنْ لَمْ يَكُنْ بِهِ وَجَعٌ، فَأَعْطَاهُ الرَّايَةَ. فَقَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ : يَا رَسُولَ اللَّهِ أُقَاتِلُهُمْ حَتَّى يَكُونُوا مِثْلَنَا؟ فَقَالَ: "انْفُذْ عَلَى رِسْلِكَ حَتَّى تَنْزِلَ بِسَاحَتِهِمْ، ثُمَّ ادْعُهُمْ إِلَى الإِسْلاَمِ، وَأَخْبِرْهُمْ بِمَا يَجِبُ عَلَيْهِمْ مِنْ حَقِّ اللَّهِ تَعَالَى فِيهِ، فَوَاللَّهِ لَأَنْ يَهْدِيَ اللَّهُ بِكَ رَجُلًا وَاحِدًا خَيْرٌ لَكَ مِنْ حُمْرُ النَّعَمِ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3409 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20175;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ فَتًى مِنْ أَسْلَمَ قَالَ: يَا رَسُولَ اللَّهِ إِنِّي أُرِيدُ الغَزْوَ وَلَيْسَ مَعِي مَا أَتَجَهَّزُ بِهِ؟ قَالَ: «ائْتِ فُلَانًا فَإِنَّهُ قَدْ كَانَ تَجَهَّزَ فَمَرِضَ» فَأَتَاهُ فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقْرِئُكَ السَّلَامَ وَيَقُولُ: أَعْطِنِي الَّذِي تَجَهَّزْتَ بِهِ، فَقَالَ: يَا فُلَانَةُ أَعْطِيهِ الَّذِي تَجَهَّزْتُ بِهِ، وَلَا تَحْبِسِي مِنْهُ شَيْئاً ، فَوَاللَّهِ لَا تَحْبِسِينَ مِنْهُ شَيْئاً فَيُبَارَكَ لَكِ فِيهِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20176;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ زَيْدِ بْنِ خَالِدٍ الجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «مَنْ جَهَّزَ غَازِياً فِي سَبِيلِ اللَّهِ فَقَدْ غَزَا وَمَنْ خَلَفَ غَازِيا فِي أَهْلِهِ بِخَيْرٍ فَقَدْ غَزَا».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20177;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ أنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بَعَثَ بَعْثاً إِلَى بَنِي لِحْيَانَ مِنْ هُذَيلٍ فَقَالَ: « لِيَنْبَعِثْ مِن كُلِّ رَجُلَينِ أَحَدُهُما والأَجْرُ بَينهُما».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3068 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20178;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقِيَ رَكْبًا بالرَّوحاءِ فَقَالَ : "مَنِ القَوْمُ؟" قَالُوا: المُسْلِمُونَ، فَقَالُوا: مَنْ أَنْتَ؟ قَالَ: "رَسُولُ اللَّهِ" فَرَفَعَتْ إِلَيْهِ امْرَأَةٌ صَبِيًّا فَقَالَتْ : أَلِهَذَا حَجٌّ؟ قَالَ: "نَعَمْ وَلَكِ أَجْرٌ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65673 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20179;
update hadith set arabic = 'عَنْ أَبِي مُوسَى الأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ ، عَنِ النبيِّ صَلّى اللهُ عَلَيْهِ وسَلَّم أَنَّهُ قَالَ: « الخَاِزنُ المُسْلِمُ الأَمِينُ الَّذِي يُنْفِذُ مَا أُمِرَ بِهِ، فَيُعْطِيهِ كَامِلاً مُوَفَّراً، طَيِّبَةً بِهِ نَفسُهُ فَيَدْفَعُهُ إِلَى الَّذِي أُمِرَ لَهُ بِهِ أَحَدُ المُتَصَدِّقِينَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3125 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20180;
update hadith set arabic = 'عَنْ أَبِي رُقَيَّةَ تَمِيمِ بْنِ أَوْسٍ الدَّارِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « الدِّينُ النَّصِيحَةُ» قُلْنَا: لِمَنْ؟ قَالَ: لِلهِ وَلِكِتَابِهِ وَلِرَسُولِهِ وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ.', updated_at = now() where id = 20181;
update hadith set arabic = 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَايَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى إِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالنُّصْحِ لِكُلِّ مُسْلِمٍ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20182;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قالَ: «لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4717 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20183;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ الخُدْريِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ ، فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65001 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20184;
update hadith set arabic = 'عَنْ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «مَا مِنْ نَبِيٍّ بَعَثَهُ اللهُ فِي أُمَّةٍ قَبْلِي إِلَّا كَانَ لَهُ مِنْ أُمَّتِهِ حَوَارِيُّونَ وَأَصْحَابٌ يَأْخُذُونَ بِسُنَّتِهِ وَيَقْتَدُونَ بِأَمْرِهِ، ثُمَّ إِنَّهَا تَخْتَلِفُ مِنْ بَعْدِهِمْ خُلُوفٌ يَقُولُونَ مالَا يَفْعَلُونَ وَيَفْعَلُونَ مَا لَا يُؤْمَرُونَ، فَمَنْ جَاهَدَهُمْ بِيَدِهِ فَهُوَ مُؤْمِنٌ، وَمَنْ جَاهَدَهُمْ بِقَلْبِهِ فَهُوَ مُؤْمِنٌ، وَمَنْ جَاهَدَهُمْ بِلِسَانِهِ فَهُوَ مُؤْمِنٌ ، وَلَيْسَ وَرَاءَ ذَلِكَ الْإِيمَانِ حَبَّةُ خَرْدَلٍ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3480 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20185;
update hadith set arabic = 'عَنْ أَبِي الوَلِيدِ عُبَادَةَ بْنِ الصَّامتِ رَضِيَ اللَّهُ عَنْهُ قَالَ: «بَايَعْنَا رسولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ فِي الْعُسْرِ وَالْيُسْرِ وَالْمَنْشَطِ وَالْمَكْرَهِ، وَعَلَى أَثَرَةٍ عَلَيْنَا، وَعَلَى أَنْ لَا نُنَازِعَ الْأَمْرَ أهلَهُ إِلَّا أَنْ تَرَوْا كُفْرًا بَوَاحًا عِنْدَكُمْ مِنَ اللَّهِ تَعَالَى فِيهِ بُرْهَانٌ ، وَعَلَى أَنْ نَقُولَ بِالْحَقِّ أَيْنَمَا كُنَّا لَا نَخَافُ فِي اللَّهِ لَوْمَةَ لَائِمٍ» ((مُتَّفَقٌ عَلَيْهِ)) . المَنْشَطُ وَالمَكْرَهُ بِفَتْحِ مِيمَيْهِمَا: أَيْ: فِي السَّهْلِ وَالصَّعْبِ. وَالأَثَرَةُ : الِاخْتِصَاصُ بِالمُشْتَرَكِ، وَقَدْ سَبَقَ بَيَانُهَا. بَوَاحًا بِفَتْحِ البَاءِ المُوَحَّدَةِ بَعْدَهَا وَاوٌ ثُمَّ أَلِفٌ ثُمَّ حَاءٌ مُهْمَلَةٌ: أَيْ ظَاهِرٌ لَا يَحْتَمِلُ تَأْوِيلًا.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3061 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20186;
update hadith set arabic = 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «مَثَلُ القَائِمِ عَلَى حُدُودِ اللَّهِ وَالوَاقِعِ فِيهَا كَمَثَلِ قَوْمٍ اسْتَهَمُوا عَلَى سَفِينَةٍ، فَصَارَ بَعْضُهُمْ أَعْلاَهَا وَبَعْضُهُمْ أَسْفَلَهَا، وَكَانَ الَّذِينَ فِي أَسْفَلِهَا إِذَا اسْتَقَوْا مِنَ المَاءِ مَرُّوا عَلَى مَنْ فَوْقَهُمْ فَقَالُوا: لَوْ أَنَّا خَرَقْنَا فِي نَصِيبِنَا خَرْقًا وَلَمْ نُؤْذِ مَنْ فَوْقَنَا ، فَإِنْ تَرَكُوهُمْ وَمَا أَرَادُوا هَلَكُوا وَهَلَكُوا جَمِيعًا، وَإِنْ أَخَذُوا عَلَى أَيْدِيهِمْ نَجَوْا وَنَجَوْا جَمِيعًا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3341 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20187;
update hadith set arabic = 'عَنْ أُمِّ المُؤْمِنِينَ أُمِّ سَلَمَةَ هِنْدِ بِنْتِ أَبِي أُمَيَّةَ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: " إِنَّهُ يُسْتَعْمَلُ عَلَيْكُمْ أُمَرَاءُ فَتَعْرِفُونَ وَتُنْكِرُونَ فَمَنْ كَرِهَ فَقَدْ بَرِئَ، وَمَنْ أَنْكَرَ فَقَدْ سَلِمَ، وَلَكِنْ مَنْ رَضِيَ وَتَابَعَ" قَالُوا: يَا رَسُولَ اللَّهِ أَلَا نُقَاتِلُهُمْ؟ قَالَ: "لَا ، الإِمَامُ أَقَامُوا فِيكُمُ الصَّلَاةَ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20188;
update hadith set arabic = 'عَنْ أُمِّ المُؤْمِنِينَ أُمِّ الحَكَمِ زَيْنَبَ بِنْتِ جَحْشٍ رَضِيَ اللَّهُ عَنْها أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا فَزِعًا يَقُولُ: "لاَ إِلَهَ إِلَّا اللَّهُ، وَيْلٌ لِلْعَرَبِ مِنْ شَرٍّ قَدِ اقْتَرَبَ، فُتِحَ اليَوْمَ مِنْ رَدْمِ يَأْجُوجَ وَمَأْجُوجَ مِثْلُ هَذِهِ" وَحَلَّقَ بِأُصْبُعَيْهِ الإِبْهَامِ وَالَّتِي تَلِيهَا. فَقُلْتُ: يَا رَسُولَ اللَّهِ أَنَهْلِكُ وَفِينَا الصَّالِحُونَ؟ قَالَ: "نَعَمْ إِذَا كَثُرَ الخَبَثُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3145 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20189;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِيَّاكُمْ وَالجُلُوسَ فِي الطُّرُقَاتِ" فَقَالُوا : يَا رَسُولَ اللَّهِ مَا لَنَا مِنْ مَجَالِسِنَا بُدٌّ؛ نَتَحَدَّثُ فِيهَا! فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَإِذَا أَبَيْتُمْ إِلَّا المَجْلِسَ فَأَعْطُوا الطَّرِيقَ حَقَّهُ" قَالُوا: وَمَا حَقُّ الطَّرِيقِ يَا رَسُولَ اللَّهِ؟ قَالَ: "غَضُّ البَصَرِ وَكَفُّ الأَذَى وَرَدُّ السَّلَامِ، وَالأَمْرُ بِالمَعْرُوفِ ، وَالنَّهْيُ عَنِ المُنْكَرِ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20190;
update hadith set arabic = 'عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى خَاتَمًا مِنْ ذَهَبٍ فِي يَدِ رَجُلٍ، فَنَزَعَهُ فَطَرَحَهُ وَقَالَ: « يَعْمِدُ أَحَدُكُمْ إِلَى جَمْرَةٍ مِنْ نَارٍ فَيَجْعَلُهَا فِي يَدِهِ !» فَقِيلَ لِلرَّجُلِ بَعْدَ مَا ذَهَبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : خُذْ خَاتِمَكَ؛ انْتَفِعْ بِهِ. قَالَ: لَا وَاللهِ لَا آخُذُهُ أَبَدًا وَقَدْ طَرَحَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ.', updated_at = now() where id = 20191;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ الحَسَنِ البَصْرِيِّ أنَّ عَائِذَ بْنَ عَمْرٍو رَضِيَ اللَّهُ عَنْهُ دَخَلَ عَلَى عُبَيدِ اللَّهِ بْنِ زِيَادٍ فَقَالَ: أَيْ بُنَيَّ، إِنِّي سَمِعتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «إِنَّ شَرَّ الرِّعَاءِ الحُطَمَةُ» فَإِيَّاكَ أَن تَكُونَ مِنهُم. فَقَالَ لَهُ : اجْلِسْ فَإِنَّما أَنْتَ مِن نُخَالَةِ أَصحَابِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَ: وَهَلْ كَانَت لَهُم نُخَالَةٌ، إِنَّمَا كَانَتِ النُخَالَةُ بَعدَهُم وَفِي غَيرِهِم !.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3532 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20192;
update hadith set arabic = 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « وَالَّذِي نَفسِي بِيَدِهِ لَتَأْمُرُنَّ بِالمَعرُوفِ، وَلَتَنهَوُنَّ عَنِ المُنْكَرِ، أَو لَيُوشِكَنَّ اللَّهُ أَن يَبْعَثَ عَلَيكُم عِقَاباً مِنْهُ، ثُمَّ تَدعُونَهُ فَلاَ يُسْتَجَابُ لَكُم».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3531 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20193;
update hadith set arabic = 'الحَادِي عَشَرَ: عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «أَفْضَلُ الجِهَادِ كَلِمَةُ عَدْلٍ عِنْدَ سُلْطَانٍ جَائِرٍ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20194;
update hadith set arabic = 'الثَّانِي عَشَرَ: عَنْ أَبِي عَبْدِ اللَّهِ طَارِقِ بْنِ شِهَابٍ البَجَلِيِّ الأَحْمَسِيِّ رَضِيَ اللَّهُ عَنْهُ أنّ رجُلًا سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَدْ وضَعَ رِجلَهُ فِي الغَرْزِ: أَيُّ الجِهَادِ أَفْضَلُ؟ قَالَ: «كَلِمَةُ حَقًّ عِندَ سُلطَانٍ جَائِرٍ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3485 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20195;
update hadith set arabic = 'الثَّالِثَ عَشَرَ: عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "إِنَّ أَوَّلَ مَا دَخَلَ النَّقْصُ عَلَى بَنِي إِسْرَائِيلَ أَنَّهُ كَانَ الرَّجُلُ يَلْقَى الرَّجُلَ فَيَقُولُ: يَا هَذَا اتَّقِ اللَّهَ وَدَعْ مَا تَصْنَعُ فَإِنَّهُ لَا يَحِلُّ لَكَ، ثُمَّ يَلْقَاهُ مِنَ الغَدِ وَهُوَ عَلَى حَالِهِ، فَلَا يَمْنَعُهُ ذَلِكَ أَنْ يَكُونَ أَكِيلَهُ وَشَرِيبَهُ وَقَعِيدَهُ، فَلَمَّا فَعَلُوا ذَلِكَ ضَرَبَ اللَّهُ قُلُوبَ بَعْضِهِمْ بِبَعْضٍ" ثُمَّ قَالَ: {لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ عَلَى لِسَانِ دَاوُدَ وَعِيسَى ابْنِ مَرْيَمَ ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ. كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ. تَرَى كَثِيرًا مِنْهُمْ يَتَوَلَّوْنَ الَّذِينَ كَفَرُوا لَبِئْسَ مَا قَدَّمَتْ لَهُمْ أَنْفُسُهُمْ } إِلَى قَوْلِهِ: {فَاسِقُونَ} ((المَائِدُ: 78،81)) ثُمَّ قَالَ: " كَلَّا، وَاللَّهِ لَتَأْمُرُنَّ بِالمَعْرُوفِ وَلَتَنْهَوُنَّ عَنِ المُنْكَرِ، وَلَتَأْخُذُنَّ عَلَى يَدِ الظَّالِمِ وَلَتَأْطُرُنَّهُ عَلَى الحَقِّ أَطْرًا، وَلَتَقْصُرُنَّهُ عَلَى الحَقِّ قَصْرًا، أَوْ لَيَضْرِبَنَّ اللَّهُ بِقُلُوبِ بَعْضِكُمْ عَلَى بَعْضٍ، ثُمَّ لَيَلْعَنَنَّكُمْ كَمَا لَعَنَهُمْ" ((رَوَاهُ أَبُو دَاوُدَ، وَالتِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ)). هَذَا لَفْظُ أَبِي دَاوُدَ، وَلَفْظُ التِّرْمِذِيِّ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَمَّا وَقَعَتْ بَنُو إِسْرَائِيلَ فِي المَعَاصِي نَهَتْهُمْ عُلَمَاؤُهُمْ فَلَمْ يَنْتَهُوا، فَجَالَسُوهُمْ فِي مَجَالِسِهِمْ وَوَاكَلُوهُمْ وَشَارَبُوهُمْ، فَضَرَبَ اللَّهُ قُلُوبَ بَعْضِهِمْ بِبَعْضٍ، وَلَعَنَهُمْ عَلَى لِسَانِ دَاوُدَ وَعِيسَى ابْنِ مَرْيَمَ ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ فَجَلَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ مُتَّكِئًا فَقَالَ: لَا وَالَّذِي نَفْسِي بِيَدِهِ حَتَّى تَأْطُرُوهُمْ عَلَى الحَقِّ أَطْرًا . قَوْلُهُ: تَأْطُرُوهُمْ أَيْ تَعْطِفُوهُمْ. وَلَتَقْصُرُنَّهُ أَيْ لَتَحْبِسُنَّهُ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20196;
update hadith set arabic = 'الرَّابِعَ عَشَرَ: عَنْ أَبِي بَكْرٍ الصِّدِّيقِ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: يَا أَيُّهَا النَّاسُ إِنَّكُمْ لَتَقْرَءُونَ هَذِهِ الآيَةَ: {يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنْفُسَكُمْ لاَ يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ}.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3470 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20197;
update hadith set arabic = 'عَنْ أَبِي زَيْدٍ أُسَامَةَ بْنِ زَيْدِ بْنِ حَارِثَةَ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: "يُؤْتَى بِالرَّجُلِ يَوْمَ القِيَامَةِ فَيُلْقَى فِي النَّارِ فَتَنْدَلِقُ أَقْتَابُ بَطْنِهِ فَيَدُورُ بِهَا كَمَا يَدُورُ الحِمَارُ فِي الرَّحَى فَيَجْتَمِعُ إِلَيْهِ أَهْلُ النَّارِ فَيَقُولُونَ: يَا فُلَانُ مَا لَكَ ؟ أَلَمْ تَكُ تَأْمُرُ بِالمَعْرُوفِ وَتَنْهَى عَنِ المُنْكَرِ؟ فَيَقُولُ: بَلَى، كُنْتُ آمُرُ بِالمَعْرُوفِ وَلَا آتِيهِ، وَأَنْهَى عَنِ المُنْكَرِ وَآتِيهِ" ((مُتَّفَقٌ عَلَيْهِ)) . قَوْلُهُ: تَنْدَلِقُ هُوَ بِالدَّالِ المُهْمَلَةِ، وَمَعْنَاهُ تَخْرُجُ. وَ"الأَقْتَابُ": الأَمْعَاءُ، وَاحِدُهَا قِتْبٌ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20198;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ ، رَضِيَ اللَّهُ عَنْهُ ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «آيَةُ المُنَافِقِ ثَلاَثٌ: إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا اؤْتُمِنَ خَانَ».', updated_at = now() where id = 20199;
update hadith set arabic = 'عَنْ حُذَيْفَةَ بْنِ اليَمَانِ. رَضِيَ اللَّهُ عَنْهُ ، قَالَ: حَدَثَنا رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حدِيثَينِ قَد رَأَيتُ أَحَدَهُما، وَأَنَا أَنْتَظِرُ الآخَرَ: حَدَّثَنَا أنَّ الأمَانةَ نَزَلَت فِي جَذرِ قُلُوبِ الرِّجالِ، ثمَّ نَزَلَ القُرْآنُ فَعَلِموا مِنَ القُرْآنِ، وعَلِمُوا مِنَ السُنَّةِ، ثمَّ حدَّثنا عَنْ رَفْعِ الأَمَانَةِ فَقَالَ: "يَنَامُ الرَّجُلُ النَّومَةَ فَتُقْبَضُ الأَمَانَةُ مِنْ قَلْبِهِ، فَيَظَلُّ أَثَرُهَا مِثلَ الوَكْتِ، ثُمَّ يَنَامُ النَّومَةَ فتُبْضُ الأَمَانَةُ مِن قَلْبِهِ، فَيَظَلُّ أَثَرُها مِثلَ أَثَرِ المَجْلِ، كَجَمْرٍ دَحْرَجْتَهُ عَلى رِجْلِكَ، فَنَفِطَ فَتَرَاهُ مُنْتَبِراً وَلَيسَ فِيهِ شَيءٌ " ثُمَّ أَخَذَ حَصَاةً فَدَحْرَجَهُ عَلَى رِجْلِهِ "فَيُصبِحُ النَّاسُ يَتَبَايَعُونَ، فَلاَ يَكَادُ أَحَدٌ يُؤَدِّي الأَمَانَةَ حَتَّى يُقَالَ:" إِنَّ فِي بَنِي فُلاَنٍ رَجُلاً أَمِيناً، حَتَّى يُقَالَ لِلرَّجُلِ، مَا أَجْلَدَهُ مَا أَظْرَفَهُ، مَا أَعْقَلَهُ! وَمَا فِي قَلبِهِ مِثْقَالُ حَبَّةٍ مِن خَرْدَلٍ مِنْ إِيمَانٍ . ولَقَد أَتَى عَلَيَّ زَمَانٌ وَمَا أُبَالِي أَيُّكُم بَايَعتُ؛ لَئِن كَانَ مُسلِمًا لَيَرُدَنَّهُ عَلَيَّ دِينُهُ، وَلَئِنْ كَانَ نَصْرَانِيًّا أَوْ يَهُودِيًّا ليَرُدنَّهُ عَلَيَّ سَاعِيهِ، وأَمَّا اليَوْمَ فَمَا كُنتُ أُبَايِعُ مِنكُم إِلاَّ فُلاَنا وَ فُلَانًا".', updated_at = now() where id = 20200;
update hadith set arabic = 'عَنْ حُذَيْفَةَ، وَأَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُمَا ، قَالَا: قَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَجْمَعُ اللَّهُ، تَبَارَكَ وَتَعَالَى النَّاسَ، فَيَقُومُ المُؤْمِنُونَ حَتَّى تُزْلَفَ لَهُمُ الجَنَّةُ، فَيَأْتُونَ آدَمَ، صَلَوَاتُ اللَّهِ عَلَيْهِ، فَيَقُولُونَ: يَا أَبَانَا اسْتَفْتِحْ لَنَا الجَنَّةَ، فَيَقُولُ: وَهَلْ أَخْرَجَكُمْ مِنَ الجَنَّةِ إِلَّا خَطِيئَةُ أَبِيكُمْ ! لَسْتُ بِصَاحِبِ ذَلِكَ، اذْهَبُوا إِلَى ابْنِي إِبْرَاهِيمَ خَلِيلِ اللَّهِ، قَالَ: فَيَأْتُونَ إِبْرَاهِيمَ، فَيَقُولُ إِبْرَاهِيمُ: لستُ بِصَاحِبِ ذَلِكَ ، اذْهَبُوا إِلَى مُوسَى الَّذِي كَلَّمَهُ اللَّهُ تَكْلِيمًا، فَيَأْتُونَ مُوسَى، فَيَقُولُ: لستُ بِصَاحِبِ ذَلِكَ؛ اذْهَبُوا إِلَى عِيسَى كَلِمَةِ اللَّهِ وَرُوحِهِ. فَيَقُولُ عِيسَى: لَسْتُ بِصَاحِبِ ذَلِكَ. فَيَأْتُونَ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَقُومُ فَيُؤْذَنُ لَهُ، وتُرسَلُ الأَمَانَةُ وَالرَّحِمُ فَتَقُومَانِ جَنْبَتَيِ الصِّرَاطِ يَمِينًا وَشِمَالًا، فيَمُرُّ أوَّلُكُم كَبِالْبَرْقِ" قلتُ: بِأَبِي وَأُمِّي، أَيُّ شَيْءٍ كَمَرِّ البرْقِ؟ قَالَ: "أَلَمْ تَرَوْا كَيْفَ يَمُرُّ وَيَرْجِعُ فِي طَرْفِة عَيْنٍ؟ ثُمَّ كَمَرِّ الرِّيحِ، ثُمَّ كَمَرِّ الطَّيْرِ، وَأَشَدِّ الرِّجَالِ تَجْرِي بِهِمْ أَعْمَالُهُمْ، وَنَبِيُّكُمْ قَائِمٌ عَلَى الصِّرَاطِ يَقُولُ:" رَبِّ سَلِّمْ سَلِّمْ، حَتَّى تَعْدِزَ أَعْمَالُ العِبَادِ، حَتَّى يَجِيءَ الرَّجُلُ لَا يَسْتَطِيعُ السَّيْرَ إِلَّا زَحْفَا، وَفِي حَافَتَيِ الصِّرَاطِ كَلالِيبُ مُعَلَّقَةٌ مَأْمُورَةٌ بِأَخْذِ مَنْ أُمِرَتْ بِهِ، فَمَخْدُوشٌ نَاجٍ، ومُكَرْدَسٌ فِي النَّارِ" وَالَّذِي نَفْسُ أَبِي هُرَيْرَةَ بِيَدِهِ إِنَّ قَعْرَ جَهَنَّمَ لَسَبْعُونَ خَرِيفًا.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5865 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20201;
update hadith set arabic = 'عَنْ أَبِي خُبَيْبٍ -بِضَمِّ الخَاءِ المُعْجَمَةِ- عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: لَمَّا وَقَفَ الزُّبَيْرُ يَوْمَ الجَمَلِ دَعَانِي فَقُمْتُ إِلَى جَنْبِهِ، فَقَالَ: يَا بُنَيَّ إِنَّهُ لاَ يُقْتَلُ اليَوْمَ إِلَّا ظَالِمٌ أَوْ مَظْلُومٌ ،وَإِنِّي لَا أُرَانِى إِلَّا سَأُقْتَلُ اليَوْمَ مَظْلُومًا، وَإِنَّ مِنْ أَكْبَرِ هَمِّي لَدَيْنِي، أَفَتَرَى دَيْنَنَا يُبقِي مِنْ مَالِنا شَيْئًا؟ ثُمَّ قَالَ: يَا بُنَيَّ بِعْ مَالَنَا وَاقْضِ دَيْنِي، وَأَوْصَى بِالثُّلُثِ وَثُلُثِهِ لِبَنِيهِ، يَعْنِي لِبَنِي عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ثُلُثُ الثُّلُثِ. قَالَ فَإِنْ فَضَلَ مِنْ مَالِنَا بَعْدَ قَضَاءِ الدَّيْنِ شَيْءٌ فَثُلُثُهُ لِبَنِيكَ ، قَالَ هِشَامٌ : وَكَانَ بَعْضُ وَلَدِ عَبْدِ اللَّهِ قَدْ وَازَى بَعْضَ بَنِي الزُّبَيْرِ خُبَيْبٌ وعَبَّادٌ، وَلَهُ يَوْمَئِذٍ تِسْعَةُ بَنِينَ وَتِسْعُ بَنَاتٍ. قَالَ عَبْدُ اللَّهِ : فَجَعَلَ يُوصِينِي بِدَيْنِهِ وَيَقُولُ: يَا بُنَىَّ إِنْ عَجَزْتَ عَنْ شَيْءٍ مِنْهُ فَاسْتَعِنْ عَلَيْهِ بِمَوْلَايَ. قَالَ فَوَاللَّهِ مَا دَرَيْتُ مَا أَرَادَ حَتَّى قُلْتُ: يَا أَبَتِ مَنْ مَوْلَاكَ؟ قَالَ: اللَّهُ. قَالَ: فَوَاللَّهِ مَا وَقَعْتُ فِي كُرْبَةٍ مِنْ دَيْنِهِ إِلَّا قُلْتُ: يَا مَوْلَى الزُّبَيْرِ اقْضِ عَنْهُ دَيْنَهُ، فَيَقْضِيهِ. قَالَ: فَقُتِلَ الزُّبَيْرُ وَلَمْ يَدَعْ دِينَارًا وَلَا دِرْهَمًا إِلَّا أَرَضِينَ، مِنْهُمَا الغَابَةُ وَإِحْدَى عَشْرَةَ دَارًا بِالمَدِينَةِ، وَدَارَيْنِ بِالبَصْرَةِ، وَدَارًا بِالكُوفَةِ وَدَارًا بِمِصْرَ. قَالَ: وَإِنَّمَا كَانَ دَيْنُهُ الَّذِي كَانَ عَلَيْهِ أَنَّ الرَّجُلَ كَانَ يَأْتِيهِ بِالمَالِ، فَيَسْتَوْدِعُهُ إِيَّاهُ، فَيَقُولُ الزُّبَيْرُ: لَا وَلَكِنْ هُوَ سَلَفٌ إِنِّي أَخْشَى عَلَيْهِ الضَّيْعَةَ. وَمَا وَلِيَ إِمَارَةً قَطُّ وَلَا جِبَايَةً وَلَا خَرَاجًا وَلَا شَيْئًا إِلَّا أَنْ يَكُونَ فِي غَزْوٍ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَوْ مَعَ أَبِي بَكْرٍ وَعُمَرَ وَعُثْمَانَ رَضِيَ اللَّهُ عَنْهُمْ، قَالَ عَبْدُ اللَّهِ: فَحَسَبْتُ مَا كَانَ عَلَيْهِ مِنَ الدَّيْنِ فَوَجَدْتُهُ أَلْفَيْ أَلْفٍ وَمِائَتَيْ أَلْفٍ! فَلَقِيَ حَكِيمُ بْنُ حِزَامٍ عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ فَقَالَ: يَا ابْنَ أَخِي كَمْ عَلَى أَخِي مِنَ الدَّيْنِ؟ فَكَتَمْتُهُ وَقُلْتُ : مِائَةُ أَلْفٍ. فَقَالَ حَكِيمٌ: وَاللَّهِ مَا أَرَى أَمْوَالَكُمْ تَسَعُ هَذِهِ ! فَقَالَ عَبْدُ اللَّهِ: أَرَأَيْتَكَ إِنْ كَانَتْ أَلْفَ أَلْفٍ؟ وَمِائَتَيْ أَلْفٍ؟ قَالَ: مَا أُرَاكُمْ تُطِيقُونَ هَذَا، فَإِنْ عَجَزْتُمْ عَنْ شَيْءٍ مِنْهُ فَاسْتَعِينُوا بِي. قَالَ: وَكَانَ الزُّبَيْرُ قَدِ اشْتَرَى الغَابَةَ بِسَبْعِينَ وَمِائَةِ أَلْفٍ، فَبَاعَهَا عَبْدُ اللَّهِ بِأَلْفِ أَلْفٍ وَسِتِّمِائَةِ أَلْفٍ ، ثُمَّ قَامَ فَقَالَ: مَنْ كَانَ لَهُ عَلَى الزُّبَيْرِ شَيْءٌ فَلْيُوَافِنَا بِالغَابَةِ، فَأَتَاهُ عَبْدُ اللَّهِ بْنُ جَعْفَرٍ، وَكَانَ لَهُ عَلَى الزُّبَيْرِ أَرْبَعُمِائَةِ أَلْفٍ، فَقَالَ لِعَبْدِ اللَّهِ: إِنْ شِئْتُمْ تَرَكْتُهَا لَكُمْ؟ قَالَ عَبْدُ اللَّهِ: لَا، قَالَ: فَإِنْ شِئْتُمْ جَعَلْتُمُوهَا فِيمَا تُؤَخِّرُونَ إِنْ أَخَّرْتُمْ، فَقَالَ عَبْدُ اللَّهِ: لَا قَالَ: فَاقْطَعُوا لِي قِطْعَةً، قَالَ عَبْدُ اللَّهِ: لَكَ مِنْ هَهُنَا إِلَى هَهُنَا. فَبَاعَ عَبْدُ اللَّهِ مِنْهَا، فَقَضَى عَنْهُ دَيْنَهُ، وَأَوْفَاهُ وَبَقِيَ مِنْهَا أَرْبَعَةُ أَسْهُمٍ وَنِصْفٌ، فَقَدِمَ عَلَى مُعَاوِيَةَ وَعِنْدَهُ عَمْرُو بْنُ عُثْمَانَ، وَالمُنْذِرُ بْنُ الزُّبَيْرِ، وَابْنُ زَمْعَةَ فَقَالَ لَهُ مُعَاوِيَةُ: كَمْ قُوِّمَتِ الغَابَةُ؟ قَالَ : كُلُّ سَهْمٍ بِمِائَةِ أَلْفٍ قَالَ: كَمْ بَقِيَ مِنْهَا؟ قَالَ: أَرْبَعَةُ أَسْهُمٍ وَنِصْفٌ، فَقَالَ المُنْذِرُ ابْنُ الزُّبَيْرِ: قَدْ أَخَذْتُ مِنْهَا سَهْمًا بِمِائَةِ أَلْفٍ، قَالَ عَمْرُو بْنُ عُثْمَانَ: قَدْ أَخَذْتُ مِنْهَا سَهْمًا بِمِائَةِ أَلْفٍ. وَقَالَ ابْنُ زَمْعَةَ: قَدْ أَخَذْتُ سَهْمًا بِمِائَةِ أَلْفٍ، فَقَالَ مُعَاوِيَةُ: كَمْ بَقِيَ مِنْهَا؟ قَالَ: سَهْمٌ وَنِصْفُ سَهْمٍ، قَالَ: قَدْ أَخَذْتُهُ بِخَمْسِينَ وَمِائَةِ أَلْفٍ . قَالَ: وَبَاعَ عَبْدُ اللَّهِ بْنُ جَعْفَرٍ نَصِيبَهُ مِنْ مُعَاوِيَةَ بِسِتِّمِائَةِ أَلْفٍ. فَلَمَّا فَرَغَ ابْنُ الزُّبَيْرِ مِنْ قَضَاءِ دَيْنِهِ قَالَ بَنُو الزُّبَيْرِ : اقْسِمْ بَيْنَنَا مِيرَاثَنَا. قَالَ: : وَاللَّهِ لَا أَقْسِمُ بَيْنَكُمْ حَتَّى أُنَادِيَ بِالمَوْسِمِ أَرْبَعَ سِنِينَ : أَلَا مَنْ كَانَ لَهُ عَلَى الزُّبَيْرِ دَيْنٌ فَلْيَأْتِنَا فَلْنَقْضِهِ. فَجَعَلَ كُلَّ سَنَةٍ يُنَادِي فِي المَوْسِمِ، فَلَمَّا مَضَى أَرْبَعُ سِنِينَ قَسَمَ بَيْنَهُمْ وَدَفَعَ الثُّلُثَ. وَكَانَ لِلزُّبَيْرِ أَرْبَعُ نِسْوَةٍ، فَأَصَابَ كُلَّ امرَأةٍ أَلْفُ أَلْفٍ وَمِائَتَا أَلْفٍ، فَجَمِيعُ مَالِهِ خَمْسُونَ أَلْفَ أَلْفٍ وَمِائَتَا أَلْفٍ، رَوَاهُ البُخَارِيُّ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5864 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20202;
update hadith set arabic = 'عَنْ جَابِرِ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «اتَّقُوا الظُّلْمَ، فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ، وَاتَّقُوا الشُّحَّ فَإِنَّ الشُّحَّ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ، حَمَلَهُمْ عَلَى أَنْ سَفَكُوا دِمَاءَهُمْ وَاسْتَحَلُّوا مَحَارِمَهُمْ».', updated_at = now() where id = 20203;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «لَتُؤَدُّنَّ الحُقُوقَ إِلَى أَهْلِهَا يَوْمَ القِيَامَةِ حَتَّى يُقادَ لِلشَّاةِ الجَلْحَاءِ مِنَ الشَّاةِ القَرْنَاءِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5824 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20204;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا نَتَحَدَّثُ عَنْ حَجَّةِ الوَدَاعِ، وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَظْهُرِنَا، وَلَا نَدْرِي مَا حَجَّةُ الوَدَاعِ، حَتَّى حَمِدَ اللهَ رسولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَثْنَى عَلَيْهِ، ثُمَّ ذَكَرَ المَسِيحَ الدَّجَالَ فأَطْنَبَ فِي ذِكْرِهِ، وَقَالَ: " مَا بَعَثَ اللَّهُ مِنْ نَبِيٍّ إِلَّا أَنْذَرَهُ أُمَّتَهُ: أَنْذَرَهُ نُوحٌ وَالنَّبِيُّونَ مِنْ بَعْدِهِ، وَإِنَّهُ إِنْ يَخْرُجْ فِيكُمْ فَمَا خَفِيَ عَلَيْكُمْ مِنْ شَأْنِهِ فَلَيْسَ يَخْفَى عَلَيْكُمْ، إِنَّ رَبَّكُمْ لَيْسَ بأَعْوَرَ، وَإِنَّهُ أَعْوَرُ عَيْنِ اليُمْنَى، كأنَّ عَيْنَهُ عِنَبَةٌ طَافِيَةٌ. أَلَا إِنَّ اللَّهَ حَرَّمَ عَلَيْكُمْ دِمَاءَكُمْ وَأَمْوَالَكُمْ ، كحُرْمَةِ يَوْمِكُمْ هَذَا، فِي بَلَدِكُمْ هَذَا، فِي شَهْرِكُمْ هَذَا، أَلَا هَلْ بَلَّغْتُ؟" قَالُوا: نَعَمْ، قَالَ: "اللَّهُمَّ اشْهَدْ -ثَلَاثًا- وَيْلَكُمْ، أَوْ وَيْحَكُمْ، انْظُرُوا، لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ".', updated_at = now() where id = 20205;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «مَنْ ظَلَمَ قِيدَ شِبْرٍ مِنَ الأرْضِ طُوِّقَهُ مِن سَبْعِ أَرَضِينَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5843 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20206;
update hadith set arabic = 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "إِنَّ اللهَ لَيُمْلِي لِلظَّالِمِ فَإِذَا أَخَذَهُ لَمْ يُفْلِتْهُ ثُمَّ قَرَأَ: {وَكَذَلِكَ أَخْذُ رَبِّكَ إِذَا أَخَذَ الْقُرَى وَهِيَ ظَالِمَةٌ إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ}.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5811 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20207;
update hadith set arabic = 'عَنْ مُعَاذٍ رَضِيَ اللَّهُ عَنْهُ قَالَ : بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: «إِنَّكَ تَأْتِي قَوْمًا مِنْ أَهْلِ الكِتَابِ، فَادْعُهُمْ إِلَى شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنِّي رَسُولُ اللَّهِ ، فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ، فَأَعْلِمْهُمْ أَنَّ اللَّهَ قَدِ افْتَرَضَ عَلَيْهِمْ خَمْسَ صَلَوَاتٍ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ، فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ، فَإِيَّاكَ وَكَرَائِمَ أَمْوَالِهِمْ. وَاتَّقِ دَعْوَةَ المَظْلُومِ فَإِنَّهُ لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ حِجَابٌ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20208;
update hadith set arabic = 'عَنْ أَبِي حُمَيْدٍ عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: اسْتَعْمَلَ النَّبِيُّ رَجُلاً مِنَ الأَزْدِ يُقَالُ لَهُ: ابْنُ اللُّتْبِيَّةِ عَلَى الصَّدَقَةِ، فَلَمَّا قَدِمَ قَالَ : هَذَا لَكُمْ، وَهَذَا أُهْدِيَ إِلَيَّ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى المِنْبَرِ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: "أَمَّا بَعْدُ فَإِنِّي أَسْتَعْمِلُ الرَّجُلَ مِنْكُمْ عَلَى العَمَلِ مِمَّا وَلَّانِي اللَّهُ، فَيَأْتِي فَيَقُولُ: هَذَا لَكُمْ، وَهَذَا هَدِيَّةٌ أُهْدِيَتْ إِلَيَّ، أَفَلَا جَلَسَ فِي بَيْتِ أَبِيهِ وَأُمِّهِ حَتَّى تَأْتِيَهُ هَدِيَّتُهُ إِنْ كَانَ صَادِقًا، وَاللَّهِ لَا يَأْخُذُ أَحَدٌ مِنْكُمْ شَيْئًا بِغَيْرِ حَقِّهِ إِلَّا لَقِىَ اللَّهَ تَعَالَى، يَحْمِلُهُ يَوْمَ القِيَامَةِ، فَلَا أَعْرِفَنَّ أَحَدًا مِنْكُمْ لَقِيَ اللَّهَ يَحْمِلُ بَعِيرًا لَهُ رُغَاءٌ، أَوْ بَقَرَةً لَهَا خُوَارٌ، أَوْ شَاةً تَيْعَرُ" ثُمَّ رَفَعَ يَدَيْهِ حَتَّى رُؤِيَ بَيَاضُ إِبْطَيْهِ فَقَالَ : "اللَّهُمَّ هَلْ بَلَّغْتُ" ثَلَاثًا.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20209;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « مَنْ كَانَتْ عِنْدَهُ مَظْلَمَةٌ لِأَخِيهِ، مِنْ عِرْضِهِ أَوْ مِنْ شَيْءٍ، فَلْيَتَحَلَّلْهُ مِنْهُ اليَوْمَ قَبْلَ أَنْ لَا يَكُونَ دِينَارٌ وَلاَ دِرْهَمٌ ، إِنْ كَانَ لَهُ عَمَلٌ صَالِحٌ أُخِذَ مِنْهُ بِقَدْرِ مَظْلَمَتِهِ، وَإِنْ لَمْ يَكُنْ لَهُ حَسَنَاتٌ أُخِذَ مِنْ سَيِّئَاتِ صَاحِبِهِ فَحُمِلَ عَلَيْهِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20210;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «المُسْلِمُ مَنْ سَلِمَ المُسْلِمُونَ مِنْ لِسَانِهِ، وَيَدِهِ، وَالمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10101 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20211;
update hadith set arabic = 'وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ عَلَى ثَقَلِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ يُقالُ لَهُ كِرْكِرَةُ، فماتَ، فقال رسولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "هُوَ فِي النَّارِ" فَذَهَبُوا يَنْظُرُونَ إليهِ فَوَجَدُوا عَبَاءَةً قَدْ غَلَّهَا".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4945 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20212;
update hadith set arabic = 'عَنْ أَبِي بَكْرَةَ نُفَيْعِ بْنِ الحَارِثِ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الزمانَ قَدِ اسْتَدَارَ كَهَيْئَتِهِ يَوْمَ خَلَقَ اللهُ السَّمَوَاتِ والأَرْضَ: السنةُ اثنا عَشَرَ شَهْرًا، مِنْهَا أربعةٌ حُرُمٌ: ثلاثٌ مُتَوَالِيَاتٌ: ذُو القَعْدَةِ، وذُو الحَجَّةِ، والمُحَرَّمُ، ورَجَبُ مُضَرَ الَّذِي بَيْنَ جُمَادَى وشَعْبَانَ، أَيُّ شَهْرٍ هَذَا؟" قُلْنَا: اللهُ ورسولُهُ أَعْلَمُ، فَسَكَتَ حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ، قَالَ: أَلَيْسَ ذَا الحَجَّةِ؟ قُلْنَا بَلَى. قَالَ: "فأَيُّ بَلَدٍ هَذَا؟" قُلْنَا : اللهُ ورسولُهُ أَعْلَمُ فَسَكَتَ حَتَّى ظَنَنَّا أَنَّهُ سُيَسَمِّيهِ بِغَيْرِ اسْمِهِ. قَالَ:"أَلَيْسَ البَلْدَةَ" قُلْنَا: بَلَى . قَالَ: "فأَيُّ يَوْمٍ هَذَا؟" قُلْنَا: اللهُ ورسولُهُ أَعْلَمُ، فَسَكَتَ حَتَّى ظَنَنَّا أَنْ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ. قَالَ: "أَلَيْسَ يَوْمَ النَّحْرِ؟" قُلْنَا بَلَى. قَالَ "فَإِّنَّ دِمَاءَكُمْ وأَمْوَالَكُمْ وأَعْرَاضَكُمْ عَلَيْكُمْ حَرَامٌ، كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا، وَسَتَلْقَونَ رَبَّكُمْ فَيَسْأَلُكُمْ عَنْ أَعْمَالِكُمْ، أَلَا فَلَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُم رِقَابَ بَعْضٍ، أَلَا لِيُبَلِّغِ الشَّاهِدُ الغَائِبَ، فَلَعَلَّ بَعْضَ مَنْ يَبْلُغُهُ أَنْ يَكُونَ أَوْعَى لَهُ مِنْ بَعْضِ مَنْ سَمِعَهُ" ثُمَّ قَالَ: " أَلَا هَلْ بَلَّغْتُ، أَلَا هَلْ بَلَّغْتُ؟" قُلْنَا : نَعَمْ. قَالَ: " اللَّهُمَّ اشْهَدْ".', updated_at = now() where id = 20213;
update hadith set arabic = 'عَنْ أَبِي أُمَامَةَ إِياسِ بنِ ثَعْلَبَةَ الحَارِثِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: " مَنِ اقْتَطَعَ حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ فَقَدْ أَوْجَبَ اللهُ لَهُ النَّارَ، وَحَرَّمَ عَلَيْهِ الْجَنَّةَ" فَقَالَ رَجُلٌ: وَإِنْ كَانَ شَيْئًا يَسِيرًا يَا رَسُولَ اللهِ ؟ فَقَالَ: "وَإِنْ قَضِيبًا مِنْ أَرَاكٍ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5430 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20214;
update hadith set arabic = 'عَنْ عَدِيِّ ابْنِ عَمِيرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنِ اسْتَعْمَلْنَاهُ مِنْكُمْ عَلَى عَمَلٍ، فكَتَمَنَا مِخْيَطًا فَمَا فَوْقَهُ، كَانَ غُلُولا يَأْتِي بِهِ يَوْمَ القِيَامَةِ" فَقَامَ إِلَيْهِ رجلٌ أسودُ مِنَ الأَنْصَارِ، كَأَنِّي أَنْظُرُ إِلَيْهِ ، فَقَالَ: يَا رَسُولَ اللَّهِ اقْبَلْ عَنِّي عَمَلَكَ، قَالَ: "وَمَالَكَ؟" قَالَ سَمِعْتُكَ تَقُولُ كَذَا وَكَذَا، قَالَ: "وَأَنَا أَقُولُهُ الآنَ: مَنِ اسْتَعْمَلْنَاهُ عَلَى عَمَلٍ فَلْيَجِئْ بِقَلِيلِهِ وَكَثِيرِهِ، فَمَا أُوتِيَ مِنْهُ أَخَذَ، وَمَا نُهِيَ عَنْهُ انْتَهَى.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5412 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20215;
update hadith set arabic = 'عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا كَانَ يَوْمُ خَيْبَرَ أَقْبَلَ نَفَرٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا فُلَانٌ شَهِيدٌ، وَفُلَانٌ شَهِيدٌ، حَتَّى مَرُّوا عَلَى رَجُلٍ فَقَالُوا : فُلَانٌ شَهِيدٌ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : كَلَّا إِنِّي رَأَيْتُهُ فِي النَّارِ فِي بُرْدَةٍ غَلَّهَا-أَوْ عَبَاءَةٍ-".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4238 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20216;
update hadith set arabic = 'عَنْ أَبِي قَتَادَةَ الحَارِثِ بْنِ رِبْعِيِّ رَضِيَ اللَّهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قامَ فِيهِمْ ، فذكرَ لَهُمْ أَنَّ الجهادَ فِي سبيلِ اللهِ، والإيمانَ باللهِ أفضلُ الأعمالِ، فقامَ رَجُلٌ فَقَالَ: يا رسولَ اللهِ أرأيتَ إن قُتِلْتُ فِي سبيلِ اللهِ، تُكَفَّرُ عَنِّي خَطَايَايَ؟ فقالَ لَهُ رسولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ إنْ قُتِلْتَ فِي سبيلِ اللهِ وأنتَ صَابِرٌ مُحْتَسِبٌ، مُقْبِلٌ غَيْرُ مُدْبِرٍ" ثُمَّ قَالَ رسولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَيْفَ قُلْتَ؟" قَالَ: أَرَأَيتَ إنْ قُتِلْتُ فِي سَبِيلِ اللهِ، أَتُكَفَّرُ عَنِّي خَطَايَايَ؟ فقالَ رسولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ وأنتَ صَابِرٌ مُحْتَسِبٌ، مُقْبِلٌ غَيْرُ مُدْبِرٍ، إِلَّا الدَّيْنَ فَإنَّ جِبْرِيلَ قالَ لِي ذَلِكَ".', updated_at = now() where id = 20217;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ":أَتَدْرُونَ مَنِ الْمُفْلِسُ؟" قَالُوا : الْمُفْلِسُ فِينَا مَنْ لَا دِرْهَمَ لَهُ وَلَا مَتَاعَ فَقَالَ: "إِنَّ الْمُفْلِسَ مِنْ أُمَّتِي يَأْتِي يَوْمَ الْقِيَامَةِ بِصَلَاةٍ وَصِيَامٍ وَزَكَاةٍ، وَيَأْتِي قَدْ شَتَمَ هَذَا، وَقَذَفَ هَذَا وَأَكَلَ مَالَ هَذَا، وَسَفَكَ دَمَ هَذَا، وَضَرَبَ هَذَا، فَيُعْطَى هَذَا مِنْ حَسَنَاتِهِ، وَهَذَا مِنْ حَسَنَاتِهِ، فَإِنْ فَنِيَتْ حَسَنَاتُهُ قَبْلَ أَنْ يُقْضَى مَا عَلَيْهِ، أُخِذَ مِنْ خَطَايَاهُمْ فَطُرِحَتْ عَلَيْهِ، ثُمَّ طُرِحَ فِي النَّارِ".', updated_at = now() where id = 20218;
update hadith set arabic = 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِنَّمَا أَنَا بَشَرٌ، وَإِنَّكُمْ تَخْتَصِمُونَ إِلَيَّ، وَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ أَلْحَنَ بِحُجَّتِهِ مِنْ بَعْضٍ، فَأَقْضِيَ لَهُ بِنَحْوِ مَا أَسْمَعُ ، فَمَنْ قَضَيْتُ لَهُ بِحَقِّ أَخِيهِ فَإِنَّمَا أَقْطَعُ لَهُ قِطْعَةً مِنَ النَّارِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20219;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: « لا يَزَالَ المُؤْمِنُ فِي فُسْحَةٍ مِنْ دِينِهِ مَا لَمْ يُصِبْ دَمًا حرًا».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20220;
update hadith set arabic = 'عَنْ خَولَةَ بِنْتِ عَامِرٍ الأَنْصَارِيِّ ، وَهِيَ امْرَأَةُ حَمْزَةَ رَضِيَ اللَّهُ عَنْهُ وَعَنْهَا، قَالَتْ : سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «إِنَّ رِجَالًا يَتَخَوَّضُونَ فِي مَالِ اللهِ بِغَيْرِ حَقٍّ، فَلَهُمُ النَّارُ يَوْمَ الْقِيَامَةِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5331 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20221;
update hadith set arabic = 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ « المُؤْمِنُ لِلْمُؤْمِنِ كَالبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا» وَشَبَّكَ بَيْنَ أَصَابِعِهِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20222;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلّى اللهُ عَلَيْهِ وسَلَّم : «مَنْ مرَّ فِي شَيْءٍ مِنْ مَسَاجِدِنَا، أَوْ أَسْوَاقِنَا، وَمَعَهُ نَبْلٌ فَلْيُمْسِكْ، أَوْ لِيَقْبِضْ عَلَى نِصَالِهَا بكفِّهِ أنْ يُصِيبَ أَحَدًا مِنَ المُسْلِمِينَ مِنْهَا بِشَيْءٍ».', updated_at = now() where id = 20223;
update hadith set arabic = 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ « مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَرَاحُمِهِمْ وَتَعَاطُفِهِمْ، مَثَلُ الْجَسَدِ إِذَا اشْتَكَى مِنْهُ عُضْوٌ تَدَاعَى لَهُ سَائِرُ الْجَسَدِ بِالسَّهَرِ وَالْحُمَّى».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4969 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20224;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَبَّلَ النبيُّ الحسنَ بنَ عليٍّ رَضِيَ اللَّهُ عَنْهُمَا، وَعِنْدَهُ الأَقْرَعُ بنُ حَابِسٍ، فَقَالَ الأَقْرَعُ: إنَّ لِي عَشَرَةً مِنَ الوَلَدِ مَا قَبَّلْتُ مِنْهُمْ أَحَدًا. فَنَظَرَ إليهِ رسولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: «مَنْ لَا يَرْحَمْ لَا يُرْحَمْ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5440 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20225;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَدِمَ نَاسٌ مِنَ الأَعْرَابِ عَلَى رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا : أَتُقَبِّلُونَ صِبْيَانَكُمْ؟ فَقَالَ: "نَعَمْ" قَالُوا: لَكِنَّا واللهِ مَا نُقَبِّلُ ! فقال رسولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "أَوَ أَمْلِكُ إنْ كانَ اللهُ نَزَعَ مِنْ قُلُوبِكُمُ الرَّحْمَةَ؟".', updated_at = now() where id = 20226;
update hadith set arabic = 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ « مَنْ لَا يَرْحَمِ النَّاسَ لَا يَرْحَمْهُ اللهُ ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5439 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20227;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِذَا صَلَّى أَحَدُكُمْ لِلنَّاسِ، فَلْيُخَفِّفْ، فَإِنَّ فِيهِمُ الضَّعِيفَ وَالسَّقِيمَ وَالكَبِيرَ. وَإِذَا صَلَّى لِنَفْسِهِ فَلْيُطَوِّلْ مَا شَاءَ» ((مُتَّفَقٌ عَلَيْهِ)) . (10)', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20228;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: إنْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيَدَعُ العَمَلَ، وَهُوَ يُحِبُّ أَنْ يعملَ بِهِ، خَشْيَةَ أَنْ يعملَ بِهِ النَّاسُ فَيُفْرَضَ عَلَيْهِمْ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11282 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20229;
update hadith set arabic = 'وَعَنْهَا رَضِيَ اللَّهُ عَنْهَا قَالَتْ: نَهَاهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الوِصَالِ رَحْمَةً لَهُمْ، فَقَالُوا: إِنَّكَ تُوَاصِلُ؟ قَالَ: «إِنِّي لَسْتُ كَهَيْئَتِكُمْ، إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي وَيَسْقِينِي » ((مُتَّفَقٌ عَلَيْهِ)). مَعْنَاهُ يُجْعَلُ فِي قُوَّةِ مَنْ أَكَلَ وَشَرِبَ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20230;
update hadith set arabic = 'عَنْ أَبِي قَتَادَةَ الحَارِثِ بْنِ رِبْعِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِنِّي لَأَقُومُ إِلَى الصَّلَاةِ، وَأُرِيدُ أَنْ أُطَوِّلَ فِيهَا ، فَأَسْمَعُ بُكَاءَ الصَّبِيِّ، فأَتَجَوَّزُ فِي صَلَاتِي كَرَاهِيَةَ أَنْ أَشُقَّ عَلَى أُمِّهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4249 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20231;
update hadith set arabic = 'عَنْ جُندُبِ بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «مَنْ صَلَّى صَلَاةَ الصُّبْحِ فَهُوَ فِي ذِمَّةِ اللهِ فَلَا يَطْلُبَنَّكُمُ اللهُ مِنْ ذِمَّتِهِ بِشَيْءٍ، فَإِنَّهُ مَنْ يَطْلُبْهُ مِنْ ذِمَّتِهِ بِشَيْءٍ يُدْرِكْهُ، ثُمَّ يَكُبَّهُ عَلَى وَجْهِهِ فِي نَارِ جَهَنَّمَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5435 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20232;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «المُسْلِمُ أَخُو المُسْلِمِ، لَا يَظْلِمُهُ، وَلَايُسْلِمُهُ، مَنْ كَانَ فِي حَاجَةِ أَخِيهِ كَانَ اللَّهُ فِي حَاجَتِهِ، وَمَنْ فَرَّجَ عَنْ مُسْلِمٍ كُرْبَةً فَرَّجَ اللَّهُ عَنْهُ بِهَا كُرْبَةً مِنْ كُرَبِ يَوْمِ القِيَامَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ يَوْمَ القِيَامَةِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20233;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «المُسْلِمُ أَخُو المُسْلِمِ لَا يَخُونُهُ وَلَا يَكْذِبُهُ وَلَا يَخْذُلُهُ، كُلُّ المُسْلِمِ عَلَى المُسْلِمِ حَرَامٌ عِرْضُهُ وَمَالُهُ وَدَمُهُ، التَّقْوَى هَهُنَا، بِحَسْبِ امْرِئٍ مِنَ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ المُسْلِمَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20234;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا تَحَاسَدُوا، وَلَا تَنَاجَشُوا، وَلَا تَبَاغَضُوا، وَلَا تَدَابَرُوا وَلَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ، وَكُونُوا عِبَادَ اللهِ إِخْوَانًا. الْمُسْلِمُ أَخُو الْمُسْلِمِ: لَا يَظْلِمُهُ وَلَا يَحْقِرُهُ، وَلَا يَخْذُلُهُ. التَّقْوَى هَهُنَا- وَيُشِيرُ إِلَى صَدْرِهِ ثَلَاثَ مَرَّاتٍ- بِحَسْبِ امْرِئٍ مِنَ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ دَمُهُ وَمَالُهُ وَعِرْضُهُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4706 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20235;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قالَ: « لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4717 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20236;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا" فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ أَنْصُرُهُ إِذَا كَانَ مَظْلُومًا أَرَأَيْتَ إِنْ كَانَ ظَالِمًا كَيْفَ أَنْصُرُهُ؟ قَالَ: "تَحْجُزُهُ -أَوْ تَمْنَعُهُ- مِنَ الظُّلْمِ فَإِنَّ ذَلِكَ نَصْرُهُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4236 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20237;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "حَقُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ خَمْسٌ: رَدُّ السَّلَامِ، وَعِيَادَةُ الْمَرِيضِ، وَاتِّبَاعُ الْجَنَائِزِ وَإِجَابَةُ الدَّعْوَةِ، وَتَشْمِيتُ الْعَاطِسِ" ((مُتَّفَقٌ عَلَيْهِ)) . وَ فِي رِوَايَةٍ لِمُسْلِمٍ: "حَقُّ المُسْلِمِ عَلَى المُسْلِمِ سِتٌّ: اذَا لَقِيتَهُ فَسَلِّمْ عَلَيْهِ، وَ اذَا دَعَاكَ فَأَجِبْهُ، وَ اذَا اسْتَنْصَحَكَ فَانْصَحْ لَهُ، وَ اذَا عَطَسَ فَحَمِدَ اللَّهَ فَشَمِّتْهُ، وَ اذَا مَرِضَ فَعُدْهُ، وَ اذَا مَاتَ فَاتَّبِعْهُ."', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3706 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20238;
update hadith set arabic = 'عَنِ أَبِي عُمَارَةَ الْبَرَاءِ بْنِ عَازِبٍ رَضيَ اللهُ عنهما قَالَ: أَمَرَنَا رَسُولُ اللهِ r بِسَبْعٍ، وَنَهَانَا عَنْ سَبْعٍ: أَمَرَنَا بِعِيَادَةِ الْمَرِيضِ، وَاتِّبَاعِ الْجَنَازَةِ، وَتَشْمِيتِ الْعَاطِسِ، وَإِبْرَارِ الْمُقْسِمِ، وَنَصْرِ الْمَظْلُومِ، وَإِجَابَةِ الدَّاعِي، وَإِفْشَاءِ السَّلَامِ. وَنَهَانَا عَنْ خَوَاتِيمَ أَوْ تَخَتُّمٍ بِالذَّهَبِ ، وَعَنْ شُرْبٍ بِالْفِضَّةِ، وَعَنِ الْمَيَاثِرِ الحُمْرِ، وَعَنِ الْقَسِّيِّ، وَعَنْ لُبْسِ الْحَرِيرِ وَالْإِسْتَبْرَقِ وَالدِّيبَاجِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20239;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «لَا يَسْتُرُ عَبْدٌ عَبْدًا فِي الدُّنْيَا إِلَّا سَتَرَهُ اللهُ يَوْمَ الْقِيَامَةِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3777 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20240;
update hadith set arabic = 'وَعَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «كُلُّ أُمَّتِي مُعَافًى إِلَّا المُجَاهِرِينَ، وَإِنَّ مِنَ المُجَاهَرَةِ أَنْ يَعْمَلَ الرَّجُلُ بِاللَّيْلِ عَمَلًا، ثُمَّ يُصْبِحَ وَقَدْ سَتَرَهُ اللَّهُ عَلَيْهِ فَيَقُولَ: يَا فُلاَنُ عَمِلْتُ البَارِحَةَ كَذَا وَكَذَا، وَقَدْ بَاتَ يَسْتُرُهُ رَبُّهُ، وَيُصْبِحُ يَكْشِفُ سِتْرَ اللَّهِ عَنْهُ».', updated_at = now() where id = 20241;
update hadith set arabic = 'وَعَنْهُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِذَا زَنَتِ الأَمَةُ فَتَبَيَّنَ زِنَاهَا فَلْيَجْلِدْهَا الحَدَّ، وَلَا يُثَرِّبْ عَلَيْهَا، ثُمَّ إِنْ زَنَتِ الثَّانِيَةَ فَلْيَجْلِدْهَا الحَدَّ وَلَا يُثَرِّبْ عَلَيْهَا، ثُمَّ إِنْ زَنَتِ الثَّالِثَةَ فَلْيَبِعْهَا وَلَوْ بِحَبْلٍ مِنْ شَعَرٍ» ((مُتَّفَقٌ عَلَيْهِ)) . (15)', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20242;
update hadith set arabic = 'وَعَنْهُ قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَجُلٍ قَدْ شَرِبَ خَمْرًا قَالَ: "اضْرِبُوهُ" قَالَ أَبُو هُرَيْرَةَ : فَمِنَّا الضَّارِبُ بِيَدِهِ، وَالضَّارِبُ بِنَعْلِهِ، وَالضَّارِبُ بِثَوْبِهِ. فَلَمَّا انْصَرَفَ قَالَ بَعْضُ القَوْمِ: أَخْزَاكَ اللَّهُ قَالَ: "لَا تَقُولُوا هَكَذَا لَا تُعِينُوا عَلَيْهِ الشَّيْطَانَ".', updated_at = now() where id = 20243;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «المُسْلِمُ أَخُو المُسْلِمِ لَا يَظْلِمُهُ وَلَا يُسْلِمُهُ. مَنْ كَانَ فِي حَاجَةِ أَخِيهِ كَانَ اللَّهُ فِي حَاجَتِهِ، وَمَنْ فَرَّجَ عَنْ مُسْلِمٍ كُرْبَةً فَرَّجَ اللَّهُ عَنْهُ بِهَا كُرْبَةً مِنْ كُرَبِ يَوْمِ القِيَامَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ يَوْمَ القِيَامَةِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20244;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا، نَفَّسَ اللهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللهُ فِي الدُّنْيَا وَالْآخِرَةِ، وَاللهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ، وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللهُ لَهُ طَرِيقًا إِلَى الْجَنَّةِ. وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللهِ تَعَالَى، يَتْلُونَ كِتَابَ اللهِ، وَيَتَدَارَسُونَهُ بَيْنَهُمْ إِلَّا نَزَلَتْ عَلَيْهِمِ السَّكِينَةُ، وَغَشِيَتْهُمُ الرَّحْمَةُ، وَحَفَّتْهُمُ الْمَلَائِكَةُ، وَذَكَرَهُمُ اللهُ فِيمَنْ عِنْدَهُ. وَمَنْ بَطَّأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4801 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20245;
update hadith set arabic = 'عَنْ أَبِي مُوسَى الأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَتَاهُ طَالِبُ حَاجَةٍ أَقْبَلَ عَلَى جُلسائِهِ فَقَالَ: :اشْفَعُوا تُؤجَرُوا ويَقْضِي اللَّهُ عَلَى لسانِ نَبِيِّهِ مَا أَحَبَّ" ((مُتَّفَقٌ عَلَيْهِ)). (16)', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3563 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20246;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا فِي قِصَّةِ بَرِيرَةَ وَزَوْجِهَا. قَالَ: قَالَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْ رَاجَعْتِهِ؟" قَالَتْ: يَا رَسُولَ اللَّهِ تَأْمُرُنِي؟ قَالَ : "إِنَّمَا أشْفَعُ" قَالَتْ: لَا حَاجَةَ لِي فِيهِ.', updated_at = now() where id = 20247;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «كُلُّ سُلَامَى مِنَ النَّاسِ عَلَيْهِ صَدَقَةٌ، كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ: تَعْدِلُ بَيْنَ الِاثْنَيْنِ صَدَقَةٌ، وَتُعِينُ الرَّجُلَ عَلَى دَابَّتِهِ فَتَحْمِلُهُ عَلَيْهَا، أَوْ تَرْفَعُ لَهُ عَلَيْهَا مَتَاعَهُ صَدَقَةٌ. وَالكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ، وَبِكُلِّ خُطْوَةٍ تَمْشِيهَا إِلَى الصَّلَاةِ صَدَقَةٌ، وَتُمِيطُ الأَذَى عَنِ الطَّرِيقِ صَدَقَةٌ» ((مُتَّفَقٌ عَلَيْهِ)). (17)', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66527 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20248;
update hadith set arabic = 'عَنْ أُمِّ كُلْثُومٍ بِنْتِ عُقْبَةَ بْنِ أَبِي مُعَيطٍ رَضِيَ اللَّهُ عَنْهَا قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَيْسَ الكَذَّابُ الَّذِي يُصلِحُ بَيْنَ النَّاسِ فَيَنْمِي خَيْرًا، أَوْ يَقُولُ خَيْرًا" ((مُتَّفَقٌ عَلَيْهِ)). وَ فِي رِوَايَةِ مُسْلِمٍ زِيَادَةٌ، قَالَتْ: "وَ لَمْ اسْمَعْهُ يُرَخِّصُهُ فِي شَيْءٍ مِمَّا يَقُولُهُ النَّاسُ الا فِي ثَلَاثٍ، تَعْنِي: الحَرْبَ، وَ الاصْلَاحَ بَيْنَ النَّاسِ، وَ حَدِيثَ الرَّجُلِ امْرَاتَهُ، وَ حَدِيثَ المَرْأَةِ زَوْجَهَا".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20249;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَوْتَ خُصُومٍ بِالبَابِ عاليةً أصواتُهما، وَإِذَا أَحدُهُمَا يَسْتَوْضِعُ الآخَرَ وَيَسْتَرْفِقُهُ فِي شَيْءٍ، وَهُوَ يَقُولُ: وَاللَّهِ لَا أَفْعَلُ، فَخَرَجَ عَلَيْهِمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: «أَيْنَ المُتَأَلِّي عَلَى اللَّهِ لَا يَفْعَلُ المَعْرُوفَ؟ » فَقَالَ: أَنَا يَا رَسُولَ اللَّهِ ، فَلَهُ أَيُّ ذَلِكَ أَحَبَّ.', updated_at = now() where id = 20250;
update hadith set arabic = 'عَنْ أَبِي العَبَّاسِ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَلَغَهُ أَنَّ بَنِي عَمْرِو بْنِ عَوْفٍ كَانَ بَيْنَهُمْ شَرٌّ، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصْلِحُ بَيْنَهُمْ فِي أُنَاسٍ مَعَهُ ، فحُبِسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وحَانَتِ الصَّلَاةُ، فَهَلْ لَكَ أَنْ تَؤُمَّ النَّاسَ؟ قَالَ: نَعَمْ إِنْ شِئتَ، فَأَقَامَ بِلَالٌ الصَّلَاةَ، وَتَقَدَّمَ أَبُو بَكْرٍ فكبَّرَ وكبَّرَ النَّاسُ،وَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْشِي فِي الصُّفُوفِ حَتَّى قَامَ فِي الصفِّ، فَأَخَذَ النَّاسُ فِي التَّصْفيقِ، وَكَانَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ لَا يَلْتَفِتُ فِي صَلَاتِهِ، فَلَمَّا أَكْثَرَ النَّاسُ التَّصْفيقِ الْتَفَتَ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَشَارَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَرَفَعَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ يَدَهُ فَحَمِدَ اللَّهَ، وَرَجَعَ القَهْقَرَى وَرَاءَهُ حَتَّى قَامَ فِي الصَّفِّ، فَتَقَدَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَصَلَّى لِلنَّاسِ، فَلَمَّا فَرَغَ أَقْبَلَ عَلَى النَّاسِ فَقَالَ: «أَيُّهَا النَّاسُ مَا لَكُمْ حِينَ نَابَكُمْ شَيْءٌ فِي الصَّلَاةِ أَخَذْتُمْ فِي التَّصْفِيقِ ؟ إِنَّمَا التَّصْفِيقُ لِلنِّسَاءِ. مَنْ نَابَهُ شَيْءٌ فِي صَلَاتِهِ فليَقُلْ سُبْحَانَ اللَّهِ، فَإِنَّهُ لَا يَسْمَعُهُ أَحَدٌ حِينَ يَقُولُ سُبْحَانَ اللَّهِ إِلَّا التَفَتَ، : يَا أَبَا بَكْرٍ: مَا مَنَعَكَ أَنْ تُصَلِّيَ النَّاسَ حِينَ أشَرْتُ إِلَيْكَ؟» فَقَالَ أَبُو بَكْرٍ: مَا كَانَ يَنْبَغِي لِابْنِ أَبِي قُحَافَةَ أَنْ يُصَلِّيَ بِالنَّاسِ بَيْنَ يَدَيْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. ((مُتَّفَقٌ عَلَيْهِ)). (20).', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6973 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20251;
update hadith set arabic = 'عَنْ حَارِثَةَ بْنِ وَهْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «أَلاَ أُخْبِرُكُمْ بِأَهْلِ الجَنَّةِ؟ كُلُّ ضَعِيفٍ مُتَضَعِّفٍ ، لَوْ أَقْسَمَ عَلَى اللَّهِ لَأَبَرَّهُ. أَلاَ أُخْبِرُكُمْ بِأَهْلِ النَّارِ؟ كُلُّ عُتُلٍّ جَوَّاظٍ مُسْتَكْبِرٍ» ((مُتَّفَقٌ عَلَيْهِ)) . (21)', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3573 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20252;
update hadith set arabic = 'عَنْ أَبِي العَبَّاسِ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَرَّ رجلٌ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لِرَجُلٍ عِنْدَهُ جالسٌ: "مَا رأيُكَ فِي هَذا؟" فَقَالَ: رَجُلٌ مِنْ أَشرافِ النَّاسِ، هَذَا وَاللَّهِ حَرِيٌّ إِنْ خَطبَ أَنْ يُنْكَحَ، وَإِنْ شَفعَ أَنْ يُشَفَّعَ . فَسكتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ مرَّ رجلٌ آخَرُ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: " مَا رأيُكَ فِي هَذَا؟" فَقَالَ: يَا رَسُولَ اللَّهِ هَذَا رجلٌ مِنْ فُقَرَاءِ المُسْلِمِينَ هَذَا حَرِيٌّ إِنْ خَطبَ أَنْ لَا يُنْكَحَ، وَإِنْ شَفَعَ أَنْ لَا يُشَفَّعَ، وَإِنْ قَالَ أَنْ لَا يُسمَعَ لِقَوْلِهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَذَا خَيرٌ مِنْ مِلءِ الأَرْضِ مِثْلَ هَذَا" ((مُتَّفَقٌ عَلَيْهِ)) . (22)', updated_at = now() where id = 20253;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « احْتَجَّتِ الجنَّةُ وَالنَّارُ فقالتِ النَّارُ: فيَّ الجبَّارونَ والمُتَكَبِّرُونَ، وقالتِ الجنَّةُ: فيَّ ضُعَفَاءُ النَّاسِ ومساكِينُهُم، فَقَضَى اللَّهُ بَيْنَهُمَا: إِنَّكِ الجنَّةُ رحْمَتي أَرحمُ بِكِ مَنْ أَشَاءُ، وَإِنَّكِ النَّارُ أُعذبُ بِكِ مَنْ أَشَاءُ، ولِكِلَيْكُمَا عليَّ مِلْؤُهَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3261 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20254;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « إِنَّهُ لَيَأتِي الرَّجلُ السَّمِينُ العَظِيمُ يَوْمَ القِيَامَةِ لَا يَزِنُ عِنْدَ اللَّهِ جَناحَ بَعُوضَةٍ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3776 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20255;
update hadith set arabic = 'وَعَنْهُ أَنَّ امْرَأَةً سَوْدَاءَ كَانَتْ تَقُمُّ المَسْجِدَ، أَوْ شَابًّا، فَفَقَدَهَا، رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَ عَنْهَا أَوْ عَنْهُ، فَقَالُوا: مَاتَ. قَالَ: " أَفَلَا كُنْتُمْ آذَنْتُمُونِي" فَكَأَنَّهُمْ صَغَّرُوا أَمْرَهَا، أَوْ أَمْرَهُ، فَقَالَ: " دُلُّونِي عَلَى قَبْرِهِ" فَدَلُّوهُ فَصَلَّى عَلَيْهِ، ثُمَّ قَالَ: " إِنَّ هَذِهِ القُبُورَ مَمْلُوءَةٌ ظُلْمَةً عَلَى أَهْلِهَا، وَإِنَّ اللَّهَ تَعَالَى يُنَوِّرُهَا لَهُمْ بِصَلَاتِي عَلَيْهِمْ" ((مُتَّفَقٌ عَلَيْهِ)). (23)', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65413 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20256;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «رُبَّ أَشْعَثَ أَغْبَرَ مَدْفُوعٍ بِالأَبْوَابِ لَوْ أَقْسَمَ عَلَى اللَّهِ لَأَبَرَّهُ ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20257;
update hadith set arabic = 'عَنْ أُسَامَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « قُمْتُ عَلَى بَابِ الجنَّةِ، فَإِذَا عامَّةُ مَنْ دَخَلَهَا المَسَاكِينُ، وَأَصْحَابُ الجَدِّ مَحْبُوسُونَ، غَيْرَ أَنَّ أصحابَ النَّارِ قَدْ أُمِرَ بِهِمْ إِلَى النَّارِ. وقُمْتُ عَلَى بَابِ النَّارِ فَإِذَا عَامَّةُ مَنْ دَخَلَهَا النِّسَاءُ» ((مُتَّفَقٌ عَلَيْهِ)). (24)', updated_at = now() where id = 20258;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: " لَمْ يتكلَّمْ فِي المَهْدِ إِلَّا ثَلَاثَةٌ: عِيسَى ابْنُ مَرْيَمَ، وَصَاحِبُ جرَيجٍ، وَكَانَ جُريجٌ رَجُلًا عابِدًا، فَاتَّخَذَ صَوْمَعَةً فَكَانَ فِيهَا، فَأَتَتْهُ أُمُّهُ وَهُوَ يُصَلِّي فَقَالَتْ: يَا جُرَيْجُ، فَأَتَتْهُ أُمُّهُ وَهُوَ يُصَلِّي فَقَالَتْ: يَا جُرَيْجُ، فَقَالَ: يَا رَبِّ أُمِّي وَصَلَاتِي فَأَقْبَلَ عَلَى صَلَاتِهِ فَانْصَرفَتْ. فلمَّا كَانَ مِنَ الغَدِ أتَتْهُ وَهُوَ يُصَلِّي، فَقَالَتْ: يَا جُريجُ، فَقَالَ: أَيْ رَبِّ أمِّي وَصَلَاتِي، فَأَقْبَلَ عَلَى صَلَاتِهِ، فَقَالَتْ: اللَّهُمَّ لَاتُمِتْهُ حَتَّى يَنظُرَ إِلَى وُجُوهِ المُومِسَاتِ. فَتَذَاكَرَ بَنُو إِسْرَائِيلَ جُريجًا وَعِبَادَتَهُ، وَكَانَتِ امْرَأَةٌ بَغِيٌّ يُتَمَثَّلُ بحُسنِهَا، فَقَالَتْ: إِنْ شِئتُمْ لَأَفْتِنَنَّهُ، فتَعرَّضَتْ لَهُ، فَلَمْ يَلتَفِتْ إِلَيْهَا، فَأَتَتْ راعِيًا كَانَ يَأوِي إِلَى صَوْمَعَتِهِ، فَأَمْكَنَتْهُ مِنْ نَفسِهَا فَوَقَعَ عَلَيْهَا. فَحَمَلَتْ، وَجَعَلُوا يَضرِبُونَهُ، فَقَالَ: مَا شَأنُكُمْ؟ قَالُوا: زَنَيْتَ بِهَذِهِ البَغِيِّ فوَلَدَتْ مِنْكَ. قَالَ: أَيْنَ الصَّبِيُّ؟ فَجَاءُوا بِهِ فَقَالَ: دَعونِي حَتَّى أُصلَّيَ، فصلَّى، فلمَّا انْصرفَ أَتَى الصَّبِيَّ فَطَعنَ فِي بَطنِهِ وَقَالَ: يَاغُلَامُ مَنْ أَبُوكَ؟ قَالَ: فلانٌ الرَّاعِي، فَأَقْبَلُوا عَلَى جُريجٍ يُقَبِّلُونَهُ وَيَتمسَّحُونَ بِهِ وَقَالُوا: نَبْنِي لَكَ صَوْمَعَتَكَ مِنْ ذَهَبٍ، قَالَ: لَا، أعِيدُوهَا مِنْ طِينٍ كَمَا كَانَتْ، فَفَعَلُوا. وَبَيْنَا صَبِيٌّ يَرضَعُ مِنْ أُمِّهِ، فمرَّ رَجُلٌ رَاكِبٌ عَلَى دَابَّةٍ فَارِهَةٍ وَشَارَةٍ حسَنَةٍ، فَقَالَتْ: " اللَّهُمَّ اجْعَلِ ابْنِي مِثْلَ هَذَا، فَتركَ الثَّدْيَ وأقْبَلَ إِلَيْهِ فنَظَرَ إِلَيْهِ فَقَالَ: اللَّهُمَّ لَا تَجْعَلْنِي مثْلَهُ، ثُمَّ أقْبَلَ عَلَى ثَدْيِهِ فَجَعَلَ يَرتَضِعُ" فَكَأَنِّي أَنْظُرُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَحكِي ارتْضَاعَهُ بِأصْبَعِهِ السَّبَّابَةِ فِي فِيهِ، فَجَعَلَ يَمُصُّهَا، قَالَ: "ومَرُّوا بِجَارِيَةٍ وَهُمْ يَضْرِبُونَهَا، وَيَقُولُونَ: زَنَيْتِ سَرَقْتِ، وَهِيَ تَقُولُ: حَسبِيَ اللَّهُ وَنِعْمَ الوَكِيلُ. فَقَالَتْ أُمُّهُ: اللَّهُمَّ لَا تَجْعَلِ ابْنِي مِثلَهَا، فَتَرَكَ الرَّضاعَ وَنَظَرَ إِلَيْهَا فَقَالَ: اللَّهُمَّ اجْعَلْنِي مِثْلَهَا، فَهُنَاكَ تَرَاجَعَا الحَدِيثَ فَقَالَتْ: مرَّ رجلٌ حَسَنُ الهَيْئَةِ فَقُلْتُ: اللَّهُمَّ اجْعَلِ ابْنِي مِثْلَهُ فَقُلْتَ: اللَّهُمَّ لَا تَجْعَلْنِي مِثْلَهُ، ومَرُّوا بِهَذِهِ الأَمَةِ وَهُمْ يَضرِبُونَهَا وَيَقُولُونَ: زَنَيْتِ سَرَقْتِ، فَقُلْتُ: اللَّهُمَّ لَا تَجْعَلِ ابْنِي مِثلَهَا فَقُلْتَ: اللَّهُمَّ اجْعَلْنِي مِثلَهَا؟! قَالَ: إِنَّ ذَلِكَ الرَّجُلَ كَانَ جبَّارًا فَقُلْتُ: اللَّهُمَّ لَا تَجْعَلْنِي مِثْلَهُ، وَإِنَّ هَذِهِ يَقُولُونَ لَهَا زَنَيْتِ، وَلَمْ تَزْنِ وسَرَقْتِ، وَلَمْ تَسْرِقْ، فَقُلْتُ: اللَّهُمَّ اجْعَلْنِي مِثْلَهَا" ((مُتَّفَقٌ عَلَيْهِ)). (25)', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/7041 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20259;
update hadith set arabic = 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سِتَّةَ نَفَرٍ، فَقَالَ المُشْرِكُونَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اطْرُدْ هَؤُلَاءِ لَايَجْتَرِئُونَ عَلَيْنَا، وَكُنْتُ أَنَا وَابْنُ مَسْعُودٍ وَرَجُلَانِ لَسْتُ أُسَمِّيهِمَا، فَوَقَعَ فِي نَفْسِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا شَاءَ اللَّهُ أَنْ يَقَعَ، فَحَدَّثَ نَفْسَهُ، فَأَنْزَلَ اللَّهُ تَعَالَى: {وَلَا تَطْرُدِ الَّذِينَ يَدْعُونَ رَبَّهُمْ بِالْغَدَاةِ وَالْعَشِيِّ يُرِيدُونَ وَجْهَهُ}.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20260;
update hadith set arabic = 'عَنْ أَبِي هُبَيْرَةَ عَائِذِ بْنِ عَمْرٍو المُزَنِيِّ وَهُوَ مِنْ أَهْلِ بَيْعَةِ الرِّضْوَانِ رَضِيَ اللَّهُ عَنْهُ، أَنَّ أَبَا سُفْيَانَ أَتَى عَلَى سَلْمَانَ وَصُهَيْبٍ وَبِلَالٍ فِي نَفَرٍ فَقَالُوا: مَا أخذتْ سيوفُ اللهِ مِنْ عدوِّ اللَّهِ مَأْخَذَهَا، فَقَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: أَتَقُولُونَ هَذَا لشيخِ قريشٍ وسيدِهم؟ فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخْبَرَهُ فَقَالَ: «يَا أَبَا بَكْرٍ لَعَلَّكَ أغضبتَهم؟ لَئِنْ كنتَ أَغْضَبْتَهُمْ لَقَدْ أغضبتَ ربَّكَ» فَأَتَاهُمْ فَقَالَ: يَاإِخْوَتَاهْ أغضبتُكم؟ قَالُوا: لَا، يَغْفِرُ اللَّهُ لَكَ يَا أُخَيَّ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20261;
update hadith set arabic = 'عَنْ سَهْلِ بْنِ سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ: قَالَ رَسُولُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « أَنَا وَكَافِلُ اليَتِيمِ فِي الجَنَّةِ هَكَذَا» وَأَشَارَ بِالسَّبَّابَةِ وَالوُسْطَى، وَفَرَّجَ بَيْنَهُمَا.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20262;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « كَافِلُ اليَتِيمِ لَهُ أَوْ لِغَيْرِهِ أَنَا وَهُوَ كَهَاتَيْنِ فِي الجَنَّةِ» وَأَشَارَ الرَّاوِي وَهُوَ مَالِكُ ابْنُ أَنَسٍ بِالسَّبَّابَةِ وَالوُسْطَى.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20263;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رسُولَ اللَّهِ صَلّى اللهُ عَلَيْهِ وسَلَّم: « لَيسَ المِسْكِينُ الَّذِي تَرُدُّهُ التَّمْرَةُ والتَّمْرَتَانِ، وَلا اللُّقْمَةُ واللُّقْمَتَانِ إِنَّمَا المِسْكِينُ الَّذِي يَتَعَفَّفُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3141 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20264;
update hadith set arabic = 'وَعَنْهُ عَنْ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: " السَّاعِي عَلَى الأَرْمَلَةِ وَالمِسْكِينِ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ" وَأَحْسِبُهُ قَالَ: " وَكَالْقَائِمِ الَّذِي لَا يَفْتُرُ، وَكَالصَّائِمِ الَّذِي لَا يُفْطِرُ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20265;
update hadith set arabic = 'وَعَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « شَرُّ الطَّعَامِ طَعَامُ الوَلِيمَةِ، يُمْنَعُهَا مَنْ يَأْتِيهَا، وَيُدْعَى إِلَيْهَا مَنْ يَأْبَاهَا، وَمَنْ لَمْ يُجِبِ الدَّعْوَةَ فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20266;
update hadith set arabic = 'عَنْ أَنَسِ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «مَنْ عَالَ جَارِيَتَيْنِ حَتَّى تَبْلُغَا جَاءَ يَوْمَ الْقِيَامَةِ أَنَا وَهُوَ كَهَاتَيْنِ» وَضَمَّ أَصَابِعَهُ.((رَوَاهُ مُسْلِمٌ)). (29)', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3360 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20267;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: "دَخَلَتْ عَلَيَّ امْرَأَةٌ وَمَعَهَا ابْنَتَانِ لَهَا تَسْأَلُ ، فَلَمْ تَجِدْ عِنْدِي شَيْئًا غَيْرَ تَمْرَةٍ وَاحِدَةٍ، فَأَعْطَيْتُهَا إِيَّاهَا فَقَسَمَتْهَا بَيْنَ ابْنَتَيْهَا وَلَمْ تَأْكُلْ مِنْهَا، ثُمَّ قَامَتْ فَخَرَجَتْ، فَدَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْنَا، فَأَخْبَرْتُهُ فَقَالَ: "مَنِ ابْتُلِيَ مِنْ هَذِهِ البَنَاتِ بِشَيْءٍ فَأَحْسَنَ إِلَيْهِنَّ كُنَّ لَهُ سِتْرًا مِنَ النَّارِ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20268;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضيَ اللهُ عنها قَالَتْ: جَاءَتْنِي مِسْكِينَةٌ تَحْمِلُ ابْنَتَيْنِ لَهَا، فَأَطْعَمْتُهَا ثَلَاثَ تَمَرَاتٍ، فَأَعْطَتْ كُلَّ وَاحِدَةٍ مِنْهُمَا تَمْرَةً وَرَفَعَتْ إِلَى فِيهَا تَمْرَةً لِتَأْكُلَهَا ، فَاسْتَطْعَمَتْهَا ابْنَتَاهَا، فَشَقَّتِ التَّمْرَةَ الَّتِي كَانَتْ تُرِيدُ أَنْ تَأْكُلَهَا بَيْنَهُمَا، فَأَعْجَبَنِي شَأْنُهَا، فَذَكَرْتُ الَّذِي صَنَعَتْ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: «إِنَّ اللهَ قَدْ أَوْجَبَ لَهَا بِهَا الْجَنَّةَ، أَوْ أَعْتَقَهَا بِهَا مِنَ النَّارِ».', updated_at = now() where id = 20269;
update hadith set arabic = 'عَنْ أَبِي شُرَيْحٍ خُوَيْلِدِ بْنِ عَمْرٍو الخُزَاعِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «اللَّهُمَّ إِنِّي أُحَرِّجُ حَقَّ الضَّعِيفَيْنِ اليَتِيمِ وَالمَرْأَةِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20270;
update hadith set arabic = 'عَنْ مُصْعَبِ بْنِ سَعْدٍ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: رَأَى سَعْدٌ أَنَّ لَهُ فَضْلًا عَلَى مَنْ دُونَهُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «هَلْ تُنْصَرُونَ وَتُرْزَقُونَ إِلَّا بِضُعَفَائِكُمْ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20271;
update hadith set arabic = 'عَنْ أَبِي الدَّرْدَاءِ عُوَيْمِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «ابْغُونِي فِي الضُّعَفَاءِ ، فَإِنَّمَا تُنْصَرُونَ، وَتُرْزَقُونَ بِضُعَفَائِكُمْ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20272;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "اسْتَوْصُوا بالنِّساءِ خَيْرًا، فَإِنَّ المَرْأَةَ خُلِقَتْ مِن ضِلعٍ، وَإنَّ أعْوَجَ مَا فِي الضِّلَعِ أعْلاهُ، فَإنْ ذَهَبتَ تُقيمُهُ كَسَرْتَهُ، وَإِنْ تَرَكْتَهُ، لَمْ يَزَلْ أَعْوَجَ، فَاسْتَوْصُوا بِالنِّسَاءِ" ((مُتَّفَقٌ عَلَيْهِ)). وَفِي رِوَايَةٍ فِي ((الصَّحِيحَيْنِ)) : "المَرْأَةُ كَالضِّلَعِ إنْ أقَمْتَهَا كَسَرْتَهَا، وَإنِ اسْتَمتَعْتَ بِهَا، اسْتَمْتَعْتَ وَفِيهَا عوَجٌ". وَفِي رِوَايَةٍ لِمُسْلِمٍ: "إنَّ المَرأةَ خُلِقَت مِنْ ضِلَعٍ ، لَنْ تَسْتَقِيمَ لَكَ عَلَى طَريقةٍ، فَإِنِ اسْتَمَعْتَ بِهَا وَفِيهَا عِوَجٌ، وإنْ ذَهَبْتَ تُقِيمُهَا كَسَرْتَها ، وَكَسْرُهَا طَلاَقُهَا".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3049 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20273;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ زَمْعَةَ رَضِيَ اللَّهُ عَنْهُ ، أنّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ، وَذَكَرَ النَّاقَةَ وَالَّذِي عَقَرَهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : (إذِ انبَعَثَ أَشْقَاهَا) انْبَعَثَ لَهَا رَجُلٌ عزِيزٌ، عَارِمٌ مَنِيعٌ فِي رَهطِهِ" ثُمَّ ذَكَرَ النِّسَاءَ، فَوَعَظَ فيهنَّ، فَقَالَ : "يَعمِدُ أَحَدُكُمْ فَيَجْلِدُ امْرَأَتَهُ جَلْدَ العَبْدِ فلعلَّهُ يُضَاجِعُهَا مِنْ آخِرِ يَوْمِهِ" ثمَّ وَعَظَهُمْ فِي ضَحِكِهم مِنَ الضَّرطَةِ وَقَالَ: "لِمَ يَضْحَكُ أَحَدُكُمْ ممَّا يَفْعَلُ؟".', updated_at = now() where id = 20274;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ : قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : "لَا يَفْرَكْ مُؤْمِنٌ مُؤْمِنَةً إِنْ كَرِهَ مِنْهَا خُلُقًا رَضِيَ مِنْهَا آخَرَ" أَوْ قَالَ : "غَيْرَهُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3071 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20275;
update hadith set arabic = 'عَنْ عَمْرِو بْنِ الأَحْوَضِ الجُشَمِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الوَدَاعِ يَقُولُ بَعْدَ أَنْ حَمِدَ اللَّهَ تَعَالَى، وَأَثْنَى عَلَيْهِ وَذَكَّرَ وَوَعَظَ، ثُمَّ قَالَ: «أَلَا وَاسْتَوْصُوا بِالنِّسَاءِ خَيْرًا فَإِنَّمَا هُنَّ عَوَانٍ عِنْدَكُمْ لَيْسَ تَمْلِكُونَ مِنْهُنَّ شَيْئًا غَيْرَ ذَلِكَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ، فَإِنْ فَعَلْنَ فَاهْجُرُوهُنَّ فِي المَضَاجِعِ، وَاضْرِبُوهُنَّ ضَرْبًا غَيْرَ مُبَرِّحٍ، فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا عَلَيْهِنَّ سَبِيلًا، أَلَا إِنَّ لَكُمْ عَلَى نِسَائِكُمْ حَقًّا، وَلِنِسَائِكُمْ عَلَيْكُمْ حَقًّا، فَحَقُّكُمْ عَلَيْهِنَّ أَنْ لَا يُوطِئْنَ فُرُشَكُمْ مَنْ تَكْرَهُونَ، وَلَا يَأْذَنَّ فِي بُيُوتِكُمْ لِمَنْ تَكْرَهُونَ، أَلَا وَحَقُّهُنَّ عَلَيْكُمْ أَنْ تُحْسِنُوا إِلَيْهِنَّ فِي كِسْوَتِهِنَّ وَطَعَامِهِنَّ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20276;
update hadith set arabic = 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ : قُلْتُ يَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا حَقُّ زَوْجَةِ أَحَدِنَا عَلَيْهِ؟ قَالَ: "أَنْ تُطْعِمَهَا إِذَا طَعِمْتَ ، وَتَكْسُوَهَا إِذَا اكْتَسَيْتَ وَلَا تَضْرِبِ الْوَجْهَ، وَلَا تُقَبِّحْ، وَلَا تَهْجُرْ إِلَّا فِي الْبَيْتِ " حَدِيثٌ حَسَنٌ رَوَاهُ أَبُو دَاوُدَ وَقَالَ: مَعْنَى "لَاتُقَبِّحْ" أَيْ : لَا تَقُلْ قَبَّحَكِ اللَّهُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/58093 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20277;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ : قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا، وَخِيَارُكُمْ خِيَارُكُمْ لِنِسَائِهِمْ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5792 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20278;
update hadith set arabic = 'عَنْ إِيَاسِ بْنِ أَبِي ذُبَابٍ رَضيَ اللهُ عنه قَالَ: قَالَ رَسُولُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : "لَاتَضْرِبُوا إِمَاءَ اللَّهِ" فَجَاءَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَ : ذَئِرْنَ النِّسَاءُ عَلَى أَزْوَاجِهِنَّ، فَرَخَّصَ فِي ضَرْبِهِنَّ، فَأَطَافَ بِآلِ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نِسَاءٌ كَثِيرٌ يَشْكُونَ أَزْوَاجَهُنَّ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : "لَقَدْ أَطَافَ بِآلِ بَيْتِ مُحَمَّدٍ نِسَاءٌ كَثِيرٌ يَشْكُونَ أَزْوَاجَهُنَّ لَيْسَ أُولَئِكَ بِخِيَارِكُمْ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20279;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «الدُّنْيَا مَتَاعٌ، وَخَيْرُ مَتَاعِهَا المَرْأَةُ الصَّالِحَةُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20280;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :"إِذَا دَعَا الرَّجُلُ امْرَأَتَهُ إِلَى فِرَاشِهِ فَلَمْ تَأْتِهِ فَبَاتَ غَضْبَانَ عَلَيْهَا لَعَنَتْهَا المَلَائِكَةُ حَتَّى تُصْبِحَ" ((مُتَّفَقٌ عَلَيْهِ)). وَفِي رِوَايَةٍ لَهَا "إِذَا بَاتَتِ المَرْأَةُ هَاجِرَةً فِرَاشَ زَوْجِهَا لَعَنَتْهَا المَلَائِكَةُ حَتَّى تُصْبِحَ". وَفِي رِوَايَةٍ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : " وَالَّذِي نَفْسِي بِيَدِهِ مَا مِنْ رَجُلٍ يَدْعُو امْرَأَتَهُ إِلَى فِرَاشِهِ فَتَأْبَى عَلَيْهِ إِلَّا كَانَ الَّذِي فِي السَّمَاءِ سَاخِطًا عَلَيْهَا حَتَّى يَرْضَى عَنْهَا".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/58098 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20281;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَيْضًا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ؛ « لَا يَحِلُّ لِامْرَأَةٍ أَنْ تَصُومَ وَزَوْجُهَا شَاهِدٌ إِلَّا بِإِذْنِهِ، وَلَا تَأْذَنَ فِي بَيْتِهِ إِلَّا بِإِذْنِهِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20282;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « كُلُّكُمْ رَاعٍ، وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالأَمِيرُ رَاعٍ، وَالرَّجُلُ رَاعٍ عَلَى أَهْلِ بَيْتِهِ؛ وَالمَرْأَةُ رَاعِيَةٌ عَلَى بَيْتِ زَوْجِهَا وَوَلَدِهِ، فَكُلُّكُمْ رَاعٍ، وَكُلُّكُمْ مَسْؤُولٌ عَنْ رَعِيَّتِهِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20283;
update hadith set arabic = 'عَنْ أَبِي عَلِيٍّ طَلْقِ بْنِ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « إِذَا دَعَا الرَّجُلُ زَوْجَتَهُ لِحَاجَتِهِ فَلْتَأتِهِ وَإِنْ كَانَتْ عَلَى التَّنُّورِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5788 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20284;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « لَوْ كُنْتُ آمِرًا أَحَدًا أَنْ يَسْجُدَ لِأَحَدٍ لَأَمَرْتُ المَرْأَةَ أَنْ تَسْجُدَ لِزَوْجِهَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5826 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20285;
update hadith set arabic = 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « أَيُّمَا امْرَأَةٍ مَاتَتْ، وَزَوْجُهَا عَنْهَا رَاضٍ دَخَلَتِ الجَنَّةَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20286;
update hadith set arabic = 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « لَا تُؤْذِي امرأةٌ زوجَهَا فِي الدُّنْيَا إِلَّا قَالَتْ زَوْجَةٌ مِنَ الحُورِ العِينِ لَا تُؤْذِيهِ قَاتَلَكِ اللَّهُ! فَإِنَّمَا هُوَ عِنْدَكِ دَخِيلٌ يُوشِكُ أَنْ يُفارِقَكِ إِلَيْنَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5822 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20287;
update hadith set arabic = 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « مَا تَرَكْتُ بَعْدِي فِتْنَةً هِيَ أَضَرَّ عَلَى الرِّجَالِ مِنَ النِّسَاءِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5830 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20288;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قالَ: قالَ رَسُولُ اللَّهِ صلَّى اللَّهُ عليْهِ وسلَّمَ : « دِينَارٌ أَنْفَقْتَهُ فِي سَبِيلِ اللهِ، وَدِينَارٌ أَنْفَقْتَهُ فِي رَقَبَةٍ، وَدِينَارٌ تَصَدَّقْتَ بِهِ عَلَى مِسْكِينٍ، وَدِينَارٌ أَنْفَقْتَهُ عَلَى أَهْلِكَ، أَعْظَمُهَا أَجْرًا الَّذِي أَنْفَقْتَهُ عَلَى أَهْلِكَ».', updated_at = now() where id = 20289;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ اللَّهِ - وَيُقَالُ لَهُ: أَبُو عَبْدِ الرَّحْمَنِ - ثَوْبَانَ بْنِ بُجْدُدٍ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « أَفْضَلُ دِينَارٍ يُنْفِقُهُ الرَّجُلُ دِينَارٌ يُنْفِقُهُ عَلَى عِيَالِهِ، وَدِينَارٌ يُنْفِقُهُ عَلَى دَابَّتِهِ فِي سَبِيلِ اللَّهِ، وَدِينَارٌ يُنْفِقُهُ عَلَى أَصْحَابِهِ فِي سَبِيلِ اللَّهِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20290;
update hadith set arabic = 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قُلْتُ يَارَسُولَ اللَّهِ، هَلْ لِي أجرٌ فِي بَنِي أَبِي سَلَمَةَ أَنْ أُنْفِقَ عَلَيْهِمْ، ولستُ بِتَارِكَتِهِمْ هَكَذَا وَهَكَذَا إِنَّمَا هُمْ بَنِيَّ؟ فَقَالَ: « نَعَمْ لَكِ أجرُ مَا أنفقتِ عَلَيْهِمْ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4959 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20291;
update hadith set arabic = 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ فِي حَدِيثِهِ الطَّوِيلِ الَّذِي قَدَّمْنَاهُ فِي أَوَّلِ الكِتَابِ فِي بَابِ النِّيَّةِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: « وَإِنَّكَ لَنْ تُنْفِقَ تَبْغِي بِهَا وَجْهَ اللَّهِ إِلَّا أُجِرْتَ بِهَا حَتَّى مَا تَجْعَلُ فِي فِي امْرَأَتِكَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20292;
update hadith set arabic = 'عَنْ أَبِي مَسْعُودٍ البَدْرِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « إِذَا أَنْفَقَ الرَّجُلُ عَلَى أَهْلِهِ نَفَقَةً يَحْتَسِبُهَا فَهِيَ لَهُ صَدَقَةٌ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20293;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : " كَفَى بِالمَرْءِ إِثْمًا أَنْ يُضَيِّعَ مَنْ يَقُوتُ" حَدِيثٌ صَحِيحٌ ((رَوَاهُ أَبُو دَاوُدَ وَغَيْرُهُ)). وَرَوَاهُ مُسْلِمٌ فِي صَحِيحِهِ بِمَعْنَاهُ قَالَ: " كَفَى بِالمَرْءِ إِثْمًا أَنْ يَحْبِسَ عَمَّنْ يَمْلِكُ قُوتَهُ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20294;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « مَا مِنْ يَوْمٍ يُصْبِحُ العِبَادُ فِيهِ إِلَّا مَلَكَانِ يَنْزِلاَنِ، فَيَقُولُ أَحَدُهُمَا: اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا، وَيَقُولُ الآخَرُ: اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا».', updated_at = now() where id = 20295;
update hadith set arabic = 'وَعَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « اليَدُ العُلْيَا خَيْرٌ مِنَ اليَدِ السُّفْلَى وَابْدَأْ بِمَنْ تَعُولُ، وَخَيْرُ الصَّدَقَةِ مَا كَانَ عَنْ ظَهْرِ غِنًى، وَمَنْ يَسْتَعْفِفْ، يُعِفَّهُ اللَّهُ، وَمَنْ يَسْتَغْنِ، يُغْنِهِ اللَّهُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20296;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ أَبُو طَلْحَةَ رَضِيَ اللَّهُ عَنْهُ أَكْثَرَ الأَنْصَارِ بِالمَدِينَةِ مَالًا مِنْ نَخْلٍ، وَكَانَ أَحَبُّ أَمْوَالِهِ إِلَيْهِ بَيْرَحَاءَ، وَكَانَتْ مُسْتَقبِلَةَ المَسْجِدِ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْخُلُهَا وَيَشْرَبُ مِنْ مَاءٍ فِيهَا طَيِّبٍ قَالَ أَنَسٌ: فَلَمَّا نَزَلَتْ هَذِهِ الآيَةُ: {لَنْ تَنَالُوا البِرَّ حَتَّى تُنِفُقوا مِمَّا تُحبُّونَ} قَامَ أَبُو طَلْحَةَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يارَسُولَ إِنَّ اللَّهَ تَعَالَى أَنْزَلَ عَلَيْكَ: { لَنْ تَنَالُوا البِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ} وَإِنَّ أَحَبَّ مَالِي إِلَيَّ بَيْرَحَاءَ، وَإِنَّهَا صَدَقَةٌ لِلَّهِ تَعَالَى أَرْجُو بِرَّهَا وذُخْرَهَا عِنْدَ اللَّهِ تَعَالَى، فَضَعْهَا يَا رَسُولَ اللَّهِ حَيْثُ أَرَاكَ اللَّهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « بَخٍ! ذَلِكَ مَالٌ رَابِحٌ، ذَلِكَ مَالٌ رَابِحٌ، وَقَدْ سَمِعتُ مَا قُلتَ، وَإِنِّي أَرَى أَنْ تَجْعَلَهَا فِي الأَقْرَبِينَ» فَقَالَ أَبُو طَلْحَةَ: أَفْعَلُ يَا رَسُولَ اللَّهِ، فَقَسَمَهَا أَبُو طَلْحَةَ فِي أَقَارِبِهِ، وَبَنِي عَمِّهِ.', updated_at = now() where id = 20297;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَخَذَ الحَسَنُ بْنُ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُمَا تَمْرَةَ الصَّدَقَةِ فَجَعَلَهَا فِي فِيهِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: " كَخْ كَخْ، ارْمِ بِهَا، أَمَا عَلِمْتَ أَنَّا لَا نَأْكُلُ الصَّدَقَةَ!؟ ((مُتَّفَقٌ عَلَيْهِ)). وَفِي رِوَايَةٍ" أَنَّا لَا تَحِلُّ لَنَا الصَّدَقَةُ" وَقَوْلُهُ: " كخٍْ كخٍْ" يُقَالُ بِإِسْكَانِ الخَاءِ، وَيُقَالُ بِكَسْرِهَا مَعَ التَّنْوِينِ، وَهِيَ كَلِمَةُ زَجْرٍ لِلصَّبِيِّ عَنِ المُسْتَقْذَرَاتِ. وَكَانَ الحَسَنُ رَضِيَ اللَّهُ عَنْهُ صَبِيًّا.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10102 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20298;
update hadith set arabic = 'عَنْ أَبِي حَفْصٍ عُمَرَ بْنِ أَبِي سَلَمَةَ عَبْدِ اللَّهِ بْنِ عَبْدِ الأَسَدِ رَبِيبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُنْتُ غُلَامًا فِي حَجْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَكَانَتْ يَدِي تَطِيشُ فِي الصَّحْفَةِ، فَقَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : « يَا غُلَامُ سَمِّ اللهَ تَعَالَى، وَكُلْ بِيَمِينِكَ، وَكُلْ مِمَّا يَلِيكَ» فَمَا زَالَتْ تِلْكَ طِعْمَتِي بَعْدُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/58120 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20299;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: كُلُّكُمْ رَاعٍ، وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالمَرْأَةُ رَاعِيَةٌ فِي بَيْتِ زَوْجِهَا وَمَسْئُولَةٌ عَنْ رَعِيَّتِهَا، وَالخَادِمُ رَاعٍ فِي مَالِ سَيِّدِهِ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ، فَكُلُّكُمْ رَاعٍ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20300;
update hadith set arabic = 'عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « مُرُوا أَوْلَادَكُمِ بِالصَّلَاةِ وَهُمْ أَبْنَاءُ سَبْعِ سِنِينَ، وَاضْرِبُوهُمْ عَلَيْهَا، وَهُمْ أَبْنَاءُ عَشْرٍ، وَفَرِّقُوا بَيْنَهُمْ فِي المَضَاجِعِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5272 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20301;
update hadith set arabic = 'عَنْ أَبِي ثُرَيَّةَ سَبْرَةَ بْنِ مَعْبَدٍ الجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : " عَلِّمُوا الصَّبِيَّ الصَّلَاةَ لِسَبْعِ سِنِينَ" وَاضْرِبُوهُ عَلَيْهَا ابْنَ عَشْرِ سِنِينَ" حَدِيثٌ حَسَنٌ رَوَاهُ أَبُو دَاوُدَ، وَالتِّرْمِذِيُّ وَقَالَ حَدِيثٌ حَسَنٌ. وَلَفْظُ أَبِي دَاوُدَ: " مُرُوا الصَّبِيَّ بِالصَّلَاةِ إِذَا بَلَغَ سَبْعَ سِنِينَ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20302;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ وَعَائِشَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « مَا زَالَ جِبْرِيلُ يُوصِينِي بِالجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20303;
update hadith set arabic = 'عَنْ أَبِي ذَرٍّ رَضيَ اللهُ عنهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : "يَا أَبَا ذَرٍّ إِذَا طَبَخْتَ مَرَقَةً، فَأَكْثِرْ مَاءَهَا، وَتَعَاهَدْ جِيرَانَكَ" ((رَوَاهُ مُسْلِمٌ)). وَفِي رِوَايَةٍ لَهُ عَنْ أَبِي ذَرٍّ قَالَ: إِنَّ خَلِيلِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْصَانِي: " إِذَا طَبَخْتَ مَرَقًا فَأَكْثِرْ مَاءَهَا، ثُمَّ انْظُرْ أَهْلَ بَيْتٍ مِنْ جِيرَانِكَ، فَأَصِبْهُمْ مِنْهَا بِمَعْرُوفٍ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5336 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20304;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: " وَاللَّهِ لاَ يُؤْمِنُ، وَاللَّهِ لايُؤْمِنُ، وَاللَّهِ لاَ يُؤْمِنُ!" قِيلَ: مَنْ يَا رَسُولَ اللَّهِ؟ قَالَ: " الَّذِي لاَ يَأْمَنُ جَارُهُ بَوَائِقَهُ ! " ((مُتَّفَقٌ عَلَيْهِ)). وَفِي رِوَايَةٍ لِمُسْلِمٍ: " لايَدْخُلُ الجَنَّةَ مَنْ لَا يَأْمَنُ جَارُهُ بَوَائِقَهُ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20305;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « يَا نِسَاءَ المُسْلِمَاتِ لَا تَحْقِرَنَّ جَارَةٌ لِجَارَتِهَا وَلَوْ فِرْسِنَ شَاةٍ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20306;
update hadith set arabic = 'وَعَنْهُ أنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « لَا يَمْنَعْ جَارٌ جَارَةً أَنْ يَغْرِزَ خَشَبَةً فِي جِدَارِهِ» ثُمَّ يَقُولُ أَبُو هُرَيْرَةَ: مَا لِي أَرَاكُمْ عَنْهَا مُعْرِضِينَ! وَاللَّهِ لَأَرْمِيَنَّ بِهَا بَيْنَ أَكْتَافِكُمْ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6094 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20307;
update hadith set arabic = 'وَعَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ، فَلَا يُؤْذِ جَارَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ، فَلْيُكْرِمْ ضَيْفَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَاليَوْمِ الآخِرِ، فَلْيَقُلْ خَيْرًا أَوْ لِيَسْكُتْ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20308;
update hadith set arabic = 'عَنْ أَبِي شُرَيْحٍ الخُزَاعِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ، فَلْيُكْرِمْ ضَيْفَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ، فَلْيَقُلْ خَيْرًا أَوْ لِيَسْكُتْ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20309;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قُلْتُ: يارَسُولَ اللهِ إِنَّ لِي جَارَيْنِ، فَإِلَى أَيِّهِمَا أُهْدِي؟ قَالَ: « إِلَى أَقْرَبِهِمَا مِنْكِ بَابًا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4250 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20310;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «خَيْرُ الأَصْحَابِ عِنْدَ اللَّهِ تَعَالَى خَيْرُهُمْ لِصَاحِبِهِ، وَخَيْرُ الجِيرَانِ عِنْدَ اللَّهِ تَعَالَى خَيْرُهُمْ لِجَارِهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3709 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20311;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَيُّ العَمَلِ أَحَبُّ إِلَى اللَّهِ تَعَالَى؟ قَالَ " الصَّلَاةُ عَلَى وَقْتِهَا" قُلْتُ: ثُمَّ أَيٌّ؟ قَالَ: " بِرُّ الوَالِدَيْنِ" قُلْتُ: ثُمَّ أَيٌّ؟ قَالَ: " الجِهَادُ فِي سَبِيلِ اللَّهِ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20312;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «لاَ يَجْزِي وَلَدٌ وَالِدًا إِلَّا أَنْ يَجِدَهُ مَمْلُوكًا فَيَشْتَرِيَهُ فَيُعْتِقَهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3775 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20313;
update hadith set arabic = 'وَعَنْهُ أَيْضاً أَنَّ رَسُولَ اللَّهِ قَالَ : « مَنْ كَانَ يُؤْمِنُ باللهِ وَاليَومِ الآخِرِ ، فَلْيُكْرِمْ ضَيْفَهُ ، وَمَنْ كَانَ يُؤْمِنُ باللهِ وَاليَومِ الآخِرِ ، فَلْيَصِلْ رَحِمَهُ ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ ، فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ » . مُتَّفَقٌ عَلَيهِ .', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20314;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : " إِنَّ اللَّهَ تَعَالَى خَلَقَ الخَلْقَ حَتَّى إِذَا فَرَغَ مِنْهُمْ قَامَتِ الرَّحِمُ، فَقَالَتْ: هَذَا مَقَامُ العَائِذِ بِكَ مِنَ القَطِيعَةِ، قَالَ: نَعَمْ أَمَا تَرْضَيْنَ أَنْ أَصِلَ مَنْ وَصَلَكِ، وَأَقْطَعَ مَنْ قَطَعَكِ؟ قَالَتْ: بَلَى، قَالَ: فَذَلِكِ لَكِ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : " اقْرَءُوا إِنْ شِئْتُمْ: (فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ. أُولَئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ) ((مُتَّفَقٌ عَلَيْهِ)). وَفِي رِوَايَةٍ لِلْبُخَارِيِّ: فَقَالَ اللَّهُ تَعَالَى: " مَنْ وَصَلَكِ، وَصَلْتُهُ، وَمَنْ قَطَعَكِ، قَطَعْتُهُ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20315;
update hadith set arabic = 'وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: " أُمُّكَ" قَالَ: ثُمَّ مَنْ؟ قَالَ: " أُمُّكَ" قَالَ: ثُمَّ مَنْ؟ قَالَ: "أُمُّكَ" قَالَ: ثُمَّ مَنْ؟ قَالَ: " أَبُوكَ" ((مُتَّفَقٌ عَلَيْهِ)). وَفِي رِوَايَةٍ: يارَسُولَ اللَّهِ مَنْ أَحَقُّ بِحُسْنِ الصُّحْبَةِ؟ قَالَ: " أُمُّكَ، ثُمَّ أُمُّكَ، ثُمَّ أُمُّكَ، ثُمَّ أَبَاكَ، ثُمَّ أَدْنَاكَ أَدْنَاكَ".', updated_at = now() where id = 20316;
update hadith set arabic = 'وَعَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « رَغِمَ أَنْفُ، ثُمَّ رَغِمَ أَنْفُ، ثُمَّ رَغِمَ أَنْفُ مَنْ أَدْرَكَ أَبَوَيْهِ عِنْدَ الْكِبَرِ، أَحَدَهُمَا أَوْ كِلَيْهِمَا، فَلَمْ يَدْخُلِ الْجَنَّةَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20317;
update hadith set arabic = 'وَعَنْهُ أَنَّ رَجُلًا قَالَ : يَا رَسُولَ اللهِ ! إِنَّ لِي قَرَابَةً أَصِلُهُمْ وَيَقْطَعُونِي ، وَأُحْسِنُ إِلَيْهِمْ وَيُسِيئُونَ إِلَيَّ ، وَأَحْلُمُ عَنْهُمْ وَيَجْهَلُونَ عَلَيَّ ، فَقَالَ : « لَئِنْ كُنْتَ كَمَا قُلْتَ ، فَكَأَنَّمَا تُسِفُّهُمُ الْمَلَّ ، وَلَا يَزَالُ مَعَكَ مِنَ اللهِ ظَهِيرٌ عَلَيْهِمْ مَا دُمْتَ عَلَى ذَلِكَ ».', updated_at = now() where id = 20318;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَيُنْسَأَ لَهُ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5372 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20319;
update hadith set arabic = 'وَعَنْهُ قَالَ: كَانَ أَبُو طَلْحَةَ أَكْثَرَ الأَنْصَارِ بِالمَدِينَةِ مَالًا مِنْ نَخْلٍ، وَكَانَ أَحَبُّ أَمْوَالِهِ إِلَيْهِ بَيْرَحَاءَ، وَكَانَتْ مُسْتَقبِلَةَ المَسْجِدِ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْخُلُهَا، وَيَشْرَبُ مِنْ مَاءٍ فِيهَا طَيِّبٍ، فَلَمَّا نَزَلَتْ هَذِهِ الآيَةُ: {لَنْ تَنَالُوا البِرَّ حَتَّى تُنِفُقوا مِمَّا تُحبُّونَ} ((آلِ عِمْرَانَ: 92)) قَامَ أَبُو طَلْحَةَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَقُولُ: {لَنْ تَنَالُوا البِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ} وَإِنَّ أَحَبَّ مَالِي إِلَيَّ بَيْرَحَاءَ، وَإِنَّهَا صَدَقَةٌ لِلَّهِ تَعَالَى، وَأَرْجُو بِرَّهَا وذُخْرَهَا عِنْدَ اللَّهِ تَعَالَى، فَضَعْهَا يَا رَسُولَ اللَّهِ حَيْثُ أَرَاكَ اللَّهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «بَخٍ! ذَلِكَ مَالٌ رَابِحٌ، وَذَلِكَ مَالٌ رَابِحٌ! وَقَدْ سَمِعتُ مَا قُلتَ، وَإِنِّي أَرَى أَنْ تَجْعَلَهَا فِي الأَقْرَبِينَ» فَقَالَ أَبُو طَلْحَةَ: أَفْعَلُ يَا رَسُولَ اللَّهِ، فَقَسَمَهَا أَبُو طَلْحَةَ فِي أَقَارِبِهِ وَبَنِي عَمِّهِ. ((مُتَّفَقٌ عَلَيْهِ)). وَسَبَقَ بَيَانُ أَلْفَاظِهِ فِي: بَابِ الإِنْفَاقِ مِمَّا يُحِبُّ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20320;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَقْبَلَ رَجُلٌ إِلَى نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: أُبَايِعُكَ عَلَى الهِجْرَةِ وَالجِهَادِ أَبْتَغِي الأَجْرَ مِنَ اللَّهِ تَعَالَى. قَالَ: "فَهَل لَكَ مِنْ وَالِدَيكَ أَحَدٌ حَيٌّ؟" قَالَ: نَعَمْ بَلْ كِلَاهُمَا قَالَ: "فَتَبْتَغِي الأَجْرَ مِنَ اللَّهِ تَعَالَى؟" قَالَ: نَعَمْ. قَالَ "فَارْجِعْ إِلَى وَالِدَيكَ، فَأَحْسِنْ صُحْبَتَهُمَا" ((مُتَّفَقٌ عَلَيْهِ. وَهَذَا لَفْظُ مُسْلِمٍ)). وَفِي رِوَايَةٍ لَهُمَا: جَاءَ رَجُلٌ فَاسْتَأْذَنَهُ فِي الجِهَادِ فَقَالَ "أَحَيٌّ وَالِدَاكَ؟ قَالَ: نَعَمْ، قَالَ: "فَفِيهِمَا فَجَاهِدْ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3260 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20321;
update hadith set arabic = 'وَعَنْهُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «لَيْسَ الْوَاصِلُ بِالْمُكَافِئِ وَلَكِنِ الْوَاصِلُ الَّذِي إِذَا قُطِعَتْ رَحِمُهُ وَصَلَهَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3854 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20322;
update hadith set arabic = 'عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «الرَّحِمُ مُعَلَّقَةٌ بِالعَرْشِ تَقُولُ: مَنْ وَصَلَنِي، وَصَلَهُ اللَّهُ، وَمَنْ قَطَعَنِي، قَطَعَهُ اللَّهُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20323;
update hadith set arabic = 'عَنْ أُمِّ المُؤْمِنِينَ مَيْمُونَةَ بِنْتِ الحَارِثِ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا أَعْتَقَتْ وَليدَةً وَلَمْ تَسْتَأْذِنِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا كَانَ يَومُهَا الَّذِي يَدورُ عَلَيْهَا فِيهِ، قَالَتْ: أشَعَرْتَ يَا رَسُولَ اللَّهِ أَنِّي أَعْتَقْتُ وَلِيدَتِي؟ قَالَ: "أَوَ فَعَلْتِ؟" قَالَتْ: نَعَمْ. قَالَ: "أَمَا إِنَّكِ لَوْ أَعْطَيْتِهَا أَخْوَالَكِ كَانَ أَعْظَمَ لِأَجْرِكِ".', updated_at = now() where id = 20324;
update hadith set arabic = 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ: قَدِمَتْ عَلَى أُمِّي وَهِيَ مُشْرِكَةٌ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَفْتَيْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قُلْتُ: قَدِمَتْ عَلَيَّ أُمِّي وَهِيَ رَاغِبَةٌ، أَفَأَصِلُ أُمِّي؟ قَالَ: «نَعَمْ صِلِي أُمَّكِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65989 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20325;
update hadith set arabic = 'عَنْ زَيْنَبَ الثَّقَفِيَّةِ امْرَأَةِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ وَعَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "تَصَدَّقْنَ يَا مَعْشَرَ النِّسَاءِ وَلَوْ مِنْ حُلِيِّكُنَّ" قَالَتْ: فَرَجَعْتُ إِلَى عَبْدِ اللَّهِ بْنِ مَسْعُودٍ فَقُلْتُ لَهُ: إِنَّكَ رَجُلٌ خَفِيفُ ذَاتِ اليَدِ وَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَمَرَنَا بِالصَّدَقَةِ فَأْتِهِ، فَاسْأَلْهُ، فَإِنْ كَانَ ذَلِكَ يُجْزِئُ عَنِّي وَإِلَّا صَرَفْتُهَا إِلَى غَيْرِكُمْ. فَقَالَ عَبْدُ اللَّهِ: بَلِ ائْتِيهِ أَنْتِ، فَانْطَلَقْتُ، فَإِذَا امْرَأَةٌ مِنَ الأَنْصَارِ بِبَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَاجَتِي حَاجَتُهَا، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أُلْقِيَتْ عَلَيْهِ المَهَابَةُ، فَخَرَجَ عَلَيْنَا بِلَالٌ، فَقُلْنَا لَهُ: ائْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخْبِرْهُ أَنَّ امْرَأَتَيْنِ بِالبَابِ تَسْأَلَانِكَ: أَتُجْزِئُ الصَّدَقَةُ عَنْهُمَا عَلَى أَزْوَاجِهِمَا وَعَلَى أَيْتَامٍ فِي حُجُورِهِمَا؟ وَلَا تُخْبِرْهُ مَنْ نَحْنُ، فَدَخَلَ عَلَى أَزْوَاجِهِمَا وَعَلَى أَيْتَامٍ فِي حُجُورِهِمَا؟ وَلَا تُخْبِرْهُ مَنْ نَحْنُ، فَدَخَلَ بِلَالٌ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَهُ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "مَنْ هُمَا؟" قَالَ: امْرَأَةٌ مِنَ الأَنْصَارِ وَزَيْنَبُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "أَيُّ الزَّيَانِبِ هِيَ ؟" قَالَ: امْرَأَةُ عَبْدِ اللَّهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَهُمَا أَجْرَانِ: أَجْرُ القَرَابَةِ وَأَجْرُ الصَّدَقَةِ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20326;
update hadith set arabic = 'عَنْ أَبِي سُفْيَانَ صَخْرِ بْنِ حَرْبٍ رَضِيَ اللَّهُ عَنْهُ فِي حَدِيثِهِ الطَّوِيلِ فِي قِصَّةِ هِرَقْلَ أَنَّ هِرَقْلَ قَالَ لِأَبِي سُفْيَانَ: فَمَاذَا يَأمُرُكُمْ بِهِ؟ يَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قُلْتُ: يَقُولُ: «اعْبُدُوا اللَّهَ وَحْدَهُ، وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَاتْرُكُوا مَا يَقُولُ آبَاؤُكُمْ، وَيَأْمُرُنَا بِالصَّلَاةِ، وَالصِّدْقِ، وَالعَفَافِ، وَالصِّلَةِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20327;
update hadith set arabic = 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّكُمْ سَتَفْتَحُونَ أَرْضًا يُذْكَرُ فِيهَا القِيرَاطُ". وَفِي رِوَايَةٍ: "سَتَفْتَحُونَ مِصْرَ وَهِيَ أَرْضٌ يُسَمَّى فِيهَا القِيرَاطُ، فَاسْتَوْصُوا بِأَهْلِهَا خَيْرًا، فَإِنَّ لَهُمْ ذِمَّةً وَرَحِمًا". وَفِي رِوَايَةٍ: "فَإِذَا افْتَتَحْتُمُوهَا، فَأَحْسِنُوا إِلَى أَهْلِهَا، فَإِنَّ لَهُمْ ذِمَّةً وَرَحِمًا" أَوْ قَالَ: "ذِمَّةً وَصِهْرًا".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20328;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ هَذِهِ الآيَةُ: (وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ).', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20329;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ اللَّهِ عَمْرِو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جِهَارًا غَيْرَ سِرٍّ يَقُولُ: «إِنَّ آلَ بَنِي فُلَانٍ لَيْسُوا بِأَوْلِيَائِي، إِنَّمَا وَلِيِّيَ اللَّهُ وَصَالِحُ المُؤْمِنِينَ، وَلَكِنْ لَهُمْ رَحِمٌ أَبُلُّهَا بِبَلَالِهَا».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20330;
update hadith set arabic = 'عَنْ أَبِي أَيُّوبَ خَالِدِ بْنِ زَيْدٍ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَجُلاً قَالَ: يَا رَسُولَ اللَّهِ أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الجَنَّةَ، وَيُبَاعِدُنِي مِنَ النَّارِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «تَعْبُدُ اللَّهَ، وَلاتُشْرِكُ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ، وَتُؤْتِي الزَّكَاةَ، وَتَصِلُ الرَّحِمَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20331;
update hadith set arabic = 'عَنْ سَلْمَانَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَفْطَرَ أَحَدُكُمْ، فَلْيُفْطِرْ عَلَى تَمْرٍ، فَإِنَّهُ بَرَكَةٌ، فَإِنْ لَمْ يَجِدْ تَمْرًا، فَالمَاءُ، فَإِنَّهُ طَهُورٌ" وَقَالَ: "الصَّدَقَةُ عَلَى المِسْكِينِ صَدَقَةٌ، وَعَلَى ذِي الرَّحِمِ ثِنْتَانِ: صَدَقَةٌ وَصِلَةٌ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20332;
update hadith set arabic = 'عَنْ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَاَل: كَانتْ تَحْتِي امْرَأةٌ، وَكُنْتُ أُحِبُّهَا، وَكَانَ عُمَرُ يَكْرَهُهَا، فَقَالَ لِيْ: طَلِّقْهَا، فَأَبيتُ، فَأَتَى عُمرُ رَضِيَ اللَّهُ عَنْهُ النَّبِيَّ صَلَّى اللهُ عَلَيهِ وَسَلَّمَ، فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيهِ وَسَلَّمَ: «طَلِّقْهَا».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20333;
update hadith set arabic = 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَجُلاً أَتَاهُ فَقَالَ: إِنَّ لِيَ امْرَأَةً وَإِنَّ أُمِّي تَأْمُرُنِي بِطَلاَقِهَا؟ فَقَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ «الوَالِدُ أَوْسَطُ أَبْوَابِ الجَنَّةِ، فَإِنْ شِئْتَ، فَأَضِعْ ذَلِكَ البَابَ، أَوْ احْفَظْهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65995 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20334;
update hadith set arabic = 'عَنِ البَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «الخَالَةُ بِمَنْزِلَةِ الأُمِّ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20335;
update hadith set arabic = 'عَنْ أَبِي بَكْرَةَ نُفَيْعِ بْنِ الحَارِثِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أُنَبِّئُكُمْ بِأَكْبَرِ الكَبَائِرِ؟" ثَلَاثًا قُلْنَا: بَلَى يَا رَسُولَ اللَّهِ: قَالَ: "الإِشْرَاكُ بِاللَّهِ، وَعُقُوقُ الوَالِدَيْنِ" وَكَانَ مُتَّكِئاً فَجَلَسَ، فَقَالَ: "أَلَا وَ قَوْلُ الزُّورِ وَ شَهَادَةُ الزُّورِ" فَمَا زَالَ يُكَرِّرُهَا حَتَّى قُلْنَا: لَيْتَهُ سكتز.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20336;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ قَالَ : «الْكَبَائِرُ : الْإِشْرَاكُ بِاللهِ ، وَعُقُوقُ الْوَالِدَيْنِ ، وَقَتْلُ النَّفْسِ ، وَالْيَمِينُ الْغَمُوسُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3044 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20337;
update hadith set arabic = 'وَعَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مِنَ الكَبَائِرِ شَتْمُ الرَّجُلِ وَالِدَيْهِ!" قَالُوا: يَا رَسُولَ اللَّهِ وَهَلْ يَشْتِمُ الرَّجُلُ وَالِدَيْهِ؟ ! قَالَ: "نَعَمْ؛ يَسُبّ أَبَا الرَّجُلِ، فَيَسُبّ أَبَاهُ، وَيَسُبّ أُمّهُ، فَيَسُبّ أُمّهُ" ((مُتَّفَقٌ عَلَيْهِ)) . وَفِي رِوَايَةٍ "إِنَّ مِنْ أَكْبَرِ الكَبَائِرِ أَنْ يَلْعَنَ الرَّجُلُ وَالِدَيْهِ!" قِيلَ : يَا رَسُولَ اللَّهِ كَيْفَ يَلْعَنُ الرَّجُلُ وَالِدَيْهِ؟ ! قَالَ "يَسُبُّ أَبَا الرَّجُلِ ، فَيَسُبُّ أَبَاهُ، وَيَسُبُّ أُمَّهُ، فَيَسُبُّ أُمَّهُ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20338;
update hadith set arabic = 'عَنْ أَبِي مُحَمَّدٍ جُبَيْرِ مِنْ مُطْعِمٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «لايَدْخُلُ الجَنَّةَ قَاطِعٌ» قَالَ سُفْيَانُ فِي رِوَايَتِهِ: يَعْنِي : قَاطِعَ رَحِمٍ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20339;
update hadith set arabic = 'عَنْ أَبِي عِيسَى المُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِنَّ اللَّهَ تَعَالَى حَرَّمَ عَلَيْكُمْ عُقُوقَ الأُمَّهَاتِ، وَمَنْعًا وَهَاتِ، وَوَأْدَ البَنَاتِ، وَكَرِهَ لَكُمْ قِيلَ وَقَالَ، وَكَثْرَةَ السُّؤَالِ ، وَإِضَاعَةَ المَالِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20340;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِنَّ أَبَرَّ البِرِّ أَنْ يَصِلَ الرَّجُلُ وُدَّ أَبِيهِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20341;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَجُلاً مِنَ الأَعْرَابِ لَقِيَهُ بِطَرِيقِ مَكَّةَ، فَسَلَّمَ عَلَيْهِ عَبْدُ اللَّهِ بْنُ عُمَرَ، وَحَمَلَهُ عَلَى حِمَارٍ كَانَ يَرْكَبُهُ، وَأَعْطَاهُ عِمَامَةً كَانَتْ عَلَى رَأْسِهِ، قَالَ ابْنُ دِينَارٍ: فَقُلْنَا لَهُ: أَصْلَحَكَ اللَّهُ إِنَّهُمُ الأَعْرَابُ وَهُمْ يَرْضَوْنَ اليَسِيرَ فَقَالَ عَبْدُ اللَّهِ بنَ عُمَرَ: إِنَّ أَبَا هَذَا كَانَ وُدًّا لِعُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ أَبَرَّ البِرِّ صِلَةُ الرَّجُلِ أَهْلَ وُدِّ أَبِيهِ". وَفِي رِوَايَةٍ عَنِ ابْنِ دِينَارٍ عَنِ ابْنِ عُمَرَ أَنَّهُ كَانَ إِذَا خَرَجَ إِلَى مَكَّةَ كَانَ لَهُ حِمَارٌ يَتَرَوَّحُ عَلَيْهِ إِذَا مَلَّ رُكُوبَ الرَّاحِلَةِ، وَعِمَامَةٌ يَشُدُّ بِهَا رَأْسَهُ، فَبَيْنَا هُوَ يَوْمًا عَلَى ذَلِكَ الحِمَارِ إِذْ مَرَّ بِهِ أَعْرَابِيٌّ، فَقَالَ: أَلَسْتَ ابْنَ فُلَانِ بْنِ فُلَانٍ؟ قَالَ: بَلَى. فَأَعْطَاهُ الحِمَارَ، فَقَالَ: ارْكَبْ هَذَا، وَأَعْطَاهُ العِمَامَةَ وَقَالَ: اشْدُدْ بِهَا رَأْسَكَ ، فَقَالَ لَهُ بَعْضُ أَصْحَابِهِ: غَفَرَ اللَّهُ لَكَ أَعْطَيْتَ هَذَا الأَعْرَابِيَّ حِمَارًا كُنْتَ تَرَوَّحُ عَلَيْهِ، وَعِمَامَةً كُنْتَ تَشُدُّ بِهَا رَأْسَكَ؟ فَقَالَ:إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ مِنْ أَبَرِّ البِرِّ أَنْ يَصِلَ الرَّجُلُ أَهْلَ وُدِّ أَبِيهِ بَعْدَ أَنْ يُوَلِّيَ" وَإِنَّ أَبَاهُ كَانَ صَدِيقًا لِعُمَرَ رَضِيَ اللَّهُ عَنْهُ ،', updated_at = now() where id = 20342;
update hadith set arabic = 'عَنْ أَبِي أُسَيْدٍ- بِضَمِّ الهَمْزَةِ وَفَتْحِ السِّينِ- مَالِكِ بْنِ رَبِيعَةَ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَا نَحْنُ جُلُوسٌ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَهُ رَجُلٌ مِنْ بَنِي سَلِمَةَ فَقَالَ: يَا رَسُولَ اللَّهِ هَلْ بَقِيَ مِنْ بِرِّ أَبَوَيَّ شَيْءٌ أَبَرُّهُمَا بِهِ بَعْدَ مَوْتِهِمَا؟ فَقَالَ: « نَعَمْ، الصَّلَاةُ عَلَيْهِمَا، وَالِاسْتِغْفَارُ لَهُمَا، وَإِنْفَاذُ عَهْدِهِمَا مِنْ بَعْدِهِمَا، وَصِلَةُ الرَّحِمِ الَّتِي لَا تُوصَلُ إِلَّا بِهِمَا، وَإِكْرَامُ صَدِيقِهِمَا».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20343;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا غِرْتُ عَلَى أَحَدٍ مِنْ نِسَاءِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا غِرْتُ عَلَى خَدِيجَةَ رَضِيَ اللَّهُ عَنْهَا، وَمَا رَأَيْتُهَا قَطُّ، وَلَكِنْ كَانَ يُكْثِرُ ذِكْرَهَا، وَرُبَّمَا ذَبَحَ الشَّاةَ، ثُمَّ يُقَطِّعُهَا أَعْضَاءً، ثُمَّ يَبْعَثُهَا فِي صَدَائِقِ خَدِيجَةَ، فَرُبَّمَا قُلْتُ لَهُ: كَأَنْ لَمْ يَكُنْ فِي الدُّنْيَا إِلَّا خَدِيجَةُ! فَيَقُولُ: "إِنَّهَا كَانَتْ وَكَانَتْ وَكَانَ لِي مِنْهَا وَلَدٌ" ((مُتَّفَقٌ عَلَيْهِ)) . وَفِي رِوَايَةٍ وَإِنْ كَانَ لَيَذْبَحُ الشَّاءَ، فَيُهْدِي فِي خَلَائِلِهَا مِنْهَا مَا يَسَعُهُنَّ. وَفِي رِوَايَةٍ كَانَ إِذَا ذَبَحَ الشَّاةَ يَقُولُ: "أَرْسِلُوا بِهَا إِلَى أَصْدِقَاءِ خَدِيجَةَ". وَفِي رِوَايَةٍ قَالَتْ: اسْتَأْذَنَتْ هَالَةُ بِنْتُ خُوَيْلِدٍ أُخْتُ خَدِيجَةَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَعَرَفَ اسْتِئْذَانَ خَدِيجَةَ، فَارْتَاحَ لِذَلِكَ فَقَالَ: اللَّهُمَّ هَالَةُ بِنْتُ خُوَيْلِدٍ".', updated_at = now() where id = 20344;
update hadith set arabic = 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْتُ مَعَ جَرِيرِ بْنِ عَبْدِ اللَّهِ البَجَلِيِّ رَضِيَ اللَّهُ عَنْهُ فِي سَفَرٍ، فَكَانَ يَخْدُمُنِي فَقُلْتُ لَهُ: لَا تَفْعَلْ، فَقَالَ: إِنِّي قَدْ رَأَيْتُ الأَنْصَارَ تَصْنَعُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا آلَيْتُ عَلَى نَفْسِي أَنْ لاَ أَصْحَبَ أَحَدًا مِنْهُمْ إِلاَّ خَدَمْتُهُ.', updated_at = now() where id = 20345;
update hadith set arabic = 'عَنْ يَزِيدَ بْنِ حَيَّانَ قَالَ: انْطَلَقْتُ أَنَا وَحُصَيْنُ بْنُ سَبْرَةَ، وَعَمْرُو بْنُ مُسْلِمٍ إِلَى زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللَّهُ عَنْهُمْ، فَلَمَّا جَلَسْنَا إِلَيْهِ قَالَ لَهُ حُصَيْنٌ: لَقَدْ لَقِيتَ يَا زَيْدُ خَيْرًا كَثِيرًا، رَأَيْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَمِعْتَ حَدِيثَهُ، وَغَزَوْتَ مَعَهُ، وَصَلَّيْتَ خَلْفَهُ: لَقَدْ لَقِيتَ يَا زَيْدُ خَيْرًا كَثِيرًا، حَدِّثْنَا يَا زَيْدُ مَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَا ابْنَ أَخِى وَاللَّهِ لَقَدْ كَبِرَتْ سِنِّي، وَقَدُمَ عَهْدِي، وَنَسِيتُ بَعْضَ الَّذِي كُنْتُ أَعِي مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَاحَدَّثْتُكُمْ ، فَاقْبَلُوا، وَمَا لَا فَلَا تُكَلِّفُونِيهِ ثُمَّ قَالَ: قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا فِينَا خَطِيبًا بِمَاءٍ يُدْعَى خُمَاءَ بَيْنَ مَكَّةَ وَالمَدِينَةِ، فَحَمِدَ اللَّهَ، وَأَثْنَى عَلَيْهِ، وَوَعَظَ، وَذَكَّرَ، ثُمَّ قَالَ: "أَمَّا بَعْدُ، أَلَا أَيُّهَا النَّاسُ، فَإِنَّمَا أَنَا بَشَرٌ يُوشِكُ أَنْ يَأْتِيَ رَسُولُ رَبِّي فَأُجِيبَ، وَأَنَا تَارِكٌ فِيكُمْ ثَقَلَيْنِ. أَوَّلُهُمَا كِتَابُ اللَّهِ، فِيهِ الهُدَى وَالنُّورُ، فَخُذُوا بِكِتَابِ اللَّهِ، وَاسْتَمْسِكُوا بِهِ. فَحَثَّ عَلَى كِتَابِ اللَّهِ، وَرَغَّبَ فِيهِ ثُمَّ قَالَ: "وَأَهْلُ بَيْتِي أُذَكِّرُكُمُ اللهَ فِي أَهْلِ بَيْتِي، أُذَكِّرُكُمُ اللهَ فِي أَهْلِ بَيْتِي"، فَقَالَ لَهُ حُصَيْنٌ: وَمَنْ أَهْلُ بَيْتِهِ يَا زَيْدُ، أَلَيْسَ نِسَاؤُهُ مِنْ أَهْلِ بَيْتِهِ؟ قَالَ: نِسَاؤُهُ مِنْ أَهْلِ بَيْتِهِ، وَلَكِنْ أَهْلُ بَيْتِهِ مَنْ حُرِمَ الصَّدَقَةَ بَعْدَهُ، قَالَ: وَمَنْ هُمْ؟ قَالَ: هُمْ آلُ عَلِيٍّ، وَآلُ عَقِيلٍ، وَآلُ جَعْفَرٍ، وَآلُ عَبَّاسٍ قَالَ: كُلُّ هَؤُلَاءِ حُرِمَ الصَّدَقَةَ؟ قَالَ: نَعَمْ. ((رَوَاهُ مُسْلِمٌ)). وَفِي رِوَايَةٍ " أَلَا وَإِنِّي تَارِكٌ فِيكُمْ ثَقَلَيْنِ: أَحَدُهُمَا كِتَابُ اللَّهِ وَحَبْلُ اللَّهِ، وَمَنْ أَتْبَعَهُ كَانَ عَلَى الهُدَى، وَمَنْ تَرَكَهُ كَانَ عَلَى ضَلَالَةٍ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3084 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20346;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُ مَوْقُوفًا عَلَيْهِ أَنَّهُ قَالَ : ارْقُبُوا مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أَهْلِ بَيْتِهِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20347;
update hadith set arabic = 'عَنْ أَبِي مَسْعُودٍ عُقْبَةَ بْنِ عَمْرٍو البَدْرِيِّ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "يَؤُمُّ القَوْمَ أَقْرَؤُهُمْ لِكِتَابِ اللَّهِ، فَإِنْ كَانُوا فِي القِرَاءَةِ سَوَاءً، فَأَعْلَمُهُمْ بِالسُّنَّةِ، فَإِنْ كَانُوا فِي السُّنَّةِ سَوَاءً، فَأَقْدَمُهُمْ هِجْرَةً، فَإِنْ كَانُوا فِي الهِجْرَةِ سَوَاءً، فَأَقْدَمُهُمْ سِنًّا، وَلَا يَؤُمَّنَّ الرَّجُلُ الرَّجُلَ فِي سُلْطَانِهِ، وَلَا يَقْعُدْ فِي بَيْتِهِ عَلَى تَكْرِمَتِهِ إِلَّا بِإِذْنِهِ" ((رَوَاهُ مُسْلِمٌ)). وَفِي رِوَايَةٍ لَهُ: "فَأَقْدَمُهُمْ سِلْمًا" بَدَلَ "سِنًّا" : أَوْ إِسْلَامًا. وَفِي رِوَايَةٍ: يَؤُمُّ القَوْمَ أَقْرَؤُهُمْ لِكِتَابِ اللَّهِ، وَأَقْدَمُهُمْ قِرَاءَةً، فَإِنْ كَانَتْ قِرَاءَتُهُمْ فَيَؤُمُّهُمْ أَقْدَمُهُمْ هِجْرَةً، فَإِنْ كَانُوا فِي الهِجْرَةِ سَوَاءً، فَلْيَؤُمَّهُمْ أَكْبَرُهُمْ سِنًّا".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11297 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20348;
update hadith set arabic = 'وَعَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ مَنَاكِبَنَا فِي الصَّلَاةِ وَيَقُولُ: «اسْتَوُوا وَلَا تَخْتَلِفُوا، فَتَخْتَلِفَ قُلُوبُكُمْ، لِيَلِنِي مِنْكُمْ أُولُو الأَحْلَامِ وَالنُّهَى، ثُمَّ الَّذِينَ يَلُونَهُمْ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65741 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20349;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لِيَلِنِي مِنْكُمْ أُولُو الأَحْلَامِ وَالنُّهَى، ثُمَّ الَّذِينَ يَلُونَهُمْ" ثَلَاثًا "وَإِيَّاكُمْ وَهَيْشَاتِ الأَسْوُقِ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20350;
update hadith set arabic = 'عَنْ أَبِي يَحْيَى وَقِيلَ: أَبِي مُحَمَّدٍ سَهْلِ بْنِ أَبِي حَثْمَةَ -بِفَتْحِ الحَاءِ المُهْمَلَةِ وَإِسْكَانِ الثَّاءِ المُثَلَّثَةِ -الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: انْطَلَقَ عَبْدُ اللَّهِ ابْنُ سَهْلٍ وَمُحَيِّصَةُ بْنُ مَسْعُودٍ إِلَى خَيْبَرَ وَهِيَ صُلْحٌ، فَتَفَرَّقَا، فَأَتَى مُحَيِّصَةُ إِلَى عَبْدِ اللَّهِ بْنِ سَهْلٍ وَهُوَ يَتَشَحَّطُ فِي دَمِهِ قَتِيلاً، فَدَفَنَهُ، ثُمَّ قَدِمَ المَدِينَةَ فَانْطَلَقَ عَبْدُ الرَّحْمَنِ بْنُ سَهْلٍ وَمُحَيِّصَةُ وَحُوَيِّصَةُ ابْنَا مَسْعُودٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَهَبَ عَبْدُ الرَّحْمَنِ يَتَكَلَّمُ فَقَالَ: " كَبِّرْ كَبِّرْ" وَهُوَ أَحْدَثُ القَوْمِ، فَسَكَتَ، فَتَكَلَّمَا فَقَالَ: "أَتَحْلِفُونَ وَتَسْتَحِقُّونَ قَاتِلَكُمْ؟ وَذَكَرَ تَمَامَ الحَدِيثِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20351;
update hadith set arabic = 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَجْمَعُ بَيْنَ الرَّجُلَيْنِ مِنْ قَتْلَى أُحُدٍ يَعْنِي فِي القَبْرِ، ثُمَّ يَقُولُ: أَيُّهُمَا أَكْثَرُ أَخْذًا لِلْقُرْآنِ؟" فَإِذَا أُشِيرَ لَهُ إِلَى أَحَدِهِمَا قَدَّمَهُ فِي اللَّحْدِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20352;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « أَرَانِي فِي المَنَامِ أَتَسَوَّكُ بِسِوَاكٍ، فَجَاءَنِي رَجُلَانِ، أَحَدُهُمَا أَكْبَرُ مِنَ الآخَرِ، فَنَاوَلْتُ السِّوَاكَ الأَصْغَرَ، فَقِيلَ لِي: كَبِّرْ، فَدَفَعْتُهُ إِلَى الأَكْبَرِ مِنْهُمَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3131 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20353;
update hadith set arabic = 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: قالَ رسولُ اللَّه صَلّى اللهُ عَلَيْهِ وسَلَّم: «إِنَّ مِنْ إِجْلاَلِ الله تَعَالَى إِكْرَامَ ذِي الشَّيْبَةِ المُسْلِمِ، وَحَامِلِ القُرْآنِ غَيرِ الغَالِي فِيه، وَالجَافِي عَنْه وَإِكْرَامَ ذِي السُّلْطَانِ المُقْسِطِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3032 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20354;
update hadith set arabic = 'عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ ، عَنْ جَدِّهِ رَضِيَ اللَّهُ عَنْهُمْ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَيْسَ مِنَّا مَنْ لَمْ يَرحمْ صَغِيرَنَا، وَيَعرفْ شَرَفَ كَبِيرِنَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3083 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20355;
update hadith set arabic = 'عَنْ مَيْمُونِ بْنِ أَبِي شَبِيبٍ رَحِمَهُ اللَّهُ أَنَّ عَائِشَةَ رَضِيَ اللَّهُ عَنْهُ الإِمَامَ مَرَّ بِهَا سَائِلٌ، فَأَعْطَتْهُ كِسْرَةً، وَمَرَّ بِهَا رَجُلٌ عَلَيْهِ ثِيَابٌ وَهَيْئَةٌ، فَأَقْعَدَتْهُ، فَأَكَلَ فَقِيلَ لَهَا فِي ذَلِكَ: ؟ فَقَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «أَنْزِلُوا النَّاسَ مَنَازِلَهُمْ» ((رَوَاهُ أَبُو دَاوُدَ)). لَكِنْ قَالَ مَيْمُونٌ لَمْ يُدْرِكْ عَائِشَةَ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20356;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَدِمَ عُيَينَةُ بْنُ حِصنٍ، فَنزَلَ عَلَى ابنِ أَخِيهِ الحُرِّ بْنِ قَيسٍ، وَكَانَ مِنَ النَّفَرِ الَّذِينَ يُدنِيهِمْ عُمَرُ رَضِيَ اللَّهُ عَنْهُ ، وَكَانَ القُرَّاءُ أَصْحَابَ مَجلِسِ عُمَرَ ومُشاوَرَتِهِ، كُهُولًا كَانُوا أَوْ شُبَّانًا ، فَقَالَ عُيَيْنَةُ لِابْنِ أَخِيهِ: يَا ابْنَ أَخِي لَكَ وَجْهٌ عِنْدَ هَذَا الأَمِيرِ، فَاسْتَأذِنْ لِي عَلَيْهِ، فَاسْتَأذَنَ لَهُ، فَأَذِنَ لَهُ عُمَرُ رَضِيَ اللَّهُ عَنْهُ ، فَلَمَّا دَخَلَ: قَالَ هِيْ يَا ابْنَ الخطَّابِ: فَوَاللَّهِ مَا تُعطِينَا الجَزْلَ، وَلَا تَحكُمُ فِينَا بِالعَدلِ، فَغَضِبَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ حَتَّى هَمَّ أَنْ يُوقِعَ بِهِ، فَقَالَ لَهُ الحُرُّ: يَا أَمِيرَ المُؤْمِنِينَ إنَّ اللَّهَ تَعَالَى قَالَ لِنَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ {خُذِ العَفْوَ وَأْمُرْ بِالعُرْفِ وَأَعْرِضْ عَنِ الجَاهِلِينَ} وإِنَّ هَذَا مِنَ الجَاهِلِينَ. وَاللَّهِ مَا جَاوَزَهَا عُمَرُ حِينَ تَلاَهَا عَلَيْهِ، وَكَانَ وَقَّافًا عِنْدَ كِتَابِ اللَّهِ تَعَالَى.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3155 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20357;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَقَدْ كُنْتُ عَلَى عَهْدِ رَسولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غُلَامًا ، فَكُنْتُ أَحْفَظُ عَنْهُ، فَمَا يَمْنَعُنِي مِنَ القَوْلِ إِلَّا أَنَّ هَهُنَا رِجَالًا أَسَنُّ مِنِّي.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3130 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20358;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «مَا أَكْرَمَ شَابٌّ شَيْخًا لِسِنِّهِ إِلَى قَيَّضَ اللَّهُ لَهُ مَنْ يُكْرِمُهُ عِنْدَ سِنِّهِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20359;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ أَبُو بَكْرٍ لِعُمَرَ رَضِيَ اللَّهُ عَنْهُمَا بَعْدَ وَفَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: انْطَلِقْ بِنَا إِلَى أُمِّ أَيْمَنَ رَضِيَ اللَّهُ عَنْهَا نَزُورُهَا كَمَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يزورهان فَلَمَّا انْتَهَيَا إِلَيْهَا، بَكَتْ، فَقَالاَ لَهَا، مَا يُبْكِيكِ أَمَا تَعْلَمِينَ أَنَّ مَا عِنْدَ اللَّهِ خَيْرٌ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَتْ: إِنِّي لاَ أَبْكِي إِنِّي لَا أَعْلَمُ أَنَّ مَا عِنْدَ اللَّهِ تَعَالَى خَيْرٌ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَلَكِنْ أَبْكِي أَنَّ الوَحْيَ قَدْ انْقَطَعَ مِنَ السَّمَاءِ، فَهَيَجَتْهُمَا عَلَى البُكَاءِ، فَجَعَلاَ يَبْكِيَانِ مَعَهَا.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3035 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20360;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَنَّ رَجُلًا زَارَ أَخًا لَهُ فِي قَرْيَةٍ أُخْرَى، فأَرْصَدَ اللَّهُ تَعَالَى عَلَى مَدْرَجَتِهِ مَلَكًا، فَلَمَّا أَتَى عَلَيْهِ قَالَ: أَيْنَ تُرِيدُ؟ قَالَ: أُرِيدُ أَخًا لِي فِي هَذِهِ القَرْيَةِ. قَالَ: هَلْ لَكَ عَلَيْهِ مِنْ نِعْمَةٍ تَرُبُّهَا عَلَيْهِ؟ قَالَ: لَا غَيْرَ أَنِّي أَحْبَبْتُ فِي اللَّهِ تَعَالَى، قَالَ: فَإِنِى رَسُولُ اللَّهِ إِلَيْكَ بِأَنَّ اللَّهَ قَدْ أَحَبَّكَ كَمَا أَحْبَبْتَهُ فِيهِ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3136 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20361;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ عَادَ مَرِيضًا أَو زَارَ أَخًا لَهُ فِي اللَّهِ، نَادَاهُ مُنَادٍ، بِأَنْ طِبْتَ، وَطَابَ مَمْشَاكَ، وَتَبَوَّأتَ مِنَ الجَنَّةِ مَنْزِلاً».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3442 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20362;
update hadith set arabic = 'عَنْ أَبِي مُوسَى الأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِنَّمَا مَثَلُ الْجَلِيسِ الصَّالِحِ وَجَلِيسِ السَّوْءِ، كَحَامِلِ الْمِسْكِ، وَنَافِخِ الْكِيرِ، فَحَامِلُ الْمِسْكِ، إِمَّا أَنْ يُحْذِيَكَ، وَإِمَّا أَنْ تَبْتَاعَ مِنْهُ، وَإِمَّا أَنْ تَجِدَ مِنْهُ رِيحًا طَيِّبَةً، وَنَافِخُ الْكِيرِ، إِمَّا أَنْ يُحْرِقَ ثِيَابَكَ ، وَإِمَّا أَنْ تَجِدَ مِنْهُ رِيحًا مُنْتِنَةً».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3127 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20363;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «تُنْكَحُ المَرْأَةُ لِأَرْبَعٍ: لِمَالِهَا، وَلِحَسَبِهَا، وَلِجَمَالِهَا، وَلِدِينِهَا، فَاظْفَرْ بِذَاتِ الدِّينِ تَرِبَتْ يَدَاكَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65940 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20364;
update hadith set arabic = 'عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِجِبْرِيلَ: مَا يَمْنَعُكَ أَنْ تَزُورَنَا أَكْثَرَ مِمَّا تَزُورُنَا؟" فَنَزَلَتْ :{وَمَا نَتَنَزَّلُ إِلاَّ بِأَمْرِ رَبِّكَ لَهُ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذَلِكَ}.', updated_at = now() where id = 20365;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « لاَ تُصَاحِبْ إِلاَّ مُؤْمِنًا، وَلاَ يَأْكُلْ طَعَامَكَ إِلاَّ تَقِيٌّ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3474 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20366;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلّى اللهُ عَلَيْهِ وسَلَّم قَالَ: « الرَّجُلُ عَلَى دِينِ خَلِيلِهِ، فَلْيَنْظُرْ أَحَدُكُمْ مَنْ يُخَالِلُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3122 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20367;
update hadith set arabic = 'عَنْ أَبِي مُوسَى الأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: " المَرْءُ مَعَ مَنْ أَحَبَّ" ((مُتَّفَقٌ عَلَيْهِ)) . وَفِي رِوَايَةٍ قَالَ: قِيلَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : الرَّجُلُ يُحِبُّ القَوْمَ وَلَمَّا يَلْحَقْ بِهِمْ؟ قَالَ: "المَرْءُ مَعَ مَنْ أَحَبَّ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20368;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ أَعْرَابِيًّا قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَتَى السَّاعَةُ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَعْدَدْتَ لَهَا؟" قَالَ: حُبَّ اللَّهِ وَرَسُولِهِ قَالَ: "أَنْتَ مَعَ مَنْ أَحْبَبْتَ" ((مُتَّفَقٌ عَلَيْهِ)) وَهَذَا لَفْظُ مُسْلِمٍ. وَفِي رِوَايَةٍ لَهُمَا: مَا أَعْدَدْتُ لَهَا مِنْ كَثِيرِ صَوْمٍ، وَلَا صَلَاةٍ، وَلَا صَدَقَةٍ وَلَكِنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20369;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ كَيفَ تَقُولُ فِي رَجُلٍ أحَبَّ قَومًا وَلَمْ يَلحَقْ بِهِمْ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « المَرْءُ مَعَ مَنْ أَحَبَّ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3074 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20370;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "النَّاسُ مَعَادِنُ كَمَعَادِنِ الذَّهَبِ وَالفِضَّةِ، خِيَارُهُمْ فِي الجَاهِلِيَّةِ خِيَارُهُمْ فِي الإِسْلاَمِ إِذَا فَقُهُوا، والأَرْوَاحُ جُنُودٌ مُجَنَّدَةٌ، فَمَا تَعَارَفَ مِنْهَا ائتَلَفَ، وَمَا تَنَاكَرَ مِنْهَا اخْتَلَفَ" ((رَوَاهُ مُسْلِمٌ؟)). ((وَرَوَى البُخَارِيُّ)) قَوْلَهُ: "الأَرْوَاحُ" مِنْ رِوَايَةِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6367 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20371;
update hadith set arabic = 'عَنْ أُسَيْرِ بْنِ عَمْرٍو وَيُقَالُ": ابْنُ جَابِرٍ وَهُوَ "بِضَمِّ الهَمْزَةِ وَفَتْحِ السِّينِ المُهْمَلَةِ" قَالَ: كَانَ عُمَرُ بْنُ الخَطَّابِ إِذَا أَتَى عَلَيْهِ أَمْدَادُ أَهْلِ اليَمَنِ سَأَلَهُمْ: أَفِيكُمْ أُوَيْسُ بْنُ عَامِرٍ؟ حَتَّى أَتَى عَلَى أُوَيْسٍ رَضِيَ اللَّهُ عَنْهُ ، فَقَالَ لَهُ: أَنْتَ أُوَيْسُ بْنُ عَامِرٍ؟ قَالَ: نَعَمْ، قَالَ: مِنْ مُرَادٍ ثُمَّ مِنْ قَرَنٍ؟ قَالَ: نَعَمْ قَالَ: فَكَانَ بِكَ بَرَصٌ، فَبَرَأَتَ مِنُه إِلاَّ مَوْضِعّ دِرْهَمٍ؟ قَالَ نَعَمْ قَالَ: لَكَ وَالِدَةٌ؟ قَالَ : نَعَمْ، قَالَ : سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ "يَأْتِي عَلَيْكُمْ أُوَيْسُ بْنُ عَامِرٍ مَعَ أَمْدَادِ أَهْلِ اليَمَنِ مِنْ مُرَادٍ، ثُمَّ مِنْ قَرَنٍ كَانَ بِهِ بَرَصٌ، فَبَرَأَ مِنْهُ إِلاَّ مَوْضِعَ دِرْهَمٍ، لَهُ وَالِدَةٌ هُوَ بِهَا بَرُّ لَوْ أَقْسَمَ عَلَى اللَّهِ لَأَبَرَّهُ، فَإِنْ اسْتَطَعْتَ أَنْ يَسْتَغْفِرَ لَكَ فَافْعَلْ" فَاسْتَغْفِرْ لِي فَاسْتَغْفَرَ لَهُ، فَقَالَ لَهُ عُمَرُ: أَيْنَ تُرِيدُ؟ قَالَ: الكُوفَةَ، قَالَ: أَلاَ أَكْتُبُ لَكَ إِلَى عَامِلِهَا؟ قَالَ: أَكُونُ فِي غَبْرَاءِ النَّاسِ أَحَبُّ إِلَيَّ، فَلَمَّا كَانَ مِنَ العَامِ الْمُقْبِلِ حَجَّ رَجُلٌ مِنْ أَشْرَافِهِمْ، فَوَافَقَ عُمَرَ، فَسَأَلَهُ عَنْ أُوَيْسٍ، فَقَالَ: تَرَكْتُهُ رَثَّ البَّيْتِ قَلِيلَ الْمَتَاعِ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ يَقُولُ: يَأْتِي عَلَيْكُمْ أُوَيْسُ بْنُ عَامِرٍ مَعَ أَمْدَادٍ مِنْ أَهْلِ اليَمَنِ مِنْ مُرَادٍ ، ثُمَّ مِنْ قَرَنٍ، كَانَ بِهِ بَرَصٌ فَبَرَأَ مِنْهُ إِلاَّ مَوْضِعَ دِرْهَمٍ، لَهُ وَالِدَةٌ هُوَ بِهَا بَرٌّ لَوْ أَقْسَمَ عَلى اللَّهِ لَأَبَرَّهُ، فَإِنْ اسْتَطَعْتَ أَنْ يَسْتَغْفِرَ لَكَ : فَافْعَلْ، فَأَتَى أُوَيْسًا، فَقَالَ اسْتَغْفِرْ لِي قَالَ: أَنْتَ أَحْدَثُ عَهْدًا بِسَفَرٍ صَالِحٍ، فَاسْتَغْفِرْ لِي. قَالَ: لَقِيتَ عُمَرَ؟ قَالَ: نَعَمْ، فَاسْتَغْفَرَ لَهُ، فَفَطِنَ لَهُ النَّاسُ، فَانْطَلَقَ عَلَى وَجْهِهِ. ((رَوَاهُ مُسْلِمٌ)). وَفِي رِوَايَةٍ لِمُسْلِمٍ أَيْضًا عَنْ أُسَيْرِ بْنِ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ أنَّ أَهْلَ الكُوفَةِ وَفَدُوا عَلَى عُمَرَ رَضِيَ اللَّهُ عَنْهُ ، وَفِيهِمْ رَجُلٌ مِمَّنْ كَانَ يَسْخَرُ بِأُوَيْسٍ، فَقَالَ عُمَرُ: هَلْ هَاهُنَا أَحَدٌ مِنَ القَرَنِيِّنَ؟ فَجَاءَ ذَلِكَ الرَّجُلُ، فَقَالَ عُمَرُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ قَالَ:"إِنَّ رَجُلاً يَأْتِيكُمْ مِنَ اليَمَنِ يُقَالُ لَهُ : أُوَيْسٌ، لاَ يَدَعُ بِاليَمَنِ غَيْرَ أُمٍّ لَهُ، قَدْ كَانَ بِهِ بَيَاضٌ فَدَعَا اللَّهَ تَعَالَى، فَأَذْهَبَهُ إِلاَّ مَوْضِعَ الدِّينَارِ أَوِ الدِّرْهَمِ ، فَمَنْ لَقِيَهُ مِنْكُمْ، فَلْيَسْتَغْفِرْ لَكُمْ". وَفِي رِوَايَةٍ لَهُ عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: "إِنِى سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ خَيْرَ التَّابِعِينَ رَجُلٌ يُقَالُ لَهُ: أُوَيْسٌ: وَلَهُ وَالِدَةٌ وَكَانَ بِهِ بَيَاضٌ، فَمُرُوهُ، فَلْيَسْتَغْفِرْ لَكُمْ".', updated_at = now() where id = 20372;
update hadith set arabic = 'عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: اسْتَأْذَنْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي العُمْرَةِ، فَأَذِنَ لِي، وَقَالَ: "لَا تَنْسَنَا يَا أُخَيَّ مِنْ دُعَائِكَ" فَقَالَ كَلِمَةً مَا يَسُرُّنِي أَنَّ لِي بِهَا الدُّنْيَا. وَفِي رِوَايَةٍ قَالَ: "أَشْرِكْنَا يَا أُخَيَّ فِي دُعَائِكَ". حَدِيثٌ صَحِيحٌ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20373;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَزورُ قُبَاءَ رَاكِبًا وَمَاشِيًا، فَيُصَلِّي فِيهِ رَكْعَتَيْنِ، ((مُتَّفَقٌ عَلَيْهِ)) . وَفِي رِوَايَةٍ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْتِي مَسْجِدَ قُبَاءَ كُلَّ سَبْتٍ رَاكِبًا وَمَاشِيًا وَكَانَ ابْنُ عُمَرَ يَفْعَلُهُ .', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3443 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20374;
update hadith set arabic = 'عَنْ أَنَسِ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «ثَلاَثٌ مَنْ كُنَّ فِيهِ وَجَدَ بِهِنَّ حَلاَوَةَ الإِيمَانِ: أَنْ يَكُونَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا، وَأَنْ يُحِبَّ المَرْءَ لاَ يُحِبُّهُ إِلَّا لِلَّهِ، وَأَنْ يَكْرَهَ أَنْ يَعُودَ فِي الكُفْرِ بَعْدَ أَنْ أَنْقَذَهُ اللَّهُ مِنْهُ، كَمَا يَكْرَهُ أَنْ يُقْذَفَ فِي النَّارِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65115 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20375;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: « سَبْعَةٌ يُظِلُّهُمُ اللَّهُ فِي ظِلِّهِ يَوْمَ لاَ ظِلَّ إِلَّا ظِلُّهُ: إِمَا عَادِلٌ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ اللَّهِ عَزَّ وَجَلَّ، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ بِالمَسَاجِدِ. وَرَجُلاَنِ تَحَابَّا فِي اللَّهِ اجْتَمَعَا عَلَيْهِ ، وَتَفَرَّقَا عَلَيْهِ، وَرَجُلٌ دَعَتْهُ امْرَأَةٌ ذَاتُ حُسْنٍ وَجَمَالٍ، فَقَالَ: إِنِّي أَخَافُ اللَّهَ، وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ، فَأَخْفَاهَا حَتَّى لاَ تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ، وَرَجُلٌ ذَكَرَ اللَّهَ خَالِيًا فَفَاضَتْ عَيْنَاهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66234 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20376;
update hadith set arabic = 'وَعَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ « إِنَّ اللَّهَ تَعَالى يَقُولُ يَوْمَ القِيَامَةِ أَيْنَ المُتَحَابُّونَ بِجَلاَلِي؟ اليَوْمَ أُظِلُّهُمْ فِي ظِلِّي يَوْمَ لاَ ظِلَّ إِلاَّ ظِلِّي».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3369 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20377;
update hadith set arabic = 'وَعَنْهُ قَالَ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : وَالَّذِي نَفْسِي بِيَدِهِ لَا تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا أَوَلَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ: أَفْشُوا السَّلَامَ بَيْنَكُمْ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3361 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20378;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :"أَنَّ رَجُلاً زَارَ أَخًا لَهُ فِي قَرْيَةٍ أُخْرَى، فَأَرْصَدَ اللَّهُ لَهُ عَلَى مَدْرَجَتِهِ مَلَكاً" وَذَكَرَ الحَدِيثَ إِلَى قَوْلِهِ: "إِنَّ اللَّهَ قَدْ أَحَبَّكَ كَمَا أَحْبَبْتَهُ فِيهِ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20379;
update hadith set arabic = 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ فِي الْأَنْصَارِ: «لَا يُحِبُّهُمْ إِلَّا مُؤْمِنٌ، وَلَا يُبْغِضُهُمْ إِلَّا مُنَافِقٌ، مَنْ أَحَبَّهُمْ أَحَبَّهُ اللهُ، وَمَنْ أَبْغَضَهُمْ أَبْغَضَهُ اللهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3438 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20380;
update hadith set arabic = 'عَنْ مُعَاذٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «قَالَ اللهُ عَزَّ وجَلَّ: المُتَحَابُّونَ فِي جَلاَلِي، لَهُمْ مَنَابِرُ مِنْ نُورٍ يَغْبِطُهُمُ النَبِيُّونَ والشُهَدَاءُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3508 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20381;
update hadith set arabic = 'عَنْ أَبِي إِدْرِيسَ الخَوْلَانِيِّ رَحِمَهُ اللَّهُ قَالَ: دَخَلْتُ مَسْجِدَ دِمَشقَ، فَإِذَا فَتًى بَرَّاقُ الثَنَايَا وَإِذَا النَّاسُ مَعَهُ، فَإِذَا اخْتَلَفُوا بِشَيْءٍ، أَسْنَدُوهُ إِلَيْهِ، وَصَدَرُوا عَنْ رَأْيِهِ، فَسَأَلْتُ عَنْهُ، فَقِيلَ: هَذَا مُعَاذُ بْنُ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ، فَلَمَّا كَانَ مِنَ الغَدِ، هَجَّرتُ، فَوَجَدتُهُ قَدْ سَبِقَنِي بِالتَهْجِيرِ، وَوَجَدتُهُ يُصَلِّي، فَانتَظَرتُهُ حَتَّى قَضَى صَلاَتَهُ، ثُمَّ جِئتُهُ مِنْ قِبَلِ وَجْهِهِ، فَسَلَّمْتُ عَلَيْهِ، ثُمَّ قُلتُ: وَاللَّهِ إِنِّي لَأُحِبُّكَ، فَقَالَ: آللَّهِ؟ فَقَالَ: اللَّهِ، فَقَالَ: آللَّهِ؟ فَقَالَتْ: اللَّهِ، فَأَخَذَنِي بَحَبْوَةِ رِدَائِي، فَجَبَذَنِي إِلَيْهِ، فَقَالَ:أَبْشِرْ، فَإِنِّي سَمِعتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: « قَالَ اللَّهُ تعَالَى وَجَبَتْ مَحَبَّتِي لِلمُتَحَابِّينَ فِيَّ، وَالمُتَجَالِسِينَ فِيَّ ، وَالمُتَزَاوِرِينَ فِيَّ ، وَالمُتَبَاذِلِينَ فِيَّ » حَدِيثٌ صَحِيحٌ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3362 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20382;
update hadith set arabic = 'عَنْ أَبِي كَرِيمَةَ المِقْدَادِ بْنِ مَعْدِ يكَرِبَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِذَا أَحَبَّ الرَّجُلُ أَخَاهُ، فَلْيُخْبِرْهُ أَنَّهُ يُحِبُّهُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20383;
update hadith set arabic = 'عَنْ مُعَاذِ رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَخَذَ بِيَدِهِ وَقَالَ: «يَا مُعَاذُ، وَاللَّهِ إِنِّي لَأُحِبُّكَ، ثُمَّ أُوصِيكَ يَا مُعَاذُ لَا تَدَعَنَّ فِي دُبُرِ كُلِّ صَلَاةٍ تَقُولُ: اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ، وَحُسْنِ عِبَادَتِكَ». حَدِيثٌ صَحِيحٌ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3518 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20384;
update hadith set arabic = 'عَنْ أَنَسٍ، رَضِيَ اللَّهُ عَنْهُ ، أنَّ رَجُلاً كَانَ عِنْدَ النَبِيِّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَرَّ رَجُلٌ بِهِ، فَقَالَ: يَا رَسُولَ اللَّهِ إِنِّي لَأُحِبُّ هَذَا، فَقَالَ لَهُ النَبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَأَعْلَمْتَهُ؟" قَالَ: لَا : قَالَ: "أَعْلِمْهُ" فَلَحِقَهُ، فَقَالَ : إِنِّي أُحِبُّكَ فِي اللَّهِ، فَقَالَ: أّحَبَّكَ اللَّهُ الَّذِي أَحْبَبْتَنِي لَهُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3028 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20385;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إنَّ اللَّهَ تَعَالَى قَالَ: "مَنْ عَادَ لِي وَلِيًّا، فَقْدْ آذَنْتُهُ بِالحَرْبِ، وَمَا تَقَرَّبَ إلَيَّ عَبْدِي بِشَيْءٍ أَحَبَّ إلَيَّ مِمَّا افْتَرَضْتُ عَلَيْهِ، وَمَا يَزَالُ عَبْدِي يَتَقَرَّبُ إلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ فَإِذَا أَحْبَبْتُهُ كُنْتُ سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَيَدَهُ الَّتِي يَبْطِشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا، وَإِنْ سَأَلَنِي، أَعْطَيْتُهُ، وَلَئِنْ اسْتَعَاذَنِي، لَأُعِيذَنَّهُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66534 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20386;
update hadith set arabic = 'وَعَنْهُ عَنِ النَّبِيِّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "إِذَا أَحَبَّ اللهُ العَبْدَ نَادَى جِبْرِيلَ: إنَّ اللهَ تَعَالَى يُحِبُّ فُلَاناً، فَأَحْبِبْهُ، فَيُحِبُّهُ جِبْرِيلُ، فَيُنَادِي فِي أَهْلِ السَّمَاءِ: إنَّ اللهَ يحِبُّ فُلَاناً، فَأَحِبُّوهُ، فَيُحِبُّهُ أَهْلُ السَّمَاءِ، ثُمَّ يُوضَعُ لَهُ القَبُولُ فِي الأَرْضِ" ((مُتَّفَقٌ عَلَيْهِ)) . وَفِي رِوَايَةٍ لِمُسْلِمٍ : قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إنَّ اللهَ تَعَالَى إِذَا أَحَبَّ عَبْدًا دَعَا جِبْرِيلَ، فَقَالَ : إِنِّي أُحِبُّ فُلَاناً فَأَحْبِبْهُ، فَيُحِبُّهُ جِبْرِيلُ، ثُمَّ يُنَادِي فِي السَّمَاءِ، فَيَقُولُ: إنَّ اللهَ يُحِبُّ فُلَاناً، فَأَحِبُّوهُ فَيُحِبُّهُ أَهْلُ السَّمَاءِ، ثُمَّ يُوضَعُ لَهُ القَبُولُ فِي الأَرْضِ، وَإِذَا أَبْغَضَ عَبْدًا دَعَا جِبْرِيلَ فَيَقُولُ: إِنِّي أُبْغِضُ فُلَاناً، فَأَبْغِضْهُ، فَيُبْغِضُهُ جِبْرِيلُ، ثُمَّ يُنَادِي فِي أَهْلِ السَّمَاءِ، إنَّ اللهَ يُبْغِضُ فُلَاناً، فَأَبْغِضُوهُ، ثُمَّ تُوضَعُ لَهُ البَغْضَاءُ فِي الأَرْضِ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10096 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20387;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بَعَثَ رَجُلًا عَلَى سَرِيَّةٍ، فَكَانَ يَقْرَأُ لِأَصْحَابِهِ فِي صَلَاتِهِمْ، فَيَخْتِمُ بـ{قُلْ هُوَ اللَّهُ أَحَدٌ} فَلَمَّا رَجَعُوا، ذَكَرُوا ذَلِكَ لِرَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "سَلُوهُ لِأَيِّ شَيْءٍ كَانَ يَصْنَعُ ذَلِكَ؟ " فَسَأَلُوهُ، فَقَالَ : لِأَنَّهَا صِفَةُ الرَّحْمَنِ، فَأَنَا أُحِبُّ أَنْ أَقْرَأَ بِهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :"أَخْبِرُوهُ أَنَّ اللَّهَ تَعَالَى يُحِبُّهُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5213 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20388;
update hadith set arabic = 'عَنْ جُنْدُبِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ صَلَّى صَلَاةَ الصُّبْحِ، فَهُوَ فِي ذِمَّةِ اللهِ، فَلَا يَطْلُبَنَّكُمُ اللهُ مِنْ ذِمَّتِهِ بِشئٍ، فَإِنَّهُ مَنْ يَطْلُبْهُ مِنْ ذِمَّتِهِ بِشئٍ، يُدْرِكْهُ، ثُمَّ يَكُبَّهُ عَلَى وَجْهِهِ فِي نَارِ جَهَنَّمَ ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5435 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20389;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لاَ إِلَهَ إِلَّا اللَّهُ ، وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ ، وَيُقِيمُوا الصَّلاَةَ، وَيُؤْتُوا الزَّكَاةَ ، فَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّ الإِسْلاَمِ، وَحِسَابُهُمْ عَلَى اللَّهِ تَعَالَى».', updated_at = now() where id = 20390;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ اللَّهِ طَارِقِ بْنِ أَشْيَمَ ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: « مَنْ قَالَ لَا إِلَهَ إِلَّا اللهُ ، وَكَفَرَ بِمَا يُعْبَدُ مِنْ دُونِ اللهِ، حَرُمَ مَالُهُ وَدَمُهُ، وَحِسَابُهُ عَلَى اللهِ تَعَالَى».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6765 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20391;
update hadith set arabic = 'عَنْ أَبِي المِقْدَادِ بْنَ الأَسْوَدِ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قُلْتُ لِرَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : أَرَأَيْتَ إِنْ لَقِيتُ رَجُلًا مِنَ الكُفَّارِ، فَاقْتَتَلْنَا، فَضَرَبَ إِحْدَى يَدَيَّ بِالسَّيْفِ، فَقَطَعَهَا، ثُمَّ لاَذَ مِنِّي بِشَجَرَةٍ، فَقَالَ أَسْلَمْتُ لِلَّهِ، أَأَقْتُلُهُ يارَسُولَ اللَّهِ بَعْدَ أَنْ قَالَهَا؟ فَقَالَ: «لاَ تَقْتُلْهُ، فَإِنْ قَتَلْتَهُ، فَإِنَّهُ بِمَنْزِلَتِكَ قَبْلَ أَنْ تَقْتُلَهُ، وَإِنَّكَ بِمَنْزِلَتِهِ قَبْلَ أَنْ يَقُولَ كَلِمَتَهُ الَّتِي قَالَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20392;
update hadith set arabic = 'عَنْ أُسَامَةَ بْنِ زَيْدٍ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: بَعَثَنَا رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِلَى الحُرَقَةِ مِنْ جُهَيْنَةَ ، فَصَبَّحْنَا القَوْمَ عَلَى مِيَاهِهِمْ، ولَحِقْتُ أَنَا وَرَجُلٌ مِنَ الأَنْصَارِ رَجُلًا مِنْهُمْ، فَلَمَّا غَشِينَاهُ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ ، فَكَفَّ عَنْهُ الأَنْصَارِيُّ، وطَعَنْتُهُ بِرُمْحِي حَتَّى قَتَلْتُهُ، فَلَمَّا قَدِمْنَا المَدِينَةَ بَلَغَ ذَلِكَ النَّبِيَّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لِي: " يَا أُسَامَةُ أَقَتَلْتَهُ بَعْدَ مَا قَالَ لَا إِلَهَ إِلَّا اللهُ؟! قُلْتُ يَا رَسُولَ اللهِ إِنَّمَا كَانَ مُتَعَوِّذًا فَقَالَ " أَقَتَلْتَهُ بَعْدَ مَا قَالَ لَا إِلَهَ إِلَّا اللهُ؟!" فَمَا زَالَ يُكَرِّرُهَا عَلَيَّ حَتَّى تَمَنَّيْتُ أَنِّي لَمْ أَكُنْ أَسْلَمْتُ قَبْلَ ذَلِكَ اليَوْمِ. ((مُتَّفَقٌ عَلَيْهِ)) . وَفِي رِوَايَةٍ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "أَقَالَ : لَا إِلَهَ إِلَّا اللهُ وَقَتَلْتَهُ؟! قُلْتُ: يَا رَسُولَ اللهِ، إِنَّمَا قَالَهَا خَوْفًا مِنَ السِّلَاحِ، قَالَ: "أَفَلَا شَقَقْتَ عَنْ قَلْبِهِ حَتَّى تَعْلَمَ أَقَالَهَا أَمْ لَا؟!" فَمَا زَالَ يُكَرِّرُهَا حَتَّى تَمَنَّيْتُ أَنِّي أَسْلَمْتُ يَوْمَئِذٍ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4816 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20393;
update hadith set arabic = 'عَنْ جُنْدُبِ بْنِ عَبْدِ اللَّهِ، رَضِيَ اللَّهُ عَنْهُ ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بَعَثَ بَعْثًا مِنَ المُسْلِمِينَ إِلَى قَوْمٍ مِنَ المُشْرِكِينَ، وَأَنَّهُمُ الْتَقَوْا فَكَانَ رَجُلاً مِنَ المُشْرِكِينَ إِذَا شَاءَ أَنْ يَقْصِدَ إِلَى رَجُلٍ مِنَ المُسْلِمِينَ قَصَدَ لَهُ فَقَتَلَهُ، وَأَنَّ رَجُلًا مِنَ المُسْلِمِينَ قَصَدَ غَفْلَتَهُ، وَكُنَّا نَتَحَدَّثُ أَنَّهُ أُسَامَةُ بْنُ زَيْدٍ، فَلَمَّا رَفَعَ عَلَيْهِ السَّيْفَ ، قَالَ: لَا إِلَهَ إِلَّا اللهُ، فَقَتَلَهُ، فَجَاءَ البَشِيرُ إِلَى رَسُولِ اللهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ ، وَأَخْبَرَهُ، حَتَّى أَخْبَرَهُ خَبَرَ الرَّجُلِ كَيْفَ صَنَعَ ، فَدَعَاهُ فَسَأَلَهُ، فَقَالَ: "لِمَ قَتَلْتَهُ؟ فَقَالَ: يَا رَسُولَ اللهِ أَوْجَعَ فِي المُسْلِمِينَ، وَقَتَلَ فُلَانًا وَفُلَانًا -وَسَمَّى لَهُ نَفَرًا- وَإِنِّي حَمَلْتُ عَلَيْهِ، فَلَمَّا رَأَى السَّيْفَ قَالَ: لَا إِلَهَ إِلَّا اللهُ. قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اقتلته؟" قَالَ نَعَمْ : قَالَ: "فَكَيْفَ تَصْنَعُ بِلَا إِلَهَ إِلَّا اللهُ، إِذَا جَاءَتْ يَوْمَ القِيَامَةِ؟ قَالَ: يَا رَسُولَ اللهِ اسْتَغْفِرْ لِي. قَالَ: "وَكَيْفَ تَصْنَعُ بِلَا إِلَهَ إِلَّا اللهُ إِذَا جَاءَتْ يَوْمَ القِيَامَةِ؟ " فَجَعَلَ لَا يَزِيدُ عَلَى أَنْ يَقُولَ: " كَيْفَ تَصْنَعُ بِلَا إِلَهَ إِلَّا اللهُ إِذَا جَاءَتْ يَوْمَ القِيَامَةِ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4816 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20394;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ قَالَ: سَمِعْتُ عُمَرَ بْنَ الخَطَّابِ، رَضِيَ اللَّهُ عَنْهُ، يَقُولُ: «إِنَّ نَاسًا كَانُوا يُؤْخَذُونَ بِالوَحْيِ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَإِنَّ الوَحْىَ قَدِ انْقَطَعَ، وَإِنَّمَا نَأْخُذُهُمُ الآنَ بِمَا ظَهَرَ لَنَا مِنْ أَعْمَالِكُمْ، فَمَنْ أَظْهَرَ لَنَا خَيْرًا، أَمَّنَّاهُ وقَرَّبْنَاهُ، وَلَيْسَ لَنَا مِنْ سَرِيرَتِهِ شَئٌ، اللَّهُ يُحَاسِبُهُ فِي سَرِيرَتِهِ، وَمَنْ أَظْهَرَ لَنَا سُوءًا، لَمْ نَأْمَنْهُ، وَلَمْ نُصَدِّقْهُ وَإِنْ قَالَ: إِنَّ سَرِيرَتَهُ حَسَنَةٌ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4234 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20395;
update hadith set arabic = 'عَنْ ابْنِ مَسْعُودٍ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: حَدَّثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ الصَّادِقُ المَصْدُوقُ: «إِنَّ أَحَدَكُمْ يُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّهِ أَرْبَعِينَ يَوْمًا نُطْفَةً، ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ، ثُمَّ يَكُونُ مُضْغَةً مِثْلَ ذَلِكَ، ثُمَّ يُرْسَلُ المَلَكُ، فَيَنْفُخُ فِيهِ الرُّوحَ، وَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ: يُكْتَبُ رِزْقُهُ، وَأَجَلُهُ، وَعَمَلُهُ، وَشَقِيٌّ أَمْ سَعِيدٌ. فَوَالَّذِي لَا إلَهَ غَيْرُهُ إنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ الجَنَّةِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَى ذِرَاعٌ، فَيَسْبِقُ عَلَيْهِ الكِتَابُ ، فَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ فَيَدْخُلُهَا، وَإِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعِلْمِ أَهْلِ النَّارِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إلَّا ذِرَاعٌ، فَيَسْبِقُ عَلَيْهِ الكِتَابُ فَيَعْمَلُ بِعَمَلِ أَهْلِ الجَنَّةِ فَيَدْخُلُهَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66513 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20396;
update hadith set arabic = 'وَعَنْهُ قَالَ : قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ « يُؤْتَى بِجَهَنَّمَ يَوْمَئِذٍ لَهَا سَبْعُونَ أَلْفَ زِمَامٍ مَعَ كُلِّ زِمَامٍ سَبْعُونَ أَلْفَ مَلَكٍ يَجُرُّونَهَا ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5463 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20397;
update hadith set arabic = 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ : سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ أَهْوَنَ أَهْلِ النَّارِ عَذَابًا يَوْمَ القِيَامَةِ لَرَجُلٌ يُوضَعُ فِي أَخْمَصِ قَدَمَيْهِ جَمْرَتَانِ يَغْلِي مِنْهُمَا دِمَاغُهُ، مَا يَرَى أَنَّ أَحَدٌ أَشَدُّ مِنْهُ عَذَابًا، وَإِنَّهُ لَأَهْوَنُهُمْ عَذَابًا".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20398;
update hadith set arabic = 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ، رَضِيَ اللَّهُ عَنْهُ، أَنَّ نَبِىَّ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « مِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى كَعْبَيْهِ، وَمِنْ مَنْ تَأْخُذُ إِلَى رُكْبَتَيْهِ، وَمِنْهُمْ مَنْ تَأْخُذُهُ إِلَى حُجْزَتِهِ، وَمِنْهُمْ مَنْ تَأْخُذُهُ إِلَى تَرْقُوَتِهِ» ((رَوَاهُ مُسْلِمٌ)). ('' الحُجْزَةُ : مَعْقِدُ الإِزَارِ تَحْتَ السُّرَّةِ وَ التَّرْقُوَةُ بِفَتْحِ التَّاءِ وَضَمِّ القَافِ: هِيَ العَظْمُ الَّذِي عِنْدَ ثُغْرَةِ النَّحْرِ، وَلِلْإِنْسَانِ تَرْقُوَتَانِ فِي جَانِبَى النَّحْرِ '')', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5445 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20399;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ « يَقُومُ النَّاسُ لِرَبِّ العَالَمِينَ حَتَّى يَغِيبَ أَحَدُهُمْ فِي رَشْحِهِ إِلَى أَنْصَافِ أُذُنَيْهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5462 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20400;
update hadith set arabic = 'عَنْ أَنَسٍ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: خَطَبَنَا رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُطْبَةً مَا سَمِعْتُ مِثْلَهَا قَطُّ، فَقَالَ: "لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلاً وَلَبَكَيْتُمْ كَثِيراً" فَغَطَّى أَصْحَابُ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وُجُوهَهُمْ، وَلَهُمْ خَنِينٌ. ((مُتَّفَقٌ عَلَيْهِ)) . وَفِي رِوَايَةٍ: بَلَغَ رَسُولَ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَصْحَابِهِ شَئٌ فَخَطَبَ ، فَقَالَ: "عُرِضَتْ عَلَى الجَنَّةُ وَالنَّارُ، فَلَمْ أَرَ كَاليَوْمِ فِي الخَيْرِ وَالشَّرِّ، وَلَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا، وَلَبَكَيْتُمْ كَثِيراً" فَمَا أَتَى عَلَى أَصْحَابِ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمٌ أَشَدُّ مِنْهُ، غَطَّوْا رُؤُوسَهُمْ وَلَهُمْ خَنِينٌ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20401;
update hadith set arabic = 'عَنِ الْمِقْدَادِ، رَضيَ اللهُ عنهُ، قَالَ: سَمِعْتُ رَسُولَ اللهِ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "تُدْنَى الشَّمْسُ يَوْمَ الْقِيَامَةِ مِنَ الْخَلْقِ حَتَّى تَكُونَ مِنْهُمْ كَمِقْدَارِ مِيلٍ" قَالَ سُلَيْمُ بْنُ عَامِرٍ الرَّاوِى عَنِ المِقْدَادِ: فَوَاللهِ مَا أَدْرِي مَا يَعْنِي المِيلَ، أَمَسَافَةَ الْأَرْضِ أَمِ الْمِيلَ الَّذِي يُكْحَلُ بِهِ الْعَيْنُ "فَيَكُونُ النَّاسُ عَلَى قَدْ أَعْمَالِهِمْ فِي الْعَرَقِ، فَمِنْهُمْ مَنْ يَكُونُ إِلَى كَعْبَيْهِ، وَمِنْهُمْ مَنْ يَكُونُ إِلَى رُكْبَتَيْهِ، وَمِنْهُمْ مَنْ يَكُونُ إِلَى حُقُوبِهِ، وَمِنْهُمْ مَنْ يُلْجِمُهُ الْعَرَقُ إِلْجَامًا" وَأَشَارَ رَسُولُ اللهِ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، بِيَدِهِ إِلَى فِيهِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20402;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: «يَعْرَقُ النَّاسُ يَوْمَ القِيَامَةِ حَتَّى يَذْهَبَ عَرَقُهُمْ فِي الأَرْضِ سَبْعِينَ ذِرَاعًا، وَيُلْجِمُهُمْ حَتَّى يَبْلُغَ آذَانَهُمْ» ((مُتَّفَقٌ عَلَيْهِ)) . ''((وَمَعْنَى يَذْهَبُ فِي الأَرْضِ : يَنْزِلُ وَيَغُوصُ)). ''', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66398 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20403;
update hadith set arabic = 'وَعَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللهِ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا سَمِعَ وَجْبَةً فَقَالَ: "هَلْ تَدْرُونَ مَا هَذَا؟" قُلْنَا: اللهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: هَذَا حَجَرٌ رُمِىَ بِهِ فِي النَّارِ مُنْذُ سَبْعِينَ خَرِيفًا فَهُوَ يَهْوِي فِي النَّارِ الْآنَ حَتَّى انْتَهَي إِلَى قَعْرِهِ، فَسَمِعْتُمْ وَجْبَتَهَا".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20404;
update hadith set arabic = 'عَنْ عَدِىِّ بْنِ حَاتِمٍ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَالَ رَسُولُ اللهِ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ «مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا سَيُكَلِّمُهُ رَبُّهُ لَيْسَ بَيْنَهُ وَبَيْنَهُ تُرْجُمَانٌ، فَيَنْظُرُ أَيْمَنَ مِنْهُ، فَلَا يَرَى إِلَّا مَاقَدَّمَ، وَيَنْظُرُ أَشْأَمَ مِنْهُ، فَلَا يَرَى إِلَّا مَا قَدَّمَ، وَيَنْظُرُ بَيْنَ يَدَيْهِ، فَلَا يَرَى إِلَّا النَّارَ تِلْقَاءَ وَجْهِهِ، فَاتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6615 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20405;
update hadith set arabic = 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَالَ رَسُولُ اللَّهِ ،صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «إِنِى أَرَى مَا لَا تَرَوْنَ؛ أطَّتِ السَّمَاءُ وحُقَّ لَهَا أَنْ تَئِطَّ، مَا فِيهَا مَوْضِعُ أَرْبَعِ أَصَابِعَ إِلَّا ومَلَكٌ وَاضِعٌ جَبْهَتَهُ سَاجِدًا لِلَّهِ تَعَالَى، وَاللَّهِ لَوْ تَعْلَمُونَ مَا أَعْلَمُ، لَضَحِكْتُمْ قَلِيلًا، وَلَبَكَيْتُمْ كَثِيرًا، وَمَا تَلَذَّذْتُمْ بِالنِّسَاءِ عَلَى الفُرُشِ، وَلَخَرَجْتُمْ إِلَى الصُّعُداتِ تجأورن إِلَى اللَّهِ تَعَالَى» ((رَوَاهُ التِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ)). وَ أَطَّتْ بِفَتْحِ الهَمْزَةِ وَتَشْدِيدِ الطَّاءِ وَ تَئِطُّ بِفَتْحِ التَّاءِ وَبَعْدَهَا هَمْزَةٌ مَكْسُورَةٌ، وَالأَطِيطُ: صَوْتُ الرَّحْلِ وَالقَتَبِ وَشِبْهِهِمَا، وَمَعْنَاهُ: أَنَّ كَثْرَةَ مَنْ فِي السَّمَاءِ مِنَ المَلَائِكَةِ العَابِدِينَ قَدْ أَثْقَلَتْهَا حَتَّى أَطَّتْ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3265 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20406;
update hadith set arabic = 'عَنْ أَبِي بَرْزَةَ -بِرَاءٍ ثُمَّ زَاىٍ- نَضْلَةَ بْنِ عُبَيْدٍ الأَسْلَمِىِّ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَا تَزُولُ قَدَمَا عَبْدٍ يَوْمَ القِيَامَةِ حَتَّى يُسْأَلَ عَنْ عُمُرِهِ فِيمَا أَفْنَاهُ ، وَعَنْ عِلْمِهِ فِيمَا فَعَلَ فِيهِ، وَعَنْ مَالِهِ مِنْ أَيْنَ اكْتَسَبَهُ، وَفِيمَا أَنْفَقَهُ، وَعَنْ جِسْمِهِ فِيمَ أَبْلَاهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4950 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20407;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَرَأَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ {يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا} ثُمَّ قَالَ: "أَتَدْرُونَ مَا أَخْبَارُهَا؟" قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: "فَإِنَّ أَخْبَارَهَا أَنْ تَشْهَدَ كُلُّ عَبْدٍ أَوْ أَمَةٍ بِمَا عَمِلَ عَلَى ظَهْرِهَا تَقُولُ: عَمِلْتَ كَذَا وَكَذَا فِي يَوْمِ كَذَا وَكَذَا، فَهَذِهِ أَخْبَارُهَا".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20408;
update hadith set arabic = 'عَنْ أَبِي سَعْدِي الخُدْرِى، رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "كَيْفَ أَنْعَمُ وصَاحِبُ القَرْنِ قَدِ التَقَمَ ، واسْتَمَعَ الإِذْنَ مَتَى يُؤْمَرُ بالنَّفْخِ فَيَنْفُخُ" فَكَأَنَّ ذَلِكَ ثَقُلَ عَلَى أَصْحَابِ رَسُولِ اللهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُمْ:"قُولُوا :حَسْبُنَا اللهُ ونِعْمَ الوَكِيلُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4949 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20409;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «مَنْ خَافَ أَدْلَجَ ، ومَنْ أَدْلَجَ، بَلَغَ المنْزِلَ، أَلَا إِنَّ سِلْعَةَ اللهِ غَالِيَةٌ، إِلَا إِنَّ سِلْعَةَ اللهِ الجَنَّةُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5434 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20410;
update hadith set arabic = 'عَنْ عَائِشَةَ، رَضيَ اللهُ عنها، قَالَتْ: سَمِعْتُ رَسُولَ اللهِ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: " يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ حُفَاةً عُرَاةً غُرْلًا" قُلْتُ: يَا رَسُولَ اللهِ الرِّجَالُ وَالنِّسَاءُ جَمِيعًا يَنْظُرُ بَعْضُهُمْ إِلَى بَعْضٍ؟ قَالَ: "يَا عَائِشَةُ الْأَمْرُ أَشَدُّ مِنْ أَنْ يُهِمَّهُمْ ذَلِكَ". وَفِي رِوَايَةٍ: "الأَمْرُ أَهَمُّ مِنْ أَنْ يَنْظُرَ بَعْضُهُمْ إِلَى بَعْضٍ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5460 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20411;
update hadith set arabic = 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَأَنَّ عِيسَى عَبْدُ اللهِ وَرَسُولُهُ، وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ وَرُوحٌ مِنْهُ، وَأَنَّ الجَنَّةَ حَقٌّ وَالنَّارَ حَقٌّ، أَدْخَلَهُ اللهُ الْجَنَّةَ عَلَى مَا كَانَ مِنَ الْعَمَلِ" ((مُتَّفَقٌ عَلَيْهِ)) . وَفِي رِوَايَةٍ لِمُسْلِمٍ:"مَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنَّ مُحَمَّداً رَسُولُ اللَّهِ، حَرَّمَ عَلَيْهِ النَّارَ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3417 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20412;
update hadith set arabic = 'عَنْ أَبِي ذَرٍّ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : «يَقُولُ اللهُ عَزَّ وَجَلَّ: مَنْ جَاءَ بِالْحَسَنَةِ، فَلَهُ عَشْرُ أَمْثَالِهَا أَوْ أَزِيدُ، وَمَنْ جَاءَ بِالسَّيِّئَةِ، فَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا أَوْغَفَرُ. وَمَنْ تَقَرَّبَ مِنِّي شِبْرًا ، تَقَرَّبْتُ مِنْهَا ذِرَاعًا، وَمَنْ تَقَرَّبَ مِنِّى ذِرَاعًا ، تَقَرَّبْتُ مِنْهُ بَاعًا، وَمَنْ أَتَانِي يَمْشِي ، أَتَيْتُهُ هَرْوَلَةً، وَمَنْ لَقِيَنِى بِقُرَابِ الْأَرْضِ خَطِيئَةً لَايُشْرِكُ بِهِ شَيْئًا ، لَقِيتُهُ بِمِثْلِهَا مَغْفِرَةً».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20413;
update hadith set arabic = 'عَنْ جَابِرٍ قَالَ : جَاءَ أَعْرَابِيٌّ إِلَى النَّبيّ فَقَالَ : يَا رَسُولَ اللَّهِ ، مَا المُوجِبَتَانِ ؟ قَالَ : « مَنْ مَاتَ لا يُشْرِكُ بِاللَّهِ شَيئاً دَخَلَ الجَنَّةَ ، وَمَنْ مَاتَ يُشْرِكُ بِهِ شَيْئاً دَخَلَ النَّارَ » . رَوَاهُ مُسْلِمٌ .', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20414;
update hadith set arabic = 'عَنْ أَنَسٍ ، رَضِيَ اللَّهُ عَنْهُ ، أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَمُعَاذٌ رَدِيفُهُ عَلَى الرَّحْلِ قَالَ: "يَا مُعَاذُ" قَالَ: لَبَّيْكَ يَا رَسُولَ اللَّهِ وَسَعْدَيْكَ، قَالَ: "يَامُعَاذُ" قَالَ :لَبَّيْكَ يَا رَسُولَ اللهِ وَسَعْدَيْكَ. قَالَ: "يَا مُعَاذُ" قَالَ: لَبَّيْكَ يَا رَسُولَ اللهِ وَسَعْدَيْكَ ثَلَاثًا، قَالَ: "مَا مِنْ عَبْدٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ صِدْقًا مِنْ قَلْبِهِ إِلَّا حَرَّمَهُ اللهُ عَلَى النَّارِ" قَالَ: يَا رَسُولَ اللهِ أَفَلَا أُخْبِرُ بِهَا النَّاسَ فَيَسْتَبْشِرُوا؟ قَالَ: "إِذًا يَتَّكِلُوا" فَأَخْبَرَ بِهَا مُعَاذٌ عِنْدَ مَوْتِهِ تَأَثُّمًا.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10098 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20415;
update hadith set arabic = '-وَعَنْ أَبِي هُرَيْرَةَ -أَوْ أَبِي سَعِيدٍ الخُدْرِى- رَضِيَ اللَّهُ عَنْهُمَا: شَكَّ الرَّاوِى، وَلَا يَضُرُّ الشَّكُّ فِي عَيْنِ الصَّحَابِيِّ: لِأَنَّهُمْ كُلَّهُمْ عُدُولٌ، قَالَ لَمَّا كَانَ غَزْوَةُ تَبُوكَ، أَصَابَ النَّاسَ مَجَاعَةٌ، فَقَالُوا : يَا رَسُولَ اللَّهِ لَوْ أَذِنْتَ لَنَا فَنَحَرْنَا نوَاضِحَنَا، فَأَكَلْنَا وَادَّهَنَّا؟ فَقَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "افْعَلُوا" فَجَاءَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ، فَقَالَ: يَا رَسُولَ اللَّهِ إِنْ فَعَلْتَ، قَلَّ الظَّهْرُ، وَلَكِنِ ادْعُهُمْ بِفَضْلِ أَزْوَادِهِمْ، ثمَ ادْعُ اللَّهَ لَهُمْ عَلَيْهَا بِالبَرَكَةِ لَعَلَّ اللَّهَ أَنْ يَجْعَلَ فِي ذَلِكَ البَرَكَةَ. فَقَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ" فَدَعَا بِنِطَعٍ فَبَسَطَهُ، ثُمَّ دَعَا بِفَضْلِ أَزْوَادِهِمْ، فَجَعَلَ الرَّجُلُ يَجِئُ بِكَفِّ ذُرَةٍ، وَيَجِئُ الآخَرُ بِكَفِّ تَمْرٍ، وَيَجِئُ الآخَرُ بِكَسْرَةٍ حَتَّى اجْتَمَعَ عَلَى النِّطَعِ مِنْ ذَلِكَ شَئٌ يَسِيرٌ، فَدَعَا رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالبَرَكَةِ، ثُمَّ قَالَ: "خُذُوا فِي أَوْعِيَتِكُمْ فَأَخَذُوا فِي أَوْعِيَتِهِمْ حَتَّى مَا تَرَكُوا فِي العَسْكَرِ وِعَاءً إِلَّا مَلَأُوهُ، وَأَكَلُوا حَتَّى شَبِعُوا وَفَضَلَ فضْلَةٌ، فَقَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ ، وَأَنِّي رَسُولُ اللَّهِ، لَا يَلْقَى اللَّهَ بِهِمَا عَبْدٌ غَيْرَ شَاكٍّ؛ فَيُحْجَبَ عَنِ الجَنَّةِ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4955 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20416;
update hadith set arabic = 'عَنْ عِتْبَانَ بْنِ مَالِكٍ، رَضِيَ اللَّهُ عَنْهُ ، وَهُوَ مِمَّنْ شَهِدَ بَدْراً ، قَالَ: كُنْتُ أُصَلِّي لِقَوْمِي بَنِى سَالِمٍ، وَكَانَ يَحُولُ بَيْنِي وَبَيْنَهُمْ وَادٍ إِذَا جَاءَتِ الأَمْطَارُ، فَيَشُقُّ عَلَيَّ اجْتِيَازُهُ قِبَلَ مَسْجِدِهِمْ ، فَجِئْتُ رَسُولَ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ لَهُ : إِنِّى أَنْكَرْتُ بَصَرِى، وَإِنَّ الوَادِيَ الَّذِي بَيْنِى وَبَيْنَ قَوْمِى يَسِيلُ إِذَا جَاءَتِ الأَمْطَارُ، فَيَشُقُّ عَلَيَّ اجْتِيَازُهُ، فَوَدِدْتُ أَنَّكَ تَأْتِي ، فَتُصَلِّي فِي بَيْتِي مَكَاناً أَتَّخِذُهُ مُصَلًّى، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :"سَأَفْعَلُ"، فَغَدَمَا عَلَيَّ رَسُولُ اللَّهِ ، وَأَبُو بَكْرٍ، رَضِيَ اللَّهُ عَنْهُ بَعْدَ مَا اشْتَدَّ النَّهَارُ، وَاسْتَأْذَنَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَأَذِنْتُ لَهُ، فَلَمْ يَجْلِسْ حَتَّى قَالَ: "أَيْنَ تُحِبُّ أَنْ أُصَلِّيَ مِنْ بَيْتِكَ؟" فَأَشَرْتُ لَهُ إِلَى المَكَانِ الَّذِي أُحِبُّ أَنْ يُصَلِّيَ فِيهِ، فَقَامَ رَسُولُ اللَّهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَبَّرَ وَصَفَفْنَا وَرَاءَهُ، فَصَلَّى رَكْعَتَيْنِ، ثُمَّ سَلَّمَ وَسَلَّمْنَا حِينَ سَلَّمَ، فَحَبَسْتُهُ عَلَى خَزِيرَةٍ تُصْنَعُ لَهُ، فَسَمِعَ أَهْلُ الدَّارِ أَنَّ رَسُولَ اللَّهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِي، فَثَابَ رِجَالٌ مِنْهُمْ حَتَّى كَثُرَ الرِّجَالُ فِي البَيْتِ، فَقَالَ رَجُلٌ : مَا فَعَلَ مَالِكٌ لَا أَرَاهُ! فَقَالَ رَجُلٌ: ذَلِكَ مُنَافِقٌ لَا يُحِبُّ اللَّهَ وَرَسُولَهُ، فَقَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: " لَا تَقُلْ ذَلِكَ، أَلَا تَرَاهُ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ يَبْتَغِي بِذَلِكَ وَجْهَ اللَّهِ تَعَالَى ؟_ !" فَقَالَ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، أَمَّا نَحْنُ فَوَ اللَّهِ مَا نَرَى وُدَّهُ، وَلَا حَدِيثَهُ إِلَّا المُنَافِقِينَ _! فَقَالَ رَسُولُ اللَّهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، "فَإِنَّ اللَّهَ قَدْ حَرَّمَ عَلَى النَّارِ مَنْ قَالَ : لَا إِلَهَ إِلَّا اللَّهُ يَبْتَغِي بِذَلِكَ وَجْهَ اللَّهِ" ((مُتَّفَقٌ عَلَيْهِ)) . (''وَ عِتْبَانُ بِكَسْرِ العَيْنِ المُهْمَلَةِ، وَإِسْكَانِ التَّاءِ المُثَنَّاةِ فَوْقُ وَبَعْدَهُمَا بَاءٌ مُوَحَّدَةٌ. وَ الخَزِيرَةُ بِالخَاءِ المُعْجَمَةِ، وَالزَّاى: هِيَ دَقِيقٌ يُطْبَخُ بِشَحْمٍ. وَقَوْلُهُ: ثَابَ رِجَالٌ بِالثَّاءِ المُثَلَّثَةِ، أَيْ : جَاؤُوا وَاجْتَمَعُوا. '')', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20417;
update hadith set arabic = 'عَنْ عُمَرَ بْنِ الخَطَّابِ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَدِمَ رَسُولُ اللَّهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بِسَبْيٍ، فَإِذَا امْرَأَةٌ مِنَ السَّبْيِ تَسْعَى، إِذْ وَجَدَتْ صَبِيّاً فِي السَّبْيِ أَخَذَتْهُ، فَأَلْزَقَتْهُ بِبَطْنِهَا، فَأَرْضَعَتْهُ، فَقَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَتَرَوْنَ هَذِهِ المَرْأَةَ طَارِحَةً وَلَدَهَا فِي النَّارِ؟" قُلْنَا لَا وَاللَّهِ . قَالَ: "لَلَّهُ أَرْحَمُ بِعِبَادِهِ مِنْ هَذِهِ الأُمِّ بِوَلَدِهَا".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20418;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَالَ رَسُولُ اللَّهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا خَلَقَ اللهُ الخَلْقَ، كَتَبَ فِي كِتَابٍ، فَهُوَ عِنْدَهُ فَوْقَ العَرْشِ: إِنَّ رَحْمَتِي تَغْلِبُ غَضَبِي".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4961 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20419;
update hadith set arabic = 'وَعَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "جَعَلَ اللهُ الرَّحْمَةَ مِائَةَ جُزْءٍ فَأَمْسَكَ عِنْدَهُ تِسْعَةً وَتِسْعِينَ، وأَنْزَلَ فِي الأَرْضِ جُزْءًا وَاحِدًا، فَمِنْ ذَلِكَ الجُزْءِ يَتَرَاحَمُ الخَلَائِقُ حَتَّى تَرْفَعَ الدَّابَّةُ حَافِرَهَا عَنْ وَلَدِهَا خَشْيَةَ أَنْ تُصِيبَهُ". "وَفِي رِوَايَةٍ: "إِنَّ للهِ تَعَالَى مِائَةَ رَحْمَةٍ أَنْزَلَ مِنْهَا رَحْمَةً وَاحِدَةً بَيْنَ الجِنِّ وَالإِنْسِ وَالبَهَائِمِ وَالهَوَامِّ، فِيهَا يَتَعَاطَفُونَ، وَبِهَا يَتَرَاحَمُونَ، وَبِهَا تَعْطِفُ الوَحْشُ عَلَى وَلَدِهَا، وَأَخَّرَ اللهُ تَعَالَى تِسْعًا وَتِسْعِينَ رَحْمَةً يَرْحَمُ بِهَا عِبَادَهُ يَوْمَ القِيَامَةِ" ((مُتَّفَقٌ عَلَيْهِ)) . وَرَوَاهُ مُسْلِمٌ أَيْضاً مِنْ رِوَايَةِ سَلْمَانَ الفَارِسِيِّ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ للهِ تَعَالَى مِائَةَ رَحْمَةٍ فَمِنْهَا رَحْمَةٌ يَتَرَاحَمُ بِهَا الخَلْقُ بَيْنَهُمْ، وَتِسْعٌ وَتِسْعُونَ لِيَوْمِ القِيَامَةِ" "وَفِي رِوَايَةٍ: "إِنَّ اللهَ تَعَالَى خَلَقَ يَوْمَ خَلَقَ السَّمَاوَاتِ وَالأَرْضَ مِائَةَ رَحْمَةٍ كُلُّ رَحْمَةٍ طِبَاقَ مَا بَيْنَ السَّمَاءِ إِلَى الأَرْضِ، فَجَعَلَ مِنْهَا فِي الأَرْضِ رَحْمَةً، فِيهَا تَعْطِفُ الوَالِدَةُ عَلَى وَلَدِهَا، وَالوَحْشُ وَالطَّيْرُ بَعْضُهَا عَلَى بَعْضٍ، فَإِذَا كَانَ يَوْمُ القِيَامَةِ، أَكْمَلَهَا بِهَذِهِ الرَّحْمَةِ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4291 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20420;
update hadith set arabic = 'وَعَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فِيمَا يَحْكِى عَنْ رَبِّهِ، تَبَارَكَ وَتَعَالَى، قَالَ: "أَذْنَبَ عَبْدِي ذَنْبًا، فَقَالَ: اللَّهُمَّ اغْفِرْ لِى ذَنْبِي، فَقَالَ اللَّهُ تَبَارَكَ وَتَعَالَى: أَذْنَبَ عَبْدِى ذَنْبًا، فَعَلِمَ أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ، وَيَأْخُذُ بِالذَّنْبِ، ثُمَّ عَادَ فَأَذْنَبَ، فَقَالَ: أَيْ رَبِّ اغْفِرْ لِي ذَنْبِي، فَقَالَ تَبَارَكَ وَتَعَالَى: أَذْنَبَ عَبْدِي ذَنْبًا، فَعَلِمَ أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ، وَيَأْخُذُ بِالذَّنْبِ، ثُمَّ عَادَ فَأَذْنَبَ، فَقَالَ: أَيْ رَبِّ اغْفِرْ لِى ذَنْبِي، فَقَالَ، تَبَارَكَ وَتَعَالَى: أَذْنَبَ عَبْدِي ذَنْباً، فَعَلِمَ أَنَّ لَهُ رَبّاً يَغْفِرُ الذَّنْبَ، وَيَأْخُذُ بِالذَّنْبِ، قَدْ غَفَرْتُ لِعَبْدِى فَلْيَفْعَلْ مَا شَاءَ" ((مُتَّفَقٌ عَلَيْهِ)) . وَقَوْلُهُ تَعَالَى: "فَلْيَفْعَلْ مَا شَاءَ" أَيْ: مَا دَامَ يَفْعَلُ هَكَذَا، يُذْنِبُ وَيَتُوبُ اغْفِرْ لَهُ، فَإِنَّ التَّوْبَةَ تَهْدِمُ مَا قَبْلَهَا.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20421;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «وَالَّذِي نَفْسِي بِيَدِهِ لَوْ لَمْ تُذْنِبُوا، لَذَهَبَ اللَّهُ بِكُمْ، وَلَجَاءَ بِقَوْمٍ يُذْنِبُونَ، فَيَسْتَغْفِرُونَ اللهَ تَعَالَى، فَيَغْفِرُ لَهُمْ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20422;
update hadith set arabic = 'عَنْ أَبِي أَيُّوبَ خَالِدِ بْنِ زَيْدٍ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: «لَوْلَا أَنَّكُمْ تُذْنِبُونَ ؛ لَخَلَقَ اللَّهُ خَلْقاً يُذْنِبُونَ، فَيَسْتَغْفِرُونَ، فَيَغْفِرُ لَهُمْ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20423;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ ، قَالَ: كُنَّا قُعُودًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَعَنَا أَبُو بَكْرٍ وَعُمَرُ، رَضِيَ اللَّهُ عَنْهُمَا فِي نَفَرٍ، فَقَامَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مِنْ بَيْنِ أَظْهُرِنَا، فَأَبْطَأَ عَلَيْنَا، فَخَشِينَا أَنْ يُقْتَطَعَ دُونَنَا، فَفَزِعْنَا، فَقُمْنَا، فَكُنْتُ أَوَّلَ مَنْ فَزِعَ، فَخَرَجْتُ ابْتَغِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَتَّى أَتَيْتُ حَائِطًا لِلْأَنْصَارِ -وَذَكَرَ الحَدِيثَ بِطُولِهِ إِلَى قَوْلِهِ: فَقَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، «اذْهَبْ فَمَنْ لَقِيتَ وَرَاءَ هَذَا الحَائِطِ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ ، مُسْتَيْقِنًا بِهَا قَلْبُهُ فبَشِّرْهُ بِالجَنَّةِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20424;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ، رَضِيَ اللَّهُ عَنْهُمَا، أَنَّ النَّبِيَّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، تَلَا قَوْلَ اللهِ عَزَّ وَجَلَّ فِي إِبْرَاهِيمَ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِنَ النَّاسِ فَمَنْ تَبِعَنِي فَإِنَّهُ مِنِّي}.', updated_at = now() where id = 20425;
update hadith set arabic = 'عَنْ مُعَاذِ بْنِ جَبَلٍ ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: كُنْتُ رِدْفَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، عَلَى حِمَارٍ فَقَالَ: " يَا مُعَاذُ هَلْ تَدْرِي مَا حَقُّ اللَّهِ عَلَى عِبَادِهِ، وَمَا حَقُّ العِبَادِ عَلَى اللَّهِ. ؟ قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ:"فَإِنَّ حَقَّ اللَّهِ عَلَى العِبَادِ أَنْ يَعْبُدُوهُ، وَلا يُشْرِكُوا بِهِ شَيْئًا، وَحَقَّ العِبَادِ عَلَى اللَّهِ أَنْ لا يُعَذِّبَ مَنْ لا يُشْرِكُ بِهِ شَيْئًا، فَقُلْتُ، يَا رَسُولَ اللَّهِ أَفَلاَ أُبَشِّرُ النَّاسَ؟ قَالَ لا تُبَشِّرْهُمْ فَيَتَّكِلُوا".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65007 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20426;
update hadith set arabic = 'عَنِ البَرَاءِ بْنِ عَازِبٍ، رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "المُسْلِمُ إِذَا سُئِلَ فِي القَبْرِ يَشْهَدُ أَنْ لاَ إِلَهَ إِلَّا اللَّهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، فَذَلِكَ قَوْلُهُ تَعَالَى: {يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالقَوْلِ الثَّابِتِ فِي الحَيَاةِ الدُّنْيَا وَفِي الآخِرَةِ}.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4206 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20427;
update hadith set arabic = 'عَنْ أَنَسٍ، رَضِيَ اللَّهُ عَنْهُ ،عَنْ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "إنَّ الكَافِرَ إِذَا عَمِلَ حَسَنَةً، أُطْعِمَ بِهَا طُعْمَةً مِنَ الدُّنْيَا، أَمَّا المُؤْمِنُ، فإِنَّ اللهَ تَعَالَى يَدَّخِرُ لَهُ حَسَنَاتِهِ فِي الآخِرَةِ، وَيُعْقِبُهُ رِزْقًا فِي الدُّنْيَا عَلَى طَاعَتِهِ". وَفِي رِوَايَةٍ: "إنَّ اللَّهَ لَا يَظْلِمُ مُؤْمِنًا حَسَنَةً يُعْطَى بِهَا فِي الدُّنْيَا، وَيُجْزَى بِهَا فِي الآخِرَةِ، وَأَمَّا الكَافِرُ، فَيُطْعَمُ بِحَسَنَاتِ مَا عَمِلَ لِلَّهِ تَعَالَى، فِي الدُّنْيَا حَتَّى إِذَا أَفْضَى إِلَى الآخِرَةِ، لَمْ يَكُنْ لَهُ حَسَنَةٌ يُجْزَى بِهَا".', updated_at = now() where id = 20428;
update hadith set arabic = 'عَنْ جَابِرٍ، رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَثَلُ الصَّلَوَاتِ الخَمْسِ كَمَثَلِ نَهْرٍ جَارٍ غَمْرٍ عَلَى بَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ» ((رَوَاهُ مُسْلِمٌ)). (''الغَمْرُ: الكَثِيرُ.'')', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20429;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: «مَا مِنْ رَجُلٍ مُسْلِمٍ يَمُوتُ فَيَقُومُ عَلَى جَنَازَتِهِ أَرْبَعُونَ رَجُلاً لَا يُشْرِكُونَ بِاللَّهِ شَيْئاً إِلَّا شَفَّعَهُمُ اللَّهُ فِيهِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20430;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي قُبَّةٍ نَحْوًا مِنْ أَرْبَعِينَ ، فَقَالَ: "أَتَرْضَونَ أَنْ تَكُونُوا رُبُعَ أَهْلِ الجَنَّةِ؟" قُلْنَا نَعَمْ، قَالَ: أَتَرْضَوْنَ أَنْ تَكُونُوا ثُلُثَ أَهْلِ الجَنَّةِ؟ قُلْنَا: نَعَمْ، قَالَ: "وَالَّذِي نَفْسِى مُحَمَّدٍ بِيَدِهِ إِنِّي لَأَرْجُو أَنْ تَكُونُوا نِصْفَ أَهْلِ الجَنَّةِ، وَذَلِكَ أَنْ الجَنَّةَ لَا يَدْخُلُهَا إِلَّا نَفْسٌ مُسْلِمَةٌ، وَمَا أَنْتُمْ فِي أَهْلِ الشِّرْكِ إِلَّا كَالشَّعْرَةِ البَيْضَاءِ فِي جِلْدِ الثَّوْرِ الأَسْوَدِ، أَوْ كَالشَّعْرَةِ السَّوْدَاءِ فِي جِلْدِ الثَّوْرِ الأَحْمَرِ".', updated_at = now() where id = 20431;
update hadith set arabic = 'عَنْ أَبِي مُوسَى الأَشْعَرِيِّ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا كَانَ يَوْمُ القِيَامَةِ دَفَعَ اللهُ إِلَى كُلِّ مُسْلِمٍ يَهُودِيًّا أَوْنَصْرَانِياً فَيَقُولُ: هَذَا فِكَاكُكَ مِنَ النَّارِ". وَفِي رِوَايَةٍ عَنْهُ عَنِ النَّبِيِّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَجِئُ يَوْمَ القِيَامَةِ نَاسٌ مِنَ المُسْلِمِينَ بِذُنُوبٍ أَمْثَالِ الجِبَالِ يَغْفِرُهَا اللَّهُ لَهُمْ ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6462 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20432;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: يُدْنَى المُؤْمِنُ يَوْمَ القِيَامَةِ مِنْ رَبِّهِ حَتَّى يَضَعَ كَنَفَهُ عَلَيْهِ، فَيُقَرِّرُهُ بِذُنُوبِهِ، فَيَقُولُ: أَتَعْرِفُ ذَنْبَ كَذَا؟ أَتَعْرِفُ ذَنْبَ كَذَا؟ فَيَقُولُ: رَبِّ أَعْرِفُ قَالَ: فَإِنِّي قَدْ سَتَرْتُهَا عَلَيْكَ فِي الدُّنْيَا، وَأَنَا أَغْفِرُهَا لَكَ اليَوْمَ، فَيُعْطَى صَحِيفَةَ حَسَنَاتِهِ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20433;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ، رَضِيَ اللَّهُ عَنْهُ ، أَنَّ رَجُلاً أَصَابَ مِنِ امْرَأَةٍ قُبْلَةً، فَأَتَى النَّبِيَّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخْبَرَهُ، فَأَنْزَلَ اللَّهُ تَعَالَى: { وَأَقِمِ الصَّلَاةَ طَرَفَيِ النَّهَارِ وزُلَفًا مِنَ اللَّيلِ إِنَّ الحَسَنَاتِ يُذْهِبنَ السَّيِئَاتِ }.', updated_at = now() where id = 20434;
update hadith set arabic = 'عَنْ أَنَسٍ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ أصَبْتُ حَدًّا، فَأَقِمْهُ عَلَيَّ، وَحَضَرَتِ الصَّلَاةُ، فَصَلَّى مَعَ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا قَضَى الصَّلَاةَ قَالَ : يارَسُولَ اللَّهِ إِنِّى أصَبْتُ حَدًّا، فَأَقِمْ فِيَّ كِتَابَ اللَّهِ. قَالَ "هَلْ حَضَرْتَ مَعَنَا الصَّلَاةَ؟ " قَالَ: نَعَمْ . قَالَ: قَدْ غُفِرَ لَكَ" ((مُتَّفَقٌ عَلَيْهِ)). (''وَقَوْلُهُ اصَبْتُ حَداً مَعْنَاهُ : مَعْصِيَةٌ تُوجِبُ التَّعْزِيرَ، وَلَيْسَ المُرَادُ الحَدَّ الشَّرْعِيَّ الحَقِيقِىَّ كَحَدِّ الزِّنَا وَالخَمْرِ وَغَيْرِهِمَا، فَإِنَّ هَذِهِ الحُدُودَ لَا تَسْقُطُ بِالصَّلَاةِ، وَلَا يَجُوزُ لِلْإِمَامِ تَرْكُهَا'')', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3658 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20435;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِنَّ اللهَ لَيَرْضَى عَنِ الْعَبْدِ أَنْ يَأْكُلَ الْأَكْلَةَ، فَيَحْمَدَهُ عَلَيْهَا، أَوْ يَشْرَبَ الشَّرْبَةَ، فَيَحْمَدَهُ عَلَيْهَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5798 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20436;
update hadith set arabic = 'عَنْ أَبِي مُوسَى، رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ «إِنَّ اللَّهَ تَعَالَى يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِئُ النَّهَارِ، وَيَبْسُطُ يَدَهُ بِالنَّهَارِ لِيَتُوبَ مُسِئُ اللَّيْلِ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20437;
update hadith set arabic = 'عَنْ أَبِي نَجِيحٍ عَمْرِو بْنِ عَبَسَةَ -بِفَتْحِ العَيْنِ وَالبَاءِ- السُّلَمِيِّ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: كُنْتُ وَأَنَا فِي الجَاهِلِيَّةِ أَظُنُّ أَنَّ النَّاسَ عَلَى ضَلَالَةٍ، وَأَنَّهُمْ لَيْسُوا عَلَى شَئٍ، وَهُمْ يَعبُدُونَ الأَوْثَانَ، فَسَمِعْتُ بِرَجُلٍ بِمَكَّةَ يُخْبِرُ أَخْبَارًا، فَقَعَدتُ عَلَى رَاحِلَتِى، فَقَدِمتُ عَلَيْهِ، فَإِذَا رَسُولُ اللَّهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُسْتَخْفِيًا، جُرَءَاءُ عَلَيْهِ قَوْمُهُ ، فَتَلَطَّفُ حَتَّى دَخَلْتُ عَلَيْهِ بِمَكَّةَ، فَقُلْتُ لَهُ : مَا أَنْتَ؟ قَالَ: "أَنَا نَبيٌّ" قُلْتُ: وَمَا نَبِيٌّ ؟ قَالَ: "أَرْسَلَنِي اللَّهُ" قُلْتُ: وبِأَيِّ شَئٍ أَرْسَكَ؟ قَالَ "أَرْسَلَنِي بِصِلَةِ الأَرْحَامِ، وَكَسْرِ الأَوْثَانِ وَأَنْ يُوَحَّدَ اللَّهُ لَا يُشْرَكُ بِهِ شَئٌ: قُلْتُ: فَمَنْ مَعَكَ عَلَى هَذَا؟ قَالَ: "حُرٌّ وعَبْدٌ" وَمَعَهُ يَوْمَئِذٍ أَبُو بَكْرٍ وَبِلَالٌ، رَضِيَ اللَّهُ عَنْهُمَا، قُلْتُ: إِنِّي مُتَّبِعُكَ، قَالَ: "إِنَّكَ لَنْ تَسْتَطِيعَ ذَلِكَ يَوْمَكَ هَذَا، أَلَا تَرَى حَالِي وَحَالَ النَّاسِ؟ وَلَكِنِ ارْجِعْ إِلَى أَهْلِكَ فَإِذَا سَمِعْتَ بِي قَدْ ظَهَرْتُ فَأْتِنِي" قَالَ: فَذَهَبْتُ إِلَى أَهْلِي وَقَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، المَدِينَةَ، وَكُنْتُ فِي أَهْلِي، فَجَعَلْتُ أَتَخَبَّرُ الأَخْبَارَ، وَاسْأَلُ النَّاسَ حِينَ قَدِمَ المَدِينَةَ حَتَّى قَدِمَ نَفرٌ مِنْ أَهْلِي المَدِينَةَ، فَقُلْتُ: مَا فَعَلَ هَذَا الرَّجُلُ الَّذِي قَدِمَ المَدِينَةَ؟ فَقَالُوا: النَّاسُ إِلَيْهِ سِرَاعٌ، وَقَدْ أَرَادَ قَوْمُهُ قَتْلَهُ، فَلَمْ يَسْتَطِيعُوا ذَلِكَ، فَقَدِمْتُ المَدِينَةَ، فَدَخَلْتُ عَلَيْهِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ أَتَعْرِفُنِي؟ قَالَ: "نَعَمْ أنتالذي لَقَيْتَنِي بِمَكَّةَ" قَالَ: فَقُلْتُ يَا رَسُولَ اللَّهِ أَخْبِرْنِي عَمَّا عَلَّمَكَ اللَّهُ وأَجْهَلُهُ، أَخْبِرْنِى عَنِ الصَّلَاةِ؟ قَالَ :" صَلِّ صَلَاةَ الصُّبْحِ، ثُمَّ أَقْصِرْ عَنِ الصَّلَاةِ حَتَّى تَرْتَفِعَ الشَّمْسُ قِيْدَ رُمْحٍ، فَإِنَّهُ تَطْلُعُ حِينَ تَطلُعُ بَيْنَ قَرْنَي شَيْطَانٍ، وَحِينَئِذٍ يَسجُدُ لَهَا الكُفَّارُ، ثُمَّ صَلِّ فَإِنَّ الصَّلَاةَ مَشهُودَةٌ مَحضُورَةٌ حَتَّى يَسْتَقِلَّ الظِّلُ بالرُّمْحِ، ثُمَّ أَقْصِرْ عَنِ الصَّلَاةِ، فَإِنَّهُ حِينَئِذٍ تُسْجَرُ جَهَنَّمُ؛ فَإِذَا أَقْبَلَ الفَيْءُ فَصَلِّ؛ فَإِنَّ الصَّلَاةَ مَشهُودَةٌ مَحضُورَةٌ حَتَّى تُصَلِّيَ العَصْرَ، ثُمَّ اقْصُرْ عَنِ الصَّلَاةِ حَتَّى تَغْرُبَ الشَّمْسُ ، فَإِنَّهَا تَغْرُبُ بَيْنَ قَرْنَيْ شَيْطَانٍ، وَحِينَئِذٍ يَسجُدُ لَهَا الكُفَّارُ" قَالَ: فَقُلْتُ: يَا نَبِىَّ اللَّهِ ؛ فَالوُضُوءُ حَدِّثْنِى عَنْهُ؟ فَقَالَ: "مَا مِنكُمْ رَجُلٌ يُقَرِّبُ وَضُوءَهُ، فَيَتَمَضْمَضُ وَيَسْتَنْشِقُ فَيَنْتَثِرُ، إِلَّا خَرَّتْ خَطَايَا وَجْهِهِ وَفِيهِ وَخَيَاشِيمِهِ، ثُمَّ إِذَا غَسَلَ وَجْهَهُ كَمَا أَمَرَهُ اللَّهُ ، إِلَّا خَرَّتْ خَطَايَا وَجْهِهِ مِنْ أَطْرَافِ لِحْيَتِهِ مَعَ المَاءِ، ثُمَّ يَغْسِلُ يَدَيْهِ إِلَى المِرْفَقَيْنِ، إِلَّا خَرَّتْ خَطَايَا يَدَيْهِ مِنْ أَنَامِلِهِ مَعَ المَاءِ ثُمَّ يَمْسَحُ رَأْسَهُ، إِلَّا خَرَّتْ خَطَايَا يَدَيْهِ مِنْ أَنَامِلِهِ مَعَ المَاءِ، ثُمَّ يَغْسِلُ يَدَيْهِ إِلَى المِرْفَقَيْنِ ، إِلَاخَرَّتْ خَطَايَا يَدَيْهِ مِنْ أَنَامِلِهِ مَعَ المَاءِ، ثُمَّ يَمْسَحُ رَأْسَهُ، إِلَّا خَرَّتْ خَطَايَا رَأْسِهِ مِنْ أَطْرَافِ شَعْرِهِ مَعَ المَاءِ، ثُمَّ يَغْسِلُ قَدِيمَهُ إِلَى الكَعْبَيْنِ إِلَّا خَرَّتْ خَطَايَا رِجْلَيْهِ مِنْ أَنَامِلِهِ مَعَ المَاءِ، فَإِنْ هُوَ قَامَ فَصَلَّى، فَحَمِدَ اللَّهَ تَعَالَى، وَأَثْنَى عَلَيْهِ وَمَجَّدَهُ بِالَّذِي هُوَ لَهُ أَهْلٌ ، وَفَرَّغَ قَلْبَهُ لِلَّهِ تَعَالَى، إِلَّا انْصَرَفَ مِنْ خَطِيئَتِهِ كَهَيْئَتِهِ يَوْمَ وَلَدَتْهُ أُمُّهُ". فَحَدَّثَ عَمْرُو بْنُ عَبَسَةَ بِهَذَا الحَدِيثِ أَبَا أُمَامَةَ صَاحِبَ رَسُولِ اللَّهِ، فَقَالَ لَهُ أَبُو أُمَامَةَ: يَا عَمْرُو بْنَ عَبَسَةَ، انْظُرْ مَا تَقُولُ! فِي مَقَامٍ وَاحِدٍ يُعْطَى هَذَا الرَّجُلُ؟ فَقَالَ عَمْرٌو: يَا أَبَا أُمَامَةَ لَقَدْ كَبِرَتْ سِنِّي، وَرَقَّ عَظْمِي ، وَاقْتَرَبَ أَجَلِي، وَمَا بِي حَاجَةٌ أَنْ أَكْذِبَ عَلَى اللَّهِ تَعَالَى، وَلَا عَلَى رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَوْ لَمْ اسْمَعْهُ مِنْ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا مَرَّةً أَوْ مَرَّتَيْنِ أَوْ ثَلَاثًا، حَتَّى عَدَّ سَبْعَ مَرَّاتٍ، مَاحَدَّثْتُ أَبَدًا بِهِ، وَلَكِنِّي سَمِعْتُهُ أَكْثَرَ مِنْ ذَلِكَ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6610 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20438;
update hadith set arabic = 'عَنْ أَبِي مُوسَى الأَشْعَرِيِّ، رَضِيَ اللَّهُ عَنْهُ ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « إِذَا أَرَادَ اللَّهُ تَعَالَى، رَحْمَةَ أُمَّةٍ ، قَبَضَ نَبِيَّهَا قَبْلَهَا، فَجَعَلَهُ لَهَا فَرَطًا وسَلَفًا بَيْنَ يَدَيْهَا، وَإِذَا أَرَادَ هَلَكَةَ أُمَّةٍ، عَذَّبَهَا وَنَبِيُّهَا حَيٌّ، فَأَهْلَكَهَا وَهُوَ حَىٌّ يَنظُرُ، فَأَقَرَّ عَيْنَهُ بِهَلاَكِهَا حِينَ كَذَّبُوهُ وَعَصَوا امرَهُ».', updated_at = now() where id = 20439;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: " قَالَ اللَّهُ، عَزَّ وَجَلَّ: أَنَا عِنْدَ ظَنِّ عَبْدِي بِي وَأَنَا مَعَهُ حَيْثُ يَذْكُرُنِي، وَاللَّهِ لَلَّهُ أَفْرَحُ بِتَوْبَةِ عَبْدِهِ مِنْ أَحَدِكُمْ يَجِدُ ضَالَّتَهُ بِالفَلَاةِ، وَمَنْ تَقَرَّبَ إِلَيَّ شِبْراً، تَقَرَّبْتُ إِلَيْهِ ذِرَاعاً، وَمَنْ تَقَرَّبَ إِلَيَّ ذِرَاعاً، تَقَرَّبْتُ إِلَيْهِ بَاعاً، وَإِذَا أَقْبَلَ إِلَيَّ يَمْشِي، أَقْبَلْتُ إِلَيْهِ أُهَرْوِلُ" ((مُتَّفَقٌ عَلَيْهِ)) . وَهَذَا لَفْظُ إِحْدَى رِوَايَاتِ مُسْلِمٍ. وَتَقَدَّمَ شَرْحُهُ فِي البَابِ قَبْلَهُ. وَرُوِيَ فِي الصَّحِيحَيْنِ : "وَأَنَا مَعَهُ حِينَ يَذْكُرُنِي" بِالنُّونِ، وَفِي هَذِهِ الرِّوَايَةِ "حَيْثُ" بِالثَّاءِ وَكِلَاهُمَا صَحِيحٌ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20440;
update hadith set arabic = 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، رَضِيَ اللَّهُ عَنْهُمَا ، أَنَّهُ سَمِعَ النَّبِيَّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَبْلَ مَوْتِهِ بِثَلَاثَةِ أَيَّامٍ يَقُولُ : لَا يَمُوتَنَّ أَحَدُكُمْ إِلَّا وَهُوَ يُحْسِنُ الظَّنَّ بِاللَّهِ عَزَّ وَجَلَّ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20441;
update hadith set arabic = 'عَنْ أَنَسِ ، رَضِيَ اللَّهُ عَنْهُ قَالَ:" سَمِعْتُ رَسُولَ اللهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "قَالَ اللَّهُ تَعَالَى: يَا ابْنَ آدَمَ، إِنَّكَ مَا دَعَوْتَنِي وَرَجَوْتَنِي غَفَرْتُ لَكَ عَلَى مَا كَانَ مِنْكَ وَلاَ أُبَالِي، يَا أبْنَ آدَمَ، لَوْ بَلَغَتْ ذُنُوبُكَ عَنَانَ السَّمَاءِ، ثُمَّ اسْتَغْفَرْتَنِي غَفَرْتُ لَكَ ، يَا ابْنَ آدَمَ، إِنَّكَ لَوْ أَتَيْتَنِى بِقُرَابِ الأَرْضِ خَطَايَا، ثُمَّ لَقِيتَنِي لاَ تُشْرِكُ بِهِ شَيْئًا، لَأَتَيْتُكَ بِقُرَابِهَا مَغْفِرَةً".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5456 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20442;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ« لَوْ يَعْلَمُ المُؤْمِنُ مَا عِنْدَ اللَّهِ مِنَ العُقُوبَةِ، مَا طَمِعَ بِجَنَّتِهِ أَحَدٌ، وَلَوْ يَعْلَمُ الكَافِرُ مَا عِنْدَ اللَّهِ مِنَ الرَّحْمَةِ، مَا قَنَطَ مِنْ جَنَّتِهِ أَحَدٌ».', updated_at = now() where id = 20443;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ الخُدْرِيَّ، رَضِيَ اللَّهُ عَنْهُ ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِذَا وُضِعَتِ الجِنَازَةُ وَاحْتَمَلَهَا النَّاسُ أَوِ الرِّجَالُ عَلَى أَعْنَاقِهِمْ، فَإِنْ كَانَتْ صَالِحَةً قَالَتْ: فَدِّمُونِي قَدِّمُونِي، وَإِنْ كَانَتْ غَيْرَ صَالِحَةٍ، قَالَتْ يَا وَيْلَهَا! أَيْنَ تَذْهَبُونَ بِهَا؟ يَسْمَعُ صَوْتَهُ كُلُّ شَئٍ إِلَّا الإِنْسَانَ، وَلَوْ سَمِعَهُ صَعِقَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20444;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، «الْجَنَّةُ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ شِرَاكِ نَعْلِهِ، وَالنَّارُ مِثْلُ ذَلِكَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3581 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20445;
update hadith set arabic = 'عَنْ ابْنِ مَسْعُودٍ، رَضيَ اللهُ عنهُ ، قَالَ: قَالَ لِي النَّبِيُّ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، "اقْرَأْ عَلَيَّ القُرْآنَ" قُلْتُ: يَا رَسُولَ اللَّهِ أَقْرَأُ عَلَيْكَ وَعَلَيْكَ أُنْزِلَ ؟! قَالَ:"إِنِّى أُحِبُّ أَنْ أَسْمَعَهُ مِنْ غَيْرِي" فَقَرَأْتُ عَلَيْهِ سُورَةَ النِّسَاءِ، حَتَّى جِئْتُ إِلَى هَذِهِ الآيَةِ (فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاَءِ شَهِيدًا}.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3571 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20446;
update hadith set arabic = 'عَنْ أَنَسٍ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: خَطَبَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، خُطْبَةً مَا سَمِعْتُ مِثْلَهَا قَطُّ، فَقَالَ: «لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلاً وَلَبَكَيْتُمْ كَثِيراً» قَالَ : فَغَطَّي أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وُجُوهَهُمْ، وَلَهُمْ خَنِينٌ ، ((مُتَّفَقٌ عَلَيْهِ)) ، وَسَبَقَ بَيَانٌ فِي بَابِ الخَوْفِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20447;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَا يَلِجُ النَّارَ رَجُلٌ بَكَى مِنْ خَشْيَةِ اللَّهِ حَتَّى يَعُودَ اللَّبَنُ فِي الضَّرْعِ، وَلَا يَجْتَمِعُ غُبَارٌ فِي سَبِيلِ اللَّهِ وَدُخَانُ جَهَنَّمَ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3778 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20448;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهُ ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ:«سَبْعَةٌ يُظِلُّهُمُ اللَّهُ فِي ظِلِّهِ يَوْمَ لاَ ظِلَّ إِلَّا ظِلُّهُ: إِمَامٌ عَادِلٌ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ اللَّهِ ، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِي المَسَاجِدِ، وَرَجُلاَنِ تَحَابَّا فِي اللَّهِ، اجْتَمَعَا عَلَيْهِ، وَتَفَرَّقَا عَلَيْهِ، وَرَجُلٌ دَعَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ، فَقَالَ: إِنِّى أَخَافُ اللَّهَ، وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفَاهَا حَتَّى لاَ تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ، وَرَجُلٌ ذَكَرَ اللَّهَ خَالِيًا فَفَاضَتْ عَيْنَاهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66234 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20449;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ يُصَلِّي وَلِجَوْفِهِ أَزِيزٌ كَأَزِيرِ المِرْجَلِ مِنَ البُكَاءِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20450;
update hadith set arabic = 'عَنْ أَنَسٍ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لِأُبَيِّ بْنِ كَعْبٍ، رَضِيَ اللَّهُ عَنْهُ : "إِنَّ اللَّهَ عَزَّ وَجَلَّ أَمَرَنِي أَنْ أَقْرَأَ عَلَيْكَ: لَمْ يَكُنِ الَّذِينَ كَفَرُو" قَالَ: وَسَمَّانِي؟ قَالَ: "نَعَمْ" فَبَكَى أُبَيٌّ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3601 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20451;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ أَبُو بَكْرٍ لِعُمَرَ، رَضِيَ اللَّهُ عَنْهُمَا، بَعْدَ وَفَاةِ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: انْطَلِقْ بِنَا إِلَى أُمِّ أَيْمَنَ ، رَضِيَ اللَّهُ عَنْهَا، نَزُورُهَا كَمَا كَانَ يَزُورُهَا ، فَلَمَّا انْتَهَيْنَا إِلَيْهَا بَكَتْ، فَقَالاَ: مَا يُبْكِيكِ؟ أَمَا تَعْلَمِينَ أَنَّ مَا عِنْدَ اللَّهِ تَعَالَى خَيْرٌ لِرَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: إِنِّى لَا أَبْكِي ، أَنِّي لَا أَعْلَمُ أَنَّ مَا عِنْدَ اللَّهِ خَيْرٌ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَلَكِنِّى أَبْكِي أَنَّ الوَحْيَ قَدْ انْقَطَعَ مِنَ السَّمَاءِ، فَهَيَجَتْهُمَا عَلَى البُكَاءِ، فَجَعَلاَ يَبْكِيَانِ مَعَهَا.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20452;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: لَمَّا اشْتَدَّ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَجَعُهُ، قِيلَ لَهُ فِي الصَّلَاةِ، فَقَالَ: مُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ بِالنَّاسِ" فَقَالَتْ عَائِشَةُ، رَضِيَ اللَّهُ عَنْهَا : إِنَّ أَبَا بَكْرٍ رَجُلٌ رَقِيقٌ، إِذَا قَرَأَ القُرْآنَ غَلَبَهُ البُكَاءُ، فَقَالَ : "مُرُوهُ فَلْيُصَلِّ". وَفِي رِوَايَةٍ عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا، قَالَتْ: قُلْتُ: إِنَّ أَبَا بَكْرٍ إِذَا قَامَ مَقَامَكَ لَمْ يُسْمِعِ النَّاسَ مِنَ البُكَاءِ.', updated_at = now() where id = 20453;
update hadith set arabic = 'عَنْ إِبْرَاهِيمَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ أَنَّ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ، رَضِيَ اللَّهُ عَنْهُ ، أُتِيَ بِطَعَامٍ وَكَانَ صَائِمًا، فَقَالَ: قُتِلَ مُصْعَبُ بْنُ عُمَيْرٍ رَضِيَ اللَّهُ عَنْهُ، وَهُوَ خَيْرٌ مِنِّي، فَلَمْ يُوجَدْ لَهُ مَا يُكَفَّنُ بِهِ إِلَّا بُرْدَةٌ إِنْ غُطِّيَ بِهَا رَأْسُهُ بَدَتْ رِجْلَاهُ، وَإِنْ غُطِّيَ بِهَا رِجْلَاهُ بَدَا رَأْسُهُ، ثُمَّ بُسِطَ لَنَا مِنَ الدُّنْيَا مَا بُسِطَ -أَوْ قَالَ: أُعْطِينَا مِنَ الدُّنْيَا مَا أُعْطِينَا -قَدْ خَشِينَا أَنْ تَكُونَ حَسَنَاتُنَا عُجِّلَتْ لَنَا. ثُمَّ جَعَلَ يَبْكِي حَتَّى تَرَكَ الطَّعَامَ.', updated_at = now() where id = 20454;
update hadith set arabic = 'عَنْ أَبِي أُمَامَةَ صُدَيِّ بْنِ عَجْلَانَ البَاهِلِيِّ، رَضِيَ اللَّهُ عَنْهُ ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «لَيْسَ شَئٌ أَحَبَّ إِلَى اللَّهِ تَعَالَى مِنْ قَطْرَتَيْنِ وَأَثَرَيْنِ: قَطْرَةُ دُمُوعٍ مِنْ خَشْيَةِ اللَّهِ، وَقَطْرَةُ دَمٍ تُهَرَاقُ فِي سَبِيلِ اللَّهِ، وَأَمَّا الأَثَرَانِ: فَأَثَرٌ فِي سَبِيلِ اللَّهِ تَعَالَى، وَأَثَرٌ فِي فَرِيضَةٍ مِنْ فَرَائِضِ اللَّهِ تَعَالَى» ((رَوَاهُ التِّرْمِذِيُّ.وَقَالَ حَدِيثٌ حَسَنٌ)). حَدِيثُ العِرْبَاضِ بْنِ سَارِيَةَ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ: وَعَظَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَوْعِظَةً وَجِلَتْ مِنْهَا القُلُوبُ، وَذَرَفَتْ مِنْهَا العُيُونُ', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20455;
update hadith set arabic = 'عَنْ عَمْرِو بْنِ عَوْفٍ الأَنْصَارِيِّ، رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بَعَثَ أَبَا عُبَيْدَةَ بْنَ الجَرَّاحِ، رَضِيَ اللَّهُ عَنْهُ ، إِلَى البَحْرَيْنِ يَأْتِي بِجِزْيَتِهَا، فَقدِمَ بِمَالٍ مِنَ البَحْرَيْنِ ، فَسَمِعَتِ الأَنْصَارُ بِقُدُومِ أَبُو عُبَيْدَةَ، فَوَافَوْا صَلَاةَ الفَجْرِ مَعَ رَسُولِ اللَّهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، انْصَرَفَ فَتَعَرَّضُوا لَهُ ، فتَبَسَّمَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ رَآهُمْ، ثُمَّ قَالَ: "أَظُنُّكُمْ سَمِعتُمْ أَنَّ أَبَا عُبَيْدَةَ قَدِمَ بِشَئٍ مِنَ البَحْرَيْنِ؟" فَقَالُوا: أَجَلْ يَا رَسُولَ اللَّهِ فَقَالَ: "أَبْشِرُوا وَأَمِّلُوا مَا يَسُرُّكُمْ ، فَوَاللَّهِ مَا الفَقرَ أَخْشَى عَلَيْكُمْ، وَلَكِنِّي أَخَشى أَنْ تُبْسَطَ الدُّنْيَا عَلَيْكُمْ كَمَا بُسِطَتْ عَلَى مَنْ كَانَ قَبْلَكُمْ، فَتَنَافَسُوهَا كَمَا تَنَافَسُوهَا ، فَتُهْلِكَكُمْ كَمَا أَهْلَكَتْهُمْ".', updated_at = now() where id = 20456;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ : جَلَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَلَى المِنْبَرِ، وَجَلَسْنَا حَوْلَهُ، فَقَالَ: «إِنَّ مِمَّا أَخَافُ عَلَيْكُمْ مِنْ بَعْدِي مَا يُفْتَحُ عَلَيْكُمْ مِنْ زَهْرَةِ الدُّنْيَا وَزِينَتِهَا».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20457;
update hadith set arabic = 'وَعَنْهُ أَنَّ رَسُولَ اللَّهِ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: «إِنَّ الدُّنْيَا حُلْوَةٌ خَضِرَةٌ وَإِنَّ اللهَ تَعَالَى مُسْتَخْلِفُكُمْ فِيهَا، فَيَنْظُرُ كَيْفَ تَعْمَلُونَ، فَاتَّقُوا الدُّنْيَا وَاتَّقُوا النِّسَاءَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20458;
update hadith set arabic = 'عَنْ أَنَسٍ ، رَضِيَ اللَّهُ عَنْهُ، أَنَّ النَّبِيَّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ:«اللَّهُمَّ لَا عَيْشَ إِلَّا عَيْشُ الآخِرَةِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20459;
update hadith set arabic = 'وَعَنْهُ عَنْ رَسُولِ اللَّهِ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «يَتْبَعُ المَيِّتَ ثَلَاثَةٌ: أَهْلُهُ وَمَالُهُ وَعَمَلُهُ: فَيَرْجِعُ اثْنَانِ وَيَبْقَى وَاحِدٌ: يَرْجِعُ أَهْلُهُ وَمَالُهُ وَيَبْقَى عَمَلُهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4240 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20460;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «يُؤتَى بِأَنْعَمِ أَهْلِ الدُّنْيَا مِنْ أَهْلِ النَّارِ يَوْمَ القِيَامَةِ، فَيُصْبَغُ فِي النَّارِ صَبْغَةً، ثُمَّ يُقَالُ: يَا ابْنَ آدَمَ هَلْ رَأَيْتَ خَيْرًا قَطُّ؟ هَلْ مَرَّ بِكَ نَعِيمٌ قَطُّ؟ فَيَقُولُ: لَا وَاللَّهِ يَا رَبِّ. وَيُؤْتَى بِأَشَدِّ النَّاسِ بُؤْسًا فِي الدُّنْيَا مِنْ أَهْلِ الجَنَّةِ، فَيُصْبَغُ صَبْغَةً فِي الجَنَّةِ، فَيُقَالُ لَهُ: يَا ابْنَ آدَمَ هَلْ رَأَيْتَ بُؤْسًا قَطُّ؟ هَلْ مَرَّبِكَ شِدَّةٌ قَطُّ؟ فَيَقُولُ: لَا، وَاللَّهِ، مَا مَرَّ بِى بُؤْسٌ قَطٌّ، وَلَا رَأَيْتُ شِدَّةً قَطُّ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4248 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20461;
update hadith set arabic = 'عَنِ المُسْتَوْرِدِ بْنِ شَدَّادٍ رَضِيَ اللَّهُ عَنْهُ ، قَالَ: قَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:«مَا الدُّنْيَا فِي الآخِرَةِ، إِلَّا مِثْلُ مَا يَجْعَلُ أَحَدُكُمْ أُصْبُعَهُ فِي اليَمِّ، فَلْيَنْظُرْ بِمَ يَرْجِعُ؟».', updated_at = now() where id = 20462;
update hadith set arabic = 'عَنْ جَابِرٍ، رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَرَّ بِالسُّوقِ وَالنَّاسُ كَنَفَتَيَهِ، فَمَرَّ بِجَدْىٍ أَسَكَّ مَيِّتٍ، فَتَنَاوَلَهُ، فَأَخَذَ بِأُذُنَيْهِ، ثُمَّ قَالَ: "أَيُّكُمْ يُحِبُّ أَنْ يَكُونَ هَذَا لَهُ بِدِرْهَمٍ؟ " فَقَالُوا: مَا نُحِبُّ أَنَّهُ لَنَا بِشَئٍ وَمَانَصْنَعُ بِهِ؟ ثُمَّ قَالَ: "أَتُحِبُّونَ أَنَّهُ لَكُمْ؟ قَالُوا: وَاللَّهِ لَوْ كَانَ حَيًّا ًكَانَ عَيْباً؛ أَنَّهُ أَسَكُّ. فَكَيْفَ وَهُوَ مَيِّتٌ _! فَقَالَ: "فَوَاللَّهِ لَلدُّنْيَا أَهْوَنُ عَلَى اللَّهِ مِنْ هَذَا عَلَيْكُمْ" ((رَوَاهُ مُسْلِمٌ)). (''قَوْلُهُ: كَنَفَتَيْهِ أَيْ: عَلَى جَانِبَيْهِ. وَ الأَسَكُّ الصَّغِيرُ الأُذُنِ.'')', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4178 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20463;
update hadith set arabic = 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ ، قَالَ كُنْتُ أَمْشَى مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَرَّةٍ بِالمَدِينَةِ ، فَاسْتَقْبَلَنَا أُحُدٌ فَقَالَ: "يَا أَبَا ذَرٍّ" قُلْتُ: لَبَّيْكَ يَا رَسُولَ اللَّهِ. فَقَالَ: "مَا يَسُرُّنِي أَنَّ عِنْدِي مِثْلَ أُحُدٍ هَذَا ذَهَبًا تَمْضِى عَلَيَّ ثَلَاثَةُ أَيَّامٍ وَعِنْدِي مِنْهُ دِينَارٌ، إِلَّا شَئٌ أَرْصُدُهُ لِدَيْنٍ، إِلَّا أَنْ أَقُولَ لَهُ بِهِ فِي عِبَادِ اللَّهِ هَكَذَا، وَهَكَذَا وَهَكَذَا" عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ وَمِنْ خَلْفِهِ، ثُمَّ سَارَ فَقَالَ: "إِنَّ الأَكْثَرِينَ هُمُ الأَقَلُّونَ يَوْمَ القِيَامَةِ إِلَّا مَنْ قَالَ بِالمَالِ هَكَذَا وَهَكَذَا وَهَكَذَا" عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ وَمِنْ خَلفِهِ" وَقَلِيلٌ مَا هُمْ" ثُمَّ قَالَ لِى "مَكَانَكَ لَا تَبْرَحْ حَتَّى آتِيَكَ" ثُمَّ انْطَلَقَ فِي سَوَادِ اللَّيْلِ حَتَّى تَوَارَى، فَسَمِعْتُ صَوْتًا قَدِ ارْتَفَعَ ، فَتَخَوَّفْتُ أَنْ يَكُونَ أَحَدٌ عَرَضَ لِلنَّبِى، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَرَدْتُ أَنْ آتِيَهُ فَذَكَرْتُ قَوْلَهُ: "لَا تَبْرَحْ حَتَّى آتِيَكَ" فَلَمْ أَبْرَحْ حَتَّى أَتَانِى، فَقُلْتُ : لَقَدْ سَمِعْتُ صَوْتًا تَخَوَّفْتُ مِنْهُ، فَذَكَرْتُ لَهُ، فَقَالَ: "وَهَلْ سَمِعْتَهُ؟" قُلْتُ: نَعَمْ، قَالَ: "ذَاكَ جِبْرِيلُ أَتَانِى فَقَالَ: مَنْ مَاتَ مِنْ أُمَّتِكَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الجَنَّةَ، قُلْتُ: وَإِنْ زَنَى وَإِنْ سَرَقَ؟ قَالَ: وَإِنْ زَنَى وَإِنْ سَرَقَ".', updated_at = now() where id = 20464;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «لَوْ كَانَ لِي مِثْلُ أُحُدٍ ذَهَبًا، لَسَرَّنِى أَنْ لَا تَمُرَّ عَلَيَّ ثَلَاثُ لَيَالٍ وَعِنْدِي مِنْهُ شَئٌ إِلَّا شَئٌ أرْصُدُهُ لِدَيْنٍ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3850 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20465;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ انْظُرُوا إِلَى مَنْ هُوَ أَسْفَلَ مِنْكُمْ وَلَا تَنْظُرُوا إِلَى مَنْ هُوَ فَوْقَكُمْ فَهُوَ أَجْدَرُ أَنْ لَا تَزْدَرُوا نِعْمَةَ اللهِ عَلَيْكُمْ" ((مُتَّفَقٌ عَلَيْهِ وَهَذَا لَفْظُ مُسْلِمٍ)). وَفِي رِوَايَةِ البُخَارِيِّ: "إِذَا نَظَرَ أَحَدُكُمْ إِلَى مَنْ فُضِّلَ عَلَيْهِ فِي المَالِ وَالخَلْقِ، فَلْيَنْظُرْ إِلَى مَنْ هُوَ أَسْفَلَ مِنْهُ". وَفِي رِوَايَةِ البُخَارِيِّ: "إِذَا نَظَرَ أَحَدُكُمْ إِلَى مَنْ فُضِّلَ عَلَيْهِ فِي المَالِ وَالخَلْقِ، فَلْيَنْظُرْ إِلَى مَنْ هُوَ أَسْفَلَ مِنْهُ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20466;
update hadith set arabic = 'وَعَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: «تَعِسَ عَبْدُ الدِّينَارِ وَالدِّرْهَمِ وَالقَطِيفَةِ وَالخَمِيصَةِ؛ إِنْ أُعْطِيَ رَضِيَ؛ وَإِنْ لَمْ يُعْطَ لَمْ يَرْضَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20467;
update hadith set arabic = 'وَعَنْهُ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: لَقَدْ رَأَيْتُ سَبْعِينَ مِنْ أَهْلِ الصُّفَّةِ، مَا مِنْهُمْ رَجُلٌ عَلَيْهِ رِدَاءٌ، إِمَّا إِزَارٌ وَأَمَّا كِسَاءٌ، قَدْ رَبَطُوا فِي أَعْنَاقِهِمْ، فَمِنْهَا مَا يَبْلُغُ نِصْفَ السَّاقَيْنِ، وَمِنْهَا مَا يَبْلُغُ الكَعْبَيْنِ، فَيَجْمَعُهُ بِيَدِهِ كَرَاهِيَةَ أَنْ تُرَى عَوْرَتُهُ".', updated_at = now() where id = 20468;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «الدُّنْيَا سِجْنُ المُؤْمِنِ وَجَنَّةُ الكَافِرِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20469;
update hadith set arabic = 'عَنْ ابْنِ عُمَرَ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: أَخَذَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمَنْكِبِي، فَقَالَ: «كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ، أَوْ عَابِرُ سَبِيلٍ». وَكَانَ ابْنُ عُمَرَ، رَضِيَ اللَّهُ عَنْهُمَا، يَقُولُ: إِذَا أَمْسَيْتَ، فَلاَ تَنْتَظِرِ الصَّبَاحَ، وَإِذَا أَصْبَحْتَ لا تَنْتَظِرِ المَسَاءَ، وَخُذْ مِنْ صِحَّتِكَ لِمَرَضِكَ وَمِنْ حَيَاتِكَ لِمَوْتِكَ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4704 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20470;
update hadith set arabic = 'عَنْ أَبِي العَبَّاسِ سَهْلِ بْنِ سَعِدٍ السَّاعِدِى، رَضِيَ اللَّهُ عَنْهُ، قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ دُلَّنِي عَلَى عَمَلٍ إِذَا عَمِلْتُهُ أَحَبَّنِي اللَّهُ، وَاحَبَّنِي النَّاسُ، فَقَالَ: «ازْهَدْ فِي الدُّنْيَا يُحِبَّكَ اللَّهُ، وَازْهَدْ فِيمَا عِنْدَ النَّاسِ يُحِبَّكَ النَّاسُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4307 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20471;
update hadith set arabic = 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: ذَكَرَ عُمَرُ ابْنُ الخَطَّابِ، رَضِيَ اللَّهُ عَنْهُ، مَا أَصَابَ النَّاسُ مِنَ الدُّنْيَا، فَقَالَ: لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَظَلُّ اليَوْمَ يَتَلَوَّى مَا يَجِدُ مِنَ الدَّقَلِ مَا يَمْلَأُ بِهِ بَطْنَهُ. ((رَوَاهُ مُسْلِمٌ)). الدَّقَلُ بِفَتْحِ الدَّالِ المُهْمَلَةِ وَالقَافِ: رَدِئُ التَّمْرِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20472;
update hadith set arabic = 'عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا، قَالَتْ: تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَا فِي بَيْتِي مِنْ شَئٍ يَأكُلُهُ ذُو كَبِدٍ إِلَّا شَطْرُ شَعِيرٍ فِي رَفٍّ لِي، فَاكَلْتُ مِنْهُ حَتَّى طَالَ عَلَيَّ، فَكِلْتُهُ فَفَنِىَ، ((مُتَّفَقٌ عَلَيْهِ)) شَطْرُ شَعِيرٍ" شَئٌ مِنْ شَعِيرٍ، كَذَا فَسَّرَهُ التِّرْمِذِيُّ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4239 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20473;
update hadith set arabic = 'عَنْ عَمْرِو بْنِ الحَارِثِ أَخِي الجُوَيْرِيَةِ بِنْتِ الحَارِثِ أُمِّ المُؤْمِنِينَ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: مَا تَرَكَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عِنْدَ مَوْتِهِ دِينَاراً وَلَا دِرْهَماً، وَلَا عَبْداً، وَلَا امَةً، وَلَا شَيْئًا إِلَّا بَغْلَتَهُ البَيْضَاءَ الَّتِى كَانَ يَرْكَبُهَا، وَسِلَاحَهُ، وَأَرْضًا جَعَلَهَا لِابْنِ السَّبِيلِ صَدَقَةً".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20474;
update hadith set arabic = 'عَنْ خَبَّابِ بْنِ الأَرَتِّ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: هَاجَرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَلْتَمِسُ وَجْهَ اللَّهِ تَعَالَى؛ فَوَقَعَ أَجْرُنَا عَلَى اللَّهِ، فَمِنَّا مَنْ مَاتَ وَلَمْ يَأْكُلْ مِنْ أَجْرِهِ شَيْئًا، مِنْهُمْ مُصْعَبُ بْنُ عُمَيْرٍ، رَضِيَ اللَّهُ عَنْهُ، قُتِلَ يَوْمَ أُحُدٍ، وَتَرَكَ نَمِرَةً، فَكُنَّا إِذَا غَطَّيْنَا بِهَا رَأْسَهُ، بَدَتْ رِجْلَاهُ، وَإِذَا غَطَّيْنَا بِهِ رِجْلَيْهِ، بَدَا رَأْسُهُ، فَأَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نُغَطِّىَ رَأْسَهُ، وَنَجْعَلَ عَلَى رِجْلَيْهِ شَيْئاً مِنَ الإِذْخِرِ، وَمِنَّا مَنْ أَيْنَعَتْ لَهُ ثَمَرَتُهُ، فَهُوَ يَهْدِيهَا. ((مُتَّفَقٌ عَلَيْهِ)). النَّمِرَةُ : كِسَاءٌ مُلَوَّنٌ مِنْ صُوفٍ. وَقَوْلُهُ: أَيْنَعَتْ أَيْ: نَضِجَتْ وَأَدْرَكَتْ. وَقَوْلُهُ يَهْدِيهَا وَهُوَ بِفَتْحِ اليَاءِ وَضَمِّ الدَّالِ وَكَسْرِهَا، لُغَتَانِ؛ أَيْ: يَقْطِفُهَا وَيَجْتَنِيهَا، وَهَذِهِ اسْتِعَارَةٌ لِمَا فَتَحَ اللَّهُ تَعَالَى عَلَيْهِمْ مِنَ الدُّنْيَا وَتَمَكَّنُوا فِيهَا.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20475;
update hadith set arabic = 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِى، ـرَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّه، صَلّى اللهُ عَلَيْهِ وسَلَّم : « لَوْ كَانَتِ الدُّنْيَا تَعْدِلُ عِنْدَ اللَّهِ جَنَاحَ بَعُوضَةٍ مَا سَقَى كَافِراً مِنْهَا شَرْبَةَ مَاءٍ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3695 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20476;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضيَ اللهُ عنهُ ، قَالَ : سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ أَلاَ إِنَّ الدُّنْيَا مَلْعُونَةٌ، مَلْعُونٌ مَا فِيهَا، إِلاَّ ذِكْرُ اللهِ تَعَالَى، وَمَا وَالاَهُ، وَعَالِماً وَمُتَعَلِّماً".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20477;
update hadith set arabic = 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ ، رَضِيَ اللَّهُ عَنْهُ ، قَالَ : قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ « لاَ تَتَّخِذُوا الضَّيْعَةَ فَتَرْغَبُوا فِي الدُّنْيَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66169 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20478;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: مَرَّ عَلَيْنَا رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَنَحْنُ نُعَالِجُ خُصًّا لَنَا فَقَالَ: " مَا هَذَا؟" فَقُلْنَا: قَدْ وَهَى، فَنَحْنُ نُصْلِحُهُ، فَقَالَ: " مَا أَرَى الأَمْرَ إِلَّا أَعْجَلَ مِنْ ذَلِكَ". رَوَاهُ أَبُو دَاوُدَ، وَالتِّرْمِذِيُّ بِإِسْنَادِ البُخَارِيِّ وَمُسْلِمٍ، وَقَالَ التِّرْمِذِيُّ:.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4205 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20479;
update hadith set arabic = 'عَنْ كَعْبِ بْنِ عِيَاضٍ، رَضِيَ اللَّهُ عَنْهُ، وَقَالَ سَمِعْتُ رَسُولَ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، يَقُولُ: « إِنَّ لِكُلِّ أُمَّةٍ فِتْنَةً، وَفِتْنَةُ أُمَّتِى المَالُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3736 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20480;
update hadith set arabic = 'عَنْ أَبِي عَمْرٍو، وَيُقَالُ: أَبُو عَبْدِ اللَّهِ: وَيُقَالُ: أَبُو لَيْلَى، عُثْمَانَ ابْنِ عَفَّانَ، رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: « لَيْسَ لِابْنِ آدَمَ حَقٌّ فِي سِوَى هَذِهِ الخِصَالِ: بَيْتٌ يَسْكُنُهُ، وَثَوْبٌ يُوَارِي عَوْرَتَهُ، وَجِلْفُ الخُبْزِ، وَالمَاءُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20481;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ " بِسكْرِ الشِّينِ وَالخَاءِ المُشَدَّدَةِ المُعْجَمَتَيْنِ" رَضِيَ اللَّهُ عَنْهُ، أَنَّهُ قَالَ: أَتَيْتُ النَّبِيَّ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ يَقْرَأُ: { أَلْهَاكُمُ التَّكَاثُرُ} قَالَ: " يَقُولُ ابْنُ آدَمَ: مَالِي، وَهَلْ لَكَ يَا ابْنَ آدَمَ مِنْ مَالِكَ إِلَّا مَا أَكَلْتَ فَأَفْنَيْتَ، أَوْ لَبِسْتَ فَأَبْلَيْتَ، أَوْ تَصَدَّقْتَ فَأَمْضَيْتَ؟ !".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20482;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَجُلٌ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَارَسُولَ اللَّهِ، وَاللَّهِ إِنِّى لَأُحِبُّكَ، فَقَالَ: " انْظُرْ مَاذْ تَقُولُ؟" قَالَ: وَاللَّهِ إِنِّى لَأُحِبُّكَ، ثَلَاثَ مَرَّاتٍ، فَقَالَ: " إِنْ كُنْتَ تُحِبُّنِى فَأَعِدَّ لِلْفَقْرِ تِجْفَافاً، فَإِنَّ الفَقْرَ أَسْرَعُ إِلَى مَنْ يُحِبُّنِى مِنَ السَّيْلِ إِلَى مُنْتَهَاهُ" ((رَوَاهُ التِّرْمِذِيُّ وَقَالَ حَدِيثٌ حَسَنٌ)). ''التِّجْفَافُ بِكَسْرِ التَّاءِ المُثَنَّاهِ فَوْقُ وَإِسْكَانِ الجِيمِ وَبِالفَاءِ المُكَرَّرَةِ، وَهُوَ شَىْءٌ يَلْبَسُةُ الفَرَسُ، لِيَتَّقِيَ بِهِ الأَذَى، وَقَدْ يَلْبَسُةُ الإِنْسَانُ.''', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20483;
update hadith set arabic = 'عَنْ كَعْبِ بْنِ مَالِكٍ، رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « مَا ذِئْبَانِ جَائِعَانِ أُرْسِلَا فِي غَنَمٍ بِأَفْسَدَ لَهَا مِنْ حِرْصِ المَرْءِ عَلَى المَالِ وَالشَّرَفِ، لِدِينِهِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20484;
update hadith set arabic = 'عَنْ عَبْدِ اللهِ بنِ مَسْعُودٍ، رَضيَ اللهُ عنهُ، قَالَ: نَامَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَلَى حَصِيرٍ، فَقَالَ وَقَدْ أَثَّرَ فِي جَنْبِهِ. قُلْنَا: يَا رَسُولَ اللهِ لَوِ اتَّخَذْنَا لَكَ وِطَاءً! فَقَالَ: « مَالِي وَلِلدُّنْيَا؟ مَا أَنَا فِي الدُّنْيَا إِلاَّ كَرَاكِبٍ اسْتَظَلَّ تَحْتَ شَجَرَةٍ ثُمَّ رَاحَ وَتَرَكَهَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65814 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20485;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « يَدْخُلُ الفُقَرَاءُ الجَنَّةَ قَبْلَ الأَغْنِيَاءِ بِخَمْسِمِائَةِ عَامٍ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20486;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ، وَعِمْرَانَ بْنِ الحُصَيْنِ، رَضِيَ اللَّهُ عَنْهُمْ، عَنِ النَّبِيِّ ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ " قَالَ " اطَّلَعْتُ فِي الجَنَّةِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا الفُقَرَاءَ، وَاطَّلَعْتُ فِي النَّارِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا النِّسَاءَ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3184 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20487;
update hadith set arabic = 'عَنْ أُسَامَةَ بْنِ زَيْدٍ، رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «قُمْتُ عَلَى بَابِ الجَنَّةِ، فَكَانَ عَامَّةَ مَنْ دَخَلَهَا المَسَاكِينُ. وَأَصْحَابُ الجَدِّ مَحْبُوسُونَ، غَيْرَ أَنَّ أَصْحَابَ النَّارِ قَدْ أُمِرَ بِهِمْ إِلَى النَّارِ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20488;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: «أَصْدَقُ كَلِمَةٍ قَالَهَا شَاعِرٌ كَلِمَةُ لَبِيدٍ: أَلَا كُلُّ شَئٍ مَا خَلَا اللَّهَ بَاطِلُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20489;
update hadith set arabic = 'عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا ، قَالَتْ: مَا شَبِعَ آلُ مُحَمَّدٍ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، مِنْ خُبْزِ شَعِيرٍ يَوْمَيْنِ مُتَتَابِعَيْنِ حَتَّى قُبِضَ. ((مُتَّفَقٌ عَلَيْهِ)). وَفِي رِوَايَةٍ: مَا شَبِعَ آلُ مُحَمَّدٍ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ، مُنْذُ قَدِمَ المَدِينَةَ مِنْ طَعَامِ البُرِّ ثَلاَثَ لَيَالٍ تِبَاعًا حَتَّى قُبِضَ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65816 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20490;
update hadith set arabic = 'عَنْ عُرْوَةَ عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا، أَنَّهَا كَانَتْ تَقُولُ: وَاللَّهِ يَا ابْنَ اخْتِي إِنْ كُنَّا لَنَنْظُرُ إِلَى الهِلَالِ، ثُمَّ الهِلَالِ: ثَلَاثَةَ أَهِلَّةٍ فِي شَهْرَيْنِ، وَمَا أُوقِدَ فِي أَبْيَاتِ رَسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، نَارٌ. قُلْتُ: يَا خَالَةُ فَمَا كَانَ يُعِيشُكُمْ؟ قَالَتْ: الأَسْوَدَانِ: التَّمْرُ وَالمَاءُ، إِلَّا أَنَّهُ قَدْ كَانَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جِيرَانٌ مِنَ الأَنْصَارِ، وَكَانَتْ لَهُمْ مَنَائِحُ وَكَانُوا يُرْسِلُونَ إِلَى رَسُولِ اللَّهِ مِنْ أَلْبَانِهَا فَيَسْقِينَا.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20491;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ المَقْبُرِيِّ عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، أَنَّهُ مَرَّ بِقَوْمٍ بَيْنَ أَيْدِيهِمْ شَاةٌ مَصْلِيَّةٌ، فَدَعَوْهُ فَأَبَي أَنْ يَأْكُلَ، وَقَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الدُّنْيَا وَلَمْ يَشْبَعْ مِنْ خُبْزِ الشَّعِيرِ. ((رَوَاهُ البُخَارِيُّ)). ''مَصْلِيَّةٌ'' بِفَتْحِ المِيمِ: أَيْ: مَشْوِيَّةٌ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20492;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ، قَالَ: لَمْ يَأْكُلِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى خِوَانٍ حَتَّى مَاتَ، وَمَا أَكَلَ خُبْزاً مُرَقَّقاً حَتَّى مَاتَ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20493;
update hadith set arabic = 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عنهما قَالَ: لَقَدْ رَأَيْتُ نَبِيَّكُمْ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ، وَمَا يَجِدُ مِنَ الدَّقَلِ مَا يَمْلَأُ بِهِ بَطْنَهُ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20494;
update hadith set arabic = 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ، قَالَ: مَا رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّقِيَّ مِنْ حِينَ ابْتَعَثَةُ اللَّهُ تَعَالَى حَتَّى قَبَضَهُ اللَّهُ تَعَالَى، فَقِيلَ لَهُ: هَلْ كَانَ لَكُمْ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنَاخِلَ؟ قَالَ: مَا رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُنْخُلًا مِنْ حِينَ ابْتَعَثَهُ اللَّهُ تَعَالَى حَتَّى قَبَضَهُ اللَّهُ تَعَالَى، فَقِيلَ لَهُ: كَيْفَ كُنْتُمْ تَأْكُلُونَ الشَّعِيرَ غَيْرَ مَنْخُولٍ؟ قَالَ: كُنَّا نَطْحَنُهُ وَنَنْفُخُهُ، فَيَطِيرُ مَا طَارَ، وَمَا بَقِىَ ثَرَّيْنَاهُ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20495;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ أَوْ لَيْلَةٍ، فَإِذَا هُوَ بِأَبِي بَكْرٍ وَعُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، فَقَالَ: " مَا أَخْرَجَكُمَا مِنْ بُيُوتِكُمَا هَذِهِ السَّاعَةَ؟" قَالَا: الْجُوعُ يَا رَسُولَ اللهِ. قَالَ: " وَأَنَا، وَالَّذِي نَفْسِي بِيَدِهِ، لَأَخْرَجَنِي الَّذِي أَخْرَجَكُمَا. قُومَا" فَقَامَا مَعَهُ، فَأَتَى رَجُلًا مِنَ الْأَنْصَارِ، فَإِذَا هُوَ لَيْسَ فِي بَيْتِهِ، فَلَمَّا رَأَتْهُ الْمَرْأَةُ قَالَتْ: مَرْحَبًا وَأَهْلًا، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "أَيْنَ فُلَانٌ؟" قَالَتْ ذَهَبَ يَسْتَعْذِبُ لَنَا الْمَاءِ، إِذْ جَاءَ الْأَنْصَارِيُّ، فَنَظَرَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَصَاحِبَيْهِ، ثُمَّ قَالَ: الْحَمْدُ اللَّهِ، مَا أَحَدٌ الْيَوْمَ أَكْرَمَ أَضْيَافًا مِنِّي. فَانْطَلَقَ فَجَاءَهُمْ بِعِذْقٍ فِيهِ بُسْرٌ وَتَمْرٌ وَرُطَبٌ، فَقَالَ: كُلُوا وَأَخَذَ الْمُدْيَةَ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ " إِيَّاكَ وَالْحَلُوبَ" فَذَبَحَ لَهُمْ فَأَكَلُوا مِنَ الشَّاةِ وَمِنْ ذَلِكَ الْعِذْقِ وَشَرِبُوا فَلَمَّا أَنْ شَبِعُوا وَرَوُوا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِأَبِي بَكْرٍ وَعُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: " وَالَّذِي نَفْسِي بِيَدِهِ، لَتُسْأَلُنَّ عَنْ هَذَا النَّعِيمِ يَوْمَ الْقِيَامَةِ، أَخْرَجَكُمْ مِنْ بُيُوتِكُمُ الْجُوعُ، ثُمَّ لَمْ تَرْجِعُوا حَتَّى أَصَابَكُمْ هَذَا النَّعِيمُ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66018 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20496;
update hadith set arabic = 'عَنْ خَالِدِ بْنِ عُمَرَ العَدَوِيِّ قَالَ: خَطَبَنَا عُتْبَةُ بْنُ غَزْوَانَ، وَكَانَ أَمِيرٌ عَلَى البَصْرَةِ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: أَمَّا بَعْدُ؛ فَإِنَّ الدُّنْيَا قَدْ آذَنَتْ بِصُرْمٍ، وَوَلَّتْ حَذَّاءَ، وَلَمْ يَبْقَ مِنْهَا إِلَّا صُبَابَةٌ كَصُبَابَةِ الإِنَاءِ يَتَصَابُّهَا صَاحِبُهَا، وَإِنَّكُمْ مُنْتَقِلُونَ مِنْهَا إِلَى دَارٍ لَا زَوَالَ لَهَا، فَانْتَقِلُوا بِخَيْرِ مَا بِحَضْرَتِكُمْ، فَإِنَّهُ قَدْ ذُكِرَ لَنَا أَنَّ الحَجَرَ يُلْقَى مِنْ شَفِيرِ جَنَهُمْ فَيَهْوِي فِيهَا سَبْعِينَ عَاماً، لَا يُدْرِكُ لَهَا قَعْراً، وَاللَّهِ لَتُمْلَأَنَّ ...أَفَعَجِبْتُمْ!؟ وَلَقَدْ ذُكِرَ لَنَا أَنَّ مَا بَيْنَ مِصْرَاعَيْنِ مِنْ مَصَارِيعِ الجَنَّةِ مَسِيرَةُ أَرْبَعِينَ عَاماً، وَلَيَأْتِيَنَّ عَلَيْهِ يَوْمٌ وَهُوَ كَظِيظٌ مِنَ الزِّحَامِ، وَلَقَدْ رَأَيْتُنِي سَابِعَ سَبْعَةٍ مَعَ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا لَنَا طَعَامٌ إِلَّا وَرَقُ الشَّجَرِ، حَتَّى قَرِحَتْ أَشْدَاقُنَا، فَالْتَقَطْتُ بُرْدَةً فَشَقَقْتُهَا بَيْنِي وَبَيْنَ سَعْدِ بْنِ مَالِكٍ، فَاتَّزَرْتُ بِنِصْفِهَا، وَاتَّزَرَ سَعْدٌ بِنِصْفِهَا، فَمَا أَصْبَحَ اليَوْمَ مِنَّا أَحَدٌ إِلَّا أَصْبَحَ أَمِيراً عَلَى مِصْرٍ مِنَ الأَمْصَارِ، وَإِنِّي أَعُوذُ بِاللَّهِ أَنْ أَكُونَ فِي نَفْسِي عَظِيماً، وَعِنْدَ اللَّهِ صَغِيراً. ((رَوَاهُ مُسْلِمٌ)). قَوْلُهُ: آذَنَتْ هُوَ بِمَدِّ الأَلِفِ، أَيْ: أَعْلَمَتْ. وَقَوْلُهُ: بِصُرْمٍ : هُوَ بِضَمِّ الصَّادِ، أَيْ بِانْقِطَاعِهَا وَفَنَائِهَا. وَقَوْلُهُ وَوَلَّتْ حَذَّاءَ هُوَ بِحَاءٍ مُهْمَلَةٍ مَفْتُوحَةٍ، ثُمَّ ذَالٍ مُعْجَمَةٍ مُشَدَّدَةٍ، ثُمَّ أَلِفٍ مَمْدُودَةٍ، أَيْ: سَرِيعَةً. وَ الصُّبَابَةُ بِضَمِّ الصَّادِ المُهْمَلَةِ: وَهِيَ البَقِيَّةُ اليَسِيرَةُ. وَقَوْلُهُ: يَتَصَابُّهَا هُوَ بِتَشْدِيدِ البَاءِ قَبْلَ الهَاءِ، أَيْ: يَجْمَعُهَا. وَ الكَظِيظُ : الكَثِيرُ المُمْتَلِيءُ. وَقَوْلُهُ: قَرِحَتْ هُوَ بِفَتْحِ القَافِ وَكَسْرِ الرَّاءِ، أَيْ: صَارَتْ فِيهَا قُرُوحٌ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20497;
update hadith set arabic = 'عَنْ أَبِي مُوسَى الأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَخْرَجَتْ لَنَا عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا كِسَاءً وَإِزَاراً غَلِيظاً قَالَتْ: قُبِضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذَيْنِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20498;
update hadith set arabic = 'عَنْ سَعِيدِ بْنِ أَبِي وَقَّاصٍ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: إِنِّي لَأَوَّلُ العَرَبِ رَمَي بِسَهْمٍ فِي سَبِيلِ اللَّهِ، وَلَقَدْ كُنَّا نَغْزُو مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا لَنَا طَعَامٌ إِلَّا وَرَقُ الحُلْبَةِ، هَذَا السَّمُرُ، حَتَّى إِنْ كَانَ أَحَدُنَا لَيَضَعُ كَمَا تَضَعُ الشَّاةُ مَا لَهُ خِلْطٌ. ((مُتَّفَقٌ عَلَيْهِ)). « الحُلْبَةُ» بِضَمِّ الحَاءِ المُهْمَلَةِ وَإِسْكَانِ البَاءِ المُوَحَّدَةِ: وَهِيَ وَالسَّمُرُ، نَوْعَانِ مَعْرُوفَانِ مِنْ شَجَرِ البَادِيَةِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20499;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : " اللَّهُمَّ اجْعَلْ رِزْقَ آلِ مُحَمَّدٍ قُوتاً" ((مُتَّفَقٌ عَلَيْهِ)). قَالَ أَهْلُ اللُّغَةِ وَالغَرِيبِ: مَعْنَى " قُوتاً" أَيْ: مَا يَسُدُّ الرَّمَقَ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20500;
update hadith set arabic = 'عَنْ أَبي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: وَاللَّهِ الَّذِي لاَ إِلَهَ إِلَّا هُوَ، إِنْ كُنْتُ لَأَعْتَمِدُ بِكَبِدِي عَلَى الأَرْضِ مِنَ الجُوعِ، وَإِنْ كُنْتُ لَأَشُدُّ الحَجَرَ عَلَى بَطْنِي مِنَ الجُوعِ. وَلَقَدْ قَعَدْتُ يَوْمًا عَلَى طَرِيقِهِمُ الَّذِي يَخْرُجُونَ مِنْهُ، فَمَرَّ بِي النَّبِيُّ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ، فَتَبَسَّمَ حِينَ رَآنِي، وَعَرَفَ مَا فِي وَجْهِي وَمَا فِي نَفْسِي، ثُمَّ قَالَ: " أَبَا هِرٍّ" قُلْتُ لَبَّيْكَ يَا رَسُولَ اللَّهِ، قَالَ: " الْحَقْ" وَمَضَى فَاتَّبَعْتُهُ، فَدَخَلَ فَاسْتَأْذَنَ، فَأُذِنَ لِي فَدَخَلْتُ، فَوَجَدَ لَبَنًا فِي قَدَحٍ فَقَالَ: " مِنْ أَيْنَ هَذَا اللَّبَنُ؟" قَالُوا: أَهْدَاهُ لَكَ فُلاَنٌ- أَوْ فُلاَنَةُ- قَالَ:" أَبَا هِرٍّ" قُلْتُ: لَبَّيْكَ يارَسُولَ اللَّهِ، قَالَ: " الْحَقْ إِلَى أَهْلِ الصُّفَّةِ فَادْعُهُمْ لِي" قَالَ: وَأَهْلُ الصُّفَّةِ أَضْيَافُ الإِسْلَامِ، لَا يَأْوُونَ عَلَى أَهْلٍ، وَلَا مَالٍ، وَإِذَا أَتَتْهُ هَدِيَّةٌ أَرْسَلَ إِلَيْهِمْ، وَأَصَابَ مِنْهَا وَأَشْرَكَهُمْ فِيهَا، فَسَاءَنِي ذَلِكَ فَقُلْتُ: وَمَا هَذَا اللَّبَنُ فِي أَهْلِ الصُّفَّةِ! كُنْتُ أَحَقُّ أَنْ أُصِيبَ مِنْ هَذَا اللَّبَنِ شَرْبَةً أَتَقَوَّى بِهَا، فَإِذَا جَأُووا وَأَمَرَنِي فَكُنْتُ أَنَا أُعْطِيهِمْ؛ وَمَا عَسَى أَنْ يَبْلُغَنِي مِنْ هَذَا اللَّبَنِ، وَلَمْ يَكُنْ مِنْ طَاعَةِ اللَّهِ وَطَاعَةِ رَسُولِهِ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بُدٌّ، فَأَتَيْتُهُمْ فَدَعَوْتُهُمْ، فَأَقْبَلُوا وَاسْتَأْذَنُوا، فَأَذِنَ لَهُمْ وَأَخَذُوا مَجَالِسَهُمْ مِنَ البَيْتِ قَالَ:" يَا أَبَا هِرٍّ" قُلْتُ: لَبَّيْكَ يَا رَسُولَ اللَّهِ قَالَ: " خُذْ فَأَعْطِهِمْ" قَالَ: فَأَخَذْتُ القَدَحَ، فَجَعَلْتُ أُعْطِيهِ الرَّجُلَ فَيَشْرَبُ حَتَّى يَرْوَى، ثُمَّ يَرُدُّ عَلَيَّ القَدَحَ، فَأُعْطِيهِ الآخَرَ فَيَشْرَبُ حَتَّى يَرْوَى، ثُمَّ يَرُدُّ عَلَيَّ القَدَحَ حَتَّى انْتَيَهْتُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ، وَقَدْ رَوِيَ القَوْمُ كُلُّهُمْ، فَأَخَذَ القَدَحَ فَوَضَعَهُ عَلَى يَدِهِ، فَنَظَرَ إِلَيَّ فَتَبَسَّمَ، فَقَالَ: " أَبَا هِرٍّ" قُلْتُ: لَبَّيْكَ يَا رَسُولَ اللَّهِ، قَالَ: " بَقِيتُ أَنَا وَأَنْتَ" قُلْتُ: صَدَقْتَ يَا رَسُولَ اللَّهِ، قَالَ: " اقْعُدْ فَاشْرَبْ" فَقَعَدْتُ فَشَرِبْتُ: فَقَالَ: " اشْرَبْ" فَشَرِبْتُ، فَمَا زَالَ يَقُولُ: " اشْرَبْ" حَتَّى قُلْتُ: لَا وَالَّذِي بَعَثَكَ بِالحَقِّ مَا أَجِدُ لَهُ مَسْلَكًا! قَالَ: " فَأَرِنِي" فَأَعْطَيْتُهُ القَدَحَ، فَحَمِدَ اللَّهَ تَعَالَى، وَسَمَّى وَشَرِبَ الفَضْلَةَ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66349 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20501;
update hadith set arabic = 'عَنْ مُحَمَّدِ بْنِ سِيرِينَ عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: لَقَدْ رَأَيْتُنِي وَإِنِّي لَأُجَرُّ فِيمَا بَيْنَ مِنْبَرِ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِلَى حُجْرَةِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا مَغْشِيّاً عَلَيَّ، فَيَجِيءُ الجَائِي، فَيَضَعُ رِجْلَةُ عَلَى عُنُقِي، وَيُرَى أَنِّي مَجْنُونٌ وَمَا بِي مِنْ جُنُونٍ، مَا بِي إِلَّا الجُوعُ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20502;
update hadith set arabic = 'عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ: تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَدِرْعُهُ مَرْهُونَةٌ عِنْدَ يَهُودِيٍّ فِي ثَلَاثِينَ صَاعًا مِنْ شَعِيرٍ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66139 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20503;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَهَنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دِرْعَهُ بِشَعِيرٍ، وَمَشَيْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِخُبْزِ شَعِيرٍ، وَإِهَالَةٍ سَنِخَةٍ، وَلَقَدْ سَمِعْتُهُ يَقُولُ: « مَا أَصْبَحَ لِآلِ مُحَمَّدٍ صَاعٌ وَلَا أَمْسَى» وَإِنَّهُمْ لَتِسْعَةُ أَبْيَاتٍ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20504;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: لَقَدْ رَأَيْتُ سَبْعِينَ مِنْ أَهْلِ الصُّفَّةِ، مَا مِنْهُمْ رَجُلٌ عَلَيْهِ رِدَاءٌ، إِمَّا إِزَارٌ وَإِمَّا كِسَاءٌ، قَدْ رَبَطُوا فِي أَعْنَاقِهِمْ مِنْهَا مَا يَبْلُغُ نِصْفَ السَّاقَيْنِ، وَمِنْهَا مَا يَبْلُغُ الكَعْبَيْنِ، فَيَجْمَعُهُ بِيَدِهِ كَرَاهِيَةَ أَنْ تُرَى عَوْرَتُهُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3645 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20505;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ فِرَاشُ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ أَدَمٍ حَشْوُهُ لِيفٌ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20506;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا جُلُوساً مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، إِذْ جَاءَ رَجُلٌ مِنَ الأَنْصَارِ، فَسَلَّمَ عَلَيْهِ، ثُمَّ أَدْبَرَ الأَنْصَارِيُّ، فَقَالَ رَسُولُ اللَّهِ. صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : " يَا أَخَا الأَنْصَارِ؛ كَيْفَ أَخِي سَعْدُ بْنُ عُبَادَةَ؟" فَقَالَ: صَالِحٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "مَنْ يَعُودُهُ مِنْكُمْ؟" فَقَامَ وَقُمْنَا مَعَهُ، وَنَحْنُ بِضْعَةَ عَشَرَ، مَا عَلَيْنَا نِعَالٌ، وَلَا خِفَافٌ، وَلَا قَلَانِسُ، وَلَا قُمُصٌ، نَمْشِي فِي تِلْكَ السِّبَاخِ، حَتَّى جِئْنَاهُ، فَاسْتَأْخَرَ قَوْمُهُ مِنْ حَوْلِهِ حَتَّى دَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ الَّذِينَ مَعَهُ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20507;
update hadith set arabic = 'عَنْ عِمْرَانَ بْنِ الحُصَيْنِ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: " خَيْرُكُمْ قَرْنِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ" قَالَ عِمْرَانُ: فَمَا أَدْرِي قَالَ: النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّتَيْنِ أَوْ ثَلَاثاً " ثُمَّ يَكُونُ بَعْدَهُمْ قَوْمٌ يَشْهَدُونَ وَلَا يُسْتَشْهَدُونَ، وَيَخُونُونَ وَلَا يُؤْتَمَنُونَ، وَيَنْذِرُونَ وَلَا يُوفُونَ، وَيَظْهَرُ فِيهِمُ السِّمَنُ".', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20508;
update hadith set arabic = 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : « يَا ابْنَ آدَمَ: إِنَّكَ أَنْ تَبْذُلَ الفَضْلَ خَيْرٌ لَكَ، وَأَنْ تُمْسِكَهُ شَرٌّ لَكَ، وَلَا تُلَامُ عَلَى كَفَافٍ، وَابْدَأْ بِمَنْ تَعُولُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20509;
update hadith set arabic = 'عَنْ عُبَيْدِ اللَّهِ بْنِ مِحْصَنٍ الأَنْصَارِيِّ الخَطْمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: « مَنْ أَصْبَحَ مِنْكُمْ آمِنًا فِي سِرْبِهِ، مُعَافًى فِي جَسَدِهِ، عِنْدَهُ قُوتُ يَوْمِهِ، فَكَأَنَّمَا حِيزَتْ لَهُ الدُّنْيَا بِحَذَافِيرِهَا».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20510;
update hadith set arabic = '-وَعَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا ، أنَّ رَسولَ اللَّهِ صلَّى اللَّهُ عليْه وسلَّمَ قَالَ : « قَدْ أَفْلَحَ مَنْ أَسْلَمَ ، وَكَانَ رِزْقُهُ كَفَافًا ، وَقَنَّعَهُ اللَّهُ بِمَا آتَاهُ ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5814 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20511;
update hadith set arabic = '-وعَنْ أَبِي مُحَمَّدٍ فَضَالَهِ بْنِ عُبَيْدٍ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ ، أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ : «طُوبَى لِمَنْ هُدِيَ إِلَى الْإِسْلَامِ ، وَكَانَ عَيْشُهُ كَفَافًا ،وقَنِعَ ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66399 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20512;
update hadith set arabic = 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ : كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَبِيتُ اللَّيَالِيَ المُتَتَابِعَهْ طَاوِياً، وَأَهْلُهُ لَايَجِدُونَ عَشَاءً ، وَكَانَ أَكْثَرُ خُبْزِهِمْ خُبْزَ الشَّعِيرِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20513;
update hadith set arabic = 'عَنْ فَضَالَةَ بْنِ عُبَيْدٍ رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا صَلَّى بِالنَّاسِ، يَخِرُّ رِجَالٌ مِنْ قَامَتِهِمْ فِي الصَّلَاةِ مِنَ الخَصَاصَةِ -وَهُمْ أَصْحَابُ الصُّفَّةِ- حَتَّى يَقُولَ الأَعْرَابُ: هَؤُلَاءِ مَجَانِينُ، فَإِذَا صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ انْصَرَفَ إِلَيْهِمْ، فَقَالَ: "لَوْ تَعْلَمُونَ مَا لَكُمْ عِنْدَ اللَّهِ تَعَالَى، لَأَحْبَبْتُمْ أَنْ تَزْدَادُوا فَاقَةً وَحَاجَةً" ((رَوَاهُ التِّرْمِذِيُّ، وَقَالَ: حَدِيثٌ صَحِيحٌ)). "الخَصَاصَةُ": الفَاقَةُ وَالجُوعُ الشَّدِيدُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5825 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20514;
update hadith set arabic = 'عَنْ أَبِي كَرِيمَةَ المِقْدَامِ بْنِ مَعْدِيكَرِبَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ "مَا مَلأَ آدَمِيٌّ وِعَاءً شَرًّا مِنْ بَطْنٍ، بِحَسْبِ ابْنِ آدَمَ أَكَلاَتٌ يُقِمْنَ صُلْبَهُ، فَإِنْ كَانَ لَا مَحَالَةَ؛ فَتُلُثٌ لِطَعَامِهِ وَثُلُثٌ لِشَرَابِهِ، وَثُلُثٌ لِنَفَسِهِ". ((رَوَاهُ التِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ)). "أَكَلَاتٌ" أَيْ: لُقَمٌ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4723 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20515;
update hadith set arabic = 'عَنْ أَبِي أُمَامَةَ إِيَاسِ بْنِ ثَعْلَبَةَ الأَنْصَارِيِّ الحَارِثِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: ذَكَرَ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْماً عِنْدَهُ الدُّنْيَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "أَلَا تَسْمَعُونَ؟ أَلَا تَسْمَعُونَ؟ إِنَّ البَذَاذَةَ مِنَ الإِيمَانِ، إِنَّ البَذَاذَةَ مِنَ الإِيمَانِ" يَعْنِي: التَّقَحُّلَ. ((رَوَاهُ أَبُو دَاوُدَ)). "البَذَاذَةُ" بِالبَاءِ المُوَحَّدَةِ وَالذَّالَيْنِ المُعْجَمَتَيْنِ، وَهِيَ رَثَاثَةُ الهَيْئَةِ، وَتَرْكُ فَاخِرِ اللِّبَاسِ. وَأَمَّا "التَّقَحُّلُ" فَبِالقَافِ وَالحَاءِ، قَالَ أَهْلُ اللُّغَةِ: المُتَقَحِّلُ: هُوَ الرَّجُلُ اليَابِسُ الجِلْدِ مِنْ خُشُونَةِ العَيْشِ، وَتَرْكِ التَّرَفَةِ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5793 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20516;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ اللَّهِ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَعَثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَمَّرَ عَلَيْنَا أَبَا عُبَيْدَةَ رَضِيَ اللَّهُ عَنْهُ، نَتَلَقَّى عِيرًا لِقُرَيْشٍ، وَزَوَّدَنَا جِرَابًا مِنْ تَمْرٍ لَمْ يَجِدْ لَنَا غَيْرَهُ، فَكَانَ أَبُوعُبَيْدَةَ يُعْطِينَا تَمْرَةً تَمْرَةً، فَقِيلَ كَيْفَ كُنْتُمْ تَصْنَعُونَ بِهَا؟ قَالَ: نَمَصُّهَا كَمَا يَمَصُّ الصَّبِيُّ، ثُمَّ نَشْرَبُ عَلَيْهَا مِنَ المَاءِ، فَتَكْفِينَا يَوْمَنَا إِلَى اللَّيْلِ، وَكُنَّا نَضْرِبُ بِعِصِيِّنَا الْخَبَطَ، ثُمَّ نَبُلُّهُ بِالمَاءِ فَنَأْكُلُهُ. قَالَ: وَانْطَلَقْنَا عَلَى سَاحِلِ البَحْرِ، فَرُفِعَ لَنَا عَلَى سَاحِلِ البَحْرِ كَهَيْئَةِ الكَثِيبِ الضَّخْمِ، فَأَتَيْنَاهُ فَإِذَا هِيَ دَابَّةٌ تُدْعَى الْعَنْبَرَ، فَقَالَ أَبُو عُبَيْدَةَ: مَيْتَةٌ، ثُمَّ قَالَ: لَا، بَلْ نَحْنُ رُسُلُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِي سَبِيلِ اللَّهِ وَقَدِ اضْطُرِرْتُمْ فَكُلُوا، فَأَقَمْنَا عَلَيْهِ شَهْرًا، وَنَحْنُ ثَلَاثُمِائَةٍ، حَتَّى سَمِنَّا، وَلَقَدْ رَأَيْتُنَا نَغْتَرِفُ مِنْ وَقْبِ عَيْنِهِ بِالْقِلاَلِ الدُّهْنَ وَنَقْطَعُ مِنْهُ الْفِدَرَ كَالثَّوْرِ أَوْ كَقَدْرِ الثَّوْرِ، وَلَقَدْ أَخَذَ مِنَّا أَبُوعُبَيْدَةَ ثَلَاثَةَ عَشَرَ رَجُلاً فَأَقْعَدَهُمْ فِي وَقْبِ عَيْنِهِ وَأَخَذَ ضِلَعًا مِنْ أَضْلَاعِهِ فَأَقَامَهَا ثُمَّ رَحَلَ أَعْظَمَ بَعِيرٍ مَعَنَا فَمَرَّ مِنْ تَحْتِهَا وَتَزَوَّدْنَا مِنْ لَحْمِهِ وَشَائِقَ، فَلَمَّا قَدِمْنَا المَدِينَةَ أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْنَا ذَلِكَ لَهُ، فَقَالَ: "هُوَ رِزْقٌ أَخْرَجَهُ اللَّهُ لَكُمْ، فَهَلْ مَعَكُمْ مِنْ لَحْمِهِ شَئٌ فَتُطْعِمُونَا؟" فَأَرْسَلْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهُ فَأَكَلَهُ. ((رَوَاهُ مُسْلِمٌ)). "الجِرَابُ": وِعَاءٌ مِنْ جِلْدٍ مَعْرُوفٌ، وَهُوَ بِكَسْرِ الجِيمِ وَفَتْحِهَا، وَالكَسْرُ أَفْصَحُ. قَوْلُهُ: نَمَصُّهَا" بِفَتْحِ المِيمِ. "وَالخَبَطُ" وَرَقُ شَجَرٍ مَعْرُوفٌ تَأْكُلُهُ الإِبِلُ. "وَالكَثِيبُ": التَّلُّ مِنَ الرَّمْلِ. "وَالوَقْبُ" بِفَتْحِ الوَاوِ وَإِسْكَانِ القَافِ وَبَعْدَهَا بَاءٌ مُوَحَّدَةٌ، وَهُوَ نُقْرَةُ العَيْنِ. "بِتَخْفِيفِ الحَاءِ: أَيْ جَعَلَ عَلَيْهِ الرَّحْلَ. "الشَّائِقُ" بِالشِّينِ المُعْجَمَةِ وَالقَافِ: اللَّحْمُ الَّذِي اقْتُطِعَ لِيُقَدَّدَ مِنْهُ، وَاللَّهُ اعْلَمُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5856 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20517;
update hadith set arabic = 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ كُمُّ قَمِيصِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الرُّصْغِ، ((رَوَاهُ أَبُو دَاوُدَ، وَالتِّرْمِذِيُّ، وَقَالَ: حَدِيثٌ حَسَنٌ)). "الرُّصْغُ: بِالصَّادِ وَالرُّسْغُ بِالسِّينِ أَيْضاً: هُوَ المَفْصِلُ بَيْنَ الكَفِّ وَالسَّاعِدِ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20518;
update hadith set arabic = 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: إِنَّا كُنَّا يَوْمَ الخَنْدَقِ نَحْفِرُ، فعَرَضَتْ كُدْيَةٌ شَدِيدَةٌ، فَجَاؤُوا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: هَذِهِ كُدْيَةٌ عَرَضَتْ فِي الخَنْدَقِ. فَقَالَ: "أَنَا نَازِلٌ" ثُمَّ قَامَ، وَبَطْنُهُ مَعْصوبٌ بحَجَرٍ، وَلَبِثْنَا ثَلَاثَةَ أَيَّامٍ لَا نَذُوقُ ذَوْقاً فَأَخَذَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ المِعْوَلَ، فَضَرَبَ، فَعَادَ كَثِيبًا أَهْيَلَ، أَوْ أَهْيَمَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ ائْذَنْ لِي إِلَى البَيْتِ، فَقُلْتُ لِامْرَأَتِي: رَأَيْتُ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا مَا فِي ذَلِكَ صَبْرٌ فَعِنْدَكِ شَيْءٌ؟ فَقَالَتْ: عِنْدِي شَعِيرٌ وعَنَاقٌ، فَذَبَحْتُ العَنَاقَ وطَحَنَتِ الشَّعِيرَ حَتَّى جَعَلْنَا اللَّحْمَ فِي البُرْمَةِ، ثُمَّ جِئْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالعَجِينُ قَدِ انْكَسَرَ، وَالبُرْمَةُ بَيْنَ الأَثَاقِي قَدْ كَادَتْ تَنْضِجُ، فَقُلْتُ: طُعَيْمٌ لِي، فَقُمْ أَنْتَ يَا رَسُولَ اللَّهِ وَرَجُلٌ أَوْ رَجُلَانِ، قَالَ: "كَمْ هُوَ؟" فَذَكَرْتُ لَهُ فَقَالَ: "كَثِيرٌ طَيِّبٌ، قُلْ لَهَا لَا تَنْزِعِ البُرْمَةَ، وَلَا الخُبْزَ مِنَ التَّنُّورِ حَتَّى آتِيَ" فَقَالَ: "قُومُوا" فَقَامَ المُهَاجِرُونَ وَالأَنْصَارُ، فَدَخَلْتُ عَلَيْهَا فَقُلْتُ: وَيْحَكِ جَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالمُهَاجِرُونَ وَالأَنْصَارُ وَمَنْ مَعَهُمْ! قَالَتْ: هَلْ سَأَلَكَ؟ قُلْتُ: نَعَمْ، قَالَ: "ادْخُلُوا وَلَا تَضَاغَطُوا فَجَعَلَ يَكْسِرُ الخُبْزَ، وَيَجْعَلُ عَلَيْهِ اللَّحْمَ، وَيُخَمِّرُ البُرْمَةَ وَالتَّنُّورَ إِذَا أَخَذَ مِنْهُ، وَيُقَرِّبُ إِلَى أَصْحَابِهِ ثُمَّ يَنْزِعُ، فَلَمْ يَزَلْ يَكْسِرُ ويَغْرِفُ حَتَّى شَبِعُوا، وَبَقِيَ مِنْهُ، فَقَالَ: كُلِي هَذَا وأَهْدِي، فَإِنَّ النَّاسَ أَصَابَتْهُمْ مَجَاعَةٌ" ((مُتَّفَقٌ عَلَيْهِ)). وَفِي رِوَايَةٍ: قَالَ جَابِرٌ: لَمَّا حُفِرَ الخَنْدَقُ رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَمَصًا، فانْكَفَأْتُ إِلَى امْرَاتَى فَقُلْتُ: هَلْ عِنْدَكِ شَيْءٌ؛ فَإِنِّي رَأَيْتُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَمَصًا شَدِيدًا فَأَخْرَجَتْ إِلَيَّ جِرَابًا فِيهِ صَاعٌ مِنْ شَعِيرٍ، وَلَنَا بُهَيْمَةٌ دَاجِنٌ فَذَبَحْتُهَا، وَطَحَنَتِ الشَّعِيرَ، فَفَرَغَتْ إِلَى فَرَاغَى، وقَطَّعْتُهَا فِي بُرْمَتِهَا، ثُمَّ وَلَّيْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: لَا تَفْضَحْنِي بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَنْ مَعَهُ، فَجِئْتُهُ وَسَارَرْتُهُ فَقُلْتُ: يَا رَسُولَ اللَّهِ، ذَبَحْنَا بُهَيْمَةً لَنَا، وَطَحَنَتْ صَاعًا مِنْ شَعِيرٍ، فَتَعَالَ أَنْتَ وَنَفَرٌ مَعَكَ، فَصَاحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا أَهْلَ الخَنْدَقِ إِنَّ جَابِرًا قَدْ صَنَعَ سُؤْرًا فَحَيَّهَلا بِكُمْ" فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "لَا تُنْزِلُنَّ بُرْمَتَكُمْ وَلَا تَخْبِزَنَّ عَجِينَكُمْ حَتَّى أَجِيءَ" فَجِئْتُ، وَجَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْدُمُ النَّاسَ، حَتَّى جِئْتُ امْرَأَتِي فَقَالَتْ: بِكَ وَبِكَ! فَقُلْتُ: قَدْ فَعَلْتُ الَّذِي قُلْتِ. فَأَخْرَجَتْ عَجِينًا، فبَسَقَ فِيهِ وبَارَكَ، ثُمَّ عَمَدَ إِلَى بُرْمَتِنَا فبَصَقَ وبَارَكَ، ثُمَّ قَالَ: "ادْعِي خَابِزَةً فلْتَخْبِزْ مَعَكِ، وَاقْدَحِي مِنْ بُرْمَتِكُمْ وَلَا تُنْزِلُوهَا"وَهُمْ أَلْفٌ، فَأُقْسِمُ بِاللَّهِ لَأَكَلُوا حَتَّى تَرَكُوهُ وَانْحَرَفُوا، وَإِنَّ بُرْمَتَنَا لتَغِطُّ كَمَا هِيَ، وَإِنَّ عَجِينَنَا ليُخْبَزُ كَمَا هُوَ. قَوْلُهُ: "عَرَضَتْ كُدْيَةٌ" : بِضَمِّ الكَافِ وَإِسْكَانِ الدَّالِ وَبِالْيَاءِ المُثَنَّاةِ تَحْتُ؛ وَهِيَ قِطْعَةٌ غَلِيظَةٌ صُلْبَةٌ مِنَ الأَرْضِ لَا يَعْمَلُ فِيهَا الفَأْسُ. "وَالكَثِيبُ" أَصْلُهُ تَلُّ الرَّمْلِ، وَالمُرَادُ هُنَا: صَارَتْ تُرَاباً نَاعِماً، وَهُوَ مَعْنَى "أَهْيَلَ". "الأَثَافِي" : الأَحْجَارُ الَّتِى يَكُونُ عَلَيْهَا القِدْرُ. وَ"تَضَاغَطُوا" : تَزَاحَمُوا. وَ"المَجَاعَةُ" :الجُوعُ، وَهُوَ بِفَتْحِ المِيمِ. وَ"الخَمَصُ" بِفَتْحِ الخَاءِ المُعْجَمَةِ وَالمِيمِ: الجُوعُ. وَ"انْكَفَأْتُ" : انْقَلَبْتُ وَرَجَعْتُ. "البُهَيْمَةُ" بِضَمِّ البَاءِ: تَصْغِيرُ بَهْمَةٍ، وَهِيَ العَنَاقُ -بِفَتْحِ العَيْنِ-. وَ"الدَّاجِنُ": هِيَ الَّتِي أَلِفَتِ البَيْتَ. وَ"السُّؤْرُ" :الطَّعَامُ الَّذِي يُدْعَى النَّاسُ إِلَيْهِ، وَهُوَ بِالفَارِسِيَّةِ. وَ"حَيَّهَلَا" أَيْ: تَعَالَوْا. وَقَوْلُهَا: "بِكَ وَبِكَ" أَيْ: خَاصَمَتْهُ وَسَبَّتْهُ، لِأَنَّهَا اعْتَقَدَتْ أَنَّ الَّذِي عِنْدَهَا لَا يَكْفِيهِمْ، فَاسْتَحْيَتْ وَخَفِيَ عَلَيْهَا مَا أَكْرَمَ اللَّهُ سُبْحَانَهُ وَتَعَالَى بِهِ نَبِيَّهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ هَذِهِ المُعْجِزَةِ الظَّاهِرَةِ وَالآيَةِ ابَاهِرَةِ. "بَسَقَ" أَيْ :بَصَقَ؛ وَيُقَالُ أَيْضاً: بَزَقَ -ثَلَاثُ لُغَاتٍ- وَ"عَمَدَ" بِفَتْحِ المِيمِ: أَيْ قَصَدَ. وَ"اقْدَحِي" أَيِ اغْرِفِي؛ وَالمِقْدَحَةُ: المِغْرَفَةُ. وَ"تَغِطُّ" أَيْ: لِغَلَيَانِهَا صَوْتٌ، وَاللَّهُ اعْلَمُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5818 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20519;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ أَبُو طَلْحَةَ لِأُمِّ سُلَيْمٍ: قَدْ سَمِعْتُ صَوْتَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَعِيفًا أَعْرِفُ فِيهِ الجُوعَ، فَهَلْ عِنْدَكِ مِنْ شَيْءٍ؟ فَقَالَتْ: نَعَمْ، فَأَخْرَجَتْ أَقْرَاصًا مِنْ شَعِيرٍ، ثُمَّ أَخَذَتْ خِمَارًا لَهَا، فَلَفَّتِ الخُبْزَ بِبَعْضِهِ، ثُمَّ دَسَّتْهُ تَحْتَ ثَوْبِي وَرَدَّتْنِي بِبَعْضِهِ، ثُمَّ أَرْسَلَتْنِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَهَبْتُ بِهِ، فَوَجَدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا فِي المَسْجِدِ، وَمَعَهُ النَّاسُ، فَقُمْتُ عَلَيْهِمْ، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "أَرْسَلَكَ أَبُو طَلْحَةَ؟" فَقُلْتُ: نَعَمْ، فَقَالَ: "أَلِطَعَامٍ" فَقُلْتُ: نَعَمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قُومُوا" فَانْطَلَقُوا بَيْنَ أَيْدِيهِمْ حَتَّى جِئْتُ أَبَا طَلْحَةَ فَأَخْبَرْتُهُ، فَقَالَ أَبُو طَلْحَةَ: يَا أُمَّ سُلَيْمٍ: قَدْ جَاءَ رَسُولُ اللَّهِ بِالنَّاسِ وَلَيْسَ عِنْدَنَا مَا نُطْعِمُهُمْ؟ فَقَالَتْ: اللَّهُ وَرَسُولُهُ أَعْلَمُ. فَانْطَلَقَ أَبُو طَلْحَةَ حَتَّى لَقِيَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَقْبَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَهُ حَتَّى دَخَلَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلُمِّى مَا عِنْدَكِ يَا أُمَّ سُلَيْمٍ" فَأَتَتْ بِذَلِكَ الخُبْزِ، فَأَمَرَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَفُتَّ وَعَصَرَتْ عَلَيْهِ أُمُّ سُلَيْمٍ عُكَّةً فَآدَمَتْهُ، ثُمَّ قَالَ فِيهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا شَاءَ اللَّهُ أَنْ يَقُولَ، ثُمَّ قَالَ: "ائْذَنْ لِعَشَرَةٍ" فَأَذِنَ لَهُمْ، فَأَكَلُوا حَتَّى شَبِعُوا ثُمَّ خَرَجُوا، ثُمَّ قَالَ: "ائْذَنْ لِعَشَرَةٍ" فَأَذِنَ لَهُمْ، فَأَكَلُوا حَتَّى شَبِعُوا، ثُمَّ خَرَجُوا، ثُمَّ قَالَ: "ائْذَنْ لِعَشَرَةٍ" فَأَذِنَ لَهُمْ حَتَّى أَكَلَ القَوْمُ كُلُّهُمْ وَشَبِعُوا، وَالقَوْمُ سَبْعُونَ رَجُلًا أَوْ ثَمَانُونَ. ((مُتَّفَقٌ عَلَيْهِ)). وَفِي رِوَايَةٍ: فَمَا زَالَ يَدْخُلُ عَشَرَةٌ وَيَخْرُجُ عَشَرَةٌ، حَتَّى لَمْ يَبْقَ مِنْهُمْ أَحَدٌ إِلَّا دَخَلَ، فَأَكَلَ حَتَّى شَبِعَ، ثُمَّ هَيَّأَهَا فَإِذَا هِيَ مِثْلُهَا حِينَ اكَلُوا مِنْهَا. وَفِي رِوَايَةٍ: فَأَكَلُوا عَشَرَةً عَشَرَةً، حَتَّى فَعَلَ ذَلِكَ بِثَمَانِينَ رَجُلًا، ثُمَّ أَكَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ ذَلِكَ وَأَهْلُ البَيْتِ، وَتَرَكُوا سُؤْرًا. وَفِي رِوَايَةٍ: ثُمَّ أفْضَلُوا مَا بَلَغُوا جِيرَانَهُمْ. وَفِي رِوَايَةٍ عَنْ أَنَسٍ قَالَ: جِئْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا، فَوَجَدْتُهُ جَالِسًا مَعَ أَصْحَابِهِ، وَقَدْ عَصَبَ بَطْنَهُ بِعُصَابَةٍ، فَقُلْتُ لِبَعْضِ أَصْحَابِهِ: لِمَ عَصَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَطْنَهُ؟ فَقَالُوا: مِنَ الجُوعِ، فَذَهَبْتُ إِلَى أَبِي طَلْحَةَ، وَهُوَ زَوْجُ أُمِّ سُلَيْمٍ بِنْتِ مِلْحَانَ، فَقُلْتُ: يَا أَبَتَاهُ، قَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَصَبَ بَطْنَهُ بِعِصَابَةٍ، فَسَأَلْتُ بَعْضَ أَصْحَابِهِ، فَقَالُوا: مِنَ الجُوعِ. فَدَخَلَ أَبُو طَلْحَةَ عَلَى أُمِّي فَقَالَ: هَلْ مِنْ شَيْءٍ ؟ قَالَتْ: نَعَمْ عِنْدِي كِسَرٌ مِنْ خُبْزٍ وَتَمَرَاتٌ، فَإِنْ جَاءَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَحْدَهُ أَشْبَعْنَاهُ وَإِنْ جَاءَ آخَرُ مَعَهُ قَلَّ عَنْهُمْ، وَذَكَرَ تَمَامَ الحَدِيثِ.', updated_at = now() where id = 20520;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ الغِنَى عَنْ كَثْرَةِ العَرَضِ، وَلَكِنَّ الغِنَى غِنَى النَّفْسِ" ((مُتَّفَقٌ عَلَيْهِ)). "العَرَضُ" بِفَتْحِ العَيْنِ وَالرَّاءِ: هُوَ المَالُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3852 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20521;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو رَضِيَ اللَّهُ عَنْهُمَا أنَّ رَسولَ اللَّهِ صلَّى اللَّهُ عليْه وسلَّمَ قَالَ: «قَدْ أَفْلَحَ مَنْ أَسْلَمَ، وَرُزِقَ كَفَافًا، وَقَنَّعَهُ اللَّهُ بِمَا آتَاهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5814 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20522;
update hadith set arabic = 'عَنْ حَكِيمِ بْنِ حِزَامٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَعْطَانِي، ثُمَّ سَأَلْتُهُ فَأَعْطَانِي، ثُمَّ سَأَلْتُهُ فَأَعْطَانِي ثُمَّ قَالَ: "يَا حَكِيمُ، إِنَّ هَذَا المَالَ خَضِرٌ حُلْوٌ، فَمَنْ أَخَذَهُ بِسَخَاوَةِ نَفْسٍ بُورِكَ لَهُ فِيهِ، وَمَنْ أَخَذَهُ بِإِشْرَافِ نَفْسٍ لَمْ يُبَارَكْ لَهُ فِيهِ، وَكَانَ كَالَّذِي يَأْكُلُ وَلاَ يَشْبَعُ، وَاليَدُ العُلْيَا خَيْرٌ مِنَ اليَدِ السُّفْلَى" قَالَ حَكِيمٌ: فَقُلْتُ يَا رَسُولَ اللَّهِ وَالَّذِي بَعَثَكَ بِالحَقِّ لاَ أَرْزَأُ أَحَدًا بَعْدَكَ شَيْئًا حَتَّى أُفَارِقَ الدُّنْيَا. فَكَانَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ يَدْعُو حَكِيمًا لِيُعْطِيَهُ العَطَاءَ، فَيَأْبَى أَنْ يَقْبَلَ مِنْهُ شَيْئًا ثُمَّ إِنَّ عُمَرَ رَضِيَ اللَّهُ عَنْهُ دَعَاهُ لِيُعْطِيَهُ، فَأَبَى أَنْ يَقْبَلَهُ. فَقَالَ: يَا مَعْشَرَ المُسْلِمِينَ، أُشْهِدُكُمْ عَلَى حَكِيمٍ أَنِّي أَعْرِضُ عَلَيْهِ حَقَّهُ الَّذِي قَسَمَهُ اللَّهُ لَهُ فِي هَذَا الفَيْءِ فَيَأْبَى أَنْ يَأْخُذَهُ فَلَمْ يَرْزَأْ حَكِيمٌ أَحَدًا بَعْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى تُوُفِّيَ. ((مُتَّفَقٌ عَلَيْهِ)). "يَرْزَأُ" بِرَاءٍ ثُمَّ زَاىٍ ثُمَّ هَمْزَةٍ، أَيْ: لَمْ يَأْخُذْ مِنْ أَحَدٍ شَيْئاً، وَأَصْلُ الرُّزْءِ: النُّقْصَانُ، أَيْ: لَمْ يَنْقُصْ أَحَداً شَيْئاً بِالأَخْذِ مِنْهُ. وَ"إِشْرَافُ النَّفْسِ": تَطَلُّعُهَا وَطَمَعُهَا بِالشَّيْءِ. "سَخَاوَةُ النَّفْسِ": هِيَ عَدَمُ الإِشْرَافِ إِلَى الشَّيْءِ، وَالطَّمَعِ فِيهِ، وَالمُبَالَاةِ بِهِ وَالشَّرَهِ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3703 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20523;
update hadith set arabic = 'عَنْ أَبِي بُرْدَةَ عَنْ أَبِي مُوسَى الأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزَاةٍ، وَنَحْنُ سِتَّةُ نَفَرٍ بَيْنَنَا بَعِيرٌ نَعْتَقِبُهُ، فَنَقِبَتْ أَقْدَامُنَا وَنَقِبَتْ قَدَمِي، وَسَقَطَتْ أَظَافِرِي، فَكُنَّا نَلُفُّ عَلَى أَرْجُلِنَا الْخِرَقَ، فَسُمِّيَتْ غَزْوَةَ ذَاتُ الرِّقَاعِ لِمَا كُنَّا نَعْصِبُ عَلَى أَرْجُلِنَا مِنَ الخِرَقِ قَالَ أَبُو بُرْدَةَ: فَحَدَّثَ أَبُومُوسَى بِهَذَا الحَدِيثِ، ثُمَّ كَرِهَ ذَلِكَ، وَقَالَ: مَا كُنْتُ أَصْنَعُ بِأَنْ أَذْكُرَهُ! قَالَ: كَأَنَّهُ كَرِهَ أَنْ يَكُونَ شَئِياً مِنْ عَمَلِهِ أفْشَاهُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3704 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20524;
update hadith set arabic = 'عَنْ عَمْرُو بْنِ تَغْلِبَ - بِفَتْحِ التَّاءِ المُثَنَّاةِ فَوْقُ وَإِسْكَانِ الغَيْنِ المُعْجَمَةِ وَكَسْرِ اللَّامِ - رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِمَالٍ أَوْ سَبْيٍ فَقَسَّمَهُ، فَأَعْطَى رِجَالًا، وَتَرَكَ رِجَالًا، فبَلَغَهُ أَنَّ الَّذِينَ تَرَكَ عَتَبُوا ؛فَحَمِدَ اللَّهَ ثُمَّ أَثْنَى عَلَيْهِ ثُمَّ قَالَ، أَمَّا بَعْدُ فَوَاللَّهِ إِنِّي لَأُعْطِي الرَّجُلَ وَأَدَعُ الرَّجُلَ وَالَّذِي أَدَعُ أَحَبُّ إِلَيَّ مِنَ الَّذِي أُعْطِي، وَلَكِنِّي إِنَّمَا أُعْطِي أَقْوَامًا لِمَا أَرَى فِي قُلُوبِهِمْ مِنَ الجَزَعِ وَالهَلَعِ، وَأَكِلُ أَقْوَامًا إِلَى مَا جَعَلَ اللَّهُ فِي قُلُوبِهِمْ مِنَ الغِنَى وَالخَيْرِ، مِنْهُمْ عَمْرُو بْنُ تَغْلِبَ" قَالَ عَمْرُو بْنُ تَغْلِبَ: فَوَاللَّهِ مَا أُحِبُّ أَنَّ لِي بِكَلِمَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُمْرَ النَّعَمِ ((رَوَاهُ البُخَارِيُّ)). "الهَلَعُ": هُوَ أَشَدُّ الجَزَعِ، وَقِيلَ: الضَّجَرُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3729 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20525;
update hadith set arabic = 'عَنْ حَكِيمِ بْنِ حِزَامٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «اليَدُ العُلْيَا خَيْرٌ مِنَ اليَدِ السُّفْلَى، وَابْدَأْ بِمَنْ تَعُولُ، وَخَيْرُ الصَّدَقَةِ عَنْ ظَهْرِ غِنًى وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ، وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20526;
update hadith set arabic = 'عَنْ أَبِي سُفْيَانَ صَخْرِ بْنِ حَرْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَا تُلْحِفُوا فِي المَسْأَلَةِ، فَوَاللَّهِ لَا يَسْأَلُنِي أَحَدٌ مِنْكُمْ شَئِياً، فَتُخْرِجَ لَهُ مَسْأَلَتُهُ مِنِّي شَئاً وَأَنَا لَهُ كَارِهٌ، فيُبَارَكَ لَهُ فِيمَا أَعْطَيْتُهُ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3580 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20527;
update hadith set arabic = 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَوْفُ بْنُ مَالِكٍ الْأَشْجَعِيُّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تِسْعَةً أَوْ ثَمَانِيَةً أَوْ سَبْعَةً فَقَالَ: "أَلَا تُبَايِعُونَ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ" وَكُنَّا حَدِيثِي عَهْدٍ بِبَيْعَةٍ، فَقُلْنَا: قَدْ بَايَعْنَاكَ يَا رَسُولَ اللهِ، فَعَلَامَ نُبَايِعُكَ؟ قَالَ: "عَلَى أَنْ تَعْبُدُوا اللهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَالصَّلَوَاتِ الْخَمْسِ وَتُطِيعُوا" وَأَسَرَّ كَلِمَةً خَفِيَّةً: "وَلَا تَسْأَلُوا النَّاسَ شَيْئًا" فَلَقَدْ رَأَيْتُ بَعْضَ أُولَئِكَ النَّفَرِ يَسْقُطُ سَوْطُ أَحَدِهِمْ فَمَا يَسْأَلُ احَداً يُنَاوِلُهُ ايَّاهُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4176 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20528;
update hadith set arabic = 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَزَالُ المَسْأَلَةُ بِأَحَدِكُمْ حَتَّى يَلْقَى اللَّهَ تَعَالَى وَلَيْسَ فِي وَجْهِهِ مُزْعَةُ لَحْمٍ" ((مُتَّفَقٌ عَلَيْهِ)). "المُزْعَةُ" بِضَمِّ المِيمِ وَإِسْكَانِ الزَّاى وَبِالعَيْنِ المُهْمَلَةِ: القِطْعَةُ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20529;
update hadith set arabic = 'وَعَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ وَهُوَ عَلَى المِنْبَرِ، وَذَكَرَ الصَّدَقَةَ وَالتَّعَفُّفَ عَنِ المَسْأَلَةِ: «اليَدُ العُلْيَا خَيْرٌ مِنَ اليَدِ السُّفْلَى. وَاليَدُ العُلْيَا هِيَ المُنْفِقَةُ، وَالسُّفْلَى هِيَ السَّائِلَةُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20530;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «مَنْ سَأَلَ النَّاسَ تَكَثُّرًا فَإِنَّمَا يَسْأَلُ جَمْرًا؛ فَلْيَسْتَقِلَّ أَوْ لِيَسْتَكْثِرْ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65618 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20531;
update hadith set arabic = 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "إِنَّ المَسْأَلَةَ كَدٌّ يَكُدُّ بِهَا الرَّجُلُ وَجْهَهُ، إِلَّا أَنْ يَسْأَلَ الرَّجُلُ سُلْطَاناً أَوْ فِي أَمْرٍ لَا بُدَّ مِنْهُ" ((رَوَاهُ التِّرْمِذِيُّ، وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ)). "الكَدُّ" :الخَدْشُ وَنَحْوُهُ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20532;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَصَابَتْهُ فَاقَةٌ فَأَنْزَلَهَا بِالنَّاسِ لَمْ تُسَدَّ فَاقَتُهُ، وَمَنْ أَنْزَلَهَا بِاللَّهِ، فَيُوشِكُ اللَّهُ لَهُ بِرِزْقٍ عَاجِلٍ أَوْ آجِلٍ" ((رَوَاهُ أَبُو دَاوُدَ، وَالتِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ)) "يُوشِكُ" بِكَسْرِ الشِّينِ: أَيْ يُسْرِعُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4183 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20533;
update hadith set arabic = 'عَنْ ثَوْبَانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ تَكَفَّلَ لِي أَنْ لَا يَسْأَلَ النَّاسَ شَيْئًا، وَأَتَكَفَّلُ لَهُ الجَنَّةَ؟» فَقُلْتُ: أَنَا؛ فَكَانَ لَا يَسْأَلُ أَحَدًا شَيْئًا.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4189 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20534;
update hadith set arabic = 'عَنْ أَبِي بِشْرٍ قَبِيصَةَ بْنِ المُخَارِقِ رَضِيَ اللَّهُ عَنْهُ قَالَ: تَحَمَّلْتُ حَمَالَةً رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَسْأَلُهُ فِيهَا، فَقَالَ: "أَقِمْ حَتَّى تَأْتِيَنَا الصَّدَقَةُ فَنَأْمُرَ لَكَ بِهَا" ثُمَّ قَالَ: "يَا قَبِيصَةُ إِنَّ المَسْأَلَةَ لَا تَحِلُّ إِلَّا لِأَحَدِ ثَلَاثَةٍ: رَجُلٌ تَحَمَّلَ حَمَالَةً، فحَلَّتْ لَهُ المَسْأَلَةُ حَتَّى يُصِيبَهَا، ثُمَّ يُمْسِكُ. وَرَجُلٌ أَصَابَتْهُ جَائِحَةٌ اجْتَاحَتْ مَالَهُ، فَحَلَّتْ لَهُ المَسْأَلَةُ حَتَّى يُصِيبَ قَوْماً مِنْ عَيْشٍ، أَوْ قَالَ: سِدَادًا مِنْ عَيْشٍ، وَرَجُلٌ أَصَابَتْهُ فَاقَةٌ، حَتَّى يَقُولَ ثَلَاثَةٌ مِنْ ذَوِى الحِجَى مِنْ قَوْمِهِ: لَقَدْ أَصَابَتْ فُلَانًا فَاقَةٌ، فَحَمَلَتْ لَهُ المَسْأَلَةُ حَتَّى يُصِيبَ قِوَامًا مِنْ عَيْشٍ، أَوْ قَالَ: سِدَادًا مِنْ عَيْشٍ. فَمَا سِوَاهُنَّ مِنَ المَسْأَلَةِ يَا قَبِيصَةُ سُحْتٌ، يَأْكُلُهَا صَاحِبُهَا سُحْتًا" ((رَوَاهُ مُسْلِمٌ)). "الحَمَالَةُ" بِفَتْحِ الحَاءِ: أَنْ يَقَعَ قِتَالٌ وَنَحْوُهُ بَيْنَ فَرِيقَيْنِ، فَيُصْلِحَ إِنْسَانٌ بَيْنَهُمْ عَلَى مَالٍ يَتَحَمَّلُهُ وَيَلْتَزِمُهُ عَلَى نَفْسِهِ. وَ"الجَائِحَةُ" : الآفَةُ تُصِيبُ مَالَ الإِنْسَانِ. وَ"القِوَامُ" بِكَسْرِ القَافِ وَفَتْحِهَا: هُوَ مَا يَقُومُ بِهِ أَمْرُ الإِنْسَانِ مِنْ مَالٍ وَنَحْوِهِ. وَ"السِّدَادُ" بِكَسْرِ السِّينِ: مَا يَسُدُّ حَاجَةَ المُعْوِزِ وَيَكْفِيهِ، وَ"الفَاقَةُ" : الفَقْرُ. وَ"الحِجَى": العَقْلُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65619 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20535;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «لَيْسَ المِسْكِينُ الَّذِي يَطُوفُ عَلَى النَّاسِ تَرُدُّهُ اللُّقْمَةُ وَاللُّقْمَتَانِ، وَالتَّمْرَةُ وَالتَّمْرَتَانِ، وَلَكِنَّ المِسْكِينَ الَّذِي لَا يَجِدُ غِنًى يُغْنِيهِ، وَلَا يُفْطَنُ لَهُ، فَيُتَصَدَّقَ عَلَيْهِ، وَلَا يَقُومُ فَيَسْأَلَ النَّاسَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20536;
update hadith set arabic = 'عَنْ سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ، عَنْ أَبِيهِ عَبْدِ اللَّهِ بْنِ عُمَرَ، عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُمْ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعْطِينِي العَطَاءَ، فَأَقُولُ: أَعْطِهِ مَنْ هُوَ أَفْقَرُ إِلَيْهِ مِنِّي، فَقَالَ: «خُذْهُ؛ إِذَا جَاءَكَ مِنْ هَذَا المَالِ شَئٌ، وَأَنْتَ غَيْرُ مُشْرِفٍ وَلَا سَائِلٍ، فَخُذْهُ فَتَمَوَّلْهُ فَإِنْ شِئْتَ كُلْهُ، وَإِنْ شِئْتَ تَصَدَّقْ بِهِ، وَمَا لَا، فَلَا تُتْبِعْهُ نَفْسَكَ» قَالَ سَالِمٌ: فَكَانَ عَبْدُ اللَّهِ لَا يَسْأَلُ أَحَداً شَيْئاً، وَلَا يَرُدُّ شَيْئاً أُعْطِيَهُ.', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20537;
update hadith set arabic = 'عَنِ أَبِي عَبْدِ اللَّهِ الزُّبَيْرِ بْنِ العَوَّامِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : «لَأَنْ يَأْخُذَ أَحَدُكُمْ أَحْبُلَهُ ثُمَّ يَأْتَى الجَبَلَ فَيَأْتِيَ بِحُزْمَةٍ مِنْ حَطَبٍ عَلَى ظَهْرِهِ فَيَبِيعَهَا، فَيَكُفَّ اللَّهُ بِهَا وَجْهَهُ، خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ أَعْطَوْهُ أَوْمَنَعُوهُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20538;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «لَأَنْ يَحْتَطِبَ أَحَدُكُمْ حُزْمَةً عَلَى ظَهْرِهِ، خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ أَحَداً فَيُعْطِيَهُ أَوْ يَمْنَعَهُ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20539;
update hadith set arabic = 'وَعَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «كَانَ دَاوُدُ عَلَيْهِ السَّلَامُ لَا يَأْكُلُ إِلَّا مِنْ عَمَلِ يَدِهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3752 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20540;
update hadith set arabic = 'وَعَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «كَانَ زَكَرِيَّا عَلَيْهِ السَّلَامُ نَجَّاراً».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20541;
update hadith set arabic = 'عَنِ المِقْدَامِ بْنِ مَعْدِ يكَرِبَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « مَا أَكَلَ أَحَدٌ طَعَامًا قَطُّ خَيْرًا مِنْ أَنْ يَأْكُلَ مِنْ عَمَلِ يَدِهِ، وَإِنَّ نَبِىَّ اللَّهِ دَوَادَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَأْكُلُ مِنْ عَمَلِ يَدِهِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3752 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20542;
update hadith set arabic = 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «لَا حَسَدَ إِلَّا فى اثْنَتَيْنِ: رَجُلٌ آتَاهُ اللَّهُ مَالًا، فسَلَّطَهُ عَلَى هَلَكَتِهِ فى الحَقِّ، وَرَجُلٌ آتَاهُ اللَّهُ حِكْمَةً، فَهُوَ يَقْضِي بِهَا ويُعَلِّمُهَا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3772 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20543;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "أَيُّكُمْ مَالُ وَارِثِهِ أَحَبُّ إِلَيْهِ مِنْ مَالَهُ؟" قَالُوا: يَا رَسُولَ اللَّهِ، مَا مِنَّا أَحَدٌ إِلَّا مَالُهُ أَحَبُّ إِلَيْهِ. قَالَ: "فَإِنَّ مَالَهُ مَا قَدَّمَ وَمَالُ وَارِثِهِ مَا أَخَّرَ".', updated_at = now() where id = 20544;
update hadith set arabic = 'عَنْ عَدِىِّ بْنِ حَاتِمٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20545;
update hadith set arabic = 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا قَطُّ فَقَالَ: لَا.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3885 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20546;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : « مَا مِنْ يَوْمٍ يُصْبِحُ العِبَادُ فِيهِ إِلَّا مَلَكَانِ يَنْزِلاَنِ فَيَقُولُ أَحَدُهُمَا: اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا، وَيَقُولُ الآخَرُ: اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3379 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20547;
update hadith set arabic = 'وَعَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «قَالَ اللَّهُ تَعَالَى: انْفِقْ يَا ابْنَ آدَمَ يُنْفَقْ عَلَيْكَ».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20548;
update hadith set arabic = 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : أَى الإِسْلاَمِ خَيْرٌ؟ قَالَ: «تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلاَمَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5808 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20549;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «أَرْبَعُونَ خَصْلَةً أَعْلَاهَا مَنِيحَةُ العَنْزِ مَا مِنْ عَامِلٍ يَعْمَلُ بِخَصْلَةٍ مِنْهَا رَجَاءَ ثَوَابِهَا وَتَصْدِيقَ مَوْعُودِهَا إِلَّا أَدْخَلَهُ اللَّهُ تَعَالَى بِهَا الجَنَّةَ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3558 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20550;
update hadith set arabic = 'عَنْ أَبِي أُمَامَةَ صُدَىِّ بْنِ عَجْلَانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «يَا ابْنَ آدَمَ إِنَّكَ أَنْ تَبْذُلَ الفَضْلَ خَيْرٌ لَكَ، وَأَنْ تُمْسِكَهُ شَرٌّ لَكَ، وَلَا تُلَامُ عَلَى كَفَافٍ، وَابْدَأْ يَمَنْ تَعُولُ وَاليَدُ العُلْيَا خَيْرٌ مِنَ اليَدِ السُّفْلَى».', review_note = 'تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20551;
update hadith set arabic = 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الإِسْلَامِ شَيْئًا إِلَّا أَعْطَاهُ، وَلَقَدْ جَاءَهُ رَجُلٌ، فَأَعْطَاهُ غَنَمًا بَيْنَ جَبَلَيْنِ فَرَجَعَ إِلَى قَوْمِهِ فَقَالَ: يَا قَوْمِ أَسْلِمُوا، فَإِنَّ مُحَمَّدًا يُعْطِى مَنْ لَا يَخْشَى الفَقْرَ، وَإِنْ كَانَ الرَّجُلُ لَيُسْلِمُ مَا يُرِيدُ إِلَّا الدُّنْيَا، فَمَا يَلْبَثُ إِلَّا يَسِيرًا حَتَّى يَكُونَ الإِسْلَامُ أَحَبَّ إِلَيْهِ مِنَ الدُّنْيَا وَمَا عَلَيْهَا".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3885 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20552;
update hadith set arabic = 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَسَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَسْمًا، فَقُلْتُ: يَا رَسُولَ اللَّهِ لَغَيْرُ هَؤُلَاءِ كَانُوا أَحَقَّ بِهِ مِنْهُمْ؟ فَقَالَ: «إِنَّهُمْ خَيَّرُونِي أَنْ يَسْأَلُونِي بِالْفُحْشِ فَأُعْطِيَهُمْ، أَوْ يُبَخِّلُونِي، وَلَسْتُ بِبَاخِلٍ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5807 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20553;
update hadith set arabic = 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: بَيْنَمَا هُوَ يَسِيرُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَقْفَلَهُ مِنْ حُنَيْنٍ، فَعَلِقَهُ الأَعْرَابُ يَسْأَلُونَهُ، حَتَّى اضْطَرُّوهُ إِلَى سَمُرَةٍ، فَخَطِفَتْ رِدَاءَهُ، فَوَقَفَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَعْطُونِى رِدَائِى، فَلَوْ كَانَ لِى عَدَدُ هَذِهِ العِضَاةِ نَعَمًا، لَقَسَمْتُهُ بَيْنَكُمْ، ثُمَّ لَا تَجِدُونِى بَخِيلًا وَلَا كَذَّابًا وَلَا جَبَانًا.', updated_at = now() where id = 20554;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ، وَمَا زَادَ اللهُ عَبْدًا بِعَفْوٍ إِلَّا عِزًّا، وَمَا تَوَاضَعَ أَحَدٌ لِلهِ إِلَّا رَفَعَهُ اللهُ عَزَّ وَجَلَّ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5512 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20555;
update hadith set arabic = 'عَنْ أَبِي كَبْشَةَ عَمْرِو بْنِ سَعْدٍ الأَنْمَارِى رَضِيَ اللَّهُ عَنْهُ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «ثَلَاثَةٌ أُقْسِمُ عَلَيْهِنَّ وَأُحَدِّثُكُمْ حَدِيثاً فَاحْفَظُوهُ: مَا نَقَصَ مَالُ عَبْدٍ مِنْ صَدَقَةٍ،وَلَا ظُلِمَ عَبْدٌ مَظْلَمَةً صَبَرَ عَلَيْهَا إِلَّا زَادَهُ اللَّهُ عِزًّا، وَلَا فَتَحَ عَبْدٌ بَابَ مَسْأَلَةٍ إِلَّا فَتَحَ اللَّهُ عَلَيْهِ بَابَ فَقْرٍ، أَوْ كَلِمَةً نَحْوَهَا وَأُحَدِّثُكُمْ حَدِيثًا فَاحْفَظُوهُ قَالَ: إِنَّمَا الدُّنْيَا لِأَرْبَعَةِ نَفَرٍ: عَبْدٍ رَزَقَهُ اللَّهُ مَالاً وَعِلْمًا، فَهُوَ يَتَّقِى فِيهِ رَبَّهُ، وَيَصِلُ فِيهِ رَحِمَهُ، وَيَعْلَمُ لِلَّهِ فِيهِ حَقًّا فَهَذَا بِأَفْضَلِ المَنَازِلِ. وَعَبْدٍ رَزَقَهُ اللَّهُ عِلْمًا، وَلَمْ يَرْزُقْهُ مَالاً فَهُوَ صَادِقُ النِّيَّةِ يَقُولُ: لَوْ أَنَّ لِى مَالًا لَعَمِلْتُ بِعَمَلِ فُلَانٍ، فَهُوَ بِنِيَّتِهِ فَأَجْرُهُمَا سَوَاءٌ. وَعَبْدٍ رَزَقَهُ اللَّهُ مَالاً، وَلَمْ يَرْزُقْهُ عِلْمًا، فَهُوَ يَخْبِطُ فِى مَالِهِ بِغَيْرِ عِلْمٍ، لَا يَتَّقِى فِيهِ رَبَّهُ وَلَا يَصِلُ فِيهِ رَحِمَهُ، وَلَا يَعْلَمُ لِلَّهِ فِيهِ حَقًّا، فَهَذَا بِأَخْبَثِ المَنَازِلِ. وَعَبْدٍ لَمْ يَرْزُقْهُ اللَّهُ مَالاً وَلَا عِلْمًا، فَهُوَ يَقُولُ: لَوْ أَنَّ لِى مَالًا لَعَمِلْتُ فِيهِ بِعَمَلِ فُلَانٍ، فَهُوَ بِنِيَّتِهِ، فَوِزْرُهُمَا سَوَاءٌ».', updated_at = now() where id = 20556;
update hadith set arabic = 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهُمْ ذَبَحُوا شَاةً، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "مَا بَقِىَ مِنْهَا؟" قَالَتْ: مَا بَقِىَ مِنْهَا إِلَّا كَتِفُهَا، قَالَ: "بَقِىَ كُلُّهَا غَيْرَ كَتِفِهَا".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5810 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20557;
update hadith set arabic = 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ: قَالَ لِى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : «لَا تُوكِى فيُوكَى عَلَيْكِ».', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5823 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20558;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَثَلُ البَخِيلِ وَالمُنْفِقِ، كَمَثَلِ رَجُلَيْنِ عَلَيْهِمَا جُنَّتَانِ مِنْ حَدِيدٍ مِنْ ثُدِيِّهِمَا إِلَى تَرَا قِيهِمَا، فَأَمَّا المُنْفِقُ، فَلَا يُنْفِقُ إِلَّا سَبَغَتْ، أَوْ وَفَرَتْ عَلَى جِلْدِهِ حَتَّى تُخْفِيَ بَنَانَهُ، وَتَعْفُوَ أَثَرَهُ، وَأَمَّا البَخِيلُ، فَلَا يُرِيدُ أَنْ يُنْفِقَ شَيْئاً إِلَّا لَزِقَتْ كُلُّ حَلْقَةٍ مَكَانَهَا، فَهُوَ يُوَسِّعُهَا فَلَا تَتَّسِعُ" ((مُتَّفَقٌ عَلَيْهِ)) . وَ"الجُنَّةُ" الدِّرْعُ، وَمَعْنَاهُ: أَنَّ المُنْفِقَ كُلَّمَا أَنْفَقَ سَبَغَتْ، وَطَالَتْ حَتَّى تَجُرَّ وَارَءَهُ، وَتُخْفِيَ رِجْلَيْهِ وَأَثَرَ مَشْيِهِ وَخُطُوَاتِهِ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5834 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20559;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "مَنْ تَصَدَّقَ بِعَدْلِ تَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ، وَلَا يَقْبَلُ إِلَّا الطَّيِّبَ، فَإِنَّ اللَّهَ يَقْبَلُهَا بِيَمِينِهِ، ثُمَّ يُرَبِّيهَا لِصَاحِبِهَا كَمَا يُرَبِّى أَحَدُكُمْ فَلُوَّهُ حَتَّى تَكُونَ مِثْلَ الجَبَلِ " ((مُتَّفَقٌ عَلَيْهِ)) "الفَلُوُّ" بِفَتْحِ الفَاءِ وَضَمِّ اللَّامِ وَتَشْدِيدِ الوَاوِ، وَيُقَالُ أَيْضاً: بِكَسْرِ الفَاءِ وَإِسْكَانِ اللَّامِ وَتَخْفِيفِ الوَاوِ: وَهُوَ المُهْرُ .', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5862 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20560;
update hadith set arabic = 'وَعَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَمَا رَجُلٌ يَمْشِى بِفَلَاةٍ مِنَ الأَرْضِ، فَسَمِعَ صَوْتًا فِى سَحَابَةٍ: إسْقِ حَدِيقَةَ فُلَانٍ، فَتَنَحَّى ذَلِكَ السَّحَابُ فَأَفْرَغَ مَاءَهُ فِى حَرَّةٍ، فَإِذَا شَرْجَةٌ مِنْ تِلْكَ الشِّرَاحِ قَدِ اسْتَوْعَبَتْ ذَلِكَ المَاءَ كُلَّهُ، فَتَتَبَّعَ المَاءَ، فَإِذَا رَجُلٌ قَائِمٌ فِى حَدِيقَتِهِ يُحَوِّلُ المَاءَ بِمِسْحَاتِهِ، فَقَالَ لَهُ: يَا عَبْدَ اللَّهِ مَا اسْمُكَ ، قَالَ: فُلَانٌ لِلِاسْمِ الَّذِى سَمِعَ فِى السَّحَابَةِ، فَقَالَ لَهُ: يَا عَبْدَ اللَّهِ لِمَ تَسْأَلُنِي عَنِ اسْمِي ؟ فَقَالَ: إِنِّى سَمِعْتُ صَوْتًا فِى السَّحَابِ الَّذِى هَذَا مَاؤُهُ يَقُولُ: اسْقِ حَدِيقَةَ فُلَانٍ لِإسْمِكَ، فَمَا تَصْنَعُ فِيهَا؟ فَقَالَ: أَمَا إِذَا قُلْتَ هَذَا فَإِنِّى أَنْظُرُ إِلَى مَا يَخْرُجُ مِنْهَا، فَأَتَصَدَّقُ بِثُلُثِهِ، وَآكُلُ أَنَا وَعِيَالِى ثُلُثًا، وَأَرُدُّ فِيهَا ثُلُثَهُ ((رَوَاهُ مُسْلِمٌ)). "الحَرَّةُ" الأَرْضُ المُلَبَّسَةُ حِجَارَةً سَوْدَاءَ. "وَالشَّرْجَةُ" بِفَتْحِ الشِّينِ المُعْجَمَةِ وَإِسْكَانِ الرَّاءِ وَبِالجِيمِ: هِىَ مَسِيلُ المَاءِ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5776 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20561;
update hadith set arabic = 'عَنْ جَابِرِ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: اتَّقُوا الظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ وَاتَّقُوا الشُّحَّ فَإِنَّ الشُّحَّ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ حَمَلَهُمْ عَلَى أَنْ سَفَكُوا دِمَاءَهُمْ وَاسْتَحَلُّوا مَحَارِمَهُمْ".', updated_at = now() where id = 20562;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّى مَجْهُودٌ، فَأَرْسَلَ إِلَى بَعْضِ نِسَائِهِ، فَقَالَتْ: وَالَّذِى بَعَثَكَ بِالحَقِّ مَا عِنْدِى إِلَّا مَاءٌ، ثُمَّ أَرْسَلَ إِلَى أُخْرَى، فَقَالَتْ مِثْلَ ذَلِكَ، حَتَّى قُلْنَ كُلُّهُنَّ مِثْلَ ذَلِكَ: لَا وَالَّذِى بَعَثَكَ بِالحَقِّ مَا عِنْدِى إِلَّا مَاءٌ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ " مَنْ يُضِيفُهُ هَذَا اللَّيْلَةَ؟" فَقَالَ رَجُلٌ مِنَ الأَنْصَارِ: أَنَا يَا رَسُولَ اللَّهِ، فَانْطَلَقَ بِهِ إِلَى رَحْلِهِ ، فَقَالَ لِامْرَأَتِهِ: أَكْرِمِي ضَيْفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِى رِوَايَةٍ قَالَ لِامْرَأَتِهِ : هَلْ عِنْدَكِ شَئٌ؟ قَالَتْ: لَا، إِلَّا قُوتَ صِبْيَانِى. قَالَ: فَعَلِّلِيهِنَّ بِشَئٍ.وَإِذَا أَرَادُوا العَشَاءَ فَنَوِّمِيهِمْ. وَإِذَا دَخَلَ ضَيْفُنَا فَأَطْفِئِ السِّرَاجَ وَأَرِيهِ أَنَّا نَأْكُلُ، فَقَعَدُوا وَأَكَلَ الضَّيْفُ وَبَاتَ طَاوِيَيْنِ، فَلَمَّا أَصْبَحَ ، غَدَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لَقَدْ عَجِبَ اللَّهُ مِنْ صَنِيعِكُمَا بِضَيْفِكُمَا اللَّيْلَةَ".', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5911 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20563;
update hadith set arabic = 'وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ « طَعَامُ الِاثْنَيْنِ كَافِي الثَّلَاثَةِ، وَطَعَامُ الثَّلَاثَةِ كَافِي الأَرْبَعَةِ» ((مُتَّفَقٌ عَلَيْهِ)) . وَفِى رِوَايَةٍ لِمُسْلِمٍ عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: طَعَامُ الوَاحِدِ يَكْفِي الِاثْنَيْنِ وَطَعَامُ الِاثْنَيْنِ يَكْفِي الأَرْبَعَةَ، وَطَعَامُ الأَرْبَعَةِ يَكْفِي الثَّمَانِيَةَ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6057 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20564;
update hadith set arabic = 'عَنْ أَبِي سَعِيدٍ الخُدْرِى قَالَ: بَيْنَمَا نَحْنُ فِى سَفَرٍ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَ رَجُلٌ عَلَى رَاحِلَةٍ لَهُ ، فَجَعَلَ يَصْرِفُ بَصَرَهُ يَمِينًا وَشِمَالًا فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :« مَنْ كَانَ مَعَهُ فَضْلُ ظَهْرٍ فَلْيَعُدْ بِهِ عَلَى مَنْ لَا ظَهْرَ لَهُ، وَمَنْ كَانَ لَهُ فَضْلٌ مِنْ زَادٍ فَلْيَعُدْ بِهِ عَلَى مَنْ لَا زَادَ لَهُ» فَذَكَرَ مِنْ أَصْنَافِ المَالِ مَا ذَكَرَ حَتَّى رَأَيْنَا أَنَّهُ لَا حَقَّ لِأَحَدٍ مِنَّا فِى فَضْلٍ.', updated_at = now() where id = 20565;
update hadith set arabic = 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ، أَنَّ امْرَأَةَ جَاءَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِبُرْدَةٍ مَنْسُوجَةٍ فَقَالَتْ: نَسَجْتُهَا لِأَكْسُوَكَهَا، فَأَخَذَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُحْتَاجاً إِلَيْهَا ، فَخَرَجَ إِلَيْنَا وَإِنَّهَا إِزَارُهُ، فَقَالَ فُلَانٌ، اكْسُونِيهَا مَا أَحْسَنَهَا! فَقَالَ:« نَعَمْ» فَجَلَسَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِى المَجْلِسِ ثُمَّ رَجَعَ فَطَوَاهَا ثُمَّ أَرْسَلَ بِهِ إِلَيْهِ: فَقَالَ لَهُ القَوْمُ: مَا أَحْسَنْتَ! لَبِسَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُحْتَاجاً إِلَيْهَا ثُمَّ سَأَلْتَهُ وَعَلِمْتَ أَنَّهُ لَا يَرُدَ سَائِلاً ، فَقَالَ: إِنِّى وَاللَّهِ مَا سَأَلْتُهُ لِأَلْبَسَهَا وَإِنَّمَا سَأَلْتُهُ لِتَكُونَ كَفَنِي، قَالَ سَهْلٌ: فَكَانَتْ كَفَنَهُ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5648 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20566;
update hadith set arabic = 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّ الأَشْعَرِيِّينَ إِذَا أَرْمَلُوا فِى الغَزْوِ، أَوْ قَلَّ طَعَامُ عِيَالِهِمْ بِالمَدِينَةِ جَمَعُوا مَا كَانَ عِنْدَهُمْ فِى ثَوْبٍ وَاحِدٍ، اقْتَسَمُوهُ بَيْنَهُمْ فِى إِنَاءٍ وَاحِدٍ بِالسَّوِيَّةِ فَهُمْ مِنِّى وَأَنَا مِنْهُمْ" ((مُتَّفَقٌ عَلَيْهِ)) . "أَرْمَلُوا" فَرَغَ زَادُهُمْ أَوْ قَارَبَ الفَرَاغَ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5543 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20567;
update hadith set arabic = 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِشَرَابٍ، فَشَرِبَ مِنْهُ وَعَنْ يَمِينِهِ غُلَامٌ، وَعَنْ يَسَارِهِ الأَشْيَاخُ، فَقَالَ لِلْغُلَامِ:" أَتَأْذَنُ لِى أَنْ أُعْطِيَ هَؤُلَاءِ؟" فَقَالَ الغُلَامُ لَا وَاللَّهِ يَا رَسُولَ اللَّهِ، لَا أُؤْثِرُ مِنْكَ أَحَداً، فَتَلَّهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِى يَدِهِ . ((مُتَّفَقٌ عَلَيْهِ)) . "تَلَّهُ" بِالتَّاءِ المُثَنَّاهِ، فَوْقُ ، أَى وَضَعَهُ، وَهَذَا الغُلَامُ هُوَ ابْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5651 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20568;
update hadith set arabic = 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَمَا أَيُّوبُ عَلَيْهِ السَّلَامُ يَغْتَسِلُ عُرْيَاناً، فَخَرَّ عَلَيْهِ جَرَادٌ مِنْ ذَهَبٍ، فَجَعَلَ أَيُّوبُ يَحْثِي فِى ثَوْبِهِ فَنَادَاهُ رَبُّهُ عَزَّ وَجَلَّ يَا أَيُّوبُ أَلَمْ أَكُنْ أَغْنَيْتُكَ عَمَّا تَرَى؟! قَالَ:بَلَى وَعِزَّتِكَ، وَلَكِنْ لَا غِنَى بِى عَنْ بَرَكَتِكَ.', review_note = 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5774 | تشكيل آلي – يحتاج مراجعة', updated_at = now() where id = 20569;
